INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92805, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "幻想", "is_correct": true, "explanation": "正确答案。幻想（huàn xiǎng）指脑子里想一些不会真的发生的事。"}, {"text": "换向", "is_correct": false, "explanation": "xiàng（第四声）与 xiǎng（第三声）韵母相同、声调不同，意思是改变方向。"}, {"text": "幻象", "is_correct": false, "explanation": "xiàng（第四声）与 xiǎng（第三声）声调不同，意思是虚幻的形象。"}, {"text": "还乡", "is_correct": false, "explanation": "huán xiāng（第二声、第一声）与 huàn xiǎng 声调不同，意思是回到家乡。"}], "explanations": {"幻想": "正确答案。幻想（huàn xiǎng）指脑子里想一些不会真的发生的事。", "换向": "xiàng（第四声）与 xiǎng（第三声）韵母相同、声调不同，意思是改变方向。", "幻象": "xiàng（第四声）与 xiǎng（第三声）声调不同，意思是虚幻的形象。", "还乡": "huán xiāng（第二声、第一声）与 huàn xiǎng 声调不同，意思是回到家乡。"}, "sentence_index": null, "correct_answer": "幻想"}, "level_3": {"options": [{"text": "幻想", "is_correct": true, "explanation": "正确：“幻想”指想象不会发生的事，可以接“自己一夜之间变成明星”。"}, {"text": "练习", "is_correct": false, "explanation": "配价：“练习”要带动作的对象，不能接“自己一夜之间变成明星”这样的小句。"}, {"text": "研究", "is_correct": false, "explanation": "配价：“研究”的宾语是问题或事物，不能接这样的句子。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，与“变成明星”没有关系，句子不通。"}], "explanations": {"幻想": "正确：“幻想”指想象不会发生的事，可以接“自己一夜之间变成明星”。", "练习": "配价：“练习”要带动作的对象，不能接“自己一夜之间变成明星”这样的小句。", "研究": "配价：“研究”的宾语是问题或事物，不能接这样的句子。", "吃": "语义：“吃”指进食，与“变成明星”没有关系，句子不通。"}, "sentence_index": 0, "correct_answer": "幻想"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她幻想着明天去参加考试。", "explanation": "这里应该用〈计划〉。幻想指想不会真的发生的事，明天的考试是可以安排的，要用计划。"}, {"text": "她幻想着把这笔钱存进银行。", "explanation": "这里应该用〈打算〉。幻想指想不会真的发生的事，把钱存进银行是可以实行的打算，要用打算。"}, {"text": "她幻想着明天会下雨，所以带了伞。", "explanation": "这里应该用〈预测〉。幻想是想象不会实现的事，根据天气判断将要发生的事要用预测。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab211b87-ba01-4b87-ab29-4a9296f4379a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92805, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "幻想", "is_correct": true, "explanation": "正确：“幻想”指想象不现实的事，可以接“自己是国王，住在很大的城堡里”。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”指清理场所，不能用来说“自己是国王”。"}, {"text": "检查", "is_correct": false, "explanation": "配价：“检查”的宾语是人或事物，不能接“自己是国王”这样的小句。"}, {"text": "清洗", "is_correct": false, "explanation": "语义：“清洗”指用水洗掉污物，与句子的意思不合。"}], "explanations": {"幻想": "正确：“幻想”指想象不现实的事，可以接“自己是国王，住在很大的城堡里”。", "打扫": "语义：“打扫”指清理场所，不能用来说“自己是国王”。", "检查": "配价：“检查”的宾语是人或事物，不能接“自己是国王”这样的小句。", "清洗": "语义：“清洗”指用水洗掉污物，与句子的意思不合。"}, "sentence_index": 6, "correct_answer": "幻想"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们幻想了三种方案，最后选了最合适的一个。", "explanation": "这里应该用〈设想〉。幻想指想象不可能实现的事，提出可以执行的方案要用设想。"}, {"text": "他幻想起童年在海边玩耍的日子。", "explanation": "这里应该用〈回忆〉。幻想指想象将来或不可能的事，已经发生过的童年生活要用回忆。"}, {"text": "根据这些证据，我幻想他就是小偷。", "explanation": "这里应该用〈推测〉。幻想不能用来根据证据做判断，这种判断要用推测。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab211b87-ba01-4b87-ab29-4a9296f4379a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92805, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他常常着幻想自己成为作家。", "corrected_sentence": "他常常幻想自己成为作家。", "error_description": "“着”应放在动词后面表示持续的状态，不能放在“幻想”前面。应改为：他常常幻想自己成为作家。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab211b87-ba01-4b87-ab29-4a9296f4379a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92805, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他幻想的很开心，忘了时间。", "corrected_sentence": "他幻想得很开心，忘了时间。", "error_description": "补语要用“得”接在动词后面表示程度，“的”不能这样用。应改为：他幻想得很开心，忘了时间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab211b87-ba01-4b87-ab29-4a9296f4379a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
