INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92807, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "改称是换一个新名字来叫。", "primary_collocate": null, "pronunciation": "gǎi chēng", "ipa": "kai˨˩˦ ʈʂʰɤŋ˥", "syllable_count": 2, "sentences": [{"text": "这家公司去年改称为新华集团。", "target_word": "改称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条街后来改称人民路。", "target_word": "改称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校改称大学以后，学生更多了。", "target_word": "改称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市以前叫长安，后来改称西安。", "target_word": "改称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北平后来改称北京。", "target_word": "改称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个商店改称超市已经三年了。", "target_word": "改称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小河村改称小河镇。", "target_word": "改称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节日后来改称春节。", "target_word": "改称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院改称人民医院后，名字更长了。", "target_word": "改称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个班改称一班，不再叫实验班。", "target_word": "改称", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "改称了", "label": "体标（了）"}, {"form": "改称为", "label": "复合（改称为）"}], "register": "中性", "sense_fingerprint": "地方、机构、事物换了新名称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '964c90de-6e63-4a08-9795-75c3d131a85e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92807, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "改称", "is_correct": true, "explanation": "正确：「改称」指给机构更换新名称，「改称为新华集团」符合句意。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：「打扫」指清除脏物，与机构改名无关。"}, {"text": "拍照", "is_correct": false, "explanation": "配价：「拍照」是动宾结构，不能再带「为新华集团」这样的结构。"}, {"text": "演唱", "is_correct": false, "explanation": "语义：「演唱」指唱歌表演，不能用于机构改名。"}], "explanations": {"改称": "正确：「改称」指给机构更换新名称，「改称为新华集团」符合句意。", "打扫": "语义：「打扫」指清除脏物，与机构改名无关。", "拍照": "配价：「拍照」是动宾结构，不能再带「为新华集团」这样的结构。", "演唱": "语义：「演唱」指唱歌表演，不能用于机构改名。"}, "sentence_index": 0, "correct_answer": "改称"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他冷的时候改称了一件外套。", "explanation": "这里应该用〈穿〉。「改称」只表示换一个名字来叫，不表示穿上衣物。"}, {"text": "我把论文改称了小说。", "explanation": "这里应该用〈改写成〉。「改称」只表示换一个名字来叫，不表示把文章改写成另一种体裁。"}, {"text": "他把头发改称了短发。", "explanation": "这里应该用〈剪成〉。「改称」只表示换一个名字来叫，不表示改变头发的样式。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f5f1d31-ca2a-49c7-8237-0c9588c31fa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92807, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "改称", "is_correct": true, "explanation": "正确：「改称」指给村镇更换新名称，「小河村改称小河镇」符合句意。"}, {"text": "煮", "is_correct": false, "explanation": "语义：「煮」指加热食物，与村镇改名无关。"}, {"text": "穿戴", "is_correct": false, "explanation": "搭配：「穿戴」的对象是衣物、饰品，不能带地名。"}, {"text": "吟诵", "is_correct": false, "explanation": "搭配：「吟诵」的对象是诗文，不能带地名。"}], "explanations": {"改称": "正确：「改称」指给村镇更换新名称，「小河村改称小河镇」符合句意。", "煮": "语义：「煮」指加热食物，与村镇改名无关。", "穿戴": "搭配：「穿戴」的对象是衣物、饰品，不能带地名。", "吟诵": "搭配：「吟诵」的对象是诗文，不能带地名。"}, "sentence_index": 6, "correct_answer": "改称"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把游戏的难度改称了简单。", "explanation": "这里应该用〈调成〉。「改称」只表示换一个名字来叫，不表示调整难度等级。"}, {"text": "我把旧手机改称了新手机。", "explanation": "这里应该用〈换成〉。「改称」只用于名称或称呼的更改，不用于手机等物品的更换。"}, {"text": "我们把会议室的温度改称了二十度。", "explanation": "这里应该用〈调到〉。「改称」只表示换一个名字来叫，不表示调节温度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f5f1d31-ca2a-49c7-8237-0c9588c31fa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92807, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这所学校去年改称成第一中学。", "corrected_sentence": "这所学校去年改称为第一中学。", "error_description": "错误：「改称成第一中学」；正确：「改称为第一中学」。「改称」引出新名称要用「为」，「成」属于「改成」，不能用在「改称」后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f5f1d31-ca2a-49c7-8237-0c9588c31fa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92807, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这所大学前年改称了为理工学院。", "corrected_sentence": "这所大学前年改称为理工学院。", "error_description": "错误：「改称了为」；正确：「改称为」。「了」不能放在「为」前面，动态助词应放在整个动词结构之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f5f1d31-ca2a-49c7-8237-0c9588c31fa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
