INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92808, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "改变原来的称呼，改用另一个名称。", "primary_collocate": null, "pronunciation": "gǎi chēng", "ipa": "kai˨˩˦ ʈʂʰɤŋ˥", "syllable_count": 2, "sentences": [{"text": "结婚后，他改称岳父为爸爸。", "target_word": "改称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "熟了以后，我们改称对方为小李。", "target_word": "改称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从今天起改称我为师兄。", "target_word": "改称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家后来改称他为老张。", "target_word": "改称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在外人面前，他改称妻子为太太。", "target_word": "改称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生毕业后，可以改称老师为朋友。", "target_word": "改称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他当上经理后，同事都改称他为王经理。", "target_word": "改称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前叫你小明，现在改称你为明哥吧。", "target_word": "改称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她嫁人后，邻居改称她为李太太。", "target_word": "改称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们结婚以后，朋友都改称她为嫂子。", "target_word": "改称", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "改称了", "label": "体标（了）"}, {"form": "改称为", "label": "复合（改称为）"}], "register": "中性", "sense_fingerprint": "改变对人的称呼，换一种叫法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '964c90de-6e63-4a08-9795-75c3d131a85e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92808, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "改称", "is_correct": true, "explanation": "正确：「改称」指改变对人的称呼，「改称岳父为爸爸」符合句意。"}, {"text": "推翻", "is_correct": false, "explanation": "语义：「推翻」指否定或颠覆，与改变称呼无关。"}, {"text": "观察", "is_correct": false, "explanation": "搭配：「观察」指注意、研究，不能用来引出新的称呼。"}, {"text": "辞退", "is_correct": false, "explanation": "语义：「辞退」指解雇、让人离职，与称呼无关。"}], "explanations": {"改称": "正确：「改称」指改变对人的称呼，「改称岳父为爸爸」符合句意。", "推翻": "语义：「推翻」指否定或颠覆，与改变称呼无关。", "观察": "搭配：「观察」指注意、研究，不能用来引出新的称呼。", "辞退": "语义：「辞退」指解雇、让人离职，与称呼无关。"}, "sentence_index": 0, "correct_answer": "改称"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师改称我为一张桌子。", "explanation": "这里应该用〈叫〉。「改称」只用于改变对人的称呼，不能把人改称为物品。"}, {"text": "他把蛋糕改称了两半。", "explanation": "这里应该用〈切成〉。「改称」只表示改变称呼，不表示把东西分开。"}, {"text": "我把文件改称了PDF格式。", "explanation": "这里应该用〈改成〉。「改称」只用于更换名称或称呼，不用于格式、形式的变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f5f1d31-ca2a-49c7-8237-0c9588c31fa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92808, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "改称", "is_correct": true, "explanation": "正确：「改称」指改变对人的称呼，「改称他为王经理」符合句意。"}, {"text": "拥抱", "is_correct": false, "explanation": "搭配：「拥抱」是身体动作，不能用来引出一个称呼。"}, {"text": "驱逐", "is_correct": false, "explanation": "语义：「驱逐」指赶走，与称呼无关。"}, {"text": "观望", "is_correct": false, "explanation": "配价：「观望」是不及物动词，不能带「他」作宾语。"}], "explanations": {"改称": "正确：「改称」指改变对人的称呼，「改称他为王经理」符合句意。", "拥抱": "搭配：「拥抱」是身体动作，不能用来引出一个称呼。", "驱逐": "语义：「驱逐」指赶走，与称呼无关。", "观望": "配价：「观望」是不及物动词，不能带「他」作宾语。"}, "sentence_index": 6, "correct_answer": "改称"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈把我的生日改称为周末。", "explanation": "这里应该用〈改到〉。「改称」只用于改变对人的称呼，不用于改换日期。"}, {"text": "这本书被改称了英文版。", "explanation": "这里应该用〈翻译成〉。「改称」只用于更换名称，不用于语言或文字的转换。"}, {"text": "我把旧手机改称了新手机。", "explanation": "这里应该用〈换成〉。「改称」只用于名称或称呼的更改，不用于手机等物品的更换。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f5f1d31-ca2a-49c7-8237-0c9588c31fa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92808, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次比赛以后，队员们改称为他刘教练。", "corrected_sentence": "这次比赛以后，队员们改称他为刘教练。", "error_description": "错误：「改称为他刘教练」；正确：「改称他为刘教练」。被称呼的人要放在「改称」后面，「为」放在新称呼前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f5f1d31-ca2a-49c7-8237-0c9588c31fa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92808, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她调到总部后，下属就改称着她为王总。", "corrected_sentence": "她调到总部后，下属就改称她为王总。", "error_description": "错误：「改称着她」；正确：「改称她」。「改称」是一次性的动作，不能带「着」表示持续状态。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f5f1d31-ca2a-49c7-8237-0c9588c31fa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
