INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92809, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "恐怕是心里担心，觉得可能会不太好。", "primary_collocate": null, "pronunciation": "kǒng pà", "ipa": "kʰʊŋ˨˩ pʰa˥˩", "syllable_count": 2, "sentences": [{"text": "我恐怕赶不上最后一班车了。", "target_word": "恐怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法恐怕行不通，你再想想。", "target_word": "恐怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "恐怕他不会同意我们的计划。", "target_word": "恐怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我恐怕自己做不好这份工作。", "target_word": "恐怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太晚了，恐怕不太方便打扰你。", "target_word": "恐怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨下得这么大，我恐怕出不了门。", "target_word": "恐怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个人去那么远，恐怕路上会出事。", "target_word": "恐怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "恐怕我说的话会让她难过。", "target_word": "恐怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事恐怕要让你失望了。", "target_word": "恐怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买这么多东西，恐怕钱不够。", "target_word": "恐怕", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词，说话人心里担忧，觉得事情可能不顺利或结果不好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af85ea54-62da-4af3-896a-ad3c590683d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92809, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "恐怕", "is_correct": true, "explanation": "正确。“我”担心自己赶不上最后一班车，表达心里的忧虑，此处用“恐怕”最合适。"}, {"text": "互相", "is_correct": false, "explanation": "语法：“互相”要求双方或多方主语，不能用于“我”一个人赶车。"}, {"text": "一向", "is_correct": false, "explanation": "搭配：“一向”表示长期习惯，不能与“赶不上最后一班车了”这一具体事件搭配。"}, {"text": "千万", "is_correct": false, "explanation": "语义：“千万”表示叮嘱或强调，不表示担忧，与“赶不上”的句意不符。"}], "explanations": {"恐怕": "正确。“我”担心自己赶不上最后一班车，表达心里的忧虑，此处用“恐怕”最合适。", "互相": "语法：“互相”要求双方或多方主语，不能用于“我”一个人赶车。", "一向": "搭配：“一向”表示长期习惯，不能与“赶不上最后一班车了”这一具体事件搭配。", "千万": "语义：“千万”表示叮嘱或强调，不表示担忧，与“赶不上”的句意不符。"}, "sentence_index": 0, "correct_answer": "恐怕"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "听到这个好消息，她恐怕很高兴。", "explanation": "这里应该用〈想必〉。“恐怕”表示心里担心，好消息带来的是正面情绪，不该用担忧的词；表示推测的“想必”才合适。"}, {"text": "能遇到你，我恐怕很幸运。", "explanation": "这里应该用〈庆幸〉。“恐怕”表示心里担心，能遇到你是值得欣慰的事，应当用表示欣慰的“庆幸”。"}, {"text": "我恐怕这次的旅行很开心。", "explanation": "这里应该用〈希望〉。“恐怕”表示心里担心，句中说旅行开心是期盼的事，应当用表示盼望的“希望”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ca9d1d-04ee-41ab-b579-02df7548e6d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92809, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "恐怕", "is_correct": true, "explanation": "正确。“他一个人去那么远”让人担心路上出事，表达忧虑，此处用“恐怕”最合适。"}, {"text": "幸好", "is_correct": false, "explanation": "语义：“幸好”表示庆幸，与“路上会出事”的不幸结果矛盾。"}, {"text": "亲自", "is_correct": false, "explanation": "搭配：“亲自”修饰亲身行动，不能修饰“路上会出事”这种结果。"}, {"text": "诚然", "is_correct": false, "explanation": "语域：“诚然”是书面语，通常需与“但”等连用，不适合这句口语。"}], "explanations": {"恐怕": "正确。“他一个人去那么远”让人担心路上出事，表达忧虑，此处用“恐怕”最合适。", "幸好": "语义：“幸好”表示庆幸，与“路上会出事”的不幸结果矛盾。", "亲自": "搭配：“亲自”修饰亲身行动，不能修饰“路上会出事”这种结果。", "诚然": "语域：“诚然”是书面语，通常需与“但”等连用，不适合这句口语。"}, "sentence_index": 6, "correct_answer": "恐怕"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明天的会议恐怕很顺利。", "explanation": "这里应该用〈应该〉。“恐怕”表示心里担心，说会议顺利这种好事不该用担忧的词，应当用表示推测的“应该”。"}, {"text": "这次比赛我们恐怕能赢。", "explanation": "这里应该用〈一定〉。“恐怕”表示心里担心，句中说能赢是希望之事，应当用表示确信的“一定”。"}, {"text": "我恐怕很高兴能帮你。", "explanation": "这里应该用〈乐意〉。“恐怕”表示心里担心，能帮你是好事，不该用担忧的词；表示乐于做某事的“乐意”才合适。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ca9d1d-04ee-41ab-b579-02df7548e6d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92809, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我很恐怕明天来不了了。", "corrected_sentence": "我恐怕明天来不了了。", "error_description": "“恐怕”是副词，前面不能加“很”。应说“我恐怕明天来不了了”，不说“我很恐怕明天来不了了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ca9d1d-04ee-41ab-b579-02df7548e6d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92809, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他要恐怕不会来了。", "corrected_sentence": "他恐怕不会来了。", "error_description": "错误在于“要”放在了“恐怕”之前。“恐怕”是副词，修饰后面的谓语，前面不能再加助动词“要”，应说“他恐怕不会来了”，不说“他要恐怕不会来了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ca9d1d-04ee-41ab-b579-02df7548e6d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
