INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92810, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示担心或估计，有“可能”的意思。", "primary_collocate": null, "pronunciation": "kǒng pà", "ipa": "kʰʊŋ˨˩ pʰa˥˩", "syllable_count": 2, "sentences": [{"text": "现在才五点，他恐怕还没下班。", "target_word": "恐怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天这么黑，恐怕要下大雨了。", "target_word": "恐怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事恐怕不是他做的。", "target_word": "恐怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上堵车，我们恐怕会迟到。", "target_word": "恐怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的病恐怕一时好不了。", "target_word": "恐怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "已经十二点了，她恐怕睡着了。", "target_word": "恐怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书太难，恐怕孩子看不懂。", "target_word": "恐怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么多菜，恐怕我们吃不完。", "target_word": "恐怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走得这么急，恐怕有重要的事。", "target_word": "恐怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听声音，楼上恐怕有人在搬家。", "target_word": "恐怕", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词，对情况作出估计，意思是“可能”，多用于推测不太理想的结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af85ea54-62da-4af3-896a-ad3c590683d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92810, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "恐怕", "is_correct": true, "explanation": "正确。“恐怕”表示估计，“现在才五点”只能推测他还没下班，此处用“恐怕”最合适。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示事情已然发生，与“还没下班”矛盾。"}, {"text": "刚刚", "is_correct": false, "explanation": "体貌：“刚刚”表示刚发生的动作，与“还没”表示的未完成状态冲突。"}, {"text": "一向", "is_correct": false, "explanation": "搭配：“一向”表示长期习惯，不能与“现在才五点”这样的时点搭配。"}], "explanations": {"恐怕": "正确。“恐怕”表示估计，“现在才五点”只能推测他还没下班，此处用“恐怕”最合适。", "已经": "语义：“已经”表示事情已然发生，与“还没下班”矛盾。", "刚刚": "体貌：“刚刚”表示刚发生的动作，与“还没”表示的未完成状态冲突。", "一向": "搭配：“一向”表示长期习惯，不能与“现在才五点”这样的时点搭配。"}, "sentence_index": 0, "correct_answer": "恐怕"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他恐怕考了满分，大家都为他感到高兴。", "explanation": "这里应该用〈肯定〉。“恐怕”表示担心或不太好的估计，句中说的是好结果，应当用“肯定”。"}, {"text": "你恐怕会成功的，别担心。", "explanation": "这里应该用〈一定〉。“恐怕”用于推测不如意的结果，“成功”是好结果，与之不合，应当用表示确信的“一定”。"}, {"text": "我们恐怕赶上了末班车。", "explanation": "这里应该用〈终于〉。“恐怕”用于推测不如意的结果，赶上末班车是好结果，应当用表示达成的“终于”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ca9d1d-04ee-41ab-b579-02df7548e6d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92810, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "恐怕", "is_correct": true, "explanation": "正确。“这本书太难”是对孩子能否看懂的推测，此处用“恐怕”最合适。"}, {"text": "千万", "is_correct": false, "explanation": "语义：“千万”表示叮嘱或强调，不表示估计，与句意不符。"}, {"text": "只好", "is_correct": false, "explanation": "搭配：“只好”需要主语被迫做出某种动作，不能修饰“孩子看不懂”这种状态。"}, {"text": "诚然", "is_correct": false, "explanation": "语域：“诚然”是书面语，通常需与“但”等连用，不适合这句口语。"}], "explanations": {"恐怕": "正确。“这本书太难”是对孩子能否看懂的推测，此处用“恐怕”最合适。", "千万": "语义：“千万”表示叮嘱或强调，不表示估计，与句意不符。", "只好": "搭配：“只好”需要主语被迫做出某种动作，不能修饰“孩子看不懂”这种状态。", "诚然": "语域：“诚然”是书面语，通常需与“但”等连用，不适合这句口语。"}, "sentence_index": 6, "correct_answer": "恐怕"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他恐怕考上了大学，全家都很高兴。", "explanation": "这里应该用〈已经〉。“恐怕”用于推测不如意的结果，考上大学是已知的好事，应当用“已经”。"}, {"text": "这个方案恐怕很好，大家都同意。", "explanation": "这里应该用〈应该〉。“恐怕”用于推测不如意的结果，方案很好是好结果，应当用表示推测的“应该”。"}, {"text": "恐怕他带了伞，没有淋湿。", "explanation": "这里应该用〈幸好〉。“恐怕”用于推测不如意的结果，句中没有淋湿是好结果，应当用表示庆幸的“幸好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ca9d1d-04ee-41ab-b579-02df7548e6d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92810, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很恐怕还在睡觉。", "corrected_sentence": "他恐怕还在睡觉。", "error_description": "“恐怕”是副词，前面不能加“很”。应说“他恐怕还在睡觉”，不说“他很恐怕还在睡觉”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ca9d1d-04ee-41ab-b579-02df7548e6d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92810, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事非常恐怕要延期了。", "corrected_sentence": "这件事恐怕要延期了。", "error_description": "“恐怕”是表示估计的副词，前面不能再加程度副词“非常”。应说“这件事恐怕要延期了”，不说“这件事非常恐怕要延期了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ca9d1d-04ee-41ab-b579-02df7548e6d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92811, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f74798a-5a73-4add-9ed7-fed78d2d8d9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
