INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92811, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "救助是别人遇到难处时，去帮他度过难关。", "primary_collocate": null, "pronunciation": "jiù zhù", "ipa": "tɕjoʊ˥˩ ʈʂu˥˩", "syllable_count": 2, "sentences": [{"text": "朋友失业后，我们几个人一起救助他。", "target_word": "救助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家里遇到困难，邻居们都来救助。", "target_word": "救助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司救助了生病的员工，帮他度过难关。", "target_word": "救助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校成立了基金，救助家庭困难的学生。", "target_word": "救助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想用自己的钱救助那些没钱上学的孩子。", "target_word": "救助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遇到难处时，有人救助真的很温暖。", "target_word": "救助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小镇的人互相救助，度过了最难的冬天。", "target_word": "救助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人没有收入，村里每月救助他一些钱。", "target_word": "救助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我曾被陌生人救助过，所以也想帮别人。", "target_word": "救助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "慈善会救助了不少穷人。", "target_word": "救助", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "救助了", "label": "完成体"}, {"form": "救助过", "label": "经历体"}, {"form": "救助站", "label": "复合"}, {"form": "救助金", "label": "复合"}], "register": "中性", "sense_fingerprint": "别人遇到难处时帮他度过难关", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0006e141-8dc4-4804-a206-f5967740a580') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92811, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "救助", "is_correct": true, "explanation": "救助（jiù zhù）：在别人遇到难处时帮他度过难关，即本词。"}, {"text": "求助", "is_correct": false, "explanation": "qiú（第二声）与 jiù（第四声）声母不同（q/j），意思是请别人帮忙。"}, {"text": "就座", "is_correct": false, "explanation": "zuò（第四声）与 zhù（第四声）声母不同（z/zh），意思是入座。"}, {"text": "旧主", "is_correct": false, "explanation": "zhǔ（第三声）与 zhù（第四声）声调不同，意思是原来的主人。"}], "explanations": {"救助": "救助（jiù zhù）：在别人遇到难处时帮他度过难关，即本词。", "求助": "qiú（第二声）与 jiù（第四声）声母不同（q/j），意思是请别人帮忙。", "就座": "zuò（第四声）与 zhù（第四声）声母不同（z/zh），意思是入座。", "旧主": "zhǔ（第三声）与 zhù（第四声）声调不同，意思是原来的主人。"}, "sentence_index": null, "correct_answer": "救助"}, "level_3": {"options": [{"text": "救助", "is_correct": true, "explanation": "救助：朋友失业后，大家一起帮他渡过难关，与句意相符。"}, {"text": "辞退", "is_correct": false, "explanation": "语义：辞退是雇主解雇员工，与朋友失业后大家来帮忙的语境相反。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：嘲笑是取笑别人，与朋友遭遇困境后的帮助语境不符。"}, {"text": "帮忙", "is_correct": false, "explanation": "配价：帮忙是离合词，不能直接带“他”作宾语，应说“帮他的忙”或“帮他”。"}], "explanations": {"救助": "救助：朋友失业后，大家一起帮他渡过难关，与句意相符。", "辞退": "语义：辞退是雇主解雇员工，与朋友失业后大家来帮忙的语境相反。", "嘲笑": "语义：嘲笑是取笑别人，与朋友遭遇困境后的帮助语境不符。", "帮忙": "配价：帮忙是离合词，不能直接带“他”作宾语，应说“帮他的忙”或“帮他”。"}, "sentence_index": 0, "correct_answer": "救助"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校救助了那个拿了金牌的学生。", "explanation": "这里应该用〈表彰〉。救助针对遇到困难的人，拿了金牌的学生应当〈表彰〉。"}, {"text": "学校救助了那辆破旧的自行车。", "explanation": "这里应该用〈修理〉。救助是帮助有难处的人度过难关，修好破旧的自行车要用〈修理〉。"}, {"text": "学校救助了那张缺了一条腿的课桌。", "explanation": "这里应该用〈换掉〉。救助针对遇到困难的人，缺了腿的课桌应当〈换掉〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f74798a-5a73-4add-9ed7-fed78d2d8d9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92811, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "救助", "is_correct": true, "explanation": "救助（jiù zhù）：在别人遇到难处时帮他度过难关，即本词。"}, {"text": "揪住", "is_correct": false, "explanation": "jiū（第一声）与 jiù（第四声）声调不同，意思是紧紧抓住。"}, {"text": "久住", "is_correct": false, "explanation": "jiǔ（第三声）与 jiù（第四声）声调不同，意思是长时间居住。"}, {"text": "旧主", "is_correct": false, "explanation": "zhǔ（第三声）与 zhù（第四声）声调不同，意思是原来的主人。"}], "explanations": {"救助": "救助（jiù zhù）：在别人遇到难处时帮他度过难关，即本词。", "揪住": "jiū（第一声）与 jiù（第四声）声调不同，意思是紧紧抓住。", "久住": "jiǔ（第三声）与 jiù（第四声）声调不同，意思是长时间居住。", "旧主": "zhǔ（第三声）与 zhù（第四声）声调不同，意思是原来的主人。"}, "sentence_index": null, "correct_answer": "救助"}, "level_3": {"options": [{"text": "救助", "is_correct": true, "explanation": "救助：小镇的人互相援助，度过了最难的冬天，与句意相符。"}, {"text": "攻击", "is_correct": false, "explanation": "语义：攻击是伤害他人，与“度过了最难的冬天”的互助语境相反。"}, {"text": "竞争", "is_correct": false, "explanation": "语义：竞争是彼此争胜，与一起熬过困难的互助语境不符。"}, {"text": "埋怨", "is_correct": false, "explanation": "语义：埋怨是互相责怪，与大家一起熬过最难冬天的互助语境不符。"}], "explanations": {"救助": "救助：小镇的人互相援助，度过了最难的冬天，与句意相符。", "攻击": "语义：攻击是伤害他人，与“度过了最难的冬天”的互助语境相反。", "竞争": "语义：竞争是彼此争胜，与一起熬过困难的互助语境不符。", "埋怨": "语义：埋怨是互相责怪，与大家一起熬过最难冬天的互助语境不符。"}, "sentence_index": 6, "correct_answer": "救助"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司救助了不少新员工。", "explanation": "这里应该用〈招聘〉。救助是对陷入困境的人的援助，雇用新员工不是救助。"}, {"text": "慈善会救助了那座老房子。", "explanation": "这里应该用〈修缮〉。救助是帮助有难处的人度过难关，修缮老房子要用〈修缮〉。"}, {"text": "街头的小混混救助了那部偷来的手机。", "explanation": "这里应该用〈藏〉。救助指给予帮助，偷来的手机应当〈藏〉起来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f74798a-5a73-4add-9ed7-fed78d2d8d9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92811, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "社区里的人一起把那个失业的年轻人救助。", "corrected_sentence": "社区里的人一起把那个失业的年轻人救助了。", "error_description": "“把”字句中，动词后面要带“了”或其他成分，不能只说“救助”。错误形式是“把那个失业的年轻人救助”，正确形式是“把那个失业的年轻人救助了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f74798a-5a73-4add-9ed7-fed78d2d8d9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92811, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那家公司没救助了他，他只好自己想办法。", "corrected_sentence": "那家公司没救助他，他只好自己想办法。", "error_description": "“没”后面的动词不能带“了”。“没”表示未发生，应说“没救助他”，不能说“没救助了他”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f74798a-5a73-4add-9ed7-fed78d2d8d9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
