INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92812, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在人遇到危难或困境时给予援救和帮助。", "primary_collocate": null, "pronunciation": "jiù zhù", "ipa": "tɕjoʊ˥˩ ʈʂu˥˩", "syllable_count": 2, "sentences": [{"text": "消防员救助了被困在大火中的老人。", "target_word": "救助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洪水来了，当地政府立刻救助受灾群众。", "target_word": "救助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "志愿者每天救助街头的流浪者。", "target_word": "救助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的渔民救助了落水的游客。", "target_word": "救助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府每年救助很多贫困的孩子。", "target_word": "救助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震后，各地的人都来救助灾区的人民。", "target_word": "救助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他被汽车撞倒后，路人马上救助了他。", "target_word": "救助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家机构专门救助孤儿。", "target_word": "救助", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察及时救助了迷路的小孩。", "target_word": "救助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民们救助过一位受伤的登山者。", "target_word": "救助", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "救助了", "label": "完成体"}, {"form": "救助过", "label": "经历体"}, {"form": "救助站", "label": "复合"}, {"form": "救助金", "label": "复合"}], "register": "中性", "sense_fingerprint": "对遇到危难的人进行援救和帮助", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0006e141-8dc4-4804-a206-f5967740a580') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92812, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "救助", "is_correct": true, "explanation": "救助（jiù zhù）：援救并帮助遇到危难的人，即本词。"}, {"text": "求助", "is_correct": false, "explanation": "qiú（第二声）与 jiù（第四声）声母不同（q/j），意思是请别人帮忙。"}, {"text": "就座", "is_correct": false, "explanation": "zuò（第四声）与 zhù（第四声）声母不同（z/zh），意思是入座。"}, {"text": "揪住", "is_correct": false, "explanation": "jiū（第一声）与 jiù（第四声）声调不同，意思是紧紧抓住。"}], "explanations": {"救助": "救助（jiù zhù）：援救并帮助遇到危难的人，即本词。", "求助": "qiú（第二声）与 jiù（第四声）声母不同（q/j），意思是请别人帮忙。", "就座": "zuò（第四声）与 zhù（第四声）声母不同（z/zh），意思是入座。", "揪住": "jiū（第一声）与 jiù（第四声）声调不同，意思是紧紧抓住。"}, "sentence_index": null, "correct_answer": "救助"}, "level_3": {"options": [{"text": "救助", "is_correct": true, "explanation": "救助：援救被大火困住的人，与“被困在大火中”的语境相符。"}, {"text": "逮捕", "is_correct": false, "explanation": "语义：逮捕指依法拘捕犯罪嫌疑人，与消防员在火场中的行为不符。"}, {"text": "逃离", "is_correct": false, "explanation": "配价：逃离的宾语是处所或危险，不能直接带“老人”这样的人作宾语。"}, {"text": "批评", "is_correct": false, "explanation": "语义：批评是言语上指出过错，与火场中对老人的抢救行动不符。"}], "explanations": {"救助": "救助：援救被大火困住的人，与“被困在大火中”的语境相符。", "逮捕": "语义：逮捕指依法拘捕犯罪嫌疑人，与消防员在火场中的行为不符。", "逃离": "配价：逃离的宾语是处所或危险，不能直接带“老人”这样的人作宾语。", "批评": "语义：批评是言语上指出过错，与火场中对老人的抢救行动不符。"}, "sentence_index": 0, "correct_answer": "救助"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他经常救助那个闹钟，每天都给它上发条。", "explanation": "这里应该用〈上〉。救助指援救遇到危难的人或动物，给闹钟上发条应当说〈上〉。"}, {"text": "修理工救助了那台坏掉的洗衣机。", "explanation": "这里应该用〈修复〉。救助是援救遇到危难的人或动物，修好坏掉的机器要用〈修复〉。"}, {"text": "我每天在医院里救助那台生病的电梯。", "explanation": "这里应该用〈维修〉。救助指援救遇到危难的人或动物，电梯出故障应当说〈维修〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f74798a-5a73-4add-9ed7-fed78d2d8d9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92812, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "救助", "is_correct": true, "explanation": "救助（jiù zhù）：援救并帮助遇到危难的人，即本词。"}, {"text": "旧主", "is_correct": false, "explanation": "zhǔ（第三声）与 zhù（第四声）声调不同，意思是原来的主人。"}, {"text": "久住", "is_correct": false, "explanation": "jiǔ（第三声）与 jiù（第四声）声调不同，意思是长时间居住。"}, {"text": "揪住", "is_correct": false, "explanation": "jiū（第一声）与 jiù（第四声）声调不同，意思是紧紧抓住。"}], "explanations": {"救助": "救助（jiù zhù）：援救并帮助遇到危难的人，即本词。", "旧主": "zhǔ（第三声）与 zhù（第四声）声调不同，意思是原来的主人。", "久住": "jiǔ（第三声）与 jiù（第四声）声调不同，意思是长时间居住。", "揪住": "jiū（第一声）与 jiù（第四声）声调不同，意思是紧紧抓住。"}, "sentence_index": null, "correct_answer": "救助"}, "level_3": {"options": [{"text": "救助", "is_correct": true, "explanation": "救助：路人及时援救受伤的人，与“被汽车撞倒”的语境相符。"}, {"text": "撞", "is_correct": false, "explanation": "语义：撞是造成伤害的动作，与路人在伤者身边施以援手的语境相反。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：嘲笑是取笑他人，与刚被撞倒、需要帮助的语境不符。"}, {"text": "讨厌", "is_correct": false, "explanation": "体貌：讨厌是状态动词，不能用“马上……了”表示瞬间完成的动作。"}], "explanations": {"救助": "救助：路人及时援救受伤的人，与“被汽车撞倒”的语境相符。", "撞": "语义：撞是造成伤害的动作，与路人在伤者身边施以援手的语境相反。", "嘲笑": "语义：嘲笑是取笑他人，与刚被撞倒、需要帮助的语境不符。", "讨厌": "体貌：讨厌是状态动词，不能用“马上……了”表示瞬间完成的动作。"}, "sentence_index": 6, "correct_answer": "救助"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司救助了不少新员工。", "explanation": "这里应该用〈招聘〉。救助是对陷入困境的人的援助，雇用新员工不是救助。"}, {"text": "慈善会救助了那座老房子。", "explanation": "这里应该用〈修缮〉。救助是援救陷入危难的人或动物，修缮老房子要用〈修缮〉。"}, {"text": "街头的小混混救助了那辆偷来的汽车。", "explanation": "这里应该用〈开走〉。救助指援救遇到危难的人，偷来的汽车应当说〈开走〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f74798a-5a73-4add-9ed7-fed78d2d8d9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92812, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "救生员把一名溺水的小男孩救助。", "corrected_sentence": "救生员把一名溺水的小男孩救助了。", "error_description": "“把”字句中，动词后面要带“了”或其他成分，不能只说“救助”。错误形式是“把一名溺水的小男孩救助”，正确形式是“把一名溺水的小男孩救助了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f74798a-5a73-4add-9ed7-fed78d2d8d9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92812, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "消防队员把一个被困在井里的工人救助。", "corrected_sentence": "消防队员把一个被困在井里的工人救助了。", "error_description": "“把”字句中，动词后面需要带“了”或其他成分。单独的“救助”结尾不成立，应改为“救助了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f74798a-5a73-4add-9ed7-fed78d2d8d9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
