INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92814, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "拿着；握住。", "primary_collocate": null, "pronunciation": "chí", "ipa": "ʈʂʰɻ̩˧˥", "syllable_count": 1, "sentences": [{"text": "小女孩右手持一朵红花，笑着跑过来。", "target_word": "持", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他左手持灯，右手扶着墙，慢慢走下楼梯。", "target_word": "持", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骑士持剑冲向前方，马跑得很快。", "target_word": "持", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生们持旗站在路边，欢迎客人的到来。", "target_word": "持", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师一手持书，走进教室开始上课。", "target_word": "持", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她双手持扇，在台上慢慢地跳舞。", "target_word": "持", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人右手持锤，用力敲着墙上的钉子。", "target_word": "持", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他持笔想了很久，还是没有写下一个字。", "target_word": "持", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "运动员右手持火炬，跑进了体育场。", "target_word": "持", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "守门的人持棍站在桥头，不让陌生人过去。", "target_word": "持", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "持着", "label": "体标"}], "register": "书面", "sense_fingerprint": "持|动词|拿着，握住", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1bf60fe-067d-49a1-bd98-e843615aaeb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92814, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "持", "is_correct": true, "explanation": "持（chí）：拿着、握住，是本题的正确答案。"}, {"text": "尺", "is_correct": false, "explanation": "尺（chǐ）与 chí 声调不同（第三声），意思是尺子。"}, {"text": "翅", "is_correct": false, "explanation": "翅（chì）与 chí 声调不同（第四声），意思是翅膀。"}, {"text": "十", "is_correct": false, "explanation": "十（shí）与 chí 声母不同（sh 与 ch），意思是数字十。"}, {"text": "直", "is_correct": false, "explanation": "直（zhí）与 chí 声母不同（zh 与 ch），意思是笔直。"}], "explanations": {"持": "持（chí）：拿着、握住，是本题的正确答案。", "尺": "尺（chǐ）与 chí 声调不同（第三声），意思是尺子。", "翅": "翅（chì）与 chí 声调不同（第四声），意思是翅膀。", "十": "十（shí）与 chí 声母不同（sh 与 ch），意思是数字十。", "直": "直（zhí）与 chí 声母不同（zh 与 ch），意思是笔直。"}, "sentence_index": null, "correct_answer": "持"}, "level_3": {"options": [{"text": "持", "is_correct": true, "explanation": "持：拿着，与“右手”和“一朵红花”的语境相符，是本题正确答案。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指把食物送进嘴里，不能用来指拿着花。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不能说唱一朵红花。"}, {"text": "骑", "is_correct": false, "explanation": "搭配：“骑”的对象是马、车等，不能说骑一朵红花。"}], "explanations": {"持": "持：拿着，与“右手”和“一朵红花”的语境相符，是本题正确答案。", "吃": "语义：“吃”指把食物送进嘴里，不能用来指拿着花。", "唱": "搭配：“唱”的对象是歌曲，不能说唱一朵红花。", "骑": "搭配：“骑”的对象是马、车等，不能说骑一朵红花。"}, "sentence_index": 0, "correct_answer": "持"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天持着书包去上学。", "explanation": "这里应该用〈背〉。“持”指用手拿住，书包是背在肩上的，应说背着书包。"}, {"text": "阳台上持着一排花盆。", "explanation": "这里应该用〈摆〉。“持”指用手拿住，不能说把东西摆放在某处，应说阳台上摆着一排花盆。"}, {"text": "他持了很大的劲儿，把箱子搬上了楼。", "explanation": "这里应该用〈使〉。“持”不能用于“劲儿”，表示用力应说使劲儿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be722e46-e32d-4a8d-8189-15ca20c8e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92814, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "持", "is_correct": true, "explanation": "持（chí）：拿着、握住，是本题的正确答案。"}, {"text": "齿", "is_correct": false, "explanation": "齿（chǐ）与 chí 声调不同（第三声），意思是牙齿。"}, {"text": "赤", "is_correct": false, "explanation": "赤（chì）与 chí 声调不同（第四声），意思是红色。"}, {"text": "时", "is_correct": false, "explanation": "时（shí）与 chí 声母不同（sh 与 ch），意思是时间。"}, {"text": "吃", "is_correct": false, "explanation": "吃（chī）与 chí 声调不同（第一声），意思是吃东西。"}], "explanations": {"持": "持（chí）：拿着、握住，是本题的正确答案。", "齿": "齿（chǐ）与 chí 声调不同（第三声），意思是牙齿。", "赤": "赤（chì）与 chí 声调不同（第四声），意思是红色。", "时": "时（shí）与 chí 声母不同（sh 与 ch），意思是时间。", "吃": "吃（chī）与 chí 声调不同（第一声），意思是吃东西。"}, "sentence_index": null, "correct_answer": "持"}, "level_3": {"options": [{"text": "持", "is_correct": true, "explanation": "持：拿着，与“右手”和“锤”的语境相符，是本题正确答案。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”指饮用液体，与“锤”不合。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”用于衣服、鞋袜等，不能说穿锤。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”指用牙齿啃咬，与用手拿锤子敲钉子的语境不符。"}], "explanations": {"持": "持：拿着，与“右手”和“锤”的语境相符，是本题正确答案。", "喝": "语义：“喝”指饮用液体，与“锤”不合。", "穿": "搭配：“穿”用于衣服、鞋袜等，不能说穿锤。", "咬": "语义：“咬”指用牙齿啃咬，与用手拿锤子敲钉子的语境不符。"}, "sentence_index": 6, "correct_answer": "持"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他持着墙慢慢往前走。", "explanation": "这里应该用〈扶〉。“持”是拿住器物，扶墙是用手轻靠支撑，不能说持墙，应说扶着墙。"}, {"text": "她持了一张奖状，大家都来祝贺。", "explanation": "这里应该用〈拿〉。“拿”可表示获得，如拿奖状；“持”没有获得的意思，不能说持奖状。"}, {"text": "妈妈每天持钢琴练习一小时。", "explanation": "这里应该用〈弹〉。“持”只表示用手拿着，不能用来指弹奏乐器，应说弹钢琴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be722e46-e32d-4a8d-8189-15ca20c8e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92814, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小男孩右手持把一面小旗，跑向操场。", "corrected_sentence": "小男孩右手持一面小旗，跑向操场。", "error_description": "“持”是动词，后面直接接宾语“一面小旗”，不能在“持”后插入“把”，应说“持一面小旗”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be722e46-e32d-4a8d-8189-15ca20c8e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92814, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他棍持站在门口，挡着来往的人。", "corrected_sentence": "他持棍站在门口，挡着来往的人。", "error_description": "“持”与宾语“棍”的语序错误，应说“持棍”，不能说“棍持”（宾语应放在动词之后）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be722e46-e32d-4a8d-8189-15ca20c8e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
