INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92817, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "摆脱是想办法离开，不再被缠着。", "primary_collocate": null, "pronunciation": "bǎi tuō", "ipa": "pai²¹⁴ tʰwɔ⁵⁵", "syllable_count": 2, "sentences": [{"text": "他想尽办法摆脱后面的人。", "target_word": "摆脱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗一直跟着我，我摆脱不了它。", "target_word": "摆脱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她终于摆脱了那个缠人的朋友。", "target_word": "摆脱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想摆脱这些无聊的电话。", "target_word": "摆脱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他快跑几步，摆脱了跟踪的人。", "target_word": "摆脱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你怎么才能摆脱他的纠缠？", "target_word": "摆脱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们走小路，想摆脱这群记者。", "target_word": "摆脱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蚊子一直追着我，真难摆脱。", "target_word": "摆脱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他借口上厕所，摆脱了那个客人。", "target_word": "摆脱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我已经摆脱过他一次了。", "target_word": "摆脱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "摆脱了", "label": "体标"}, {"form": "摆脱过", "label": "体标"}], "register": "中性", "sense_fingerprint": "想办法离开缠着自己的人或事，不再受纠缠", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7018439-109a-4c8c-8d0d-ce7e3899b663') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92817, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "摆脱", "is_correct": true, "explanation": "正确。“想尽办法摆脱后面的人”指想办法甩开纠缠自己的人。"}, {"text": "打扫", "is_correct": false, "explanation": "配价：“打扫”的宾语是房间、地面等，不能带“人”作宾语。"}, {"text": "欢送", "is_correct": false, "explanation": "语义：“欢送”表示送别，与“想尽办法”要甩掉后面的人的意思矛盾。"}, {"text": "参观", "is_correct": false, "explanation": "配价：“参观”的宾语是地点或场所，不能带“人”作宾语。"}], "explanations": {"摆脱": "正确。“想尽办法摆脱后面的人”指想办法甩开纠缠自己的人。", "打扫": "配价：“打扫”的宾语是房间、地面等，不能带“人”作宾语。", "欢送": "语义：“欢送”表示送别，与“想尽办法”要甩掉后面的人的意思矛盾。", "参观": "配价：“参观”的宾语是地点或场所，不能带“人”作宾语。"}, "sentence_index": 0, "correct_answer": "摆脱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一下子摆脱了飞来的石头。", "explanation": "这里应该用〈躲开〉。“摆脱”指脱离纠缠，躲避飞来的石头要说“躲开”。"}, {"text": "他摆脱了一杯热茶。", "explanation": "这里应该用〈喝了〉。“摆脱”指脱离纠缠，喝茶要说“喝”。"}, {"text": "老师摆脱了我们的作业。", "explanation": "这里应该用〈检查〉。“摆脱”指脱离纠缠，检查作业要说“检查”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '093b16e4-030e-40ed-8cbe-9fc7fc0231ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92817, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "摆脱", "is_correct": true, "explanation": "正确。“走小路，想摆脱这群记者”指想甩开记者。"}, {"text": "款待", "is_correct": false, "explanation": "语义：“款待”指热情招待，与“走小路”躲避记者的意图相反。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”表示迎接，与“走小路”的回避意图相反。"}, {"text": "观看", "is_correct": false, "explanation": "配价：“观看”的宾语是节目、比赛等，不能指“记者”这样的人。"}], "explanations": {"摆脱": "正确。“走小路，想摆脱这群记者”指想甩开记者。", "款待": "语义：“款待”指热情招待，与“走小路”躲避记者的意图相反。", "欢迎": "语义：“欢迎”表示迎接，与“走小路”的回避意图相反。", "观看": "配价：“观看”的宾语是节目、比赛等，不能指“记者”这样的人。"}, "sentence_index": 6, "correct_answer": "摆脱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我已经摆脱过这台机器一次了。", "explanation": "这里应该用〈修理〉。“摆脱”指脱离纠缠，修理机器要说“修理”。"}, {"text": "我已经摆脱过这件衣服一次了。", "explanation": "这里应该用〈丢掉〉。“摆脱”指脱离纠缠，把不要的衣服扔掉要说“丢掉”。"}, {"text": "我已经摆脱过这座博物馆一次了。", "explanation": "这里应该用〈参观〉。“摆脱”不用于去某个场所，参观场所要说“参观”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '093b16e4-030e-40ed-8cbe-9fc7fc0231ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92817, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她想办法摆脱被那个纠缠的人。", "corrected_sentence": "她想办法摆脱那个纠缠的人。", "error_description": "错误在“摆脱”后多加了“被”：“摆脱”是动词，后面直接带宾语，不能在它和宾语之间加“被”。应说“她想办法摆脱那个纠缠的人。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '093b16e4-030e-40ed-8cbe-9fc7fc0231ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92817, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我已经摆脱了过这种困扰了。", "corrected_sentence": "我已经摆脱过这种困扰了。", "error_description": "错误在体标：“摆脱”后不能同时紧跟“了”和“过”（“摆脱了过”）。表示曾经有过这种经历用“摆脱过”，句末的“了”表示变化。应说“我已经摆脱过这种困扰了。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '093b16e4-030e-40ed-8cbe-9fc7fc0231ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
