INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92818, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "脱离不好的束缚、困难或不利的状态。", "primary_collocate": null, "pronunciation": "bǎi tuō", "ipa": "pai²¹⁴ tʰwɔ⁵⁵", "syllable_count": 2, "sentences": [{"text": "这个家庭终于摆脱了贫困。", "target_word": "摆脱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想摆脱现在的坏习惯。", "target_word": "摆脱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司努力摆脱困难的局面。", "target_word": "摆脱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他花了三年才摆脱失败的阴影。", "target_word": "摆脱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们想摆脱考试的压力。", "target_word": "摆脱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家已经摆脱了战争。", "target_word": "摆脱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用工作摆脱了难过的心情。", "target_word": "摆脱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要摆脱坏情绪，可以多运动。", "target_word": "摆脱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直想摆脱穷日子。", "target_word": "摆脱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要摆脱这种不利的状态。", "target_word": "摆脱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "摆脱了", "label": "体标"}, {"form": "摆脱过", "label": "体标"}], "register": "中性", "sense_fingerprint": "脱离贫困、坏习惯、压力等不好的束缚或不利状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7018439-109a-4c8c-8d0d-ce7e3899b663') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92818, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "摆脱", "is_correct": true, "explanation": "正确。“终于摆脱了贫困”指脱离不利的状况。"}, {"text": "享受", "is_correct": false, "explanation": "语义：“享受”指以……为乐，“终于享受了贫困”与贫困的不利含义相反。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”用于美好的事物，不能用于“贫困”这样的不利状况。"}, {"text": "参观", "is_correct": false, "explanation": "配价：“参观”的宾语是场所，不能带“贫困”这样的抽象状况。"}], "explanations": {"摆脱": "正确。“终于摆脱了贫困”指脱离不利的状况。", "享受": "语义：“享受”指以……为乐，“终于享受了贫困”与贫困的不利含义相反。", "欣赏": "语义：“欣赏”用于美好的事物，不能用于“贫困”这样的不利状况。", "参观": "配价：“参观”的宾语是场所，不能带“贫困”这样的抽象状况。"}, "sentence_index": 0, "correct_answer": "摆脱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他摆脱了这双新鞋。", "explanation": "这里应该用〈穿上〉。“摆脱”指脱离束缚或困境，不用于穿戴物品。"}, {"text": "他刚刚摆脱了一笔奖学金。", "explanation": "这里应该用〈获得〉。“摆脱”指脱离不好的状况，奖学金是好事，不能摆脱。"}, {"text": "他摆脱了一座新房子。", "explanation": "这里应该用〈修建〉。“摆脱”指脱离不利的束缚，修建房子是中性动作，不能用“摆脱”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '093b16e4-030e-40ed-8cbe-9fc7fc0231ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92818, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "摆脱", "is_correct": true, "explanation": "正确。“用工作摆脱了难过的心情”指通过工作走出悲伤。"}, {"text": "测量", "is_correct": false, "explanation": "语义：“测量”指用工具量度，“测量难过的心情”说不通。"}, {"text": "下载", "is_correct": false, "explanation": "搭配：“下载”的对象是文件、软件，“心情”不能下载。"}, {"text": "拍卖", "is_correct": false, "explanation": "语义：“拍卖”指竞价卖出物品，不能用于“难过的心情”。"}], "explanations": {"摆脱": "正确。“用工作摆脱了难过的心情”指通过工作走出悲伤。", "测量": "语义：“测量”指用工具量度，“测量难过的心情”说不通。", "下载": "搭配：“下载”的对象是文件、软件，“心情”不能下载。", "拍卖": "语义：“拍卖”指竞价卖出物品，不能用于“难过的心情”。"}, "sentence_index": 6, "correct_answer": "摆脱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他终于摆脱了新的阶段。", "explanation": "这里应该用〈进入〉。“摆脱”指脱离不利状况，进入新阶段要说“进入”。"}, {"text": "大家都在摆脱这个假期。", "explanation": "这里应该用〈享受〉。“摆脱”指脱离不利状况，享受假期的快乐要说“享受”。"}, {"text": "我们摆脱了这份快乐。", "explanation": "这里应该用〈分享〉。“摆脱”指脱离不利状况，与人共享快乐要说“分享”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '093b16e4-030e-40ed-8cbe-9fc7fc0231ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92818, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个家庭终于被摆脱了困境。", "corrected_sentence": "这个家庭终于摆脱了困境。", "error_description": "错误在被字句：“家庭”是自己脱离困境，不能说“被摆脱”。应说“终于摆脱了困境”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '093b16e4-030e-40ed-8cbe-9fc7fc0231ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92818, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们正在摆脱过这种不利的状态。", "corrected_sentence": "我们正在摆脱这种不利的状态。", "error_description": "错误在时体：“正在”表示动作进行中，“过”表示已经经历，二者不能同时用于同一动词。应说“正在摆脱这种不利的状态”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '093b16e4-030e-40ed-8cbe-9fc7fc0231ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
