INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92819, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "明明是清清楚楚摆在眼前，可是别人不这样说。", "primary_collocate": null, "pronunciation": "míng míng", "ipa": "miŋ˧˥ miŋ˧˥", "syllable_count": 2, "sentences": [{"text": "明明是红灯，那辆车却开过去了。", "target_word": "明明", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事明明是他做的，他却说不知道。", "target_word": "明明", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "明明是我先到的，他们却说是他。", "target_word": "明明", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "明明看见他进来了，大家都说没人。", "target_word": "明明", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地上明明有水，你怎么说没有？", "target_word": "明明", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我明明说过这件事，你怎么忘了？", "target_word": "明明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明明是白色的，他非说是黄色。", "target_word": "明明", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "门明明开着，他却说关着。", "target_word": "明明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书明明在这儿，怎么找不到了？", "target_word": "明明", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "明明是他的错，老师却批评了我。", "target_word": "明明", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "事情清清楚楚摆在眼前，别人却说得不一样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8435ceb-555a-41a7-9e7c-23c1661a3389') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92819, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "忽然", "is_correct": false, "explanation": "语义：忽然表示突然发生，不能用来判断“红灯”这一事实，与句意不合。"}, {"text": "很快", "is_correct": false, "explanation": "搭配：“很快”修饰动作的快慢，不修饰“是红灯”这样的判断。"}, {"text": "马上", "is_correct": false, "explanation": "语义：马上表示即将发生，不能用来说明已经摆在眼前的红灯，与句意不合。"}, {"text": "明明", "is_correct": true, "explanation": "正确。明明表示红灯清清楚楚摆在那里，与后面“那辆车却开过去了”形成对比。"}], "explanations": {"忽然": "语义：忽然表示突然发生，不能用来判断“红灯”这一事实，与句意不合。", "很快": "搭配：“很快”修饰动作的快慢，不修饰“是红灯”这样的判断。", "马上": "语义：马上表示即将发生，不能用来说明已经摆在眼前的红灯，与句意不合。", "明明": "正确。明明表示红灯清清楚楚摆在那里，与后面“那辆车却开过去了”形成对比。"}, "sentence_index": 0, "correct_answer": "明明"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明天明明会下雨，大家却说不会。", "explanation": "这里应该用〈估计〉。明明要求事实已清清楚楚摆在眼前，不能用于尚未发生的将来；对将来的推测应用〈估计〉。"}, {"text": "明明据说这件事是他做的，他却说不知道。", "explanation": "这里应去掉〈明明〉和〈据说〉，改用〈听说〉。明明表示说话人确认的事实，与“据说”这种转述传闻相矛盾。"}, {"text": "我希望他明明能来参加。", "explanation": "这里应该用〈但愿〉。明明表示事实清清楚楚，不用于表示尚未实现的愿望；表达希望要用〈但愿〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36687aa2-dba4-4cb7-b01b-12ba6f663fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92819, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "特意", "is_correct": false, "explanation": "语义：特意表示有意做某事，不能用来说明颜色的状态，与句意不合。"}, {"text": "顺便", "is_correct": false, "explanation": "语义：顺便表示在做别的事时附带做某事，不能用来描述东西本身的颜色，与句意不合。"}, {"text": "偶尔", "is_correct": false, "explanation": "搭配：“偶尔”说的是情况时有时无，不能用来描述“是白色的”这样稳定的状态。"}, {"text": "明明", "is_correct": true, "explanation": "正确。明明表示东西清清楚楚是白色的，与后面“他非说是黄色”形成对比。"}], "explanations": {"特意": "语义：特意表示有意做某事，不能用来说明颜色的状态，与句意不合。", "顺便": "语义：顺便表示在做别的事时附带做某事，不能用来描述东西本身的颜色，与句意不合。", "偶尔": "搭配：“偶尔”说的是情况时有时无，不能用来描述“是白色的”这样稳定的状态。", "明明": "正确。明明表示东西清清楚楚是白色的，与后面“他非说是黄色”形成对比。"}, "sentence_index": 6, "correct_answer": "明明"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "听说他已经结婚了，明明他已经结婚了。", "explanation": "这句把明明用在转述的传闻上。明明表示说话人确认的事实，前半句却是转述，语气互相矛盾，此处不这么用。"}, {"text": "也许他忘了，明明他忘了。", "explanation": "明明表示说话人确认的事实，与前面表示可能性的语气相矛盾，此处不这么用。"}, {"text": "他似乎有点不舒服，他明明有点不舒服。", "explanation": "明明表示说话人确认的事实，与前面的“似乎”（表示不确定）语气矛盾，此处不这么用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36687aa2-dba4-4cb7-b01b-12ba6f663fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92819, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明明了是他的错，他却不承认。", "corrected_sentence": "明明是他的错，他却不承认。", "error_description": "错误在“明明”后面。“明明”是副词，后面不能加“了”，应说“明明是他的错”，不能说“明明了是他的错”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36687aa2-dba4-4cb7-b01b-12ba6f663fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92819, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明明地是红色的，他非说是蓝色。", "corrected_sentence": "明明是红色的，他非说是蓝色。", "error_description": "错误在“明明”后面。“明明”是副词，后面不加“地”，应说“明明是红色的”，不能说“明明地是红色的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36687aa2-dba4-4cb7-b01b-12ba6f663fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92821, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba1235cd-9732-42dd-b546-8574580fca1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92821, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba1235cd-9732-42dd-b546-8574580fca1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92821, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "教练是教大家学跑步、打球的人。", "primary_collocate": null, "pronunciation": "jiào liàn", "ipa": "tɕjɑʊ˥˩ ljɛn˥˩", "syllable_count": 2, "sentences": [{"text": "教练带我们在操场上跑步。", "target_word": "教练", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "篮球教练让大家多练习投篮。", "target_word": "教练", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教练说今天要练习打球。", "target_word": "教练", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的教练很严格。", "target_word": "教练", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教练教孩子们怎么踢足球。", "target_word": "教练", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教练站在场边，大声喊着。", "target_word": "教练", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教练给大家发了新球衣。", "target_word": "教练", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的足球教练是一位年轻人。", "target_word": "教练", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教练让我们每天跑五公里。", "target_word": "教练", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下课后，教练还陪我练了一会儿球。", "target_word": "教练", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "教练员", "label": "复合词"}], "register": "中性", "sense_fingerprint": "名词，带领大家练习跑步、打球等运动的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a80d1613-ad74-4c77-841d-4a5ae0d1a4c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92821, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "教练", "is_correct": true, "explanation": "正确：“教练”是带领大家练习跑步、打球的人，与“带我们在操场上跑步”相符。"}, {"text": "司机", "is_correct": false, "explanation": "语义：司机不带人在操场上跑步，句子说不通。"}, {"text": "裁缝", "is_correct": false, "explanation": "语义：裁缝不带人在操场上跑步，句子说不通。"}, {"text": "会计", "is_correct": false, "explanation": "语义：会计不带人在操场上跑步，句子说不通。"}], "explanations": {"教练": "正确：“教练”是带领大家练习跑步、打球的人，与“带我们在操场上跑步”相符。", "司机": "语义：司机不带人在操场上跑步，句子说不通。", "裁缝": "语义：裁缝不带人在操场上跑步，句子说不通。", "会计": "语义：会计不带人在操场上跑步，句子说不通。"}, "sentence_index": 0, "correct_answer": "教练"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "比赛中，教练判了我们犯规。", "explanation": "这里应该用〈裁判〉。教练是教大家学跑步、打球的人，判罚犯规的是裁判。"}, {"text": "我们请了一头教练。", "explanation": "这里应该用〈位〉或〈名〉。“头”用于牲畜，指人要用“位”或“名”。"}, {"text": "饭店里的教练每天给客人做菜。", "explanation": "这里应该用〈厨师〉。教练是教大家学跑步、打球的人，在饭店给客人做菜的是厨师。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba1235cd-9732-42dd-b546-8574580fca1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92821, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "教练", "is_correct": true, "explanation": "正确：“教练”是带领大家练习运动的人，给大家发球衣与此相符。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：乘客不负责给大家发球衣，句子说不通。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师不负责给大家发球衣，句子说不通。"}, {"text": "车", "is_correct": false, "explanation": "搭配：“发”的施事要是人，车不能给大家发球衣。"}], "explanations": {"教练": "正确：“教练”是带领大家练习运动的人，给大家发球衣与此相符。", "乘客": "语义：乘客不负责给大家发球衣，句子说不通。", "厨师": "语义：厨师不负责给大家发球衣，句子说不通。", "车": "搭配：“发”的施事要是人，车不能给大家发球衣。"}, "sentence_index": 6, "correct_answer": "教练"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "教练每天给病人打针。", "explanation": "这里应该用〈护士〉。教练是教大家学跑步、打球的人，给病人打针要用“护士”。"}, {"text": "我们请了一把教练。", "explanation": "这里应该用〈位〉或〈名〉。“把”用于有柄的东西，指人要用“位”或“名”。"}, {"text": "服装公司的教练每天画新衣服的样子。", "explanation": "这里应该用〈设计师〉。教练是教大家学跑步、打球的人，在服装公司设计衣服的是设计师。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba1235cd-9732-42dd-b546-8574580fca1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92821, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一教练每天都陪我练习。", "corrected_sentence": "一位教练每天都陪我练习。", "error_description": "错误：数词“一”与名词之间缺少量词。正确说法是“一位教练”，不说“一教练”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba1235cd-9732-42dd-b546-8574580fca1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92821, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她跑步教练，每天都起得很早。", "corrected_sentence": "她是跑步教练，每天都起得很早。", "error_description": "错误：名词谓语前缺少“是”。正确说法是“她是跑步教练”，不说“她跑步教练”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba1235cd-9732-42dd-b546-8574580fca1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
