INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92822, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba1235cd-9732-42dd-b546-8574580fca1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92822, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "教授运动技术或驾驶技术的人。", "primary_collocate": null, "pronunciation": "jiào liàn", "ipa": "tɕjɑʊ˥˩ ljɛn˥˩", "syllable_count": 2, "sentences": [{"text": "驾校的教练教我怎么开车。", "target_word": "教练", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教练让我慢慢踩刹车。", "target_word": "教练", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的游泳教练很有经验。", "target_word": "教练", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位教练教过很多学生。", "target_word": "教练", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教练说我今天开得不错。", "target_word": "教练", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在驾校当教练已经十年了。", "target_word": "教练", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "驾校教练坐在我旁边，看着前面的路。", "target_word": "教练", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想请一位健身教练。", "target_word": "教练", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教练告诉我动作要慢一点。", "target_word": "教练", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是滑雪教练，每年冬天都很忙。", "target_word": "教练", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "教练员", "label": "复合词"}], "register": "中性", "sense_fingerprint": "名词，教运动或开车技术的人，如驾校教练、游泳教练", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a80d1613-ad74-4c77-841d-4a5ae0d1a4c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92822, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "教练", "is_correct": true, "explanation": "正确：“教练”指教开车或运动技术的人，与“驾校的”“教我怎么开车”相符。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：乘客不教人开车，“驾校的乘客教我怎么开车”说不通。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师不教人开车，句子说不通。"}, {"text": "教授", "is_correct": false, "explanation": "语域：“教授”是学术职称，驾校里不这样称呼，用在这里不自然。"}], "explanations": {"教练": "正确：“教练”指教开车或运动技术的人，与“驾校的”“教我怎么开车”相符。", "乘客": "语义：乘客不教人开车，“驾校的乘客教我怎么开车”说不通。", "厨师": "语义：厨师不教人开车，句子说不通。", "教授": "语域：“教授”是学术职称，驾校里不这样称呼，用在这里不自然。"}, "sentence_index": 0, "correct_answer": "教练"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司请了一位教练，专门负责做财务报表。", "explanation": "这里应该用〈会计〉。教练只指教运动或驾驶的人，负责做财务报表要用“会计”。"}, {"text": "我请了一只教练。", "explanation": "这里应该用〈位〉或〈名〉。“只”用于动物或成对器官中的一个，指人要用“位”或“名”。"}, {"text": "理发店里的教练给我剪了头发。", "explanation": "这里应该用〈理发师〉。教练只指教运动或驾驶的人，在理发店给人剪头发的是理发师。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba1235cd-9732-42dd-b546-8574580fca1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92822, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "教练", "is_correct": true, "explanation": "正确：“教练”是教开车的人，坐在旁边看着前面的路与此相符。"}, {"text": "行人", "is_correct": false, "explanation": "语义：行人不会坐在我旁边的座位上看路，句子说不通。"}, {"text": "裁缝", "is_correct": false, "explanation": "语义：裁缝与坐在车里看路没有关系，句子说不通。"}, {"text": "车", "is_correct": false, "explanation": "搭配：“坐”的主语要是人，车不能坐在我旁边。"}], "explanations": {"教练": "正确：“教练”是教开车的人，坐在旁边看着前面的路与此相符。", "行人": "语义：行人不会坐在我旁边的座位上看路，句子说不通。", "裁缝": "语义：裁缝与坐在车里看路没有关系，句子说不通。", "车": "搭配：“坐”的主语要是人，车不能坐在我旁边。"}, "sentence_index": 6, "correct_answer": "教练"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的比赛，教练判了我们犯规。", "explanation": "这里应该用〈裁判〉。教练是教运动技术的人，判定比赛犯规的是裁判。"}, {"text": "我想请一辆教练。", "explanation": "这里应该用〈位〉或〈名〉。“辆”用于车辆，指人要用“位”或“名”。"}, {"text": "我在大学读研究生，教练每周都给我指导论文。", "explanation": "这里应该用〈导师〉。教练只指教运动或驾驶的人，在大学指导论文的是导师。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba1235cd-9732-42dd-b546-8574580fca1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92822, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我网球教练很有耐心。", "corrected_sentence": "我的网球教练很有耐心。", "error_description": "错误：“我”修饰“教练”时要加“的”。正确说法是“我的网球教练”，不说“我网球教练”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba1235cd-9732-42dd-b546-8574580fca1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92822, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他健身教练，每天都很早起床。", "corrected_sentence": "他是健身教练，每天都很早起床。", "error_description": "错误：名词谓语前缺少“是”。正确说法是“他是健身教练”，不说“他健身教练”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba1235cd-9732-42dd-b546-8574580fca1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92823, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f5f1d31-ca2a-49c7-8237-0c9588c31fa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92823, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f5f1d31-ca2a-49c7-8237-0c9588c31fa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92823, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "有作用是能帮上忙，有用处。", "primary_collocate": null, "pronunciation": "yǒu zuò yòng", "ipa": "jou˨˩˦ tsuo˥˩ jʊŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这把伞今天很有作用。", "target_word": "有作用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本词典对学习汉语有作用。", "target_word": "有作用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多一个人帮忙，总是有作用的。", "target_word": "有作用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些旧书对小朋友还有作用。", "target_word": "有作用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你带的地图在山里真有作用。", "target_word": "有作用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的经验对我们有作用。", "target_word": "有作用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小工具在家里很有作用。", "target_word": "有作用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的建议对我们解决问题很有作用。", "target_word": "有作用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些笔记对考试很有作用。", "target_word": "有作用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧手机给孩子玩，也有作用。", "target_word": "有作用", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "没有作用", "label": "否定式"}], "register": "中性", "sense_fingerprint": "东西或人能帮上忙，有用处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '964c90de-6e63-4a08-9795-75c3d131a85e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92823, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有作用", "is_correct": true, "explanation": "“有作用”表示能帮上忙、有用处，与“很”搭配，符合“这把伞今天很___”的语境。"}, {"text": "生气", "is_correct": false, "explanation": "语义：伞不会生气，“生气”的主语须是有情绪的人，与句中的“伞”不搭。"}, {"text": "担心", "is_correct": false, "explanation": "语义：“担心”指有意识的人对事情的忧虑，伞不会担心，句子读来不通。"}, {"text": "同意", "is_correct": false, "explanation": "搭配：“同意”需要有意愿的人作主语，不能用“伞”作主语。"}], "explanations": {"有作用": "“有作用”表示能帮上忙、有用处，与“很”搭配，符合“这把伞今天很___”的语境。", "生气": "语义：伞不会生气，“生气”的主语须是有情绪的人，与句中的“伞”不搭。", "担心": "语义：“担心”指有意识的人对事情的忧虑，伞不会担心，句子读来不通。", "同意": "搭配：“同意”需要有意愿的人作主语，不能用“伞”作主语。"}, "sentence_index": 0, "correct_answer": "有作用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个小朋友很有作用，见了老师从来不打招呼。", "explanation": "这里应该用〈有礼貌〉。形容人举止得体要用“有礼貌”，“有作用”说的是事物或办法起的实际帮助。"}, {"text": "这个新来的人很有作用，连电脑都不会开。", "explanation": "这里应该用〈有能力〉。形容人能干要用“有能力”，“有作用”说的是事物或办法起的实际帮助。"}, {"text": "他对孩子很有作用，一生气就大声吼。", "explanation": "这里应该用〈有耐心〉。形容人对别人是否耐心要用“有耐心”，“有作用”不指待人的态度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f5f1d31-ca2a-49c7-8237-0c9588c31fa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92823, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有作用", "is_correct": true, "explanation": "“有作用”表示能帮上忙、有用处，与“很”搭配，符合“这个小工具在家里很___”的语境。"}, {"text": "喜欢", "is_correct": false, "explanation": "语义：小工具没有情感，不会“喜欢”家里的环境，句子读来不通。"}, {"text": "害怕", "is_correct": false, "explanation": "语义：“害怕”指有感觉的人对危险的恐惧，工具不会害怕，句子不成立。"}, {"text": "抱怨", "is_correct": false, "explanation": "搭配：“抱怨”的主语须是能说话、有意识的人，不能用于“小工具”。"}], "explanations": {"有作用": "“有作用”表示能帮上忙、有用处，与“很”搭配，符合“这个小工具在家里很___”的语境。", "喜欢": "语义：小工具没有情感，不会“喜欢”家里的环境，句子读来不通。", "害怕": "语义：“害怕”指有感觉的人对危险的恐惧，工具不会害怕，句子不成立。", "抱怨": "搭配：“抱怨”的主语须是能说话、有意识的人，不能用于“小工具”。"}, "sentence_index": 6, "correct_answer": "有作用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位画家在城里很有作用，大家都知道他。", "explanation": "这里应该用〈有名〉。描述人的名气要用“有名”，“有作用”说的是事物或办法起的效用。"}, {"text": "他很有作用，每个月的房租都交不起。", "explanation": "这里应该用〈有钱〉。描述财富要用“有钱”，“有作用”不指财富状况。"}, {"text": "这位厨师很有作用，连鸡蛋都煎不好。", "explanation": "这里应该用〈有本事〉。形容人能力强要用“有本事”，“有作用”说的是事物或办法起的实际帮助。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f5f1d31-ca2a-49c7-8237-0c9588c31fa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92823, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把旧雨伞在路上很不有作用。", "corrected_sentence": "这把旧雨伞在路上很有作用。", "error_description": "错误：“很不有作用”；正确：“很有作用”。“有作用”是肯定形式，前面不能加“不”，否定要用“没有作用”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f5f1d31-ca2a-49c7-8237-0c9588c31fa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92823, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台旧收音机在厨房里很有作用极了。", "corrected_sentence": "这台旧收音机在厨房里很有作用。", "error_description": "错误：“很有作用极了”；正确：“很有作用”。“很”和“极了”都表示程度，不能同时修饰“有作用”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f5f1d31-ca2a-49c7-8237-0c9588c31fa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
