INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92825, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "时点是时间里的某一个点。", "primary_collocate": null, "pronunciation": "shí diǎn", "ipa": "ʂɨ³⁵ tjɛn²¹⁴", "syllable_count": 2, "sentences": [{"text": "请你记下手机坏掉的时点。", "target_word": "时点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个时点的天气和昨天不同。", "target_word": "时点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想知道火车到站的确切时点。", "target_word": "时点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个时点之间隔了一年。", "target_word": "时点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过了规定的时点，就不能再交作业了。", "target_word": "时点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生问我：疼是从哪个时点开始的？", "target_word": "时点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个时点大家都在睡觉。", "target_word": "时点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛的结束时点是九点半。", "target_word": "时点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把今天中午当作统计的时点。", "target_word": "时点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间线上每个时点都有一件事。", "target_word": "时点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "时间里的一个点，用来记录或比较事情发生的时刻", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7018439-109a-4c8c-8d0d-ce7e3899b663') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92825, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "时点", "is_correct": true, "explanation": "正确：时点（shí diǎn）指时间里用来记录或比较的某一个时刻。"}, {"text": "试点", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，试点指先选少量地方做试验。"}, {"text": "视点", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，视点指观察问题的角度。"}, {"text": "失点", "is_correct": false, "explanation": "shī（第一声）与 shí（第二声）声调不同，失点指比赛中被对方得分。"}], "explanations": {"时点": "正确：时点（shí diǎn）指时间里用来记录或比较的某一个时刻。", "试点": "shì（第四声）与 shí（第二声）声调不同，试点指先选少量地方做试验。", "视点": "shì（第四声）与 shí（第二声）声调不同，视点指观察问题的角度。", "失点": "shī（第一声）与 shí（第二声）声调不同，失点指比赛中被对方得分。"}, "sentence_index": null, "correct_answer": "时点"}, "level_3": {"options": [{"text": "时点", "is_correct": true, "explanation": "正确：「时点」指记录事情发生的具体时刻，此处指手机坏掉的那个时刻。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：记下的是手机坏掉的时刻，不是它的颜色，「颜色」与“坏掉”的记录无关。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：手机坏掉不说“味道”，「味道」不能与「坏掉」搭配。"}, {"text": "形状", "is_correct": false, "explanation": "语义：记录的重点是事件发生的时刻，「形状」与“记下…时”的记录目的不符。"}], "explanations": {"时点": "正确：「时点」指记录事情发生的具体时刻，此处指手机坏掉的那个时刻。", "颜色": "语义：记下的是手机坏掉的时刻，不是它的颜色，「颜色」与“坏掉”的记录无关。", "味道": "搭配：手机坏掉不说“味道”，「味道」不能与「坏掉」搭配。", "形状": "语义：记录的重点是事件发生的时刻，「形状」与“记下…时”的记录目的不符。"}, "sentence_index": 0, "correct_answer": "时点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个时点缩短了半个小时。", "explanation": "这里应该用〈时长〉。时点是某一个时刻，本身不能缩短；缩短的是时长。"}, {"text": "这几年时点过得真快。", "explanation": "这里应该用〈时间〉。「时间过得快」指时间流逝，时点是某一时刻，不会流逝。"}, {"text": "少年时点很快乐。", "explanation": "这里应该用〈时期〉。少年指一段人生阶段，应用〈时期〉；时点只指一个时刻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '093b16e4-030e-40ed-8cbe-9fc7fc0231ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92825, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "时点", "is_correct": true, "explanation": "正确：「时点」指时间上的某一个点，此处指大家都在睡觉的那一刻。"}, {"text": "声音", "is_correct": false, "explanation": "语义：「声音」不是时间，“这个声音大家都在睡觉”无法成立。"}, {"text": "体重", "is_correct": false, "explanation": "语义：「体重」不能指一个时间点，句子无法理解。"}, {"text": "亮度", "is_correct": false, "explanation": "搭配：「亮度」多用于光线、屏幕，不能与“大家都在睡觉”搭配。"}], "explanations": {"时点": "正确：「时点」指时间上的某一个点，此处指大家都在睡觉的那一刻。", "声音": "语义：「声音」不是时间，“这个声音大家都在睡觉”无法成立。", "体重": "语义：「体重」不能指一个时间点，句子无法理解。", "亮度": "搭配：「亮度」多用于光线、屏幕，不能与“大家都在睡觉”搭配。"}, "sentence_index": 6, "correct_answer": "时点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次会议的时点持续了两小时。", "explanation": "这里应该用〈时段〉。时段指一段时间，可以持续；时点只是一个时刻，不能持续两小时。"}, {"text": "这场比赛的时点太长了，大家都累了。", "explanation": "这里应该用〈时长〉。时点是某一个时刻，没有长短；说比赛持续多久要用〈时长〉。"}, {"text": "我们度过了美好的时点。", "explanation": "这里应该用〈时光〉。「度过」的是一段时光；时点是一个时刻，不能被度过。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '093b16e4-030e-40ed-8cbe-9fc7fc0231ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92825, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他记下了一条时点，就是八点半。", "corrected_sentence": "他记下了一个时点，就是八点半。", "error_description": "错误：「时点」是一个时刻，量词应用「个」；「条」用于长条形的事物，不能修饰时点。正确应为「一个时点」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '093b16e4-030e-40ed-8cbe-9fc7fc0231ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92825, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些时点们都标在图上了。", "corrected_sentence": "这些时点都标在图上了。", "error_description": "错误：「时点」是表示时刻的名词，不指人，不能加「们」表示复数。正确应为「这些时点」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '093b16e4-030e-40ed-8cbe-9fc7fc0231ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92827, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无意义", "is_correct": true, "explanation": "无意义：与“有意义”构成反义关系，指做这件事没有价值、没有好处。"}, {"text": "复杂", "is_correct": false, "explanation": "复杂：形容事情或结构繁多，与“有意义”没有反义关系。"}, {"text": "漂亮", "is_correct": false, "explanation": "漂亮：形容外貌或事物好看，与“有意义”没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "安静：形容环境或人不吵闹，与“有意义”没有反义关系。"}], "correct_answer": "无意义", "explanations": {"无意义": "无意义：与“有意义”构成反义关系，指做这件事没有价值、没有好处。", "复杂": "复杂：形容事情或结构繁多，与“有意义”没有反义关系。", "漂亮": "漂亮：形容外貌或事物好看，与“有意义”没有反义关系。", "安静": "安静：形容环境或人不吵闹，与“有意义”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb7c6870-df9b-44cd-b239-97d633319a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92827, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无意义", "is_correct": true, "explanation": "无意义：与“有意义”构成反义关系，指做这件事没有价值、没有好处。"}, {"text": "干净", "is_correct": false, "explanation": "干净：形容清洁、没有脏物，与“有意义”没有反义关系。"}, {"text": "饱", "is_correct": false, "explanation": "饱：形容吃足或装满，与“有意义”没有反义关系。"}, {"text": "冰冷", "is_correct": false, "explanation": "冰冷：形容温度很低，与“有意义”没有反义关系。"}], "correct_answer": "无意义", "explanations": {"无意义": "无意义：与“有意义”构成反义关系，指做这件事没有价值、没有好处。", "干净": "干净：形容清洁、没有脏物，与“有意义”没有反义关系。", "饱": "饱：形容吃足或装满，与“有意义”没有反义关系。", "冰冷": "冰冷：形容温度很低，与“有意义”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb7c6870-df9b-44cd-b239-97d633319a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92827, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "有意义是做了这件事很值得，有好处。", "primary_collocate": null, "pronunciation": "yǒu yì yì", "ipa": "jou̯˨˩˦ i˥˩ i˥˩", "syllable_count": 3, "sentences": [{"text": "周末我们去山村教孩子画画，这件事很有意义。", "target_word": "有意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "帮助别人让我觉得生活很有意义。", "target_word": "有意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他觉得每天读书写字，过得很有意义。", "target_word": "有意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参加志愿活动对年轻人来说很有意义。", "target_word": "有意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然工作很累，但是我觉得做这件事有意义。", "target_word": "有意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把旧衣服送给山区的孩子，真有意义！", "target_word": "有意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你花时间陪爷爷聊天，这样做非常有意义。", "target_word": "有意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想做一件有意义的事，所以报名当志愿者。", "target_word": "有意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说，把钱用来帮助穷人才有意义。", "target_word": "有意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个暑假我们种了一百棵树，大家都觉得很有意义。", "target_word": "有意义", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "没有意义", "label": "否定式"}, {"form": "有意义的", "label": "定语形式"}, {"form": "有意義", "label": "繁体"}], "register": "中性", "sense_fingerprint": "做某事很值得、有好处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94ef46ac-c75d-4aa5-b593-6bca6ddab68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92827, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有意义", "is_correct": true, "explanation": "有意义：指这件事值得做、有好处，与句中“山村教画画”的语境相符。"}, {"text": "便宜", "is_correct": false, "explanation": "搭配：“便宜”用于价钱，不能用来形容一件事。"}, {"text": "陡峭", "is_correct": false, "explanation": "语义：“陡峭”形容地势，与“做这件事”的语境无关。"}, {"text": "高兴", "is_correct": false, "explanation": "搭配：“高兴”形容人的情绪，不能用来形容一件事。"}], "explanations": {"有意义": "有意义：指这件事值得做、有好处，与句中“山村教画画”的语境相符。", "便宜": "搭配：“便宜”用于价钱，不能用来形容一件事。", "陡峭": "语义：“陡峭”形容地势，与“做这件事”的语境无关。", "高兴": "搭配：“高兴”形容人的情绪，不能用来形容一件事。"}, "sentence_index": 0, "correct_answer": "有意义"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她长得很有意义，很多人都喜欢她。", "explanation": "这里应该用〈好看〉。有意义指做事值得、有好处，形容人的相貌要用好看。"}, {"text": "这台旧电脑很有意义，能卖不少钱。", "explanation": "这里应该用〈有价值〉。有意义侧重事情值得做，说东西能卖多少钱要用有价值。"}, {"text": "这把剪刀很有意义，可以剪纸。", "explanation": "这里应该用〈有用〉。有意义侧重事情值得做，说工具能派上用场要用有用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb7c6870-df9b-44cd-b239-97d633319a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
