INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92828, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "有价值、有重要含义的。", "primary_collocate": null, "pronunciation": "yǒu yì yì", "ipa": "jou̯˨˩˦ i˥˩ i˥˩", "syllable_count": 3, "sentences": [{"text": "这张老照片对我们全家人来说很有意义。", "target_word": "有意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十八岁生日是一个很有意义的日子。", "target_word": "有意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的内容很有意义，值得再读一遍。", "target_word": "有意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个发现很有意义，科学家们都很高兴。", "target_word": "有意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话很有意义，我想了很久。", "target_word": "有意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一部有意义的电影，让人想到很多。", "target_word": "有意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说这个问题很有意义，大家可以讨论。", "target_word": "有意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥的名字很有意义，它记着一段历史。", "target_word": "有意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节日很有意义，人们要纪念过去的英雄。", "target_word": "有意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他送我的礼物不贵，但是很有意义。", "target_word": "有意义", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "没有意义", "label": "否定式"}, {"form": "有意义的", "label": "定语形式"}, {"form": "有意義", "label": "繁体"}], "register": "中性", "sense_fingerprint": "事物有价值、有重要含义", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94ef46ac-c75d-4aa5-b593-6bca6ddab68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92828, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有意义", "is_correct": true, "explanation": "有意义：指这张老照片对全家人有重要含义，与句中语境相符。"}, {"text": "陡峭", "is_correct": false, "explanation": "语义：“陡峭”形容地势，不能用来形容一张照片。"}, {"text": "高兴", "is_correct": false, "explanation": "搭配：“高兴”形容人的情绪，不能说照片“很高兴”。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”形容人或动物的身材，不能用来形容照片。"}], "explanations": {"有意义": "有意义：指这张老照片对全家人有重要含义，与句中语境相符。", "陡峭": "语义：“陡峭”形容地势，不能用来形容一张照片。", "高兴": "搭配：“高兴”形容人的情绪，不能说照片“很高兴”。", "瘦": "体貌：“瘦”形容人或动物的身材，不能用来形容照片。"}, "sentence_index": 0, "correct_answer": "有意义"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的身材很有意义，很多人都羡慕。", "explanation": "这里应该用〈魁梧〉。有意义指事物有价值、有重要含义，形容身材高大要用魁梧。"}, {"text": "她的头发很有意义，又黑又长。", "explanation": "这里应该用〈乌黑〉。有意义指事物有价值、有重要含义，形容头发的颜色要用乌黑。"}, {"text": "他家很有意义，孩子都上了私立学校。", "explanation": "这里应该用〈有钱〉。有意义指事物有价值或重要含义，说家庭的经济状况要用有钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb7c6870-df9b-44cd-b239-97d633319a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92828, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有意义", "is_correct": true, "explanation": "有意义：指这个问题值得讨论、有重要含义，与句中语境相符。"}, {"text": "凉", "is_correct": false, "explanation": "语义：“凉”形容温度，不能用来形容一个问题。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：“矮”形容身高或高度，不能用来形容一个问题。"}, {"text": "饱", "is_correct": false, "explanation": "语义：“饱”形容吃足或装满，与“值得讨论”的语境不合。"}], "explanations": {"有意义": "有意义：指这个问题值得讨论、有重要含义，与句中语境相符。", "凉": "语义：“凉”形容温度，不能用来形容一个问题。", "矮": "体貌：“矮”形容身高或高度，不能用来形容一个问题。", "饱": "语义：“饱”形容吃足或装满，与“值得讨论”的语境不合。"}, "sentence_index": 6, "correct_answer": "有意义"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的天气很有意义，风和日丽。", "explanation": "这里应该用〈晴朗〉。有意义指事物有价值、有重要含义，形容天气要用晴朗。"}, {"text": "这种药很有意义，吃了就好。", "explanation": "这里应该用〈有效〉。有意义指事物有价值或重要含义，说药物或方法起作用要用有效。"}, {"text": "这碗汤很有意义，又鲜又香。", "explanation": "这里应该用〈鲜美〉。有意义指事物有价值、有重要含义，形容汤的味道要用鲜美。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb7c6870-df9b-44cd-b239-97d633319a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92828, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一个有意义礼物。", "corrected_sentence": "这是一个有意义的礼物。", "error_description": "错误：“有意义礼物”；正确：“有意义的礼物”。“有意义”修饰“礼物”时，中间要加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb7c6870-df9b-44cd-b239-97d633319a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92828, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一次很有意义实验，大家都很认真。", "corrected_sentence": "这是一次很有意义的实验，大家都很认真。", "error_description": "错误：“很有意义实验”；正确：“很有意义的实验”。“有意义”修饰名词“实验”时，中间要加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb7c6870-df9b-44cd-b239-97d633319a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
