INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92829, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "步是走路时，一只脚迈出去的一下。", "primary_collocate": null, "pronunciation": "bù", "ipa": "pu˥˩", "syllable_count": 1, "sentences": [{"text": "他向前走了一步。", "target_word": "步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请往后退一步。", "target_word": "步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子走了三步就摔倒了。", "target_word": "步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "再走十步，就到门口了。", "target_word": "步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他累得一步也不想走了。", "target_word": "步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山顶离这里还有一百步。", "target_word": "步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人慢慢地走了两步。", "target_word": "步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生建议他每天至少走一万步。", "target_word": "步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请向左走两步。", "target_word": "步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每走一步，地板都响一下。", "target_word": "步", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "脚步", "label": "复合词"}, {"form": "步子", "label": "复合词"}], "register": "中性", "sense_fingerprint": "量词，计算走路时迈出一只脚的次数，如一步、两步", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a80d1613-ad74-4c77-841d-4a5ae0d1a4c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92829, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "步", "is_correct": true, "explanation": "步（bù，第四声）指走路时一只脚迈出去的一下，是本题正确答案。"}, {"text": "补", "is_correct": false, "explanation": "bǔ（第三声）与 bù（第四声）声调不同，意思是补充、修补。"}, {"text": "铺", "is_correct": false, "explanation": "pù 与 bù 声母不同（p 与 b），意思是店铺，或铺设。"}, {"text": "木", "is_correct": false, "explanation": "mù 与 bù 声母不同（m 与 b），意思是树木。"}, {"text": "度", "is_correct": false, "explanation": "dù 与 bù 声母不同（d 与 b），意思是程度、度数。"}, {"text": "墓", "is_correct": false, "explanation": "mù 与 bù 声母不同（m 与 b），意思是坟墓。"}], "explanations": {"步": "步（bù，第四声）指走路时一只脚迈出去的一下，是本题正确答案。", "补": "bǔ（第三声）与 bù（第四声）声调不同，意思是补充、修补。", "铺": "pù 与 bù 声母不同（p 与 b），意思是店铺，或铺设。", "木": "mù 与 bù 声母不同（m 与 b），意思是树木。", "度": "dù 与 bù 声母不同（d 与 b），意思是程度、度数。", "墓": "mù 与 bù 声母不同（m 与 b），意思是坟墓。"}, "sentence_index": null, "correct_answer": "步"}, "level_3": {"options": [{"text": "步", "is_correct": true, "explanation": "正确：“步”计量走路时迈出一只脚的动作，与“向前走了”相符。"}, {"text": "只", "is_correct": false, "explanation": "搭配：“只”用于某些动物或成对器官中的一个，不能计量走路的动作。"}, {"text": "条", "is_correct": false, "explanation": "语义：“条”计量细长的东西，“向前走了一条”说不通。"}, {"text": "脚", "is_correct": false, "explanation": "语义：“脚”计量踢、踹等动作，不能计量迈步。"}], "explanations": {"步": "正确：“步”计量走路时迈出一只脚的动作，与“向前走了”相符。", "只": "搭配：“只”用于某些动物或成对器官中的一个，不能计量走路的动作。", "条": "语义：“条”计量细长的东西，“向前走了一条”说不通。", "脚": "语义：“脚”计量踢、踹等动作，不能计量迈步。"}, "sentence_index": 0, "correct_answer": "步"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他敲了三步门。", "explanation": "这里应该用〈下〉。量词“步”计量走路时迈出一只脚的动作，敲门要用“下”。"}, {"text": "他读了三步课文。", "explanation": "这里应该用〈遍〉。“步”只计量迈步的动作，从头到尾读一次课文要用“遍”。"}, {"text": "他给我打了三步电话。", "explanation": "这里应该用〈通〉。“步”只计量迈步的动作，打电话要用“通”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba1235cd-9732-42dd-b546-8574580fca1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92829, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "步", "is_correct": true, "explanation": "步（bù，第四声）指走路时一只脚迈出去的一下，是本题正确答案。"}, {"text": "捕", "is_correct": false, "explanation": "bǔ（第三声）与 bù（第四声）声调不同，意思是捕捉。"}, {"text": "瀑", "is_correct": false, "explanation": "pù 与 bù 声母不同（p 与 b），意思是瀑布。"}, {"text": "目", "is_correct": false, "explanation": "mù 与 bù 声母不同（m 与 b），意思是眼睛，也指目标。"}, {"text": "付", "is_correct": false, "explanation": "fù 与 bù 声母不同（f 与 b），意思是支付、交付。"}], "explanations": {"步": "步（bù，第四声）指走路时一只脚迈出去的一下，是本题正确答案。", "捕": "bǔ（第三声）与 bù（第四声）声调不同，意思是捕捉。", "瀑": "pù 与 bù 声母不同（p 与 b），意思是瀑布。", "目": "mù 与 bù 声母不同（m 与 b），意思是眼睛，也指目标。", "付": "fù 与 bù 声母不同（f 与 b），意思是支付、交付。"}, "sentence_index": null, "correct_answer": "步"}, "level_3": {"options": [{"text": "步", "is_correct": true, "explanation": "正确：“步”计量走路时迈出的一下，与“走了两”相符。"}, {"text": "把", "is_correct": false, "explanation": "搭配：“把”计量有柄的东西，不能计量“走”的动作。"}, {"text": "座", "is_correct": false, "explanation": "语义：“座”计量山、楼等大型固定的东西，“走了两座”说不通。"}, {"text": "尺", "is_correct": false, "explanation": "语义：“尺”是长度单位，不计量走路的动作，“走了两尺”不通。"}], "explanations": {"步": "正确：“步”计量走路时迈出的一下，与“走了两”相符。", "把": "搭配：“把”计量有柄的东西，不能计量“走”的动作。", "座": "语义：“座”计量山、楼等大型固定的东西，“走了两座”说不通。", "尺": "语义：“尺”是长度单位，不计量走路的动作，“走了两尺”不通。"}, "sentence_index": 6, "correct_answer": "步"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我去过三步北京。", "explanation": "这里应该用〈次〉。量词“步”计量迈步的动作，去某地的次数要用“次”。"}, {"text": "我昨天去了一步超市。", "explanation": "这里应该用〈趟〉。“步”只计量迈步的动作，往返去一个地方要用“趟”。"}, {"text": "他喝了三步茶。", "explanation": "这里应该用〈杯〉。“步”计量迈步的动作，喝茶要用“杯”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba1235cd-9732-42dd-b546-8574580fca1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92829, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她往前迈了一条步，又停了下来。", "corrected_sentence": "她往前迈了一步，又停了下来。", "error_description": "错误：“步”计量迈步的动作，不能用量词“条”（“条”用于细长的东西）。正确说法是“迈了一步”，不说“迈了一条步”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba1235cd-9732-42dd-b546-8574580fca1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92829, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我往后退了二步，才看清楚。", "corrected_sentence": "我往后退了两步，才看清楚。", "error_description": "错误：量词“步”前的数词要用“两”，不用“二”。正确说法是“退了两步”，不说“退了二步”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba1235cd-9732-42dd-b546-8574580fca1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
