INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92831, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "本本就是本子，也可以说手提的小电脑。", "primary_collocate": null, "pronunciation": "běn běn", "ipa": "pən˨˩ pən˨˩", "syllable_count": 2, "sentences": [{"text": "我的本本坏了，今天要送去修。", "target_word": "本本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把本本带到教室，一边听课一边记。", "target_word": "本本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台本本很轻，出差带着不累。", "target_word": "本本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在本本上写了明天的计划。", "target_word": "本本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他打开本本，开始给朋友发邮件。", "target_word": "本本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给我买了一个新本本，封面是蓝色的。", "target_word": "本本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咖啡店里有人用本本上网工作。", "target_word": "本本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们把生词写在本本上。", "target_word": "本本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本本没电了，我得找个插座。", "target_word": "本本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个本本太小了，写不下这么多字。", "target_word": "本本", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "台", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "口语", "sense_fingerprint": "口语：本子，也指手提的小电脑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '964c90de-6e63-4a08-9795-75c3d131a85e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92831, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "本本", "is_correct": true, "explanation": "“本本”指本子或手提小电脑，可以送去修，与“坏了、送去修”搭配。"}, {"text": "面包", "is_correct": false, "explanation": "搭配：面包不能送去修，“修”只用于机器或器物。"}, {"text": "鸡蛋", "is_correct": false, "explanation": "搭配：鸡蛋不能送去修，“送去修”不适用于食物。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不是能送去修的物品，句子读来不通。"}], "explanations": {"本本": "“本本”指本子或手提小电脑，可以送去修，与“坏了、送去修”搭配。", "面包": "搭配：面包不能送去修，“修”只用于机器或器物。", "鸡蛋": "搭配：鸡蛋不能送去修，“送去修”不适用于食物。", "河流": "语义：河流不是能送去修的物品，句子读来不通。"}, "sentence_index": 0, "correct_answer": "本本"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一只本本，准备写日记。", "explanation": "这里应该用〈本〉或〈台〉。本子用“本”，手提电脑用“台”，“只”多用于动物或成对的东西，本子不用“只”。"}, {"text": "我买了一张本本，准备写日记。", "explanation": "这里应该用〈本〉。“张”用于纸、桌子等扁平物，本子要用“本”。"}, {"text": "我买了一把本本，准备写日记。", "explanation": "这里应该用〈本〉。“把”用于有柄的东西，本子要用“本”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f5f1d31-ca2a-49c7-8237-0c9588c31fa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92831, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "本本", "is_correct": true, "explanation": "“本本”指手提小电脑，可以用来上网工作，符合句意。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：咖啡不能用来上网，“用……上网”的工具须是电子设备。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不能用来上网工作，与“上网工作”不搭。"}, {"text": "报纸", "is_correct": false, "explanation": "搭配：报纸不能上网，“上网”的工具须是能连网的电子设备。"}], "explanations": {"本本": "“本本”指手提小电脑，可以用来上网工作，符合句意。", "咖啡": "语义：咖啡不能用来上网，“用……上网”的工具须是电子设备。", "冰箱": "语义：冰箱不能用来上网工作，与“上网工作”不搭。", "报纸": "搭配：报纸不能上网，“上网”的工具须是能连网的电子设备。"}, "sentence_index": 6, "correct_answer": "本本"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈给我一颗本本，让我记作业。", "explanation": "这里应该用〈本〉。“颗”用于颗粒状或圆形的小东西，本子要用“本”。"}, {"text": "老师发给我一支本本，让我记生词。", "explanation": "这里应该用〈本〉。“支”用于笔等细长的物件，本子要用“本”。"}, {"text": "哥哥送了我一头本本，让我记日记。", "explanation": "这里应该用〈本〉。“头”用于牛、猪等动物，本子要用“本”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f5f1d31-ca2a-49c7-8237-0c9588c31fa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92831, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了一只新本本，它很轻。", "corrected_sentence": "我买了一台新本本，它很轻。", "error_description": "错误：“一只新本本”，正确：“一台新本本”。指手提电脑时用量词“台”，“只”多用于动物或成对的东西，本子和电脑都不用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f5f1d31-ca2a-49c7-8237-0c9588c31fa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92831, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在本本画了一个圈。", "corrected_sentence": "他在本本上画了一个圈。", "error_description": "错误：“在本本画”，正确：“在本本上画”。表示在本子的表面上画，方位词“上”不能省略。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f5f1d31-ca2a-49c7-8237-0c9588c31fa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
