INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92832, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "（口语）本子；也指笔记本电脑。", "primary_collocate": null, "pronunciation": "běn běn", "ipa": "pən˨˩ pən˨˩", "syllable_count": 2, "sentences": [{"text": "请把你的本本拿出来，我们写作业。", "target_word": "本本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的本本里贴着很多照片。", "target_word": "本本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门前，我把本本放进了书包。", "target_word": "本本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司给每个同事发了一台本本。", "target_word": "本本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台本本的屏幕很大，看电影真舒服。", "target_word": "本本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在本本上画了一只小猫。", "target_word": "本本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的本本里记着朋友的电话号码。", "target_word": "本本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸用本本看新闻，还听音乐。", "target_word": "本本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥送了我一个本本做生日礼物。", "target_word": "本本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的本本太旧了，开机要五分钟。", "target_word": "本本", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "台", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "口语", "sense_fingerprint": "口语：本子；笔记本电脑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '964c90de-6e63-4a08-9795-75c3d131a85e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92832, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "本本", "is_correct": true, "explanation": "“本本”指本子，可以拿出来写作业，符合句意。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干不能用来写作业，“拿出来写作业”的物品应是学习用具。"}, {"text": "沙发", "is_correct": false, "explanation": "搭配：沙发太大，不能“拿出来”，“拿出来”只用于较小的物品。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞与“写作业”不搭，句子读来不通。"}], "explanations": {"本本": "“本本”指本子，可以拿出来写作业，符合句意。", "饼干": "语义：饼干不能用来写作业，“拿出来写作业”的物品应是学习用具。", "沙发": "搭配：沙发太大，不能“拿出来”，“拿出来”只用于较小的物品。", "雨伞": "语义：雨伞与“写作业”不搭，句子读来不通。"}, "sentence_index": 0, "correct_answer": "本本"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司给每个同事发了一颗本本。", "explanation": "这里应该用〈台〉。手提电脑用“台”，“颗”用于颗粒状或圆形的小东西。"}, {"text": "公司给每个同事发了一张本本。", "explanation": "这里应该用〈台〉。“张”用于纸、桌子等扁平物，手提电脑要用“台”。"}, {"text": "公司给每个同事发了一把本本。", "explanation": "这里应该用〈台〉。“把”用于有柄的东西，手提电脑要用“台”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f5f1d31-ca2a-49c7-8237-0c9588c31fa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92832, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "本本", "is_correct": true, "explanation": "“本本”可以用来记录电话号码，与“里记着”搭配，符合句意。"}, {"text": "房间", "is_correct": false, "explanation": "语义：房间不能记录电话号码，“记着……里”的处所应是可以记录的载体。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不能记录电话号码，句子读来不通。"}, {"text": "墙", "is_correct": false, "explanation": "搭配：“记着……里”通常指记在本子、手机等可记录的物件里，墙不宜与“我的……里”搭配。"}], "explanations": {"本本": "“本本”可以用来记录电话号码，与“里记着”搭配，符合句意。", "房间": "语义：房间不能记录电话号码，“记着……里”的处所应是可以记录的载体。", "冰箱": "语义：冰箱不能记录电话号码，句子读来不通。", "墙": "搭配：“记着……里”通常指记在本子、手机等可记录的物件里，墙不宜与“我的……里”搭配。"}, "sentence_index": 6, "correct_answer": "本本"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了一支本本，它很轻，可以放进书包。", "explanation": "这里应该用〈台〉或〈本〉。手提电脑用“台”，本子用“本”，“支”用于笔等细长的物件。"}, {"text": "我买了一块本本，它很轻，可以放进书包。", "explanation": "这里应该用〈本〉。“块”用于块状物，本子要用“本”。"}, {"text": "我买了一头本本，它很轻，可以放进书包。", "explanation": "这里应该用〈台〉或〈本〉。“头”用于牛、猪等动物，不能用于本子或电脑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f5f1d31-ca2a-49c7-8237-0c9588c31fa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
