INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92835, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "比心是用手指摆成一颗心的样子。", "primary_collocate": null, "pronunciation": "bǐ xīn", "ipa": "pi˨˩˦ ɕin˥", "syllable_count": 2, "sentences": [{"text": "你看，她用两只手指比心。", "target_word": "比心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "拇指和食指交叉，就能比心。", "target_word": "比心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小女孩刚学会比心。", "target_word": "比心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照相的时候，大家都爱比心。", "target_word": "比心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的手指太短，很难比心。", "target_word": "比心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们怎么用手比心。", "target_word": "比心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你会不会比心？我教你。", "target_word": "比心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在照片里比心，笑得很开心。", "target_word": "比心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们站成一排，一起比心。", "target_word": "比心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把手举高，对着镜头比心。", "target_word": "比心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "比个心", "label": "离合式"}, {"form": "比了个心", "label": "离合式（体标）"}], "register": "口语", "sense_fingerprint": "比心：用手指摆出心的形状这一动作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94ef46ac-c75d-4aa5-b593-6bca6ddab68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92835, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "比心", "is_correct": true, "explanation": "比心：用两根手指摆出心形，与句中“用两只手指”相符。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱歌要靠嗓子，不能用手指完成。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：咳嗽是呼吸道的生理反应，不能用两根手指完成。"}, {"text": "打", "is_correct": false, "explanation": "配价：“打”需要带被打的对象，句中没有宾语，不成立。"}], "explanations": {"比心": "比心：用两根手指摆出心形，与句中“用两只手指”相符。", "唱": "语义：唱歌要靠嗓子，不能用手指完成。", "咳嗽": "语义：咳嗽是呼吸道的生理反应，不能用两根手指完成。", "打": "配价：“打”需要带被打的对象，句中没有宾语，不成立。"}, "sentence_index": 0, "correct_answer": "比心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他比心，表示决心。", "explanation": "这里应该用〈握拳〉。比心是用手指摆出心形的手势，表示决心要握拳。"}, {"text": "我不想喝，就向服务员比心。", "explanation": "这里应该用〈摆手〉。比心是用手指摆出心形的手势，拒绝别人要摆手。"}, {"text": "他很生气，就向我比心。", "explanation": "这里应该用〈拍桌子〉。比心是用手指摆出心形的手势，生气时要拍桌子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb7c6870-df9b-44cd-b239-97d633319a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92835, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "比心", "is_correct": true, "explanation": "比心：用手指摆出心形，是可以教的动作，与“我教你”相符。"}, {"text": "生气", "is_correct": false, "explanation": "语义：生气是情绪反应，不需要别人教，与“我教你”不合。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：咳嗽是身体的生理反应，不能教，与“我教你”不合。"}, {"text": "放", "is_correct": false, "explanation": "配价：“放”后要带放置的物品和地点，句中没有宾语和地点，不成立。"}], "explanations": {"比心": "比心：用手指摆出心形，是可以教的动作，与“我教你”相符。", "生气": "语义：生气是情绪反应，不需要别人教，与“我教你”不合。", "咳嗽": "语义：咳嗽是身体的生理反应，不能教，与“我教你”不合。", "放": "配价：“放”后要带放置的物品和地点，句中没有宾语和地点，不成立。"}, "sentence_index": 6, "correct_answer": "比心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他向长辈比心，表示尊敬。", "explanation": "这里应该用〈作揖〉。比心是用手指摆出心形的手势，向长辈表示尊敬要作揖。"}, {"text": "他气得比心。", "explanation": "这里应该用〈跺脚〉。比心是用手指摆出心形的手势，生气时要跺脚。"}, {"text": "他想发言，就向老师比心。", "explanation": "这里应该用〈举手〉。比心是用手指摆出心形的手势，想发言要举手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb7c6870-df9b-44cd-b239-97d633319a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92835, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她给我个比心，我很开心。", "corrected_sentence": "她给我比个心，我很开心。", "error_description": "错误：“个比心”；正确：“比个心”。量词“个”是离合词“比心”的一部分，要放在“比”和“心”之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb7c6870-df9b-44cd-b239-97d633319a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92835, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他给我了比心，我很开心。", "corrected_sentence": "他给我比了个心，我很开心。", "error_description": "体标位置错误：“了”不能放在离合词“比心”前面，要放在“比”后面，说“比了个心”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb7c6870-df9b-44cd-b239-97d633319a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
