INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92836, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb7c6870-df9b-44cd-b239-97d633319a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92836, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手势摆出心形，表达喜爱或感谢之情。", "primary_collocate": null, "pronunciation": "bǐ xīn", "ipa": "pi˨˩˦ ɕin˥", "syllable_count": 2, "sentences": [{"text": "粉丝对着明星比心，表示喜欢。", "target_word": "比心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机帮了我，我对他比心说谢谢。", "target_word": "比心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑着给大家比心，然后走了。", "target_word": "比心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明在视频里向奶奶比心。", "target_word": "比心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谢谢你的礼物，我给你比心！", "target_word": "比心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外卖员送完饭，笑着向我比心。", "target_word": "比心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师夸我们很棒，我们一起比心。", "target_word": "比心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演唱会结束了，歌手对观众比心。", "target_word": "比心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给我做了饭，我对她比心。", "target_word": "比心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想谢谢朋友，所以隔着窗户比心。", "target_word": "比心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "比个心", "label": "离合式"}, {"form": "比了个心", "label": "离合式（体标）"}], "register": "口语", "sense_fingerprint": "比心：用心形手势向别人表达喜爱或感谢", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94ef46ac-c75d-4aa5-b593-6bca6ddab68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92836, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "比心", "is_correct": true, "explanation": "比心：用心形手势对明星表达喜欢，与句中“表示喜欢”的语境相符。"}, {"text": "摇头", "is_correct": false, "explanation": "语义：摇头表示否定，与句中“表示喜欢”的意思相反。"}, {"text": "哭", "is_correct": false, "explanation": "语义：哭表示悲伤，不能用来表示喜欢。"}, {"text": "写", "is_correct": false, "explanation": "配价：“写”需要带所写的内容，“对着明星写”不成立。"}], "explanations": {"比心": "比心：用心形手势对明星表达喜欢，与句中“表示喜欢”的语境相符。", "摇头": "语义：摇头表示否定，与句中“表示喜欢”的意思相反。", "哭": "语义：哭表示悲伤，不能用来表示喜欢。", "写": "配价：“写”需要带所写的内容，“对着明星写”不成立。"}, "sentence_index": 0, "correct_answer": "比心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师问我们懂了没有，大家都向他比心。", "explanation": "这里应该用〈点头〉。比心表示喜爱或感谢，表示同意或听懂要用点头。"}, {"text": "我问他要不要去，他只是向我比心。", "explanation": "这里应该用〈摇头〉。比心表示喜爱或感谢，表示拒绝要用摇头。"}, {"text": "士兵见到长官，向他比心。", "explanation": "这里应该用〈敬礼〉。比心是表示喜爱或感谢的手势，见到长官要敬礼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb7c6870-df9b-44cd-b239-97d633319a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92836, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "比心", "is_correct": true, "explanation": "比心：用心形手势表达喜爱或感谢，与“老师夸我们很棒”的语境相符。"}, {"text": "发火", "is_correct": false, "explanation": "语义：发火表示生气，与“老师夸我们很棒”的语境相反。"}, {"text": "叹气", "is_correct": false, "explanation": "语义：叹气表示失落，与“老师夸我们很棒”的语境不合。"}, {"text": "扔", "is_correct": false, "explanation": "配价：“扔”需要带被扔的东西，句中没有宾语，不成立。"}], "explanations": {"比心": "比心：用心形手势表达喜爱或感谢，与“老师夸我们很棒”的语境相符。", "发火": "语义：发火表示生气，与“老师夸我们很棒”的语境相反。", "叹气": "语义：叹气表示失落，与“老师夸我们很棒”的语境不合。", "扔": "配价：“扔”需要带被扔的东西，句中没有宾语，不成立。"}, "sentence_index": 6, "correct_answer": "比心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我想叫服务员，就向他比心。", "explanation": "这里应该用〈招手〉。比心表示喜爱或感谢，叫人过来要用招手。"}, {"text": "他一边比心，一边告诉我怎么走。", "explanation": "这里应该用〈比划〉。比心表示喜爱或感谢，用手势说明事情要用比划，不能用比心指路。"}, {"text": "上课时，他比心回答问题。", "explanation": "这里应该用〈举手〉。比心表示喜爱或感谢，想发言要举手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb7c6870-df9b-44cd-b239-97d633319a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92836, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我给你个比心，谢谢你。", "corrected_sentence": "我给你比心，谢谢你。", "error_description": "量词位置错误：“个”不能放在动词“比心”前面。“比心”是离合词，量词要放在“比”和“心”之间，说“比个心”，或直接说“比心”，不能说“个比心”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb7c6870-df9b-44cd-b239-97d633319a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92836, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他对我了比心，我很开心。", "corrected_sentence": "他对我比心，我很开心。", "error_description": "体标位置错误：“了”不能放在离合词“比心”前面，应直接说“比心”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb7c6870-df9b-44cd-b239-97d633319a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
