INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92837, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "没错是说你说对了。", "primary_collocate": null, "pronunciation": "méi cuò", "ipa": "mei³⁵ tsʰuo⁵¹", "syllable_count": 2, "sentences": [{"text": "你是小王吗？没错，我是小王。", "target_word": "没错", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“这家店的菜很好吃。”“没错！”", "target_word": "没错", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“你说得对吧？”“没错，我也这么想。”", "target_word": "没错", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没错，今天是我的生日。", "target_word": "没错", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“他是你哥哥吧？”“没错。”", "target_word": "没错", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没错，这就是我要找的书。", "target_word": "没错", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“明天不上课吧？”“没错，明天不上课。”", "target_word": "没错", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没错，我昨天去过那里。", "target_word": "没错", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“你想家了吧？”“没错，很想。”", "target_word": "没错", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没错，他就是我们的新老师。", "target_word": "没错", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "回应对方，表示对方说得对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2247d90f-0ad5-44a6-82f3-355e9a0b1ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92837, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "没错", "is_correct": true, "explanation": "没错表示对方说得对，是肯定的回应，与后句“我是小王”一致。"}, {"text": "不对", "is_correct": false, "explanation": "语义：“不对”否定了对方的问话，与后句“我是小王”的肯定相矛盾。"}, {"text": "不是", "is_correct": false, "explanation": "语义：“不是”否定了身份，与后句“我是小王”直接矛盾。"}, {"text": "胡说", "is_correct": false, "explanation": "语域：“胡说”带有指责意味，用来回应对方的问题很不礼貌，且与后句矛盾。"}], "explanations": {"没错": "没错表示对方说得对，是肯定的回应，与后句“我是小王”一致。", "不对": "语义：“不对”否定了对方的问话，与后句“我是小王”的肯定相矛盾。", "不是": "语义：“不是”否定了身份，与后句“我是小王”直接矛盾。", "胡说": "语域：“胡说”带有指责意味，用来回应对方的问题很不礼貌，且与后句矛盾。"}, "sentence_index": 0, "correct_answer": "没错"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "“这个多少钱？”“没错。”", "explanation": "这里应该用〈十块〉。“没错”只用于确认对方说的内容正确，不用于回答价格、数量等具体问题。"}, {"text": "我们去公园吧，没错。", "explanation": "这里应该用〈好的〉。“没错”只用于确认对方说的内容正确，不用于接受别人的提议。"}, {"text": "谢谢你送我的礼物，没错。", "explanation": "这里应该用〈不客气〉。“没错”是对对方说法的肯定，不用来回应别人的感谢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b17ac9-90e3-47d7-bc08-ac64f78b44c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92837, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "没错", "is_correct": true, "explanation": "没错表示对方说得对，与“明天不上课”的确认语气一致。"}, {"text": "没用", "is_correct": false, "explanation": "语义：“没用”说对方的话无效，与句中“明天不上课”的确认语气不符。"}, {"text": "没意思", "is_correct": false, "explanation": "语义：“没意思”评价对方的话乏味，与后句的通知语气不协调。"}, {"text": "不行", "is_correct": false, "explanation": "语义：“不行”表示不允许、不可以，与对方确认“明天不上课”的语气不合。"}], "explanations": {"没错": "没错表示对方说得对，与“明天不上课”的确认语气一致。", "没用": "语义：“没用”说对方的话无效，与句中“明天不上课”的确认语气不符。", "没意思": "语义：“没意思”评价对方的话乏味，与后句的通知语气不协调。", "不行": "语义：“不行”表示不允许、不可以，与对方确认“明天不上课”的语气不合。"}, "sentence_index": 6, "correct_answer": "没错"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我要走了，没错。", "explanation": "这里应该用〈再见〉。“没错”只用于确认对方说法正确，不能用于告别。"}, {"text": "你要喝水吗？没错。", "explanation": "这里应该用〈谢谢〉。“没错”是确认对方说法正确，不用来回应别人提出的好意或提议。"}, {"text": "“我回来了。”“没错！”", "explanation": "这里应该用〈欢迎回来〉。“没错”不用来回应对方的问候或告知。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b17ac9-90e3-47d7-bc08-ac64f78b44c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92837, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你是张经理吗？不没错，我是张经理。", "corrected_sentence": "你是张经理吗？没错，我是张经理。", "error_description": "错误：“不没错”，正确：“没错”。“没错”是表示对方说对了的固定回应，前面不能再加“不”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b17ac9-90e3-47d7-bc08-ac64f78b44c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92837, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你说明天下雨，很没错，天气预报也这么说。", "corrected_sentence": "你说明天下雨，没错，天气预报也这么说。", "error_description": "错误：“很没错”，正确：“没错”。“没错”是表示对方说对了的固定回应，本身不能再受“很”修饰。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b17ac9-90e3-47d7-bc08-ac64f78b44c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92838, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "错误", "is_correct": true, "explanation": "错误与“没错”意思相反，指事情有错。"}, {"text": "模糊", "is_correct": false, "explanation": "模糊指不清楚，与“没错”无反义关系。"}, {"text": "干净", "is_correct": false, "explanation": "干净指没有污物，与“没错”无反义关系。"}, {"text": "遥远", "is_correct": false, "explanation": "遥远指距离很远，与“没错”无反义关系。"}], "correct_answer": "错误", "explanations": {"错误": "错误与“没错”意思相反，指事情有错。", "模糊": "模糊指不清楚，与“没错”无反义关系。", "干净": "干净指没有污物，与“没错”无反义关系。", "遥远": "遥远指距离很远，与“没错”无反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b17ac9-90e3-47d7-bc08-ac64f78b44c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92838, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "错误", "is_correct": true, "explanation": "错误与“没错”意思相反，指事情有错。"}, {"text": "安静", "is_correct": false, "explanation": "安静指没有声音，与“没错”无反义关系。"}, {"text": "漂亮", "is_correct": false, "explanation": "漂亮指好看，与“没错”无反义关系。"}, {"text": "陡峭", "is_correct": false, "explanation": "陡峭指坡度很大，与“没错”无反义关系。"}], "correct_answer": "错误", "explanations": {"错误": "错误与“没错”意思相反，指事情有错。", "安静": "安静指没有声音，与“没错”无反义关系。", "漂亮": "漂亮指好看，与“没错”无反义关系。", "陡峭": "陡峭指坡度很大，与“没错”无反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b17ac9-90e3-47d7-bc08-ac64f78b44c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92838, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "表示肯定，意思是对、正确、不会错。", "primary_collocate": null, "pronunciation": "méi cuò", "ipa": "mei³⁵ tsʰuo⁵¹", "syllable_count": 2, "sentences": [{"text": "照地图走，肯定没错。", "target_word": "没错", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路没错，我来过。", "target_word": "没错", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我记得很清楚，地址没错。", "target_word": "没错", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听老师的话准没错。", "target_word": "没错", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的答案没错，我都检查过了。", "target_word": "没错", "complexity_tier": "T3", "furigana": "nǐ de dá àn méi cuò, wǒ dōu jiǎn chá guò le", "sentence_source": "generated"}, {"text": "他说的时间没错，是八点。", "target_word": "没错", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个名字我写得没错。", "target_word": "没错", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆的菜好吃，选它没错。", "target_word": "没错", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话号码没错，可是没人接。", "target_word": "没错", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数字都没错，不用再算了。", "target_word": "没错", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "表示事情正确、可靠、不会出错", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2247d90f-0ad5-44a6-82f3-355e9a0b1ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92838, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "没错", "is_correct": true, "explanation": "没错表示事情正确、不会出错，与“照地图走”的可靠性一致。"}, {"text": "错", "is_correct": false, "explanation": "语义：“错”与“照地图走”的可靠性相反，前后意思矛盾。"}, {"text": "混乱", "is_correct": false, "explanation": "语义：照地图走应当有条理，说“混乱”与句意矛盾。"}, {"text": "危险", "is_correct": false, "explanation": "搭配：“肯定危险”与“照地图走”的前提不搭配，地图指路一般被认为是可靠的。"}], "explanations": {"没错": "没错表示事情正确、不会出错，与“照地图走”的可靠性一致。", "错": "语义：“错”与“照地图走”的可靠性相反，前后意思矛盾。", "混乱": "语义：照地图走应当有条理，说“混乱”与句意矛盾。", "危险": "搭配：“肯定危险”与“照地图走”的前提不搭配，地图指路一般被认为是可靠的。"}, "sentence_index": 0, "correct_answer": "没错"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个女孩长得很没错。", "explanation": "这里应该用〈漂亮〉。“没错”表示事情正确、不会出错，不用来形容人的长相。"}, {"text": "这座城市交通没错。", "explanation": "这里应该用〈发达〉。“没错”形容事情做得正确，不用来评价交通、经济等发展水平。"}, {"text": "这个花瓶没错。", "explanation": "这里应该用〈漂亮〉。“没错”说的是事情或做法正确，不用来赞美外观。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b17ac9-90e3-47d7-bc08-ac64f78b44c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92838, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "没错", "is_correct": true, "explanation": "没错表示书写正确，与“这个名字我写得”的语境相符。"}, {"text": "糊涂", "is_correct": false, "explanation": "语义：“糊涂”形容人的头脑不清，不用来形容字迹是否正确。"}, {"text": "阴沉", "is_correct": false, "explanation": "语义：“阴沉”形容天色或神情，不用来描述写名字的样子。"}, {"text": "欢快", "is_correct": false, "explanation": "搭配：“写得欢快”不是自然的搭配，名字的书写不用“欢快”来形容。"}], "explanations": {"没错": "没错表示书写正确，与“这个名字我写得”的语境相符。", "糊涂": "语义：“糊涂”形容人的头脑不清，不用来形容字迹是否正确。", "阴沉": "语义：“阴沉”形容天色或神情，不用来描述写名字的样子。", "欢快": "搭配：“写得欢快”不是自然的搭配，名字的书写不用“欢快”来形容。"}, "sentence_index": 6, "correct_answer": "没错"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场比赛没错。", "explanation": "这里应该用〈精彩〉。“没错”形容事情正确，不用来评价比赛好看与否。"}, {"text": "这个酒店没错。", "explanation": "这里应该用〈豪华〉。“没错”形容事情做得对，不用来形容酒店的档次。"}, {"text": "她的性格没错。", "explanation": "这里应该用〈温柔〉。“没错”指事情或做法正确，不用来评价人的性格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b17ac9-90e3-47d7-bc08-ac64f78b44c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92838, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份计划的时间安排很没错，放心执行吧。", "corrected_sentence": "这份计划的时间安排没错，放心执行吧。", "error_description": "错误：“很没错”，正确：“没错”。“没错”本身已表示正确，不能再受“很”修饰。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b17ac9-90e3-47d7-bc08-ac64f78b44c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92838, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的回答不没错，老师点了头。", "corrected_sentence": "他的回答没错，老师点了头。", "error_description": "错误：“不没错”，正确：“没错”。“没错”本身是固定的肯定说法，不能再用“不”否定；要表示否定应说“错了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b17ac9-90e3-47d7-bc08-ac64f78b44c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
