INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92840, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "引进比较的对象，表示相比之下。", "primary_collocate": null, "pronunciation": "bǐ qǐ", "ipa": "pi˨˩ tɕʰi˨˩", "syllable_count": 2, "sentences": [{"text": "比起北京，上海的夏天更热。", "target_word": "比起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比起坐车，我更喜欢走路。", "target_word": "比起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比起看电影，他更爱在家看书。", "target_word": "比起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比起去年，今年的雨少多了。", "target_word": "比起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比起哥哥，弟弟说话慢一些。", "target_word": "比起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比起米饭，我更爱吃面条。", "target_word": "比起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比起手机，妈妈更喜欢用电脑看新闻。", "target_word": "比起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比起冬天，我更喜欢秋天。", "target_word": "比起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比起城市，农村的空气好得多。", "target_word": "比起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比起上个月，这个月我们忙多了。", "target_word": "比起", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "比起来", "label": "复合形式"}], "register": "中性", "sense_fingerprint": "引进比较对象，相比之下", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b0b43b2-f2a1-4aa0-8f6e-1215570c5942') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92840, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "比起", "is_correct": true, "explanation": "“比起”引进比较对象，与“上海的夏天更热”的比较相符。"}, {"text": "按照", "is_correct": false, "explanation": "语义：“按照”表示依据某种标准，“按照北京”无法引进比较对象。"}, {"text": "根据", "is_correct": false, "explanation": "语义：“根据”表示依据，“根据北京”不能表示与北京相比。"}, {"text": "通过", "is_correct": false, "explanation": "配价：“通过”需要带动作或途径作宾语，“北京”只是地点，不能充当这样的成分。"}], "explanations": {"比起": "“比起”引进比较对象，与“上海的夏天更热”的比较相符。", "按照": "语义：“按照”表示依据某种标准，“按照北京”无法引进比较对象。", "根据": "语义：“根据”表示依据，“根据北京”不能表示与北京相比。", "通过": "配价：“通过”需要带动作或途径作宾语，“北京”只是地点，不能充当这样的成分。"}, "sentence_index": 0, "correct_answer": "比起"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "比起去年，我的爸爸是医生。", "explanation": "这里误把〈比起〉当作单纯引入时间背景来用。〈比起〉要引进可比的对象并接比较结论，此句只陈述一件事实，没有比较，属于用错。"}, {"text": "比起我，我很喜欢这本书。", "explanation": "这里误把〈比起〉当作单纯的话题引入语来用。〈比起〉引进比较对象，句子的主语与对象都是“我”，没有可比的两方，无法成立。"}, {"text": "比起吃饭，他在吃饭。", "explanation": "这里误把〈比起〉当作单纯陈述正在做的事来用。〈比起〉引进比较对象，后面要有比较结论，此句只说明他在做什么，没有比较，属于用错。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '911e1fef-8b62-41ef-9787-8082a21bf08f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92840, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "比起", "is_correct": true, "explanation": "“比起”引进比较对象，与“妈妈更喜欢用电脑”的比较相符。"}, {"text": "依靠", "is_correct": false, "explanation": "语义：“依靠”表示依赖某人或某物，“依靠手机”与句意无关。"}, {"text": "为了", "is_correct": false, "explanation": "语义：“为了”表示目的，句子没有目的，“为了手机”不成立。"}, {"text": "凭借", "is_correct": false, "explanation": "配价：“凭借”要求凭以成事的手段或依据作宾语，“手机”不符合这一要求。"}], "explanations": {"比起": "“比起”引进比较对象，与“妈妈更喜欢用电脑”的比较相符。", "依靠": "语义：“依靠”表示依赖某人或某物，“依靠手机”与句意无关。", "为了": "语义：“为了”表示目的，句子没有目的，“为了手机”不成立。", "凭借": "配价：“凭借”要求凭以成事的手段或依据作宾语，“手机”不符合这一要求。"}, "sentence_index": 6, "correct_answer": "比起"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "比起这件衣服，那辆车在路上跑。", "explanation": "这里误把〈比起〉用来连接不可比的两件事。〈比起〉要比较同类对象的优劣，衣服与车在路上跑的事实之间没有可比性，属于用错。"}, {"text": "比起这件衣服，天气很好。", "explanation": "这里误把〈比起〉当作普通的话题引入语来用。〈比起〉要把两个可比的对象放在一起评判，衣服与天气不可比，属于用错。"}, {"text": "比起这件衣服，我的书很多。", "explanation": "这里误把〈比起〉当作普通的话题引入语来用。〈比起〉要比较同类事物的优劣，衣服与书的数量不可比，属于用错。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '911e1fef-8b62-41ef-9787-8082a21bf08f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92840, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "比起城市来，我很更喜欢农村。", "corrected_sentence": "比起城市来，我更喜欢农村。", "error_description": "副词叠用错误：“很”与“更”都是程度副词，不能同时修饰同一个动词“喜欢”。去掉“很”即正确，应说“比起城市来，我更喜欢农村”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '911e1fef-8b62-41ef-9787-8082a21bf08f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92840, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "比起很旧车，新车省油得多。", "corrected_sentence": "比起旧车，新车省油得多。", "error_description": "位置错误：程度副词“很”不能插在介词“比起”与它的宾语之间，应说“比起旧车”，不说“比起很旧车”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '911e1fef-8b62-41ef-9787-8082a21bf08f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92841, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "让", "is_correct": true, "explanation": "让：把机会或东西让给别人，与“抢着要”相反，是“争”的反义词。"}, {"text": "买", "is_correct": false, "explanation": "买：指用钱换取东西，与“争”没有反义关系。"}, {"text": "看", "is_correct": false, "explanation": "看：指用眼睛观察，与“争”没有反义关系。"}, {"text": "写", "is_correct": false, "explanation": "写：指用笔写字，与“争”没有反义关系。"}], "correct_answer": "让", "explanations": {"让": "让：把机会或东西让给别人，与“抢着要”相反，是“争”的反义词。", "买": "买：指用钱换取东西，与“争”没有反义关系。", "看": "看：指用眼睛观察，与“争”没有反义关系。", "写": "写：指用笔写字，与“争”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b55e6d1-d065-468e-8962-434097609120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92841, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "让", "is_correct": true, "explanation": "让：不争、把座位让给别人，与“争座位”相反，是“争”的反义词。"}, {"text": "放", "is_correct": false, "explanation": "放：指把东西置于某处，与“争”没有反义关系。"}, {"text": "走", "is_correct": false, "explanation": "走：指移动脚步，与“争”没有反义关系。"}, {"text": "教", "is_correct": false, "explanation": "教：指传授知识，与“争”没有反义关系。"}], "correct_answer": "让", "explanations": {"让": "让：不争、把座位让给别人，与“争座位”相反，是“争”的反义词。", "放": "放：指把东西置于某处，与“争”没有反义关系。", "走": "走：指移动脚步，与“争”没有反义关系。", "教": "教：指传授知识，与“争”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b55e6d1-d065-468e-8962-434097609120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92841, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "争是大家都想要同一样东西，抢着要。", "primary_collocate": null, "pronunciation": "zhēng", "ipa": "ʈʂəŋ˥", "syllable_count": 1, "sentences": [{"text": "两个孩子都想要那个玩具，争了起来。", "target_word": "争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈只买了一个苹果，弟弟和我都争着要。", "target_word": "争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫们争着吃盘子里的鱼。", "target_word": "争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打折的时候，大家都争着买这种包。", "target_word": "争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "椅子只有一把，三个人都在争。", "target_word": "争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别争了，这个玩具你们俩轮流玩。", "target_word": "争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们都想要那本书，争着借。", "target_word": "争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们争着要糖，妈妈笑了。", "target_word": "争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好东西不多，大家都来争，最后没人拿到。", "target_word": "争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们争过那个座位，现在已经是好朋友了。", "target_word": "争", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "争着", "label": "着 体标"}, {"form": "争了", "label": "了 体标"}, {"form": "争过", "label": "过 体标"}], "register": "中性", "sense_fingerprint": "多人想要同一样东西，抢着要", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c43aef69-b6a0-4454-8d6b-0589435b9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92841, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "争", "is_correct": true, "explanation": "争（zhēng，第一声）：多人抢着要同一样东西，正是本词。"}, {"text": "增", "is_correct": false, "explanation": "增（zēng，第一声）与 zhēng 声母不同（z 与 zh），意思是增加，不是抢着要。"}, {"text": "真", "is_correct": false, "explanation": "真（zhēn，第一声）与 zhēng 韵母不同（-n 与 -ng），意思是真实。"}, {"text": "张", "is_correct": false, "explanation": "张（zhāng，第一声）与 zhēng 韵母不同（āng 与 ēng），意思是张开、量词。"}, {"text": "撑", "is_correct": false, "explanation": "撑（chēng，第一声）与 zhēng 声母不同（ch 与 zh），意思是撑住。"}, {"text": "整", "is_correct": false, "explanation": "整（zhěng，第三声）与 zhēng 声调不同，意思是完整。"}, {"text": "正", "is_correct": false, "explanation": "正（zhèng，第四声）与 zhēng 声调不同，意思是正确。"}], "explanations": {"争": "争（zhēng，第一声）：多人抢着要同一样东西，正是本词。", "增": "增（zēng，第一声）与 zhēng 声母不同（z 与 zh），意思是增加，不是抢着要。", "真": "真（zhēn，第一声）与 zhēng 韵母不同（-n 与 -ng），意思是真实。", "张": "张（zhāng，第一声）与 zhēng 韵母不同（āng 与 ēng），意思是张开、量词。", "撑": "撑（chēng，第一声）与 zhēng 声母不同（ch 与 zh），意思是撑住。", "整": "整（zhěng，第三声）与 zhēng 声调不同，意思是完整。", "正": "正（zhèng，第四声）与 zhēng 声调不同，意思是正确。"}, "sentence_index": null, "correct_answer": "争"}, "level_3": {"options": [{"text": "争", "is_correct": true, "explanation": "争：多人都想要同一样东西，抢着要，填入“争了起来”语境通顺。"}, {"text": "睡", "is_correct": false, "explanation": "语义：“睡”指休息，与两个孩子争抢玩具的语境不合，“睡了起来”说不通。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语是食物，玩具不能吃，“吃了起来”与“玩具”搭配不当。"}, {"text": "送", "is_correct": false, "explanation": "配价：“送”需要“送给某人”的接受者，句中缺少这个成分，且与“都想要”矛盾。"}], "explanations": {"争": "争：多人都想要同一样东西，抢着要，填入“争了起来”语境通顺。", "睡": "语义：“睡”指休息，与两个孩子争抢玩具的语境不合，“睡了起来”说不通。", "吃": "搭配：“吃”的宾语是食物，玩具不能吃，“吃了起来”与“玩具”搭配不当。", "送": "配价：“送”需要“送给某人”的接受者，句中缺少这个成分，且与“都想要”矛盾。"}, "sentence_index": 0, "correct_answer": "争"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小偷争走了她的包，还把钱也拿走了。", "explanation": "这里应该用〈抢〉。抢是单方面强行夺取，不是多人都想要同一样东西而竞相取得，不能用“争”。"}, {"text": "他每天很努力，一个月争了五千块钱。", "explanation": "这里应该用〈挣〉。挣钱是靠劳动得到收入，不是多人抢着要同一样东西，不能用“争”。"}, {"text": "他一个人在家，却争着要那个玩具。", "explanation": "争要有两个或更多的人同时想要同一样东西，这里只有他一人，应说“想要”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b55e6d1-d065-468e-8962-434097609120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92841, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "争", "is_correct": true, "explanation": "争（zhēng，第一声）：多人抢着要同一样东西，正是本词。"}, {"text": "生", "is_correct": false, "explanation": "生（shēng，第一声）与 zhēng 声母不同（sh 与 zh），意思是生长。"}, {"text": "珍", "is_correct": false, "explanation": "珍（zhēn，第一声）与 zhēng 韵母不同（-n 与 -ng），意思是珍贵。"}, {"text": "政", "is_correct": false, "explanation": "政（zhèng，第四声）与 zhēng 声调不同，意思是政治。"}, {"text": "称", "is_correct": false, "explanation": "称（chēng，第一声）与 zhēng 声母不同（ch 与 zh），意思是称呼、称重。"}, {"text": "中", "is_correct": false, "explanation": "中（zhōng，第一声）与 zhēng 韵母不同（ōng 与 ēng），意思是中间。"}], "explanations": {"争": "争（zhēng，第一声）：多人抢着要同一样东西，正是本词。", "生": "生（shēng，第一声）与 zhēng 声母不同（sh 与 zh），意思是生长。", "珍": "珍（zhēn，第一声）与 zhēng 韵母不同（-n 与 -ng），意思是珍贵。", "政": "政（zhèng，第四声）与 zhēng 声调不同，意思是政治。", "称": "称（chēng，第一声）与 zhēng 声母不同（ch 与 zh），意思是称呼、称重。", "中": "中（zhōng，第一声）与 zhēng 韵母不同（ōng 与 ēng），意思是中间。"}, "sentence_index": null, "correct_answer": "争"}, "level_3": {"options": [{"text": "争", "is_correct": true, "explanation": "争：多人想借同一本书，抢着借，与“都想要那本书”的语境一致。"}, {"text": "还", "is_correct": false, "explanation": "语义：“还”指归还，与“都想要那本书”的意愿相反，“还着借”说不通。"}, {"text": "卖", "is_correct": false, "explanation": "搭配：“卖”与“借”意思相反，不能说“卖着借”。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”指丢弃，与想要那本书的语境矛盾。"}], "explanations": {"争": "争：多人想借同一本书，抢着借，与“都想要那本书”的语境一致。", "还": "语义：“还”指归还，与“都想要那本书”的意愿相反，“还着借”说不通。", "卖": "搭配：“卖”与“借”意思相反，不能说“卖着借”。", "扔": "语义：“扔”指丢弃，与想要那本书的语境矛盾。"}, "sentence_index": 6, "correct_answer": "争"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家都争着呼吸新鲜空气。", "explanation": "空气人人都有，不是只有一份、大家都想要的东西，不存在抢着要的情况，应去掉“争着”，说“大家都在呼吸新鲜空气”。"}, {"text": "他一个人在房间里争着看书。", "explanation": "“争”要有两个或更多的人想要同一样东西，这里只有他一个人，也没有抢的对象，应去掉“争着”，说“他一个人在房间里看书”。"}, {"text": "他在饭店打工，一个月能争三千块钱。", "explanation": "这里应该用〈挣〉。挣钱是靠劳动得到收入，不是多人抢着要同一样东西，不能用“争”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b55e6d1-d065-468e-8962-434097609120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92841, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们都想要那张票，争买着。", "corrected_sentence": "他们都想要那张票，争着买。", "error_description": "错误形式：“争买着”；正确形式：“争着买”。“着”表示“争”正在进行的状态，应紧跟动词“争”，不能放在后面的“买”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b55e6d1-d065-468e-8962-434097609120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92841, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "几个人都想买最后一张票，争很厉害。", "corrected_sentence": "几个人都想买最后一张票，争得很厉害。", "error_description": "错误形式：“争很厉害”；正确形式：“争得很厉害”。表示程度的补语要用“得”连接动词和补语，“争”后漏掉了“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b55e6d1-d065-468e-8962-434097609120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92842, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "让", "is_correct": true, "explanation": "让：把第一的机会让给别人，与“争第一”相反，是“争”的反义词。"}, {"text": "买", "is_correct": false, "explanation": "买：指用钱换取东西，与“争”没有反义关系。"}, {"text": "看", "is_correct": false, "explanation": "看：指用眼睛观察，与“争”没有反义关系。"}, {"text": "写", "is_correct": false, "explanation": "写：指用笔写字，与“争”没有反义关系。"}], "correct_answer": "让", "explanations": {"让": "让：把第一的机会让给别人，与“争第一”相反，是“争”的反义词。", "买": "买：指用钱换取东西，与“争”没有反义关系。", "看": "看：指用眼睛观察，与“争”没有反义关系。", "写": "写：指用笔写字，与“争”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b55e6d1-d065-468e-8962-434097609120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92842, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "让", "is_correct": true, "explanation": "让：把当班长的机会让给别人，与“争着当班长”相反，是“争”的反义词。"}, {"text": "走", "is_correct": false, "explanation": "走：指移动脚步，与“争”没有反义关系。"}, {"text": "教", "is_correct": false, "explanation": "教：指传授知识，与“争”没有反义关系。"}, {"text": "笑", "is_correct": false, "explanation": "笑：指露出愉快的表情，与“争”没有反义关系。"}], "correct_answer": "让", "explanations": {"让": "让：把当班长的机会让给别人，与“争着当班长”相反，是“争”的反义词。", "走": "走：指移动脚步，与“争”没有反义关系。", "教": "教：指传授知识，与“争”没有反义关系。", "笑": "笑：指露出愉快的表情，与“争”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b55e6d1-d065-468e-8962-434097609120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92842, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "争夺；力求获得（名次、机会、利益等）。", "primary_collocate": null, "pronunciation": "zhēng", "ipa": "ʈʂəŋ˥", "syllable_count": 1, "sentences": [{"text": "两个队都想争第一名。", "target_word": "争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两家公司都在争这个大客户。", "target_word": "争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天练习，想争冠军。", "target_word": "争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛，大家都在争第一。", "target_word": "争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都想争这次去北京的机会。", "target_word": "争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个国家都想争那块土地。", "target_word": "争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王想争这个名额，所以特别努力。", "target_word": "争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人争来争去，最后谁也没拿到冠军。", "target_word": "争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想和别人争，只想做好自己的事。", "target_word": "争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三个学生争着当班长。", "target_word": "争", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "争着", "label": "着 体标"}, {"form": "争了", "label": "了 体标"}, {"form": "争过", "label": "过 体标"}], "register": "中性", "sense_fingerprint": "争夺名次、机会、利益，力求获得", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c43aef69-b6a0-4454-8d6b-0589435b9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92842, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "争", "is_correct": true, "explanation": "争（zhēng，第一声）：争夺、力求获得，正是本词。"}, {"text": "增", "is_correct": false, "explanation": "增（zēng，第一声）与 zhēng 声母不同（z 与 zh），意思是增加。"}, {"text": "真", "is_correct": false, "explanation": "真（zhēn，第一声）与 zhēng 韵母不同（-n 与 -ng），意思是真实。"}, {"text": "张", "is_correct": false, "explanation": "张（zhāng，第一声）与 zhēng 韵母不同（āng 与 ēng），意思是张开。"}, {"text": "撑", "is_correct": false, "explanation": "撑（chēng，第一声）与 zhēng 声母不同（ch 与 zh），意思是撑住。"}, {"text": "整", "is_correct": false, "explanation": "整（zhěng，第三声）与 zhēng 声调不同，意思是完整。"}, {"text": "正", "is_correct": false, "explanation": "正（zhèng，第四声）与 zhēng 声调不同，意思是正确。"}], "explanations": {"争": "争（zhēng，第一声）：争夺、力求获得，正是本词。", "增": "增（zēng，第一声）与 zhēng 声母不同（z 与 zh），意思是增加。", "真": "真（zhēn，第一声）与 zhēng 韵母不同（-n 与 -ng），意思是真实。", "张": "张（zhāng，第一声）与 zhēng 韵母不同（āng 与 ēng），意思是张开。", "撑": "撑（chēng，第一声）与 zhēng 声母不同（ch 与 zh），意思是撑住。", "整": "整（zhěng，第三声）与 zhēng 声调不同，意思是完整。", "正": "正（zhèng，第四声）与 zhēng 声调不同，意思是正确。"}, "sentence_index": null, "correct_answer": "争"}, "level_3": {"options": [{"text": "争", "is_correct": true, "explanation": "争：两个队都想获得第一名，与语境一致，填入后意思通顺。"}, {"text": "丢", "is_correct": false, "explanation": "语义：“丢”指失去，与“都想”的意愿相反。"}, {"text": "让", "is_correct": false, "explanation": "语义：“让”指让出，与“都想”矛盾，“想让第一名”说不通。"}, {"text": "躲", "is_correct": false, "explanation": "搭配：“躲”的宾语一般是人或危险，不能说“躲第一名”。"}], "explanations": {"争": "争：两个队都想获得第一名，与语境一致，填入后意思通顺。", "丢": "语义：“丢”指失去，与“都想”的意愿相反。", "让": "语义：“让”指让出，与“都想”矛盾，“想让第一名”说不通。", "躲": "搭配：“躲”的宾语一般是人或危险，不能说“躲第一名”。"}, "sentence_index": 0, "correct_answer": "争"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一个月争了三千块，还要养家。", "explanation": "这里应该用〈挣〉。挣钱是靠劳动得到收入，不是争夺、争论或力求获得，不能用“争”。"}, {"text": "他太胖了，每天都在争体重。", "explanation": "这里应该用〈减〉。“争”带的是可争夺的对象，“体重”不能被争，应说“减体重”。"}, {"text": "这次比赛，观众们都在争第一。", "explanation": "这里应该用〈盼望〉。观众不参加比赛，不能“争第一”，只能盼望某人获胜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b55e6d1-d065-468e-8962-434097609120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92842, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "争", "is_correct": true, "explanation": "争（zhēng，第一声）：争夺、力求获得，正是本词。"}, {"text": "生", "is_correct": false, "explanation": "生（shēng，第一声）与 zhēng 声母不同（sh 与 zh），意思是生长。"}, {"text": "珍", "is_correct": false, "explanation": "珍（zhēn，第一声）与 zhēng 韵母不同（-n 与 -ng），意思是珍贵。"}, {"text": "政", "is_correct": false, "explanation": "政（zhèng，第四声）与 zhēng 声调不同，意思是政治。"}, {"text": "称", "is_correct": false, "explanation": "称（chēng，第一声）与 zhēng 声母不同（ch 与 zh），意思是称呼。"}, {"text": "中", "is_correct": false, "explanation": "中（zhōng，第一声）与 zhēng 韵母不同（ōng 与 ēng），意思是中间。"}], "explanations": {"争": "争（zhēng，第一声）：争夺、力求获得，正是本词。", "生": "生（shēng，第一声）与 zhēng 声母不同（sh 与 zh），意思是生长。", "珍": "珍（zhēn，第一声）与 zhēng 韵母不同（-n 与 -ng），意思是珍贵。", "政": "政（zhèng，第四声）与 zhēng 声调不同，意思是政治。", "称": "称（chēng，第一声）与 zhēng 声母不同（ch 与 zh），意思是称呼。", "中": "中（zhōng，第一声）与 zhēng 韵母不同（ōng 与 ēng），意思是中间。"}, "sentence_index": null, "correct_answer": "争"}, "level_3": {"options": [{"text": "争", "is_correct": true, "explanation": "争：小王想争取这个名额，所以特别努力，与语境一致。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语是食物，名额不能吃，“吃这个名额”说不通。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”指丢弃，与“想”的愿望矛盾。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的宾语是歌曲，不能说“唱这个名额”。"}], "explanations": {"争": "争：小王想争取这个名额，所以特别努力，与语境一致。", "吃": "搭配：“吃”的宾语是食物，名额不能吃，“吃这个名额”说不通。", "扔": "语义：“扔”指丢弃，与“想”的愿望矛盾。", "唱": "搭配：“唱”的宾语是歌曲，不能说“唱这个名额”。"}, "sentence_index": 6, "correct_answer": "争"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一把争走了我的书包，真讨厌。", "explanation": "这里应该用〈抢〉。抢是强行夺取，不是多人都想要同一样东西而竞相取得，不能用“争”。"}, {"text": "他每天晚上都争着睡觉。", "explanation": "这里应该用〈休息〉。“争”要求争夺有限的东西，睡觉不是可以争夺的对象，不能说“争着睡觉”。"}, {"text": "他每天都在争自己的影子。", "explanation": "这里应该用〈追〉。影子不能被争夺，应说“追影子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b55e6d1-d065-468e-8962-434097609120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92842, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "三支队伍都想争了冠军。", "corrected_sentence": "三支队伍都想争冠军。", "error_description": "错误形式：“争了冠军”；正确形式：“争冠军”。“想”表示意愿，还没有发生，不能和表示完成的“了”连用，“争”后应直接接宾语“冠军”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b55e6d1-d065-468e-8962-434097609120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92842, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两队为了第一名争很厉害。", "corrected_sentence": "两队为了第一名争得很厉害。", "error_description": "错误形式：“争很厉害”；正确形式：“争得很厉害”。表示程度的补语要用“得”连接动词和补语，“争”后漏掉了“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b55e6d1-d065-468e-8962-434097609120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92843, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "飞", "is_correct": false, "explanation": "“飞”指在空中移动，与“沉”没有反义关系。"}, {"text": "浮", "is_correct": true, "explanation": "“浮”与“沉”相对，指东西漂在水面上。"}, {"text": "唱", "is_correct": false, "explanation": "“唱”指发出歌声，与“沉”没有反义关系。"}, {"text": "写", "is_correct": false, "explanation": "“写”指用笔记录文字，与“沉”没有反义关系。"}], "correct_answer": "浮", "explanations": {"飞": "“飞”指在空中移动，与“沉”没有反义关系。", "浮": "“浮”与“沉”相对，指东西漂在水面上。", "唱": "“唱”指发出歌声，与“沉”没有反义关系。", "写": "“写”指用笔记录文字，与“沉”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f1ba74c-3a11-4bcb-904b-2e1ea4ec7fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92843, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "跳", "is_correct": false, "explanation": "“跳”指身体离地向上，与“沉”没有反义关系。"}, {"text": "浮", "is_correct": true, "explanation": "“浮”与“沉”相对，指东西漂在水面上。"}, {"text": "跑", "is_correct": false, "explanation": "“跑”指快速移动脚步，与“沉”没有反义关系。"}, {"text": "笑", "is_correct": false, "explanation": "“笑”指露出笑容或发出笑声，与“沉”没有反义关系。"}], "correct_answer": "浮", "explanations": {"跳": "“跳”指身体离地向上，与“沉”没有反义关系。", "浮": "“浮”与“沉”相对，指东西漂在水面上。", "跑": "“跑”指快速移动脚步，与“沉”没有反义关系。", "笑": "“笑”指露出笑容或发出笑声，与“沉”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f1ba74c-3a11-4bcb-904b-2e1ea4ec7fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92843, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "沉是东西掉到水里，一直往下去。", "primary_collocate": null, "pronunciation": "chén", "ipa": "ʈʂʰən˧˥", "syllable_count": 1, "sentences": [{"text": "石头扔进水里，很快就沉了。", "target_word": "沉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船撞到石头以后，慢慢沉下去了。", "target_word": "沉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铁块放进水里会沉，木头不会。", "target_word": "沉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小船太旧了，一到河中间就沉了。", "target_word": "沉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只杯子掉进湖里，沉到了底。", "target_word": "沉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把石头丢进河里，石头沉了下去。", "target_word": "沉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙子放进水里，很快沉到杯底。", "target_word": "沉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大船沉在海里已经一百年了。", "target_word": "沉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸡蛋放进清水里就沉，放进盐水里就浮。", "target_word": "沉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水太深，扔下去的东西都沉了。", "target_word": "沉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "沉了", "label": "体标（了）"}, {"form": "沉下去", "label": "复合"}], "register": "中性", "sense_fingerprint": "东西落入水中并往下去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f25efb-a327-4991-90ce-e83d14deee0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92843, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "沉", "is_correct": true, "explanation": "沉 chén 是本词，指东西落入水中并往下去。"}, {"text": "成", "is_correct": false, "explanation": "成 chéng 与 chén 韵母不同（-eng 对 -en），意思是成功、完成，不是沉下去。"}, {"text": "馋", "is_correct": false, "explanation": "馋 chán 与 chén 韵母不同（-an 对 -en），意思是贪吃、想吃。"}, {"text": "衬", "is_correct": false, "explanation": "衬 chèn 与 chén 声调不同（第四声），意思是衬托、衬衣。"}, {"text": "神", "is_correct": false, "explanation": "神 shén 与 chén 声母不同（sh 对 ch），意思是神灵、精神。"}], "explanations": {"沉": "沉 chén 是本词，指东西落入水中并往下去。", "成": "成 chéng 与 chén 韵母不同（-eng 对 -en），意思是成功、完成，不是沉下去。", "馋": "馋 chán 与 chén 韵母不同（-an 对 -en），意思是贪吃、想吃。", "衬": "衬 chèn 与 chén 声调不同（第四声），意思是衬托、衬衣。", "神": "神 shén 与 chén 声母不同（sh 对 ch），意思是神灵、精神。"}, "sentence_index": null, "correct_answer": "沉"}, "level_3": {"options": [{"text": "游", "is_correct": false, "explanation": "语义：石头不会游，句子说的是石头落入水中后往下去。"}, {"text": "沉", "is_correct": true, "explanation": "正确：石头扔进水里后往下去，用“沉”。"}, {"text": "浮", "is_correct": false, "explanation": "语义：“浮”指漂在水面，与石头扔进水里后往下去相反。"}, {"text": "溶", "is_correct": false, "explanation": "搭配：“溶”多用于盐、糖等溶于水，石头不会很快溶化。"}], "explanations": {"游": "语义：石头不会游，句子说的是石头落入水中后往下去。", "沉": "正确：石头扔进水里后往下去，用“沉”。", "浮": "语义：“浮”指漂在水面，与石头扔进水里后往下去相反。", "溶": "搭配：“溶”多用于盐、糖等溶于水，石头不会很快溶化。"}, "sentence_index": 0, "correct_answer": "沉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小鸟沉到了屋顶上。", "explanation": "这里应该用〈落〉。沉指东西没入水中并往下去，小鸟落到屋顶上只能说落，不能说沉。"}, {"text": "杯子从桌上沉到了地上。", "explanation": "这里应该用〈掉〉。沉只用于物体落入水中，杯子从桌上落到地上只能说掉。"}, {"text": "孩子沉到了沙发底下。", "explanation": "这里应该用〈钻〉。沉指东西没入水中并往下去，人钻进沙发底下不能说沉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f1ba74c-3a11-4bcb-904b-2e1ea4ec7fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92843, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "城", "is_correct": false, "explanation": "城 chéng 与 chén 韵母不同（-eng 对 -en），意思是城市、城墙。"}, {"text": "沉", "is_correct": true, "explanation": "沉 chén 是本词，指东西落入水中并往下去。"}, {"text": "缠", "is_correct": false, "explanation": "缠 chán 与 chén 韵母不同（-an 对 -en），意思是缠绕。"}, {"text": "趁", "is_correct": false, "explanation": "趁 chèn 与 chén 声调不同（第四声），意思是趁着、利用。"}, {"text": "程", "is_correct": false, "explanation": "程 chéng 与 chén 韵母不同（-eng 对 -en），意思是路程、过程。"}], "explanations": {"城": "城 chéng 与 chén 韵母不同（-eng 对 -en），意思是城市、城墙。", "沉": "沉 chén 是本词，指东西落入水中并往下去。", "缠": "缠 chán 与 chén 韵母不同（-an 对 -en），意思是缠绕。", "趁": "趁 chèn 与 chén 声调不同（第四声），意思是趁着、利用。", "程": "程 chéng 与 chén 韵母不同（-eng 对 -en），意思是路程、过程。"}, "sentence_index": null, "correct_answer": "沉"}, "level_3": {"options": [{"text": "飘", "is_correct": false, "explanation": "语义：“飘”指浮在水面或空中，与沙子落到杯底相反。"}, {"text": "溅", "is_correct": false, "explanation": "搭配：“溅”指液体向外飞散，沙子不会溅到杯底。"}, {"text": "沉", "is_correct": true, "explanation": "正确：沙子放进水里后往下去，到达杯底，用“沉”。"}, {"text": "抛", "is_correct": false, "explanation": "配价：“抛”需要有人把东西扔出去，沙子自己不能抛到杯底。"}], "explanations": {"飘": "语义：“飘”指浮在水面或空中，与沙子落到杯底相反。", "溅": "搭配：“溅”指液体向外飞散，沙子不会溅到杯底。", "沉": "正确：沙子放进水里后往下去，到达杯底，用“沉”。", "抛": "配价：“抛”需要有人把东西扔出去，沙子自己不能抛到杯底。"}, "sentence_index": 6, "correct_answer": "沉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个湖很沉，船不能靠近。", "explanation": "这里应该用〈深〉。沉指东西掉到水里并一直往下去，说湖的深浅要用深。"}, {"text": "气球沉在了天花板上。", "explanation": "这里应该用〈飘〉。沉指东西没入水中并往下去，气球飘在天花板上只能说飘，不能说沉。"}, {"text": "他沉在门口，一直没有进来。", "explanation": "这里应该用〈站〉。沉指东西没入水中或往下落，人站在门口不能说沉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f1ba74c-3a11-4bcb-904b-2e1ea4ec7fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92843, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "铁块沉上去了，很快就看不见了。", "corrected_sentence": "铁块沉下去了，很快就看不见了。", "error_description": "方向补语用反：沉指东西往下去，应说“沉下去”，“沉上去”方向相反，不能用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f1ba74c-3a11-4bcb-904b-2e1ea4ec7fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92843, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这艘旧船没沉了下去，大家都松了口气。", "corrected_sentence": "这艘旧船没沉下去，大家都松了口气。", "error_description": "错误：“没”否定的是未发生的动作，动词后面不能再加“了”，应删去“了”，说“没沉下去”，不能说“没沉了下去”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f1ba74c-3a11-4bcb-904b-2e1ea4ec7fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
