INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92845, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "物资是生活和做事要用的各种东西。", "primary_collocate": null, "pronunciation": "wù zī", "ipa": "u˥˩ tsɨ˥˥", "syllable_count": 2, "sentences": [{"text": "家里的物资够用一个月。", "target_word": "物资", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "去山里露营，要带够物资。", "target_word": "物资", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这批物资很重要，要放在仓库里。", "target_word": "物资", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地震后，各地送来了很多物资。", "target_word": "物资", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校把物资分给了需要的同学。", "target_word": "物资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村的物资很丰富，大家不愁吃穿。", "target_word": "物资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雪封了山路，村里的物资越来越少。", "target_word": "物资", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "志愿者把物资一箱一箱搬上了车。", "target_word": "物资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出发以前，大家检查了一遍带的物资。", "target_word": "物资", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天快到了，山上的人需要更多物资。", "target_word": "物资", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一批物资", "label": "量词"}, {"form": "救灾物资", "label": "复合"}, {"form": "生活物资", "label": "复合"}], "register": "中性", "sense_fingerprint": "生活和做事要用的各种东西，如食物、用品、工具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd2a1ec9-6f0b-449f-8068-f924ac67d7eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92845, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "物资", "is_correct": true, "explanation": "物资（wù zī）指生活和做事要用的各种东西，是正确答案。"}, {"text": "舞姿", "is_correct": false, "explanation": "wǔ（第三声）与 wù（第四声）声调不同，舞姿指舞蹈的姿势。"}, {"text": "污渍", "is_correct": false, "explanation": "wū（第一声）与 wù 声调不同，zì（第四声）与 zī（第一声）声调也不同，污渍指污迹。"}, {"text": "误机", "is_correct": false, "explanation": "jī（第一声）与 zī 声母不同（j 与 z），误机指错过航班。"}], "explanations": {"物资": "物资（wù zī）指生活和做事要用的各种东西，是正确答案。", "舞姿": "wǔ（第三声）与 wù（第四声）声调不同，舞姿指舞蹈的姿势。", "污渍": "wū（第一声）与 wù 声调不同，zì（第四声）与 zī（第一声）声调也不同，污渍指污迹。", "误机": "jī（第一声）与 zī 声母不同（j 与 z），误机指错过航班。"}, "sentence_index": null, "correct_answer": "物资"}, "level_3": {"options": [{"text": "物资", "is_correct": true, "explanation": "物资指生活所需的各种东西，与“够用一个月”搭配，符合句意。"}, {"text": "房间", "is_correct": false, "explanation": "语义：房间是空间，不能像物资那样被“够用一个月”消耗。"}, {"text": "学生", "is_correct": false, "explanation": "语义：学生是人，不是可以按月计算够不够用的东西。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“够用一个月”多说可以消耗的东西，空气一般不这样计算用量。"}], "explanations": {"物资": "物资指生活所需的各种东西，与“够用一个月”搭配，符合句意。", "房间": "语义：房间是空间，不能像物资那样被“够用一个月”消耗。", "学生": "语义：学生是人，不是可以按月计算够不够用的东西。", "空气": "搭配：“够用一个月”多说可以消耗的东西，空气一般不这样计算用量。"}, "sentence_index": 0, "correct_answer": "物资"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "地震后，他成了村里的物资。", "explanation": "这里把人当作物资，但物资指生活和做事要用的各种东西，不指人。"}, {"text": "地震后，各地送来了一只物资。", "explanation": "这里应该用〈批〉。物资用“批”计量，“只”多用于动物等，不能用于物资。"}, {"text": "地震后，那座山成了村里的物资。", "explanation": "这里把地方当作物资，但物资指生活和做事要用的各种东西，不指山这样的地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9bab58-da2f-4ece-9e35-f06ef4287688') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92845, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "物资", "is_correct": true, "explanation": "物资（wù zī）指生活和做事要用的各种东西，是正确答案。"}, {"text": "五指", "is_correct": false, "explanation": "wǔ（第三声）与 wù 声调不同，zhǐ 与 zī 声母和声调都不同，五指指五根手指。"}, {"text": "路资", "is_correct": false, "explanation": "lù（第四声）与 wù 声母不同（l 与 w），路资指路上的费用。"}, {"text": "误期", "is_correct": false, "explanation": "qī（第一声）与 zī 声母不同（q 与 z），误期指耽误期限。"}], "explanations": {"物资": "物资（wù zī）指生活和做事要用的各种东西，是正确答案。", "五指": "wǔ（第三声）与 wù 声调不同，zhǐ 与 zī 声母和声调都不同，五指指五根手指。", "路资": "lù（第四声）与 wù 声母不同（l 与 w），路资指路上的费用。", "误期": "qī（第一声）与 zī 声母不同（q 与 z），误期指耽误期限。"}, "sentence_index": null, "correct_answer": "物资"}, "level_3": {"options": [{"text": "物资", "is_correct": true, "explanation": "物资指村里的生活用品，与“越来越少”搭配，符合句意。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳不能按村里的数量逐渐减少，句意不通。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是可以在村里增减的东西，句意不通。"}, {"text": "面貌", "is_correct": false, "explanation": "搭配：“越来越少”说数量，“面貌”不能计数，不说面貌越来越少。"}], "explanations": {"物资": "物资指村里的生活用品，与“越来越少”搭配，符合句意。", "太阳": "语义：太阳不能按村里的数量逐渐减少，句意不通。", "天空": "语义：天空不是可以在村里增减的东西，句意不通。", "面貌": "搭配：“越来越少”说数量，“面貌”不能计数，不说面貌越来越少。"}, "sentence_index": 6, "correct_answer": "物资"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "冬天快到了，这个道理成了山上的物资。", "explanation": "这里把道理当作物资，但物资指生活和做事要用的各种东西，不指抽象的道理。"}, {"text": "冬天快到了，山上的人需要一颗物资。", "explanation": "这里应该用〈批〉。物资用“批”计量，“颗”用于颗粒状或圆形的小东西，不用于物资。"}, {"text": "冬天快到了，一场大雪成了山上的物资。", "explanation": "这里把大雪当作物资，但物资指生活和做事要用的各种东西，不指天气现象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9bab58-da2f-4ece-9e35-f06ef4287688') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92845, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "仓库里堆着一个物资。", "corrected_sentence": "仓库里堆着一批物资。", "error_description": "“一个物资”错误，应说“一批物资”。物资应搭配量词“批”，“个”不能用于物资。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9bab58-da2f-4ece-9e35-f06ef4287688') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92845, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "救灾队把一个物资送到了村里。", "corrected_sentence": "救灾队把一批物资送到了村里。", "error_description": "“一个物资”错误，应说“一批物资”。物资应搭配量词“批”，“个”不能用于物资。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9bab58-da2f-4ece-9e35-f06ef4287688') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
