INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92846, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "生产和生活所需的物质资料。", "primary_collocate": null, "pronunciation": "wù zī", "ipa": "u˥˩ tsɨ˥˥", "syllable_count": 2, "sentences": [{"text": "工厂缺少生产物资。", "target_word": "物资", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "国家正在储备重要物资。", "target_word": "物资", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "战争时期，物资非常缺乏。", "target_word": "物资", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家公司负责运送物资到各个城市。", "target_word": "物资", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "洪水来了，政府马上调来大量物资。", "target_word": "物资", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人们把生产物资放进了新仓库。", "target_word": "物资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家要保证人民生活所需的物资。", "target_word": "物资", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "物资运不进去，城里的人只能等着。", "target_word": "物资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些物资的价格最近涨得很快。", "target_word": "物资", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司买了一批物资，准备送给山区的学校。", "target_word": "物资", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一批物资", "label": "量词"}, {"form": "生产物资", "label": "复合"}, {"form": "战略物资", "label": "复合"}], "register": "中性", "sense_fingerprint": "生产和生活所需的物质资料，多指国家、单位调配储备的物品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd2a1ec9-6f0b-449f-8068-f924ac67d7eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92846, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "物资", "is_correct": true, "explanation": "物资（wù zī）指生产和生活所需的物质资料，是正确答案。"}, {"text": "舞姿", "is_correct": false, "explanation": "wǔ（第三声）与 wù（第四声）声调不同，舞姿指舞蹈的姿势。"}, {"text": "污渍", "is_correct": false, "explanation": "wū（第一声）与 wù 声调不同，zì（第四声）与 zī（第一声）声调也不同，污渍指污迹。"}, {"text": "误机", "is_correct": false, "explanation": "jī（第一声）与 zī 声母不同（j 与 z），误机指错过航班。"}], "explanations": {"物资": "物资（wù zī）指生产和生活所需的物质资料，是正确答案。", "舞姿": "wǔ（第三声）与 wù（第四声）声调不同，舞姿指舞蹈的姿势。", "污渍": "wū（第一声）与 wù 声调不同，zì（第四声）与 zī（第一声）声调也不同，污渍指污迹。", "误机": "jī（第一声）与 zī 声母不同（j 与 z），误机指错过航班。"}, "sentence_index": null, "correct_answer": "物资"}, "level_3": {"options": [{"text": "物资", "is_correct": true, "explanation": "物资指生产和生活所需的物质资料，与“缺少”搭配，符合句意。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳不是工厂需要补充的东西，句意不通。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是工厂可以缺少的生产要素，句意不通。"}, {"text": "面貌", "is_correct": false, "explanation": "搭配：“缺少”的宾语多是具体的东西，“面貌”不说缺少。"}], "explanations": {"物资": "物资指生产和生活所需的物质资料，与“缺少”搭配，符合句意。", "太阳": "语义：太阳不是工厂需要补充的东西，句意不通。", "天空": "语义：天空不是工厂可以缺少的生产要素，句意不通。", "面貌": "搭配：“缺少”的宾语多是具体的东西，“面貌”不说缺少。"}, "sentence_index": 0, "correct_answer": "物资"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司成了城市的物资。", "explanation": "这里把公司当作物资，但物资指生产和生活所需的物质资料，不指企业。"}, {"text": "这家公司负责运送一只物资到各个城市。", "explanation": "这里应该用〈批〉。物资用“批”计量，“只”不能用于物资。"}, {"text": "这座仓库成了山里的物资。", "explanation": "这里把仓库当作物资，但物资指生产和生活所需的物质资料，不指建筑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9bab58-da2f-4ece-9e35-f06ef4287688') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92846, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "物资", "is_correct": true, "explanation": "物资（wù zī）指生产和生活所需的物质资料，是正确答案。"}, {"text": "五指", "is_correct": false, "explanation": "wǔ（第三声）与 wù 声调不同，zhǐ 与 zī 声母和声调都不同，五指指五根手指。"}, {"text": "路资", "is_correct": false, "explanation": "lù（第四声）与 wù 声母不同（l 与 w），路资指路上的费用。"}, {"text": "误期", "is_correct": false, "explanation": "qī（第一声）与 zī 声母不同（q 与 z），误期指耽误期限。"}], "explanations": {"物资": "物资（wù zī）指生产和生活所需的物质资料，是正确答案。", "五指": "wǔ（第三声）与 wù 声调不同，zhǐ 与 zī 声母和声调都不同，五指指五根手指。", "路资": "lù（第四声）与 wù 声母不同（l 与 w），路资指路上的费用。", "误期": "qī（第一声）与 zī 声母不同（q 与 z），误期指耽误期限。"}, "sentence_index": null, "correct_answer": "物资"}, "level_3": {"options": [{"text": "物资", "is_correct": true, "explanation": "物资指生产和生活所需的物质资料，与“生活所需”搭配，符合句意。"}, {"text": "学生", "is_correct": false, "explanation": "语义：学生是人，不是国家为保证生活而提供的物质。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字不是生活所需的物质，句意不通。"}, {"text": "面孔", "is_correct": false, "explanation": "搭配：“保证”的宾语多是权利或生活条件，不说保证面孔。"}], "explanations": {"物资": "物资指生产和生活所需的物质资料，与“生活所需”搭配，符合句意。", "学生": "语义：学生是人，不是国家为保证生活而提供的物质。", "名字": "语义：名字不是生活所需的物质，句意不通。", "面孔": "搭配：“保证”的宾语多是权利或生活条件，不说保证面孔。"}, "sentence_index": 6, "correct_answer": "物资"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个道理成了山区学校的物资。", "explanation": "这里把道理当作物资，但物资指生产和生活所需的物质资料，不指抽象的道理。"}, {"text": "公司买了一颗物资，准备送给山区的学校。", "explanation": "这里应该用〈批〉。物资用“批”计量，“颗”不能用于物资。"}, {"text": "一场大雨成了山区学校的物资。", "explanation": "这里把大雨当作物资，但物资指生产和生活所需的物质资料，不指天气现象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9bab58-da2f-4ece-9e35-f06ef4287688') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92846, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "货车上装着一个物资。", "corrected_sentence": "货车上装着一批物资。", "error_description": "“一个物资”错误，应说“一批物资”。物资应搭配量词“批”，“个”不能用于物资。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9bab58-da2f-4ece-9e35-f06ef4287688') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92846, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人们把一个物资运到了车站。", "corrected_sentence": "工人们把一批物资运到了车站。", "error_description": "“一个物资”错误，应说“一批物资”。物资应搭配量词“批”，“个”不能用于物资。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9bab58-da2f-4ece-9e35-f06ef4287688') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
