INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92849, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "病人是生了病的人。", "primary_collocate": null, "pronunciation": "bìng rén", "ipa": "piŋ˥˩ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "他是个病人，需要多休息。", "target_word": "病人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我奶奶是病人，不能吃太咸的菜。", "target_word": "病人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "病人的脸色很不好。", "target_word": "病人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "邻居家有个病人，我们常去看看他。", "target_word": "病人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "病人要吃清淡的东西。", "target_word": "病人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个病人从早到晚一直在咳嗽。", "target_word": "病人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别吵了，家里有病人在睡觉。", "target_word": "病人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他照顾病人照顾了三年，一点儿也不觉得累。", "target_word": "病人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人的心情好，病也会好得快一些。", "target_word": "病人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈给病人煮了一碗热热的粥。", "target_word": "病人", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位病人", "label": "量词"}, {"form": "一个病人", "label": "量词"}, {"form": "病人们", "label": "复数"}], "register": "中性", "sense_fingerprint": "生了病的人，泛指日常生活中需要休息和照顾的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd2a1ec9-6f0b-449f-8068-f924ac67d7eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92849, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "病人", "is_correct": true, "explanation": "正确：“病人”指生了病的人，“他是个病人，需要多休息”成立。"}, {"text": "词典", "is_correct": false, "explanation": "语义：词典是工具书，不是人，也不需要休息。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”是抽象名词，不能用“个”来数，也不能说“他是个天气”。"}, {"text": "铅笔", "is_correct": false, "explanation": "语义：铅笔是文具，“他”指人，两者不能等同。"}], "explanations": {"病人": "正确：“病人”指生了病的人，“他是个病人，需要多休息”成立。", "词典": "语义：词典是工具书，不是人，也不需要休息。", "天气": "搭配：“天气”是抽象名词，不能用“个”来数，也不能说“他是个天气”。", "铅笔": "语义：铅笔是文具，“他”指人，两者不能等同。"}, "sentence_index": 0, "correct_answer": "病人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "剧院里的座椅是病人，都需要多休息。", "explanation": "这里把座椅当作病人，但“病人”指生病的人，座椅不是人，不能用〈病人〉。"}, {"text": "超市里的货架是病人，都需要人照顾。", "explanation": "这里把货架当作病人，但“病人”指生病的人，货架不是人，不能用〈病人〉。"}, {"text": "我们学校的操场是病人，每天都要休息。", "explanation": "这里把操场当作病人，但“病人”指生病的人，操场不是人，不能用〈病人〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9bab58-da2f-4ece-9e35-f06ef4287688') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92849, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "病人", "is_correct": true, "explanation": "正确：“病人”指生了病的人，可以在家里睡觉，符合“别吵了”的语境。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视不会睡觉，“睡觉”的主语要是人或动物。"}, {"text": "空调", "is_correct": false, "explanation": "配价：“睡觉”要求有生命的主语，空调不能睡觉。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑部件，没有生命，不会睡觉。"}], "explanations": {"病人": "正确：“病人”指生了病的人，可以在家里睡觉，符合“别吵了”的语境。", "电视": "语义：电视不会睡觉，“睡觉”的主语要是人或动物。", "空调": "配价：“睡觉”要求有生命的主语，空调不能睡觉。", "窗户": "语义：窗户是建筑部件，没有生命，不会睡觉。"}, "sentence_index": 6, "correct_answer": "病人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家的狗昨天是病人，需要人照顾。", "explanation": "“病人”只指人。狗生病应说〈生病的狗〉，不能用〈病人〉。"}, {"text": "院子里的树是病人，叶子掉了很多。", "explanation": "“病人”只指人。树生病应说〈生病的树〉，不能用〈病人〉。"}, {"text": "我家的鸡是病人，最近不下蛋。", "explanation": "“病人”只指人。鸡生病应说〈生病的鸡〉，不能用〈病人〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9bab58-da2f-4ece-9e35-f06ef4287688') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92849, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我爷爷病人，不能吃太咸的菜。", "corrected_sentence": "我爷爷是病人，不能吃太咸的菜。", "error_description": "漏了“是”：“病人”作谓语时要加“是”，应说“是病人”，漏掉“是”不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9bab58-da2f-4ece-9e35-f06ef4287688') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92849, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "别吵了，家里有一只病人在睡觉。", "corrected_sentence": "别吵了，家里有一位病人在睡觉。", "error_description": "量词用错：“只”用于动物或物品，“病人”指人，应用“位”或“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9bab58-da2f-4ece-9e35-f06ef4287688') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
