INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92850, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "患病的人，特指接受治疗的人。", "primary_collocate": null, "pronunciation": "bìng rén", "ipa": "piŋ˥˩ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "医生正在给病人检查身体。", "target_word": "病人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位病人今天要做手术。", "target_word": "病人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "护士每天按时给病人量体温。", "target_word": "病人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "病人躺在床上，不能下地走路。", "target_word": "病人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院里有很多病人在排队挂号。", "target_word": "病人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生让病人多喝水，好好休息。", "target_word": "病人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "病人的家人一直守在病房外面。", "target_word": "病人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨天来了一位发高烧的病人，医生马上给他打了针。", "target_word": "病人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院的病人越来越多，床位不够用。", "target_word": "病人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说这个病人吃过药，现在好多了。", "target_word": "病人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位病人", "label": "量词"}, {"form": "一名病人", "label": "量词"}, {"form": "病人们", "label": "复数"}], "register": "中性", "sense_fingerprint": "接受医生治疗的患者，多用于医院、看病的场合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd2a1ec9-6f0b-449f-8068-f924ac67d7eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92850, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "病人", "is_correct": true, "explanation": "正确：“病人”是接受治疗的人，符合“医生正在给…检查身体”的语境。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：“检查身体”只用于人或动物，汽车没有身体。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“检查”可以搭“作业”，但“检查身体”的对象只能是人或动物。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是场所，不能接受身体检查。"}], "explanations": {"病人": "正确：“病人”是接受治疗的人，符合“医生正在给…检查身体”的语境。", "汽车": "语义：“检查身体”只用于人或动物，汽车没有身体。", "作业": "搭配：“检查”可以搭“作业”，但“检查身体”的对象只能是人或动物。", "教室": "语义：教室是场所，不能接受身体检查。"}, "sentence_index": 0, "correct_answer": "病人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家餐厅的招牌是病人，经常要排队。", "explanation": "这里把招牌当作病人，但“病人”指生病的人，招牌不是人，不能用〈病人〉。"}, {"text": "这辆公交车是病人，上下班时特别挤。", "explanation": "这里把公交车当作病人，但“病人”指生病的人，公交车不是人，不能用〈病人〉。"}, {"text": "我家的猫今天是病人，不吃东西。", "explanation": "“病人”只指人。猫生病应说〈生病的猫〉，不能用〈病人〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9bab58-da2f-4ece-9e35-f06ef4287688') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92850, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "病人", "is_correct": true, "explanation": "正确：“病人”指接受治疗的人，可以有家人在病房外等候。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有家人，不能作“家人”的所属者。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“家人”指人的亲属，手机不能有家人。"}, {"text": "铅笔", "is_correct": false, "explanation": "语义：铅笔是文具，没有家人，也不会守在病房外面。"}], "explanations": {"病人": "正确：“病人”指接受治疗的人，可以有家人在病房外等候。", "石头": "语义：石头没有家人，不能作“家人”的所属者。", "手机": "搭配：“家人”指人的亲属，手机不能有家人。", "铅笔": "语义：铅笔是文具，没有家人，也不会守在病房外面。"}, "sentence_index": 6, "correct_answer": "病人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "周末家里的电视是病人，妈妈做了很多好菜招待它。", "explanation": "这里把电视当作病人，但“病人”指生病的人，电视不是人，不能用〈病人〉。"}, {"text": "教室里的黑板是病人，它正在认真听课。", "explanation": "这里把黑板当作病人，但“病人”指生病的人，黑板不是人，不能用〈病人〉。"}, {"text": "路口的红绿灯是病人，正在指挥交通。", "explanation": "这里把红绿灯当作病人，但“病人”指生病的人，红绿灯不是人，不能用〈病人〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9bab58-da2f-4ece-9e35-f06ef4287688') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92850, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医生正在给一只病人检查身体。", "corrected_sentence": "医生正在给一位病人检查身体。", "error_description": "量词用错：“病人”指人，量词应用“位”或“名”，“只”多用于动物或物品，不能用来数人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9bab58-da2f-4ece-9e35-f06ef4287688') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92850, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医生说这头病人吃过药，现在好多了。", "corrected_sentence": "医生说这位病人吃过药，现在好多了。", "error_description": "量词用错：“头”用于牛、猪等动物，“病人”指人，应用“位”或“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9bab58-da2f-4ece-9e35-f06ef4287688') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
