INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92853, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "研究所是很多人一起研究学问的地方。", "primary_collocate": null, "pronunciation": "yán jiū suǒ", "ipa": "jɛn˧˥ tɕjoʊ̯˥ suɔ˨˩˦", "syllable_count": 3, "sentences": [{"text": "我姐姐在一家研究所工作。", "target_word": "研究所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个研究所离我家很近。", "target_word": "研究所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他大学毕业后进了研究所。", "target_word": "研究所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究所里有很多年轻的学者。", "target_word": "研究所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个研究所做过很多重要的研究。", "target_word": "研究所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天我要去研究所开会。", "target_word": "研究所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究所的图书馆很大，也很安静。", "target_word": "研究所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他下个月要去研究所参观实验室。", "target_word": "研究所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家研究所有一百多个研究人员。", "target_word": "研究所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究所的同事们常常一起讨论问题。", "target_word": "研究所", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "家", "label": "量词"}], "register": "中性", "sense_fingerprint": "很多人一起研究学问的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f09b97c-38a8-4ff2-bcb2-0a886cdc7162') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92853, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学生", "is_correct": false, "explanation": "搭配：量词“家”只用于机构、店铺等，不能数人，“一家学生”不通。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是自然景物，不是可以工作的单位。"}, {"text": "研究所", "is_correct": true, "explanation": "研究所是做研究的机构，“在一家研究所工作”说得通。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是单位，不能在那里工作。"}], "explanations": {"学生": "搭配：量词“家”只用于机构、店铺等，不能数人，“一家学生”不通。", "河流": "语义：河流是自然景物，不是可以工作的单位。", "研究所": "研究所是做研究的机构，“在一家研究所工作”说得通。", "天空": "语义：天空不是单位，不能在那里工作。"}, "sentence_index": 0, "correct_answer": "研究所"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我妈妈每天去研究所买菜。", "explanation": "这里应该用〈菜市场〉。买菜要去菜市场，研究所是做研究的机构，不是买东西的地方。"}, {"text": "这家研究所每天生产很多零件。", "explanation": "这里应该用〈工厂〉。研究所以科学研究为主，大批量生产零件要用工厂。"}, {"text": "这个研究所每天接待很多游客。", "explanation": "这里应该用〈景点〉。供游客参观、接待游客的地方要说景点，研究所不做这些。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f13dd8b-44f3-452d-9085-3d547cbca762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92853, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "研究所", "is_correct": true, "explanation": "研究所是机构，有自己的图书馆，“研究所的图书馆很大，也很安静”说得通。"}, {"text": "苹果", "is_correct": false, "explanation": "语义：苹果是水果，不是机构，没有图书馆，这句话说不通。"}, {"text": "电影", "is_correct": false, "explanation": "语义：电影是影片，不是机构，没有图书馆，这句话说不通。"}, {"text": "早饭", "is_correct": false, "explanation": "语义：早饭是食物，不是机构，没有图书馆，这句话说不通。"}], "explanations": {"研究所": "研究所是机构，有自己的图书馆，“研究所的图书馆很大，也很安静”说得通。", "苹果": "语义：苹果是水果，不是机构，没有图书馆，这句话说不通。", "电影": "语义：电影是影片，不是机构，没有图书馆，这句话说不通。", "早饭": "语义：早饭是食物，不是机构，没有图书馆，这句话说不通。"}, "sentence_index": 6, "correct_answer": "研究所"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "研究所的演员每天都要排练。", "explanation": "这里应该用〈剧院〉。演员排练演出是剧院的工作，研究所是做研究的地方。"}, {"text": "研究所的法官常常要判案子。", "explanation": "这里应该用〈法院〉。判案子是法院的职责，研究所不做这类工作。"}, {"text": "研究所的工作人员每天接送旅客。", "explanation": "这里应该用〈火车站〉。接送旅客是车站的工作，研究所不接送旅客。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f13dd8b-44f3-452d-9085-3d547cbca762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92853, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每天研究所上班。", "corrected_sentence": "他每天在研究所上班。", "error_description": "“在研究所上班”中的“在”引出工作地点，不能省略，“研究所上班”不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f13dd8b-44f3-452d-9085-3d547cbca762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92853, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我妈妈在一条研究所工作。", "corrected_sentence": "我妈妈在一家研究所工作。", "error_description": "“条”用于细长的东西，“研究所”是机构，量词应该用“家”。错误形式：一条研究所；正确形式：一家研究所。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f13dd8b-44f3-452d-9085-3d547cbca762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
