INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92854, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "专门从事科学研究的机构。", "primary_collocate": null, "pronunciation": "yán jiū suǒ", "ipa": "jɛn˧˥ tɕjoʊ̯˥ suɔ˨˩˦", "syllable_count": 3, "sentences": [{"text": "这家研究所专门研究天气。", "target_word": "研究所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家建了一个新的医学研究所。", "target_word": "研究所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究所的科学家发明了新材料。", "target_word": "研究所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个研究所每年都发表很多论文。", "target_word": "研究所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农业研究所培育了一种新的水稻。", "target_word": "研究所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在海洋研究所做了十年研究。", "target_word": "研究所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个研究所得到了国家的支持。", "target_word": "研究所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究所里的实验室需要保持干净。", "target_word": "研究所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国有很多研究所研究环境问题。", "target_word": "研究所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究所的专家来学校做了一场报告。", "target_word": "研究所", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "家", "label": "量词"}], "register": "中性", "sense_fingerprint": "专门从事科学研究的机构", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f09b97c-38a8-4ff2-bcb2-0a886cdc7162') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92854, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "餐厅", "is_correct": false, "explanation": "语义：餐厅是卖饭菜的地方，不做天气研究，这句话说不通。"}, {"text": "研究所", "is_correct": true, "explanation": "研究所是专门从事科学研究的机构，“专门研究天气”说得通。"}, {"text": "银行", "is_correct": false, "explanation": "语义：银行做金融业务，不专门研究天气。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能研究天气，这句话说不通。"}], "explanations": {"餐厅": "语义：餐厅是卖饭菜的地方，不做天气研究，这句话说不通。", "研究所": "研究所是专门从事科学研究的机构，“专门研究天气”说得通。", "银行": "语义：银行做金融业务，不专门研究天气。", "石头": "语义：石头不能研究天气，这句话说不通。"}, "sentence_index": 0, "correct_answer": "研究所"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家研究所每天播出很多节目。", "explanation": "这里应该用〈电视台〉。播出节目是电视台的工作，研究所不做节目播出。"}, {"text": "这家研究所每天给很多人理发。", "explanation": "这里应该用〈理发店〉。给人理发要去理发店，研究所不提供这类服务。"}, {"text": "这家研究所每年演出很多场。", "explanation": "这里应该用〈歌剧院〉。演出要在歌剧院等场所进行，研究所不做演出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f13dd8b-44f3-452d-9085-3d547cbca762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92854, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天空", "is_correct": false, "explanation": "语义：天空是自然景物，不是机构，不能得到国家的支持。"}, {"text": "团伙", "is_correct": false, "explanation": "语义：团伙指一起做坏事的一群人，不会得到国家的支持，这句话说不通。"}, {"text": "研究所", "is_correct": true, "explanation": "研究所是机构，可以得到国家的支持，这句话说得通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有行为能力，“得到国家的支持”的说法不能指它。"}], "explanations": {"天空": "语义：天空是自然景物，不是机构，不能得到国家的支持。", "团伙": "语义：团伙指一起做坏事的一群人，不会得到国家的支持，这句话说不通。", "研究所": "研究所是机构，可以得到国家的支持，这句话说得通。", "石头": "语义：石头没有行为能力，“得到国家的支持”的说法不能指它。"}, "sentence_index": 6, "correct_answer": "研究所"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我奶奶每周去研究所跳舞。", "explanation": "这里应该用〈文化馆〉。跳舞、唱歌这类活动要去文化馆或活动中心，研究所是做研究的机构，不是活动场所。"}, {"text": "研究所的演员来学校演了一场戏。", "explanation": "这里应该用〈剧团〉。来学校演戏的是剧团，研究所不演戏。"}, {"text": "研究所在路口指挥交通。", "explanation": "这里应该用〈交警〉。指挥交通是交警的职责，研究所不做这类工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f13dd8b-44f3-452d-9085-3d547cbca762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92854, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一只很有名的研究所。", "corrected_sentence": "这是一家很有名的研究所。", "error_description": "“一只”是动物的量词，“研究所”是机构，应该用量词“家”。“这是一家很有名的研究所”是正确说法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f13dd8b-44f3-452d-9085-3d547cbca762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
