INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92855, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "无人机是不用人坐在里面，能飞上天的小飞机。", "primary_collocate": null, "pronunciation": "wú rén jī", "ipa": "u˧˥ ʐən˧˥ tɕi˥", "syllable_count": 3, "sentences": [{"text": "小明的生日礼物是一架无人机。", "target_word": "无人机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无人机在天上飞，像一只大鸟。", "target_word": "无人机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在公园里玩无人机。", "target_word": "无人机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这架无人机很小，不用人坐在里面。", "target_word": "无人机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们抬头看着无人机。", "target_word": "无人机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把无人机放在桌子上。", "target_word": "无人机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无人机飞得很高，我看不见了。", "target_word": "无人机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸教我怎么操作无人机。", "target_word": "无人机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风太大了，无人机飞不起来。", "target_word": "无人机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无人机的声音像一只大蚊子。", "target_word": "无人机", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "架", "label": "量词"}, {"form": "航拍无人机", "label": "复合"}, {"form": "农用无人机", "label": "复合"}], "register": "中性", "sense_fingerprint": "不用人坐在里面、能飞上天的小飞机", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac744e40-6efc-45f3-935b-6099401ba30e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92855, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "无人机", "is_correct": true, "explanation": "“小明的生日礼物是一架无人机”中，无人机可以作为生日礼物，量词“架”也正确。"}, {"text": "桥", "is_correct": false, "explanation": "语义：桥是固定的大型建筑，不能当作生日礼物送人。"}, {"text": "葡萄架", "is_correct": false, "explanation": "语义：葡萄架是固定在院子里的大型棚架，不是生日礼物。"}, {"text": "脚手架", "is_correct": false, "explanation": "语义：脚手架是建筑施工用的设施，不是生日礼物。"}], "explanations": {"无人机": "“小明的生日礼物是一架无人机”中，无人机可以作为生日礼物，量词“架”也正确。", "桥": "语义：桥是固定的大型建筑，不能当作生日礼物送人。", "葡萄架": "语义：葡萄架是固定在院子里的大型棚架，不是生日礼物。", "脚手架": "语义：脚手架是建筑施工用的设施，不是生日礼物。"}, "sentence_index": 0, "correct_answer": "无人机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "春天的公园里，孩子们在草地上放无人机，它的尾巴一摆一摆的，很好看。", "explanation": "这里应该用〈风筝〉。风筝有尾巴，会随风摆动；无人机没有尾巴，不会这样摆动。"}, {"text": "无人机里坐着驾驶员，慢慢滑下山坡。", "explanation": "这里应该用〈滑翔机〉。无人机机上没有驾驶员，也不能载人，这些只适用于滑翔机。"}, {"text": "无人机在山顶上空盘旋，里面有三名驾驶员。", "explanation": "这里应该用〈直升机〉。无人机里没有驾驶员，“里面有三名驾驶员”只适用于载人的直升机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2cb7137-79f2-4b9c-ad24-a966302ee0bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92855, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无人机", "is_correct": true, "explanation": "“无人机飞得很高，我看不见了”中，主语是能飞的无人机，正确。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不会飞，“冰箱飞得很高”说不通。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不会飞，句子与常识相悖。"}, {"text": "石板", "is_correct": false, "explanation": "语义：石板是沉重的石块，不会飞，句子说不通。"}], "explanations": {"无人机": "“无人机飞得很高，我看不见了”中，主语是能飞的无人机，正确。", "冰箱": "语义：冰箱不会飞，“冰箱飞得很高”说不通。", "桌子": "语义：桌子是家具，不会飞，句子与常识相悖。", "石板": "语义：石板是沉重的石块，不会飞，句子说不通。"}, "sentence_index": 6, "correct_answer": "无人机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我看见一条无人机在天上盘旋，我以为是鸟。", "explanation": "这里应该用〈架〉。〈条〉多用于细长的东西，如河、路、裤子；无人机不用〈条〉计量。"}, {"text": "我买了一座无人机，准备周末去拍照。", "explanation": "这里应该用〈架〉。〈座〉用于山、桥、房屋这类大型固定的东西，无人机不用〈座〉计量。"}, {"text": "一块无人机在天上飞，声音很大。", "explanation": "这里应该用〈架〉。〈块〉用于石头、蛋糕等块状或片状的东西，无人机不用〈块〉计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2cb7137-79f2-4b9c-ad24-a966302ee0bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92855, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "弟弟玩无人机得很开心。", "corrected_sentence": "弟弟玩无人机玩得很开心。", "error_description": "错误：动词带宾语时，补语“得很开心”要紧接在动词后面，要说“玩无人机玩得很开心”，不能在宾语后直接用“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2cb7137-79f2-4b9c-ad24-a966302ee0bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92855, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹把无人机放了在床上。", "corrected_sentence": "妹妹把无人机放在了床上。", "error_description": "错误：“了”的位置错误。“放在”中的“在”要紧跟动词“放”，“了”放在“在”之后，应说“放在了床上”，不能说“放了在床上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2cb7137-79f2-4b9c-ad24-a966302ee0bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
