INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92856, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2cb7137-79f2-4b9c-ad24-a966302ee0bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92856, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "由无线电遥控或自主程序控制飞行、机上没有驾驶员的飞行器。", "primary_collocate": null, "pronunciation": "wú rén jī", "ipa": "u˧˥ ʐən˧˥ tɕi˥", "syllable_count": 3, "sentences": [{"text": "这架无人机能飞很远。", "target_word": "无人机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民用无人机给农田喷药。", "target_word": "无人机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了一架航拍无人机。", "target_word": "无人机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无人机从空中拍下了整座城市。", "target_word": "无人机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察用无人机寻找走丢的人。", "target_word": "无人机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无人机的电池只能用半小时。", "target_word": "无人机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司打算用无人机送快递。", "target_word": "无人机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无人机可以用遥控器控制。", "target_word": "无人机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这架无人机没有驾驶员。", "target_word": "无人机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上信号差，无人机飞不远。", "target_word": "无人机", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "架", "label": "量词"}, {"form": "航拍无人机", "label": "复合"}, {"form": "农用无人机", "label": "复合"}], "register": "中性", "sense_fingerprint": "遥控或自主控制、机上无驾驶员的飞行器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac744e40-6efc-45f3-935b-6099401ba30e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92856, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "无人机", "is_correct": true, "explanation": "“这架无人机能飞很远”中，“无人机”是会飞的飞行器，量词“架”也搭配，正确。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴是乐器，不会飞，“这架钢琴能飞很远”说不通。"}, {"text": "桥", "is_correct": false, "explanation": "体貌：桥是固定的大型建筑，形体上不能飞，句子与常识相悖。"}, {"text": "梯子", "is_correct": false, "explanation": "搭配：“能飞很远”的主语应是飞行器，梯子不能与“飞”搭配。"}], "explanations": {"无人机": "“这架无人机能飞很远”中，“无人机”是会飞的飞行器，量词“架”也搭配，正确。", "钢琴": "语义：钢琴是乐器，不会飞，“这架钢琴能飞很远”说不通。", "桥": "体貌：桥是固定的大型建筑，形体上不能飞，句子与常识相悖。", "梯子": "搭配：“能飞很远”的主语应是飞行器，梯子不能与“飞”搭配。"}, "sentence_index": 0, "correct_answer": "无人机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "无人机上坐满了乘客，空姐在发饮料。", "explanation": "这里应该用〈飞机〉。无人机机上没有乘客和空姐，也不能载人，这些只适用于飞机。"}, {"text": "无人机在海上航行，甲板上很热闹。", "explanation": "这里应该用〈轮船〉。无人机是空中飞行的飞行器，不在海上航行，也没有甲板。"}, {"text": "无人机慢慢升空，篮子里坐着两个人。", "explanation": "这里应该用〈热气球〉。无人机没有装人的篮子，也不能载人，这些只适用于热气球。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2cb7137-79f2-4b9c-ad24-a966302ee0bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92856, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无人机", "is_correct": true, "explanation": "“公司打算用无人机送快递”中，无人机是可以用来运送快递的运输工具，正确。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是运输工具，无法用来送快递，句子说不通。"}, {"text": "钢笔", "is_correct": false, "explanation": "语义：钢笔是书写用具，不能用来运送快递。"}, {"text": "白菜", "is_correct": false, "explanation": "搭配：“用……送”要求运输工具或人力，白菜与“送快递”搭配不上。"}], "explanations": {"无人机": "“公司打算用无人机送快递”中，无人机是可以用来运送快递的运输工具，正确。", "空气": "语义：空气不是运输工具，无法用来送快递，句子说不通。", "钢笔": "语义：钢笔是书写用具，不能用来运送快递。", "白菜": "搭配：“用……送”要求运输工具或人力，白菜与“送快递”搭配不上。"}, "sentence_index": 6, "correct_answer": "无人机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了一条无人机，准备周末去拍风景。", "explanation": "这里应该用〈架〉。〈条〉多用于细长的东西，如河、路、裤子；无人机不用〈条〉计量。"}, {"text": "我看见一本无人机在天上飞。", "explanation": "这里应该用〈架〉。〈本〉用于书籍、本子一类的东西，无人机不用〈本〉计量。"}, {"text": "一张无人机在天上盘旋，像一只大鸟。", "explanation": "这里应该用〈架〉。〈张〉多用于纸、桌子等平面的东西，无人机不用〈张〉计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2cb7137-79f2-4b9c-ad24-a966302ee0bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92856, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "农民用一辆无人机给果园喷药，很省力。", "corrected_sentence": "农民用一架无人机给果园喷药，很省力。", "error_description": "错误：无人机的量词应为“架”，不能用“辆”。“辆”用于车，无人机属于飞行器，要说“一架无人机”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2cb7137-79f2-4b9c-ad24-a966302ee0bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92856, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那架无人机飞得高很。", "corrected_sentence": "那架无人机飞得很高。", "error_description": "错误：程度补语的语序错了，“很”要放在“高”前面，要说“飞得很高”，不能说“飞得高很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2cb7137-79f2-4b9c-ad24-a966302ee0bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
