INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92857, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "问", "is_correct": true, "explanation": "正确：问与答相对，二者互为反义。"}, {"text": "吃", "is_correct": false, "explanation": "无反义关系：吃是进食，与“答”没有对立关系。"}, {"text": "跑", "is_correct": false, "explanation": "无反义关系：跑是移动，与“答”的意义不对立。"}, {"text": "睡", "is_correct": false, "explanation": "无反义关系：睡是休息，与“答”没有对立关系。"}], "correct_answer": "问", "explanations": {"问": "正确：问与答相对，二者互为反义。", "吃": "无反义关系：吃是进食，与“答”没有对立关系。", "跑": "无反义关系：跑是移动，与“答”的意义不对立。", "睡": "无反义关系：睡是休息，与“答”没有对立关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72d4ba4f-26a6-401a-a7cf-4f3bd8c05067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92857, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "答是别人问你，你说出回答。", "primary_collocate": null, "pronunciation": "dá", "ipa": "ta³⁵", "syllable_count": 1, "sentences": [{"text": "老师问问题，小明马上就答了。", "target_word": "答", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我问一句，他答一句。", "target_word": "答", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题太难，我答不上来。", "target_word": "答", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她答得又快又对。", "target_word": "答", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问，学生答，课堂很热闹。", "target_word": "答", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没听清问题，答错了。", "target_word": "答", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你问吧，我来答。", "target_word": "答", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道题我答对了。", "target_word": "答", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈问他去哪儿，他只答了一个字。", "target_word": "答", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试时，他一道题也没答出来。", "target_word": "答", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "答了", "label": "体标"}, {"form": "答过", "label": "体标"}], "register": "通用", "sense_fingerprint": "别人提出问题，自己开口说出回答", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df81c267-6b39-4d12-95ab-3643a04c33bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92857, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "答", "is_correct": true, "explanation": "正确：答，dá，指回答别人的问题，是本词。"}, {"text": "大", "is_correct": false, "explanation": "声调不同：dà（第四声）与 dá（第二声）只差声调，意思是大，不是回答。"}, {"text": "打", "is_correct": false, "explanation": "声调不同：dǎ（第三声）与 dá（第二声）声调不同，意思是打。"}, {"text": "搭", "is_correct": false, "explanation": "声调不同：dā（第一声）与 dá（第二声）声调不同，意思是搭。"}], "explanations": {"答": "正确：答，dá，指回答别人的问题，是本词。", "大": "声调不同：dà（第四声）与 dá（第二声）只差声调，意思是大，不是回答。", "打": "声调不同：dǎ（第三声）与 dá（第二声）声调不同，意思是打。", "搭": "声调不同：dā（第一声）与 dá（第二声）声调不同，意思是搭。"}, "sentence_index": null, "correct_answer": "答"}, "level_3": {"options": [{"text": "答", "is_correct": true, "explanation": "正确：“答”指小明对老师问题作出回应，与“老师问问题”相合。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱是唱歌，与“老师问问题”的情境不符。"}, {"text": "哭", "is_correct": false, "explanation": "语义：哭与问答无关，句子说的是回应问题。"}, {"text": "睡", "is_correct": false, "explanation": "语义：睡是休息，与“老师问问题”的情境不符。"}], "explanations": {"答": "正确：“答”指小明对老师问题作出回应，与“老师问问题”相合。", "唱": "语义：唱是唱歌，与“老师问问题”的情境不符。", "哭": "语义：哭与问答无关，句子说的是回应问题。", "睡": "语义：睡是休息，与“老师问问题”的情境不符。"}, "sentence_index": 0, "correct_answer": "答"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他答了我的电话。", "explanation": "这里应该用〈接〉。“答”指回答问题，接电话要用〈接〉。"}, {"text": "她答了一杯水。", "explanation": "这里应该用〈喝〉。“答”指回答，不能与“水”搭配，喝水要用〈喝〉。"}, {"text": "我把钱答给了老师。", "explanation": "这里应该用〈交〉。“答”不表示交付，交钱要用〈交〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72d4ba4f-26a6-401a-a7cf-4f3bd8c05067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92857, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "答", "is_correct": true, "explanation": "正确：“答”指回应对方的话，与“你问吧”的语境相合。"}, {"text": "吃", "is_correct": false, "explanation": "语义：吃是进食，与“你问吧”的回应无关。"}, {"text": "跑", "is_correct": false, "explanation": "语义：跑是移动，与对方提出的问话无关。"}, {"text": "睡", "is_correct": false, "explanation": "语义：睡是休息，与“你问吧，我来……”的表述不符。"}], "explanations": {"答": "正确：“答”指回应对方的话，与“你问吧”的语境相合。", "吃": "语义：吃是进食，与“你问吧”的回应无关。", "跑": "语义：跑是移动，与对方提出的问话无关。", "睡": "语义：睡是休息，与“你问吧，我来……”的表述不符。"}, "sentence_index": 6, "correct_answer": "答"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他答了我一个苹果。", "explanation": "这里应该用〈给〉。“答”指回答问题，不表示给东西。"}, {"text": "他一道题也没答掉。", "explanation": "这里应该用〈出来〉。“答”后接结果补语“出来”，不能接“掉”。"}, {"text": "他答了我一碗面，我很感动。", "explanation": "这里应该用〈煮〉。“答”不能带“面”作宾语，煮面要用〈煮〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72d4ba4f-26a6-401a-a7cf-4f3bd8c05067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92857, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师问完，他马上答来了。", "corrected_sentence": "老师问完，他马上答出来了。", "error_description": "“答”后应接结果补语“出来”，不能说“答来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72d4ba4f-26a6-401a-a7cf-4f3bd8c05067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92857, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我答了过这道题。", "corrected_sentence": "我答过这道题。", "error_description": "“了”和“过”不能同时用在动词“答”之后，应只用“答过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72d4ba4f-26a6-401a-a7cf-4f3bd8c05067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
