INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92858, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "应声；听到别人呼唤后出声作出反应。", "primary_collocate": null, "pronunciation": "dá", "ipa": "ta³⁵", "syllable_count": 1, "sentences": [{"text": "我叫了他好几声，他都没答。", "target_word": "答", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我敲了半天门，屋里没人答。", "target_word": "答", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈喊你，你怎么不答？", "target_word": "答", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师点他的名，他立刻答了一声。", "target_word": "答", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喊他，他在远处答了一声。", "target_word": "答", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他听见有人叫，就大声答了。", "target_word": "答", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人叫了一声，服务员马上答了。", "target_word": "答", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "喊他的名字，他没有答。", "target_word": "答", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友在楼下喊我，我从窗口探出头来答了一声。", "target_word": "答", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对着山谷大喊，山谷里好像有人在答。", "target_word": "答", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "答了", "label": "体标"}, {"form": "答过", "label": "体标"}], "register": "通用", "sense_fingerprint": "听到别人呼唤，出声应一声作为回应", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df81c267-6b39-4d12-95ab-3643a04c33bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92858, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "答", "is_correct": true, "explanation": "正确：答，dá，指听到呼唤后出声作出反应，是本词。"}, {"text": "大", "is_correct": false, "explanation": "声调不同：dà（第四声）与 dá（第二声）只差声调，意思是大，不是应答。"}, {"text": "打", "is_correct": false, "explanation": "声调不同：dǎ（第三声）与 dá（第二声）声调不同，意思是打。"}, {"text": "搭", "is_correct": false, "explanation": "声调不同：dā（第一声）与 dá（第二声）声调不同，意思是搭。"}], "explanations": {"答": "正确：答，dá，指听到呼唤后出声作出反应，是本词。", "大": "声调不同：dà（第四声）与 dá（第二声）只差声调，意思是大，不是应答。", "打": "声调不同：dǎ（第三声）与 dá（第二声）声调不同，意思是打。", "搭": "声调不同：dā（第一声）与 dá（第二声）声调不同，意思是搭。"}, "sentence_index": null, "correct_answer": "答"}, "level_3": {"options": [{"text": "答", "is_correct": true, "explanation": "正确：“答”指对呼叫作出出声的回应，与“叫了他好几声”相合。"}, {"text": "吃", "is_correct": false, "explanation": "语义：吃是进食，与“叫了他好几声”的回应无关。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱是唱歌，与呼叫后的回应不相关。"}, {"text": "写", "is_correct": false, "explanation": "语义：写是书写，与对呼叫的反应不符。"}], "explanations": {"答": "正确：“答”指对呼叫作出出声的回应，与“叫了他好几声”相合。", "吃": "语义：吃是进食，与“叫了他好几声”的回应无关。", "唱": "语义：唱是唱歌，与呼叫后的回应不相关。", "写": "语义：写是书写，与对呼叫的反应不符。"}, "sentence_index": 0, "correct_answer": "答"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一看见蛋糕，就立刻答了一块。", "explanation": "这里应该用〈吃〉。“答”不表示吃，吃蛋糕要用〈吃〉。"}, {"text": "他一听就答了一碗面。", "explanation": "这里应该用〈吃〉。〈答〉不能与“面”搭配，吃面要用〈吃〉。"}, {"text": "风一吹，我立刻答了一口气。", "explanation": "这里应该用〈叹〉。“答”表示回答或应声，不能用于叹气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72d4ba4f-26a6-401a-a7cf-4f3bd8c05067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92858, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "答", "is_correct": true, "explanation": "正确：“答”指服务员听到客人的呼唤后作出回应，与句意相合。"}, {"text": "睡", "is_correct": false, "explanation": "语义：睡是休息，与客人呼唤后服务员的反应无关。"}, {"text": "哭", "is_correct": false, "explanation": "语义：客人叫人不会引出服务员哭，与情境不符。"}, {"text": "跳", "is_correct": false, "explanation": "语义：跳是跳跃，与呼叫后的应答不相关。"}], "explanations": {"答": "正确：“答”指服务员听到客人的呼唤后作出回应，与句意相合。", "睡": "语义：睡是休息，与客人呼唤后服务员的反应无关。", "哭": "语义：客人叫人不会引出服务员哭，与情境不符。", "跳": "语义：跳是跳跃，与呼叫后的应答不相关。"}, "sentence_index": 6, "correct_answer": "答"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我渴了，想答一杯茶。", "explanation": "这里应该用〈喝〉。“答”指应声，不能与“茶”搭配。"}, {"text": "这些钱我今天要答给你。", "explanation": "这里应该用〈还〉。〈答〉不表示还钱，还钱要用〈还〉。"}, {"text": "我叫他的时候，他正在答我的手机。", "explanation": "这里应该用〈接〉。〈答〉指应声或回答，接电话要用〈接〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72d4ba4f-26a6-401a-a7cf-4f3bd8c05067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92858, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他听见有人喊，马上答了一个声。", "corrected_sentence": "他听见有人喊，马上答了一声。", "error_description": "“答”作应声讲时，动量词要用“声”，不能用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72d4ba4f-26a6-401a-a7cf-4f3bd8c05067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92858, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我喊他一声，他答没。", "corrected_sentence": "我喊他一声，他没答。", "error_description": "否定词“没”须放在动词“答”之前，写成“答没”是语序错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72d4ba4f-26a6-401a-a7cf-4f3bd8c05067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
