INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92860, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "由古代植物经长期地质作用形成的可燃黑色固体矿物，用作燃料和工业原料。", "primary_collocate": null, "pronunciation": "méi tàn", "ipa": "meɪ˧˥ tʰan˥˩", "syllable_count": 2, "sentences": [{"text": "这个城市的电厂主要用煤炭发电。", "target_word": "煤炭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国是世界上煤炭产量很大的国家。", "target_word": "煤炭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "煤炭是一种重要的能源。", "target_word": "煤炭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座矿山每年出产大量煤炭。", "target_word": "煤炭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "煤炭价格今年上涨了不少。", "target_word": "煤炭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂需要煤炭作为燃料。", "target_word": "煤炭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "煤炭是由古代植物形成的。", "target_word": "煤炭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多国家正在减少煤炭的使用。", "target_word": "煤炭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山西的煤炭运到全国各地。", "target_word": "煤炭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "烧煤炭会污染空气。", "target_word": "煤炭", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一吨煤炭", "label": "量词（吨）"}], "register": "中性", "sense_fingerprint": "作为能源和工业原料的可燃黑色矿物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0006e141-8dc4-4804-a206-f5967740a580') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92860, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "煤炭", "is_correct": true, "explanation": "煤炭是能源，可以用来发电，符合句意。"}, {"text": "牛奶", "is_correct": false, "explanation": "语义：牛奶不能用来发电，句意不通。"}, {"text": "布", "is_correct": false, "explanation": "搭配：“用……发电”要用能源，布不是能源，搭配不当。"}, {"text": "糖", "is_correct": false, "explanation": "语义：糖不能燃烧发电，句意矛盾。"}], "explanations": {"煤炭": "煤炭是能源，可以用来发电，符合句意。", "牛奶": "语义：牛奶不能用来发电，句意不通。", "布": "搭配：“用……发电”要用能源，布不是能源，搭配不当。", "糖": "语义：糖不能燃烧发电，句意矛盾。"}, "sentence_index": 0, "correct_answer": "煤炭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工厂运来了一根煤炭。", "explanation": "这里应该用〈吨〉。煤炭按重量计量，“根”用于细长的东西，不能用来数煤炭。"}, {"text": "这座电厂烧掉了一条煤炭。", "explanation": "这里应该用〈吨〉。“条”用于细长的东西，煤炭不能用“条”来计量。"}, {"text": "他们买了一只煤炭。", "explanation": "这里应该用〈吨〉。“只”多用于动物或成对物品中的一件，煤炭不能用“只”来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f74798a-5a73-4add-9ed7-fed78d2d8d9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92860, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "煤炭", "is_correct": true, "explanation": "煤炭是由古代植物形成的，符合句意。"}, {"text": "冰", "is_correct": false, "explanation": "语义：冰是由水凝结而成的，不是由古代植物形成的。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃是人工制造的，不是由古代植物形成的。"}, {"text": "水泥", "is_correct": false, "explanation": "搭配：“形成”用于自然过程，水泥是人工制成的，应说“制成”。"}], "explanations": {"煤炭": "煤炭是由古代植物形成的，符合句意。", "冰": "语义：冰是由水凝结而成的，不是由古代植物形成的。", "玻璃": "语义：玻璃是人工制造的，不是由古代植物形成的。", "水泥": "搭配：“形成”用于自然过程，水泥是人工制成的，应说“制成”。"}, "sentence_index": 6, "correct_answer": "煤炭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他往咖啡里放了一大块煤炭。", "explanation": "这里应该用〈糖〉。咖啡里放的是〈糖〉，煤炭不能用来调味。"}, {"text": "工匠用煤炭做家具。", "explanation": "这里应该用〈木头〉。做家具用木材，煤炭是燃料，不能用来做家具。"}, {"text": "他们用煤炭给机器润滑。", "explanation": "这里应该用〈机油〉。机器润滑要用液体的机油，煤炭是固体，不能用来润滑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f74798a-5a73-4add-9ed7-fed78d2d8d9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92860, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座矿山每年要挖几百万个煤炭。", "corrected_sentence": "这座矿山每年要挖几百万吨煤炭。", "error_description": "量词错误：煤炭按重量计量，应用“吨”来数，“个”用于单个的东西。正确说法是“几百万吨煤炭”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f74798a-5a73-4add-9ed7-fed78d2d8d9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92860, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个工厂每个月要买两万吨煤炭们。", "corrected_sentence": "这个工厂每个月要买两万吨煤炭。", "error_description": "“们”只用于指人的名词，煤炭是物质名词，不能加“们”。错误形式是“两万吨煤炭们”，正确形式是“两万吨煤炭”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f74798a-5a73-4add-9ed7-fed78d2d8d9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
