INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92861, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "总之是前面说了很多，最后用一句话说完。", "primary_collocate": null, "pronunciation": "zǒng zhī", "ipa": "tsʊŋ˨˩ tʂɻ̩˥", "syllable_count": 2, "sentences": [{"text": "他讲了一个小时，总之，就是不同意。", "target_word": "总之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说来说去，总之，还是想回家。", "target_word": "总之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家吵了半天，总之，没有一个好办法。", "target_word": "总之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说了很多话，总之，她想换工作。", "target_word": "总之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸讲了很多道理，总之，要好好学习。", "target_word": "总之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他解释了很多遍，总之，我还是不明白。", "target_word": "总之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友说了一大堆，总之，他想借钱。", "target_word": "总之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板开了三个小时的会，总之，下个月要加班。", "target_word": "总之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说了很多，总之，你要多休息。", "target_word": "总之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说了很久，总之，他很想家。", "target_word": "总之", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "说了很多话之后，用一句话收尾说出要点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c43aef69-b6a0-4454-8d6b-0589435b9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92861, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "总之", "is_correct": true, "explanation": "总之（zǒng zhī）表示前面说了很多，最后用一句话收尾，是本题的目标词。"}, {"text": "宗旨", "is_correct": false, "explanation": "宗旨（zōngzhǐ）与总之（zǒng zhī）两个音节的声调都不同，意思是主要目标。"}, {"text": "总是", "is_correct": false, "explanation": "总是（zǒngshì）第二音节的声母 zh 与 sh 不同，声调也不同，意思是一直。"}, {"text": "总值", "is_correct": false, "explanation": "总值（zǒngzhí）第二音节声调不同（zhí 与 zhī），意思是总价值。"}], "explanations": {"总之": "总之（zǒng zhī）表示前面说了很多，最后用一句话收尾，是本题的目标词。", "宗旨": "宗旨（zōngzhǐ）与总之（zǒng zhī）两个音节的声调都不同，意思是主要目标。", "总是": "总是（zǒngshì）第二音节的声母 zh 与 sh 不同，声调也不同，意思是一直。", "总值": "总值（zǒngzhí）第二音节声调不同（zhí 与 zhī），意思是总价值。"}, "sentence_index": null, "correct_answer": "总之"}, "level_3": {"options": [{"text": "总之", "is_correct": true, "explanation": "总之用在前面说了很多之后，引出一句话的结论，符合句子语境。"}, {"text": "一起", "is_correct": false, "explanation": "语法：“一起”是副词，不能用在分句之间引出结论，句子不通。"}, {"text": "例如", "is_correct": false, "explanation": "语义：例如用来举例，前面的讲话并不是后面的例子。"}, {"text": "曾经", "is_correct": false, "explanation": "语法：“曾经”是副词，表示过去的经历，不能引出结论，句子不通。"}], "explanations": {"总之": "总之用在前面说了很多之后，引出一句话的结论，符合句子语境。", "一起": "语法：“一起”是副词，不能用在分句之间引出结论，句子不通。", "例如": "语义：例如用来举例，前面的讲话并不是后面的例子。", "曾经": "语法：“曾经”是副词，表示过去的经历，不能引出结论，句子不通。"}, "sentence_index": 0, "correct_answer": "总之"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我先洗碗，总之，然后做饭。", "explanation": "总之用于概括前文，不用于引出先后的动作。这里应说“然后”。"}, {"text": "她今天很开心，总之，明天是星期天。", "explanation": "“总之”表示概括前文，但“明天是星期天”不是对“她很开心”的概括，而是原因，应换成“因为”。"}, {"text": "这本书很厚，总之，我的笔很贵。", "explanation": "“总之”表示概括前文，这里用来并列另一件事，应换成“而且”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b55e6d1-d065-468e-8962-434097609120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92861, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "总之", "is_correct": true, "explanation": "总之用在列举几件事之后，引出概括性的结论，符合句子语境。"}, {"text": "很", "is_correct": false, "explanation": "语法：“很”是程度副词，只能修饰形容词或心理动词，不能单独用在分句之间，句子不通。"}, {"text": "把", "is_correct": false, "explanation": "语法：“把”是介词，后面须接宾语和动词，这里缺少这些成分，句子不通。"}, {"text": "尽管", "is_correct": false, "explanation": "配价：尽管需要与“却”或“但”呼应，这里缺少后续关联词，不成立。"}], "explanations": {"总之": "总之用在列举几件事之后，引出概括性的结论，符合句子语境。", "很": "语法：“很”是程度副词，只能修饰形容词或心理动词，不能单独用在分句之间，句子不通。", "把": "语法：“把”是介词，后面须接宾语和动词，这里缺少这些成分，句子不通。", "尽管": "配价：尽管需要与“却”或“但”呼应，这里缺少后续关联词，不成立。"}, "sentence_index": 6, "correct_answer": "总之"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "总之，他们有三个条件：时间、钱和人手。", "explanation": "“总之”只用于一大段话之后做归纳，不能放在列举之前引出内容，这里应去掉“总之”。"}, {"text": "总之，因为下雨，我们没去公园。", "explanation": "“总之”只能用在一连串内容之后做归纳，这里放在句首引出原因，应换成“由于”。"}, {"text": "他先去图书馆，总之，再回家。", "explanation": "总之不用于引出先后顺序。这里应说“然后”或“再”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b55e6d1-d065-468e-8962-434097609120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92861, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他问了很多问题，总之了，他没有听懂。", "corrected_sentence": "他问了很多问题，总之，他没有听懂。", "error_description": "错误形式：“总之了”；正确形式：“总之，”。“总之”是连词，不能带动态助词“了”，它后面只接逗号再引出概括性的结论。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b55e6d1-d065-468e-8962-434097609120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92861, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们努力了很久，总之过，结果还是很好。", "corrected_sentence": "我们努力了很久，总之，结果还是很好。", "error_description": "错误形式：“总之过”；正确形式：“总之，”。“总之”是连词，不能带动态助词“过”，它后面只接逗号再引出概括性的结论。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b55e6d1-d065-468e-8962-434097609120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
