INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92862, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，用在总括性话语前，表示概括起来说。", "primary_collocate": null, "pronunciation": "zǒng zhī", "ipa": "tsʊŋ˨˩ tʂɻ̩˥", "syllable_count": 2, "sentences": [{"text": "又要买菜，又要做饭，总之，妈妈今天很忙。", "target_word": "总之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他会唱歌，会跳舞，总之，他很有才。", "target_word": "总之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气冷，路又滑，总之，今天别出门了。", "target_word": "总之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的菜好吃，价钱也不贵，总之，我很满意。", "target_word": "总之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她学习好，工作也认真，总之，大家都喜欢她。", "target_word": "总之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子大，离学校近，总之，这个家我很喜欢。", "target_word": "总之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买票，坐车，找路，总之，旅行很麻烦。", "target_word": "总之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说了很多理由，总之，他不想去。", "target_word": "总之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服太贵，颜色也不好，总之，我不买。", "target_word": "总之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教得好，同学也友好，总之，我爱这个班。", "target_word": "总之", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "用在几项说明之后，引出概括性的结论", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c43aef69-b6a0-4454-8d6b-0589435b9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92862, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "总之", "is_correct": true, "explanation": "总之（zǒng zhī）表示概括地说，是本题的目标词。"}, {"text": "宗旨", "is_correct": false, "explanation": "宗旨（zōngzhǐ）与总之（zǒng zhī）两个音节的声调都不同，意思是主要目标。"}, {"text": "总是", "is_correct": false, "explanation": "总是（zǒngshì）第二音节的声母 zh 与 sh 不同，声调也不同，意思是一直。"}, {"text": "总值", "is_correct": false, "explanation": "总值（zǒngzhí）第二音节声调不同（zhí 与 zhī），意思是总价值。"}], "explanations": {"总之": "总之（zǒng zhī）表示概括地说，是本题的目标词。", "宗旨": "宗旨（zōngzhǐ）与总之（zǒng zhī）两个音节的声调都不同，意思是主要目标。", "总是": "总是（zǒngshì）第二音节的声母 zh 与 sh 不同，声调也不同，意思是一直。", "总值": "总值（zǒngzhí）第二音节声调不同（zhí 与 zhī），意思是总价值。"}, "sentence_index": null, "correct_answer": "总之"}, "level_3": {"options": [{"text": "总之", "is_correct": true, "explanation": "总之用在前面几件事之后，引出概括性的结论，符合句子语境。"}, {"text": "但是", "is_correct": false, "explanation": "语义：但是表示转折，而前面说的是事情很多，后面并不是转折关系。"}, {"text": "例如", "is_correct": false, "explanation": "语义：例如用来举例，前面的买菜和做饭并不是后面的例子。"}, {"text": "然而", "is_correct": false, "explanation": "语域：然而偏书面，用在这种口语叙述中显得生硬，而且同样表示转折。"}], "explanations": {"总之": "总之用在前面几件事之后，引出概括性的结论，符合句子语境。", "但是": "语义：但是表示转折，而前面说的是事情很多，后面并不是转折关系。", "例如": "语义：例如用来举例，前面的买菜和做饭并不是后面的例子。", "然而": "语域：然而偏书面，用在这种口语叙述中显得生硬，而且同样表示转折。"}, "sentence_index": 0, "correct_answer": "总之"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们先去超市，总之，然后去银行。", "explanation": "总之用于概括前文，不用于引出先后的动作。这里应说“然后”。"}, {"text": "我今天很开心，总之，明天是星期天。", "explanation": "“总之”表示概括前文，但“明天是星期天”不是对“我很开心”的概括，而是原因，应换成“因为”。"}, {"text": "他会打篮球，总之，他的书法很好。", "explanation": "“总之”表示概括前文，这里用来并列另一件事，应换成“而且”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b55e6d1-d065-468e-8962-434097609120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92862, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "总之", "is_correct": true, "explanation": "总之用在列举的几件事之后，引出概括性的结论，符合句子语境。"}, {"text": "曾经", "is_correct": false, "explanation": "语法：“曾经”是副词，表示过去的经历，不能用在列举之后引出结论，句子不通。"}, {"text": "比如", "is_correct": false, "explanation": "语义：比如用来举例，前面列的动作并不是后面的例子。"}, {"text": "尽管", "is_correct": false, "explanation": "配价：尽管需要与“却”或“但”呼应，这里缺少后续关联词，不成立。"}], "explanations": {"总之": "总之用在列举的几件事之后，引出概括性的结论，符合句子语境。", "曾经": "语法：“曾经”是副词，表示过去的经历，不能用在列举之后引出结论，句子不通。", "比如": "语义：比如用来举例，前面列的动作并不是后面的例子。", "尽管": "配价：尽管需要与“却”或“但”呼应，这里缺少后续关联词，不成立。"}, "sentence_index": 6, "correct_answer": "总之"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "总之，他有三个爱好：唱歌、跳舞和画画。", "explanation": "“总之”是概括词，用在一连串内容之后做归纳，不能放在列举之前引出内容，这里应去掉“总之”。"}, {"text": "我先写作业，总之，然后去睡觉。", "explanation": "总之不用于引出先后顺序。这里应说“然后”。"}, {"text": "今天天气很好，总之，我的书包很重。", "explanation": "“总之”表示概括前文，这里用来转到一件与前文无关的新事情，应换成“另外”或“顺便说一下”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b55e6d1-d065-468e-8962-434097609120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92862, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他跑得快，跳得高，总之了，他很有运动天赋。", "corrected_sentence": "他跑得快，跳得高，总之，他很有运动天赋。", "error_description": "错误形式：“总之了”；正确形式：“总之，”。“总之”是连词，不能带动态助词“了”，它后面只接逗号再引出概括性的结论。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b55e6d1-d065-468e-8962-434097609120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92862, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们忙了一整天，总之着，今天终于结束了。", "corrected_sentence": "我们忙了一整天，总之，今天终于结束了。", "error_description": "错误形式：“总之着”；正确形式：“总之，”。“总之”是连词，不能带动态助词“着”，它后面只接逗号再引出概括性的结论。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b55e6d1-d065-468e-8962-434097609120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92863, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "失败", "is_correct": true, "explanation": "反义：获胜与失败相对，指比赛中没有赢。"}, {"text": "参加", "is_correct": false, "explanation": "参加与获胜没有反义关系，参加指加入某项活动。"}, {"text": "练习", "is_correct": false, "explanation": "练习与获胜没有反义关系，练习指反复做以提高技能。"}, {"text": "休息", "is_correct": false, "explanation": "休息与获胜没有反义关系，休息指停下来不做事。"}], "correct_answer": "失败", "explanations": {"失败": "反义：获胜与失败相对，指比赛中没有赢。", "参加": "参加与获胜没有反义关系，参加指加入某项活动。", "练习": "练习与获胜没有反义关系，练习指反复做以提高技能。", "休息": "休息与获胜没有反义关系，休息指停下来不做事。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0bf8eaf-afd7-4b38-9a3d-cb96ad77dcd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92863, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "失败", "is_correct": true, "explanation": "反义：获胜与失败相对，指比赛中没有赢。"}, {"text": "放弃", "is_correct": false, "explanation": "放弃与获胜没有反义关系，放弃指不再坚持做某事。"}, {"text": "起床", "is_correct": false, "explanation": "起床与获胜没有反义关系，起床指从床上起来。"}, {"text": "散步", "is_correct": false, "explanation": "散步与获胜没有反义关系，散步指随意地走一走。"}], "correct_answer": "失败", "explanations": {"失败": "反义：获胜与失败相对，指比赛中没有赢。", "放弃": "放弃与获胜没有反义关系，放弃指不再坚持做某事。", "起床": "起床与获胜没有反义关系，起床指从床上起来。", "散步": "散步与获胜没有反义关系，散步指随意地走一走。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0bf8eaf-afd7-4b38-9a3d-cb96ad77dcd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92863, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "获胜是比赛的时候赢了。", "primary_collocate": null, "pronunciation": "huò shèng", "ipa": "xuɔ˥˩ ʂɤŋ˥˩", "syllable_count": 2, "sentences": [{"text": "昨天的足球比赛，我们队获胜了。", "target_word": "获胜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跑得很快，最后获胜的是他。", "target_word": "获胜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场篮球赛哪个队会获胜？", "target_word": "获胜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明下棋获胜了，非常高兴。", "target_word": "获胜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在游泳比赛中获胜，得了第一名。", "target_word": "获胜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班在拔河比赛中获胜了。", "target_word": "获胜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们队获胜以后，大家一起唱歌。", "target_word": "获胜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从来没有在比赛中获胜过。", "target_word": "获胜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛，谁获胜谁就能拿奖。", "target_word": "获胜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟打乒乓球获胜了，笑得很开心。", "target_word": "获胜", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "获胜了", "label": "体标"}, {"form": "获胜过", "label": "体标"}, {"form": "获胜者", "label": "复合"}], "register": "中性", "sense_fingerprint": "比赛时赢了", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b978dc-3304-4b6f-922b-d87fbcdc36f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92863, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "获胜", "is_correct": true, "explanation": "获胜（huòshèng）指在比赛、战斗或竞争中取得胜利。"}, {"text": "好胜", "is_correct": false, "explanation": "好胜（hàoshèng）与获胜（huòshèng）韵母不同（ao／uo），意思是争强好胜，不指比赛赢了。"}, {"text": "火盛", "is_correct": false, "explanation": "火盛（huǒshèng）与获胜（huòshèng）第一音节声调不同（三声与四声），意思是火势旺盛。"}, {"text": "过盛", "is_correct": false, "explanation": "过盛（guòshèng）与获胜（huòshèng）第一音节声母不同（g／h），意思是过于旺盛。"}], "explanations": {"获胜": "获胜（huòshèng）指在比赛、战斗或竞争中取得胜利。", "好胜": "好胜（hàoshèng）与获胜（huòshèng）韵母不同（ao／uo），意思是争强好胜，不指比赛赢了。", "火盛": "火盛（huǒshèng）与获胜（huòshèng）第一音节声调不同（三声与四声），意思是火势旺盛。", "过盛": "过盛（guòshèng）与获胜（huòshèng）第一音节声母不同（g／h），意思是过于旺盛。"}, "sentence_index": null, "correct_answer": "获胜"}, "level_3": {"options": [{"text": "获胜", "is_correct": true, "explanation": "正确。句子说我们队在足球比赛中赢了，应填“获胜”。"}, {"text": "生病", "is_correct": false, "explanation": "语义：“生病”只用于人或动物，不能说“我们队生病了”。"}, {"text": "阵亡", "is_correct": false, "explanation": "语域：“阵亡”是战争用语，与足球比赛的口语语境不合。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“出生”指人或动物的诞生，与足球比赛无关。"}], "explanations": {"获胜": "正确。句子说我们队在足球比赛中赢了，应填“获胜”。", "生病": "语义：“生病”只用于人或动物，不能说“我们队生病了”。", "阵亡": "语域：“阵亡”是战争用语，与足球比赛的口语语境不合。", "出生": "语义：“出生”指人或动物的诞生，与足球比赛无关。"}, "sentence_index": 0, "correct_answer": "获胜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次实验获胜了，老师很满意。", "explanation": "这里应该用〈成功〉。获胜指在比赛、战斗或竞争中胜过对方，实验没有对手，只能说成功。"}, {"text": "他数学考试获胜了。", "explanation": "这里应该用〈及格〉。获胜要有对手，考试只能说及格。"}, {"text": "我在医院获胜了。", "explanation": "这里应该用〈痊愈〉。获胜指在比赛、战斗或竞争中胜过对手，病好了不是胜过谁，要说痊愈。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0bf8eaf-afd7-4b38-9a3d-cb96ad77dcd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92863, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "获胜", "is_correct": true, "explanation": "正确。“以后，大家一起唱歌”说明是赢了之后的庆祝，应填“获胜”。"}, {"text": "哭泣", "is_correct": false, "explanation": "语义：“哭泣”与后面“大家一起唱歌”的欢乐语境相反。"}, {"text": "殒命", "is_correct": false, "explanation": "语域：“殒命”是书面语且表示死亡，与口语化的庆祝语境不合。"}, {"text": "出版", "is_correct": false, "explanation": "语义：“出版”指书报等印刷品的发行，球队不能“出版”。"}], "explanations": {"获胜": "正确。“以后，大家一起唱歌”说明是赢了之后的庆祝，应填“获胜”。", "哭泣": "语义：“哭泣”与后面“大家一起唱歌”的欢乐语境相反。", "殒命": "语域：“殒命”是书面语且表示死亡，与口语化的庆祝语境不合。", "出版": "语义：“出版”指书报等印刷品的发行，球队不能“出版”。"}, "sentence_index": 6, "correct_answer": "获胜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的作业今天获胜了。", "explanation": "这里应该用〈完成〉。获胜用于比赛或竞争，作业只能说完成。"}, {"text": "他的感冒获胜了。", "explanation": "这里应该用〈痊愈〉。获胜要有对手，感冒只能说痊愈。"}, {"text": "这顿饭获胜了。", "explanation": "这里应该用〈做好〉。获胜指在比赛或竞争中胜过对手，饭菜没有对手，只能说做好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0bf8eaf-afd7-4b38-9a3d-cb96ad77dcd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92863, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们队在比赛中获胜了了。", "corrected_sentence": "我们队在比赛中获胜了。", "error_description": "错误：“获胜了了”，多了一个“了”。正确：“获胜了”。一个动词后只用一个“了”，多出的“了”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0bf8eaf-afd7-4b38-9a3d-cb96ad77dcd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92863, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们队以前获胜了过。", "corrected_sentence": "他们队以前获胜过。", "error_description": "错误：“获胜了过”，“了”和“过”不能一起用在动词后面。正确：“获胜过”。表示曾经有过这种经历，用“动词＋过”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0bf8eaf-afd7-4b38-9a3d-cb96ad77dcd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92864, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "失败", "is_correct": true, "explanation": "反义：获胜与失败相对，指竞争中没有赢。"}, {"text": "开始", "is_correct": false, "explanation": "开始与获胜没有反义关系，开始指事情从头做起。"}, {"text": "休息", "is_correct": false, "explanation": "休息与获胜没有反义关系，休息指停下来不做事。"}, {"text": "练习", "is_correct": false, "explanation": "练习与获胜没有反义关系，练习指反复做以提高技能。"}], "correct_answer": "失败", "explanations": {"失败": "反义：获胜与失败相对，指竞争中没有赢。", "开始": "开始与获胜没有反义关系，开始指事情从头做起。", "休息": "休息与获胜没有反义关系，休息指停下来不做事。", "练习": "练习与获胜没有反义关系，练习指反复做以提高技能。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0bf8eaf-afd7-4b38-9a3d-cb96ad77dcd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92864, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "失败", "is_correct": true, "explanation": "反义：获胜与失败相对，指比赛中没有赢。"}, {"text": "放弃", "is_correct": false, "explanation": "放弃与获胜没有反义关系，放弃指不再坚持做某事。"}, {"text": "起床", "is_correct": false, "explanation": "起床与获胜没有反义关系，起床指从床上起来。"}, {"text": "散步", "is_correct": false, "explanation": "散步与获胜没有反义关系，散步指随意地走一走。"}], "correct_answer": "失败", "explanations": {"失败": "反义：获胜与失败相对，指比赛中没有赢。", "放弃": "放弃与获胜没有反义关系，放弃指不再坚持做某事。", "起床": "起床与获胜没有反义关系，起床指从床上起来。", "散步": "散步与获胜没有反义关系，散步指随意地走一走。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0bf8eaf-afd7-4b38-9a3d-cb96ad77dcd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92864, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在比赛、战斗或竞争中取得胜利。", "primary_collocate": null, "pronunciation": "huò shèng", "ipa": "xuɔ˥˩ ʂɤŋ˥˩", "syllable_count": 2, "sentences": [{"text": "经过三天的战斗，我军终于获胜。", "target_word": "获胜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两家公司竞争很激烈，最后新公司获胜了。", "target_word": "获胜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在比赛中获胜，成为冠军。", "target_word": "获胜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次选举，老张获胜了。", "target_word": "获胜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想在竞争中获胜，需要努力和聪明。", "target_word": "获胜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国队在乒乓球比赛中获胜，全国人民都很高兴。", "target_word": "获胜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们获胜的办法很简单：每天练习。", "target_word": "获胜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支小队伍居然获胜了，没人想到。", "target_word": "获胜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了获胜，运动员们每天训练八个小时。", "target_word": "获胜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛结束时，红队以三比二获胜。", "target_word": "获胜", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "获胜了", "label": "体标"}, {"form": "获胜过", "label": "体标"}, {"form": "获胜者", "label": "复合"}], "register": "中性", "sense_fingerprint": "在比赛、战斗、竞争中取胜", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b978dc-3304-4b6f-922b-d87fbcdc36f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92864, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "获胜", "is_correct": true, "explanation": "获胜（huòshèng）指在比赛、战斗或竞争中取得胜利。"}, {"text": "好胜", "is_correct": false, "explanation": "好胜（hàoshèng）与获胜（huòshèng）韵母不同（ao／uo），意思是争强好胜，不指取得胜利。"}, {"text": "火盛", "is_correct": false, "explanation": "火盛（huǒshèng）与获胜（huòshèng）第一音节声调不同（三声与四声），意思是火势旺盛。"}, {"text": "过盛", "is_correct": false, "explanation": "过盛（guòshèng）与获胜（huòshèng）第一音节声母不同（g／h），意思是过于旺盛。"}], "explanations": {"获胜": "获胜（huòshèng）指在比赛、战斗或竞争中取得胜利。", "好胜": "好胜（hàoshèng）与获胜（huòshèng）韵母不同（ao／uo），意思是争强好胜，不指取得胜利。", "火盛": "火盛（huǒshèng）与获胜（huòshèng）第一音节声调不同（三声与四声），意思是火势旺盛。", "过盛": "过盛（guòshèng）与获胜（huòshèng）第一音节声母不同（g／h），意思是过于旺盛。"}, "sentence_index": null, "correct_answer": "获胜"}, "level_3": {"options": [{"text": "获胜", "is_correct": true, "explanation": "正确。“经过三天的战斗，我军终于……”需要表示战斗取得胜利，应填“获胜”。"}, {"text": "参观", "is_correct": false, "explanation": "配价：“参观”需要带宾语，如“参观基地”，“我军终于参观”缺少对象。"}, {"text": "出版", "is_correct": false, "explanation": "语义：“出版”指书报等印刷品的出版，不能用于军队。"}, {"text": "失眠", "is_correct": false, "explanation": "语义：“失眠”指睡不着，与战斗取胜的语境无关。"}], "explanations": {"获胜": "正确。“经过三天的战斗，我军终于……”需要表示战斗取得胜利，应填“获胜”。", "参观": "配价：“参观”需要带宾语，如“参观基地”，“我军终于参观”缺少对象。", "出版": "语义：“出版”指书报等印刷品的出版，不能用于军队。", "失眠": "语义：“失眠”指睡不着，与战斗取胜的语境无关。"}, "sentence_index": 0, "correct_answer": "获胜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这项工程终于获胜了。", "explanation": "这里应该用〈完工〉。获胜要有对手，工程只能说完工。"}, {"text": "这批产品检验获胜了。", "explanation": "这里应该用〈合格〉。获胜要有对手，检验只能说合格。"}, {"text": "这盏灯获胜了。", "explanation": "这里应该用〈亮〉。获胜指在比赛或竞争中胜过对手，灯没有对手，只能说亮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0bf8eaf-afd7-4b38-9a3d-cb96ad77dcd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92864, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "获胜", "is_correct": true, "explanation": "正确。“……的办法很简单：每天练习”说的是取得胜利的办法，应填“获胜”。"}, {"text": "哭泣", "is_correct": false, "explanation": "语义：“哭泣”与“每天练习”的办法无关，句子读不通。"}, {"text": "殒命", "is_correct": false, "explanation": "语域：“殒命”是书面语且表示死亡，与“每天练习”的办法不合。"}, {"text": "发烧", "is_correct": false, "explanation": "语义：“发烧”指身体发热，不能作为办法的对象。"}], "explanations": {"获胜": "正确。“……的办法很简单：每天练习”说的是取得胜利的办法，应填“获胜”。", "哭泣": "语义：“哭泣”与“每天练习”的办法无关，句子读不通。", "殒命": "语域：“殒命”是书面语且表示死亡，与“每天练习”的办法不合。", "发烧": "语义：“发烧”指身体发热，不能作为办法的对象。"}, "sentence_index": 6, "correct_answer": "获胜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器终于获胜了。", "explanation": "这里应该用〈修好〉。获胜要有对手，机器只能说修好。"}, {"text": "这份作业终于获胜了。", "explanation": "这里应该用〈完成〉。获胜用于比赛或竞争，作业只能说完成。"}, {"text": "今天的天气获胜了。", "explanation": "这里应该用〈放晴〉。获胜指胜过对手，天气没有对手，天转晴只能说放晴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0bf8eaf-afd7-4b38-9a3d-cb96ad77dcd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92864, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次比赛，我们终于获胜着。", "corrected_sentence": "这次比赛，我们终于获胜了。", "error_description": "错误：“获胜着”。正确：“获胜了”。获胜是一次性的结果，表示动作已经完成，要用“了”，不能用表示持续状态的“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0bf8eaf-afd7-4b38-9a3d-cb96ad77dcd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92864, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "红队以前获胜了过。", "corrected_sentence": "红队以前获胜过。", "error_description": "错误：“获胜了过”，“了”和“过”不能一起用在动词后面。正确：“获胜过”。表示曾经有过这种经历，用“动词＋过”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0bf8eaf-afd7-4b38-9a3d-cb96ad77dcd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
