INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92865, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "背是人身体后面，和肚子相反的一边。", "primary_collocate": null, "pronunciation": "bèi", "ipa": "pei˥˩", "syllable_count": 1, "sentences": [{"text": "我的背有点儿疼。", "target_word": "背", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的背上有一只小虫。", "target_word": "背", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈轻轻拍着孩子的背。", "target_word": "背", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游泳以后，他的背都湿了。", "target_word": "背", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她站得很直，背一点儿也不弯。", "target_word": "背", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸累了，我给他捶捶背。", "target_word": "背", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把手放在我的背上。", "target_word": "背", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生让我转过身，看看我的背。", "target_word": "背", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐了一天，我的腰和背都很酸。", "target_word": "背", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫跳到哥哥的背上睡着了。", "target_word": "背", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "后背", "label": "复合"}, {"form": "背部", "label": "复合"}], "register": "中性", "sense_fingerprint": "人身体的后面，与肚子相反的一边", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5582003f-0fa5-4559-bf80-a34613800f6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92865, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "背", "is_correct": true, "explanation": "正确答案：背（bèi），指人身体后面、与肚子相反的一边。"}, {"text": "杯", "is_correct": false, "explanation": "bēi（第一声）与 bèi（第四声）只有声调不同，意思是杯子。"}, {"text": "北", "is_correct": false, "explanation": "běi（第三声）与 bèi（第四声）只有声调不同，意思是北方。"}, {"text": "配", "is_correct": false, "explanation": "pèi 与 bèi 只有声母不同（p 送气，b 不送气），意思是配合、搭配。"}, {"text": "拜", "is_correct": false, "explanation": "bài 与 bèi 只有韵母不同（-ai 与 -ei），意思是拜访、行礼。"}], "explanations": {"背": "正确答案：背（bèi），指人身体后面、与肚子相反的一边。", "杯": "bēi（第一声）与 bèi（第四声）只有声调不同，意思是杯子。", "北": "běi（第三声）与 bèi（第四声）只有声调不同，意思是北方。", "配": "pèi 与 bèi 只有声母不同（p 送气，b 不送气），意思是配合、搭配。", "拜": "bài 与 bèi 只有韵母不同（-ai 与 -ei），意思是拜访、行礼。"}, "sentence_index": null, "correct_answer": "背"}, "level_3": {"options": [{"text": "背", "is_correct": true, "explanation": "正确答案：背，指人身体后面的部位，可以感到疼。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不是人身体的部分，不会疼，“我的桌子有点儿疼”说不通。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“疼”用于身体部位，不能说“我的声音有点儿疼”。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材指体型，不是可以感到疼的部位，这里不能用。"}], "explanations": {"背": "正确答案：背，指人身体后面的部位，可以感到疼。", "桌子": "语义：桌子不是人身体的部分，不会疼，“我的桌子有点儿疼”说不通。", "声音": "搭配：“疼”用于身体部位，不能说“我的声音有点儿疼”。", "身材": "体貌：身材指体型，不是可以感到疼的部位，这里不能用。"}, "sentence_index": 0, "correct_answer": "背"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "吃得太多以后，我的背鼓得像个皮球。", "explanation": "这里应该用〈肚子〉。背在身体后面，与肚子相反；吃饱后鼓起来的是肚子，不能说背鼓。"}, {"text": "他的背太细，我一只手就能握住。", "explanation": "这里应该用〈腰〉。背在身后，一只手能握住的细处是腰，不能说背太细。"}, {"text": "他的背太粗，衬衫领子扣不上。", "explanation": "这里应该用〈脖子〉。衬衫领子套在脖子上，背在身后，背粗不会让领子扣不上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d88747a-ad7c-4c30-8cd2-ef8e3ad8f667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92865, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "背", "is_correct": true, "explanation": "正确答案：背（bèi），指人身体后面、与肚子相反的一边。"}, {"text": "悲", "is_correct": false, "explanation": "bēi（第一声）与 bèi（第四声）只有声调不同，意思是伤心、悲伤。"}, {"text": "妹", "is_correct": false, "explanation": "mèi 与 bèi 只有声母不同（m 与 b），意思是妹妹。"}, {"text": "笨", "is_correct": false, "explanation": "bèn 与 bèi 只有韵母不同（-en 与 -ei），意思是不聪明、笨拙。"}, {"text": "费", "is_correct": false, "explanation": "fèi 与 bèi 只有声母不同（f 与 b），意思是花费、费用。"}], "explanations": {"背": "正确答案：背（bèi），指人身体后面、与肚子相反的一边。", "悲": "bēi（第一声）与 bèi（第四声）只有声调不同，意思是伤心、悲伤。", "妹": "mèi 与 bèi 只有声母不同（m 与 b），意思是妹妹。", "笨": "bèn 与 bèi 只有韵母不同（-en 与 -ei），意思是不聪明、笨拙。", "费": "fèi 与 bèi 只有声母不同（f 与 b），意思是花费、费用。"}, "sentence_index": null, "correct_answer": "背"}, "level_3": {"options": [{"text": "背", "is_correct": true, "explanation": "正确答案：背，指人身体的后部，手可以放在上面。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间是抽象概念，没有实体可以承放手，“放在我的时间上”说不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是体型的高度，不是可以放手的部位。"}, {"text": "意见", "is_correct": false, "explanation": "语义：意见是抽象的想法，没有实体，不能“把手放在我的意见上”。"}], "explanations": {"背": "正确答案：背，指人身体的后部，手可以放在上面。", "时间": "语义：时间是抽象概念，没有实体可以承放手，“放在我的时间上”说不通。", "身高": "体貌：身高是体型的高度，不是可以放手的部位。", "意见": "语义：意见是抽象的想法，没有实体，不能“把手放在我的意见上”。"}, "sentence_index": 6, "correct_answer": "背"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把戒指戴在背上，很得意。", "explanation": "这里应该用〈手指〉。戒指要戴在手指上，背在身后，不能戴戒指。"}, {"text": "他张开背，大声地唱起歌来。", "explanation": "这里应该用〈嘴〉。唱歌要张开嘴，背是躯干后部，不能张开唱歌。"}, {"text": "他用背听了一下，然后笑了起来。", "explanation": "这里应该用〈耳朵〉。听声音要用耳朵，背不能用来听。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d88747a-ad7c-4c30-8cd2-ef8e3ad8f667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92865, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把行李放在背里，走进了山里。", "corrected_sentence": "他把行李放在背上，走进了山里。", "error_description": "错误：“放在背里”；正确：“放在背上”。“背”在身体表面，表示位置要用“上”，不能用“里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d88747a-ad7c-4c30-8cd2-ef8e3ad8f667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92865, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在海边晒了一天，把背黑晒了。", "corrected_sentence": "他在海边晒了一天，把背晒黑了。", "error_description": "错误：“把背黑晒了”；正确：“把背晒黑了”。表示结果的“黑”要放在动词“晒”之后作结果补语，不能放在动词前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d88747a-ad7c-4c30-8cd2-ef8e3ad8f667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
