INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92866, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "动物（如鸟、兽、鱼）躯干的后部，与肚子相对的一面。", "primary_collocate": null, "pronunciation": "bèi", "ipa": "pei˥˩", "syllable_count": 1, "sentences": [{"text": "小鸟的背是灰色的。", "target_word": "背", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只骆驼的背上放着很多东西。", "target_word": "背", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩骑在大象的背上笑着。", "target_word": "背", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条鱼的背是黑色的，肚子是白色的。", "target_word": "背", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猫一生气，背就弯得高高的。", "target_word": "背", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乌龟的背上有一个硬壳。", "target_word": "背", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗的背上落了很多雪。", "target_word": "背", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牛的背上站着一只小鸟。", "target_word": "背", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "青蛙的背是绿色的。", "target_word": "背", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老虎的背上有黑色的条纹。", "target_word": "背", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "背部", "label": "复合"}], "register": "中性", "sense_fingerprint": "动物躯干的后部（背上、背是某种颜色）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5582003f-0fa5-4559-bf80-a34613800f6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92866, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "背", "is_correct": true, "explanation": "正确答案：背（bèi），指人或动物躯干的后部。"}, {"text": "北", "is_correct": false, "explanation": "běi（第三声）与 bèi（第四声）只有声调不同，意思是北方。"}, {"text": "配", "is_correct": false, "explanation": "pèi 与 bèi 只有声母不同（p 送气，b 不送气），意思是配合、搭配。"}, {"text": "拜", "is_correct": false, "explanation": "bài 与 bèi 只有韵母不同（-ai 与 -ei），意思是拜访、行礼。"}, {"text": "悲", "is_correct": false, "explanation": "bēi（第一声）与 bèi（第四声）只有声调不同，意思是伤心、悲伤。"}], "explanations": {"背": "正确答案：背（bèi），指人或动物躯干的后部。", "北": "běi（第三声）与 bèi（第四声）只有声调不同，意思是北方。", "配": "pèi 与 bèi 只有声母不同（p 送气，b 不送气），意思是配合、搭配。", "拜": "bài 与 bèi 只有韵母不同（-ai 与 -ei），意思是拜访、行礼。", "悲": "bēi（第一声）与 bèi（第四声）只有声调不同，意思是伤心、悲伤。"}, "sentence_index": null, "correct_answer": "背"}, "level_3": {"options": [{"text": "背", "is_correct": true, "explanation": "正确答案：背，指小鸟身体的后部，颜色可以是灰色的。"}, {"text": "道理", "is_correct": false, "explanation": "语义：道理是抽象的事理，没有颜色，“小鸟的道理是灰色的”说不通。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材指体型，不能用颜色来描述，这里说不通。"}, {"text": "头发", "is_correct": false, "explanation": "搭配：“灰色”多用于羽毛等，不能说小鸟的“头发是灰色的”。"}], "explanations": {"背": "正确答案：背，指小鸟身体的后部，颜色可以是灰色的。", "道理": "语义：道理是抽象的事理，没有颜色，“小鸟的道理是灰色的”说不通。", "身材": "体貌：身材指体型，不能用颜色来描述，这里说不通。", "头发": "搭配：“灰色”多用于羽毛等，不能说小鸟的“头发是灰色的”。"}, "sentence_index": 0, "correct_answer": "背"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小鸟张开背，飞上了天空。", "explanation": "这里应该用〈翅膀〉。背是躯干后部，不能张开；鸟飞要张开的是翅膀。"}, {"text": "小狗高兴地摇着背，跑来跑去。", "explanation": "这里应该用〈尾巴〉。摇动的是尾巴，尾巴在身体末端，不是躯干后部。"}, {"text": "小猪吃得太饱，背鼓得像个皮球。", "explanation": "这里应该用〈肚子〉。背与肚子在躯干两侧，吃饱后鼓起来的是肚子，不能说背鼓。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d88747a-ad7c-4c30-8cd2-ef8e3ad8f667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92866, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "背", "is_correct": true, "explanation": "正确答案：背（bèi），指人或动物躯干的后部。"}, {"text": "杯", "is_correct": false, "explanation": "bēi（第一声）与 bèi（第四声）只有声调不同，意思是杯子。"}, {"text": "妹", "is_correct": false, "explanation": "mèi 与 bèi 只有声母不同（m 与 b），意思是妹妹。"}, {"text": "笨", "is_correct": false, "explanation": "bèn 与 bèi 只有韵母不同（-en 与 -ei），意思是不聪明、笨拙。"}, {"text": "费", "is_correct": false, "explanation": "fèi 与 bèi 只有声母不同（f 与 b），意思是花费、费用。"}], "explanations": {"背": "正确答案：背（bèi），指人或动物躯干的后部。", "杯": "bēi（第一声）与 bèi（第四声）只有声调不同，意思是杯子。", "妹": "mèi 与 bèi 只有声母不同（m 与 b），意思是妹妹。", "笨": "bèn 与 bèi 只有韵母不同（-en 与 -ei），意思是不聪明、笨拙。", "费": "fèi 与 bèi 只有声母不同（f 与 b），意思是花费、费用。"}, "sentence_index": null, "correct_answer": "背"}, "level_3": {"options": [{"text": "背", "is_correct": true, "explanation": "正确答案：背，指小狗身体的后部，雪可以落在上面。"}, {"text": "影子", "is_correct": false, "explanation": "语义：影子是光线形成的暗影，不能积雪，“小狗的影子上落了很多雪”说不通。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字是抽象的称呼，不会有雪落在上面。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“落”指雪、灰尘等落在实体上，“颜色”不能承接积雪。"}], "explanations": {"背": "正确答案：背，指小狗身体的后部，雪可以落在上面。", "影子": "语义：影子是光线形成的暗影，不能积雪，“小狗的影子上落了很多雪”说不通。", "名字": "语义：名字是抽象的称呼，不会有雪落在上面。", "颜色": "搭配：“落”指雪、灰尘等落在实体上，“颜色”不能承接积雪。"}, "sentence_index": 6, "correct_answer": "背"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小猫用背看清了远处的小鸟。", "explanation": "这里应该用〈眼睛〉。看东西要用眼睛，背是动物躯干的后部，不能用来看。"}, {"text": "小狗把背张开，汪汪地叫了起来。", "explanation": "这里应该用〈嘴〉。汪汪叫要张嘴，背不能张开叫。"}, {"text": "小鸟用背闻了闻花的香味。", "explanation": "这里应该用〈鼻子〉。闻气味要用鼻子，背不能用来闻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d88747a-ad7c-4c30-8cd2-ef8e3ad8f667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92866, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小猫被吓到以后，背弓高高的。", "corrected_sentence": "小猫被吓到以后，背弓得高高的。", "error_description": "错误：“背弓高高的”；正确：“背弓得高高的”。动词后接表示程度或结果的补语时要用“得”，不能直接接形容词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d88747a-ad7c-4c30-8cd2-ef8e3ad8f667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92866, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只狮子的背金黄色的。", "corrected_sentence": "这只狮子的背是金黄色的。", "error_description": "错误：“背金黄色的”；正确：“背是金黄色的”。描述事物的颜色时，主语后要用“是”连接，漏掉“是”句子不完整。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d88747a-ad7c-4c30-8cd2-ef8e3ad8f667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
