INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92867, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "真是的是说话的人有点生气，觉得对方做得不好。", "primary_collocate": null, "pronunciation": "zhēn shì de", "ipa": "ʈʂən˥ ʂɻ̩˥˩ tə", "syllable_count": 3, "sentences": [{"text": "真是的，你怎么又忘了带钥匙？", "target_word": "真是的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不打招呼就走了，真是的！", "target_word": "真是的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "真是的，说好六点见面，现在都七点了。", "target_word": "真是的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈看到房间这么乱，生气地说：“真是的！”", "target_word": "真是的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "真是的，这么晚还不回家，也不打电话。", "target_word": "真是的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你真是的，我说过很多次了，别在床上吃东西。", "target_word": "真是的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥又把杯子放在桌子边上，真是的。", "target_word": "真是的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "真是的，下雨天出门也不带伞。", "target_word": "真是的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师小声说：“真是的，作业又没写完。”", "target_word": "真是的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把我的书弄脏了，还不说话，真是的！", "target_word": "真是的", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "口语感叹：有点生气，觉得对方做得不好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '964c90de-6e63-4a08-9795-75c3d131a85e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92867, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "真是的", "is_correct": true, "explanation": "真是的是口语感叹，表示埋怨和不满，是本题的目标词。"}, {"text": "真实的", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是真实的。"}, {"text": "阵势的", "is_correct": false, "explanation": "zhèn（第四声）与 zhēn（第一声）声调不同，意思是阵势。"}, {"text": "诊室的", "is_correct": false, "explanation": "zhěn（第三声）与 zhēn（第一声）声调不同，意思是诊室。"}], "explanations": {"真是的": "真是的是口语感叹，表示埋怨和不满，是本题的目标词。", "真实的": "shí（第二声）与 shì（第四声）声调不同，意思是真实的。", "阵势的": "zhèn（第四声）与 zhēn（第一声）声调不同，意思是阵势。", "诊室的": "zhěn（第三声）与 zhēn（第一声）声调不同，意思是诊室。"}, "sentence_index": null, "correct_answer": "真是的"}, "level_3": {"options": [{"text": "真是的", "is_correct": true, "explanation": "真是的表示埋怨、不满，与“又忘了带钥匙”的语境相符。"}, {"text": "太好了", "is_correct": false, "explanation": "语义：“太好了”表示高兴、满意，与“又忘了带钥匙”的责备语境相反。"}, {"text": "好耶", "is_correct": false, "explanation": "语义：“好耶”表示欢呼和高兴，与责备的语境不合。"}, {"text": "呸", "is_correct": false, "explanation": "语域：“呸”是带轻蔑的粗口式感叹，不能用于轻微的埋怨。"}], "explanations": {"真是的": "真是的表示埋怨、不满，与“又忘了带钥匙”的语境相符。", "太好了": "语义：“太好了”表示高兴、满意，与“又忘了带钥匙”的责备语境相反。", "好耶": "语义：“好耶”表示欢呼和高兴，与责备的语境不合。", "呸": "语域：“呸”是带轻蔑的粗口式感叹，不能用于轻微的埋怨。"}, "sentence_index": 0, "correct_answer": "真是的"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "尊敬的各位来宾，真是的，欢迎大家光临本次会议。", "explanation": "这里混淆了“真是的”的埋怨义与正式致辞的客套义：“真是的”是私下的埋怨口语，不能用在正式的迎宾致辞中。"}, {"text": "这幅画的颜色太漂亮了，真是的！", "explanation": "“真是的”只表示埋怨和不满，用来赞美画作时感情色彩完全相反。"}, {"text": "他刚拿到奖学金，真是的，全家都高兴极了。", "explanation": "这里把“真是的”用成了表示高兴、庆贺的感叹，但它只表示埋怨和不满，与喜讯的语气不合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f5f1d31-ca2a-49c7-8237-0c9588c31fa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92867, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "真是的", "is_correct": true, "explanation": "真是的表示埋怨，与“又把杯子放在桌子边上”的不满语境相符。"}, {"text": "哇塞", "is_correct": false, "explanation": "语域：“哇塞”是年轻人俏皮的赞叹语，与对家人的埋怨语气不合。"}, {"text": "嘻嘻", "is_correct": false, "explanation": "语义：“嘻嘻”表示轻松嬉笑，没有埋怨的意思，与语境不合。"}, {"text": "咦", "is_correct": false, "explanation": "语义：“咦”表示疑惑或意外，与“又把杯子放在桌子边上”的责备语境不符。"}], "explanations": {"真是的": "真是的表示埋怨，与“又把杯子放在桌子边上”的不满语境相符。", "哇塞": "语域：“哇塞”是年轻人俏皮的赞叹语，与对家人的埋怨语气不合。", "嘻嘻": "语义：“嘻嘻”表示轻松嬉笑，没有埋怨的意思，与语境不合。", "咦": "语义：“咦”表示疑惑或意外，与“又把杯子放在桌子边上”的责备语境不符。"}, "sentence_index": 6, "correct_answer": "真是的"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个消息太好了，真是的，我们都笑得合不拢嘴。", "explanation": "这里把“真是的”用成了表示高兴、称赞的语气，但它只表示埋怨和不满，与喜讯的情感不合。"}, {"text": "他第一次做饭，真是的，味道好极了。", "explanation": "这里把“真是的”用成了赞美义，但它只表示埋怨和不满，夸奖味道时语气相反。"}, {"text": "这份研究报告的结论十分严谨，真是的，值得大家认真学习。", "explanation": "这里把“真是的”用成了赞许义，但它只表示埋怨和不满，与对报告的肯定语气不合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f5f1d31-ca2a-49c7-8237-0c9588c31fa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92867, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "真是的了，你怎么又把钥匙忘在家里了？", "corrected_sentence": "真是的，你怎么又把钥匙忘在家里了？", "error_description": "错误形式：“真是的了”；正确形式：“真是的”。“真是的”是独立的口语感叹语，后面不能再加语气助词“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f5f1d31-ca2a-49c7-8237-0c9588c31fa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92867, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "太真是的，你们怎么又吵起来了？", "corrected_sentence": "真是的，你们怎么又吵起来了？", "error_description": "错误形式：“太真是的”；正确形式：“真是的”。“太”是程度副词，不能修饰叹词“真是的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f5f1d31-ca2a-49c7-8237-0c9588c31fa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
