INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92868, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "（口语）表示埋怨、不满的感叹语。", "primary_collocate": null, "pronunciation": "zhēn shì de", "ipa": "ʈʂən˥ ʂɻ̩˥˩ tə", "syllable_count": 3, "sentences": [{"text": "真是的，电梯怎么又坏了？", "target_word": "真是的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "真是的，我刚洗好的衣服又脏了。", "target_word": "真是的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他笑着说：“你真是的，别开这种玩笑。”", "target_word": "真是的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "真是的，路这么堵，我们要迟到了。", "target_word": "真是的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟又把玩具扔得到处都是，真是的。", "target_word": "真是的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "真是的，你为什么不早点告诉我？", "target_word": "真是的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶看着不吃饭的孙子说：“真是的！”", "target_word": "真是的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "真是的，大家都在等你，你还在玩手机。", "target_word": "真是的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同事又没关灯就走了，真是的。", "target_word": "真是的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "真是的，我的话你一点都不听。", "target_word": "真是的", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "口语感叹语：表示埋怨、不满", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '964c90de-6e63-4a08-9795-75c3d131a85e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92868, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "真是的", "is_correct": true, "explanation": "真是的是口语感叹，表示埋怨和不满，是本题的目标词。"}, {"text": "真实的", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是真实的。"}, {"text": "阵势的", "is_correct": false, "explanation": "zhèn（第四声）与 zhēn（第一声）声调不同，意思是阵势。"}, {"text": "身世的", "is_correct": false, "explanation": "shēn 与 zhēn 的声母不同（sh 与 zh），意思是身世。"}, {"text": "诊室的", "is_correct": false, "explanation": "zhěn（第三声）与 zhēn（第一声）声调不同，意思是诊室。"}], "explanations": {"真是的": "真是的是口语感叹，表示埋怨和不满，是本题的目标词。", "真实的": "shí（第二声）与 shì（第四声）声调不同，意思是真实的。", "阵势的": "zhèn（第四声）与 zhēn（第一声）声调不同，意思是阵势。", "身世的": "shēn 与 zhēn 的声母不同（sh 与 zh），意思是身世。", "诊室的": "zhěn（第三声）与 zhēn（第一声）声调不同，意思是诊室。"}, "sentence_index": null, "correct_answer": "真是的"}, "level_3": {"options": [{"text": "真是的", "is_correct": true, "explanation": "真是的表示埋怨，与“电梯怎么又坏了”的不满语境相符。"}, {"text": "好耶", "is_correct": false, "explanation": "语义：“好耶”表示欢呼和高兴，与电梯又坏了的不满语境相反。"}, {"text": "耶", "is_correct": false, "explanation": "语义：“耶”用于欢呼庆祝，与埋怨的语境不符。"}, {"text": "太棒了", "is_correct": false, "explanation": "语义：“太棒了”表示称赞和高兴，与电梯又坏了的不满语境相反。"}], "explanations": {"真是的": "真是的表示埋怨，与“电梯怎么又坏了”的不满语境相符。", "好耶": "语义：“好耶”表示欢呼和高兴，与电梯又坏了的不满语境相反。", "耶": "语义：“耶”用于欢呼庆祝，与埋怨的语境不符。", "太棒了": "语义：“太棒了”表示称赞和高兴，与电梯又坏了的不满语境相反。"}, "sentence_index": 0, "correct_answer": "真是的"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "各位同事请注意，真是的，本次会议请准时参加。", "explanation": "这里混淆了“真是的”的埋怨义与正式通知的语体：它是私下的口语感叹，不能用于正式通知。"}, {"text": "这首歌真好听，真是的！", "explanation": "“真是的”只表示埋怨和不满，用来称赞歌曲时感情色彩相反。"}, {"text": "妈妈听到好消息，真是的，笑个不停。", "explanation": "这里把“真是的”用成了表示高兴的感叹，但它只表示埋怨和不满，与喜悦的语气不合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f5f1d31-ca2a-49c7-8237-0c9588c31fa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92868, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "真是的", "is_correct": true, "explanation": "真是的表示埋怨，与奶奶对不吃饭的孙子的不满语气相符。"}, {"text": "太好了", "is_correct": false, "explanation": "语义：“太好了”表示高兴满意，与孙子不吃饭引起的不满语气相反。"}, {"text": "嘻嘻", "is_correct": false, "explanation": "语义：“嘻嘻”表示轻松嬉笑，没有责备的意思，与语境不合。"}, {"text": "咦", "is_correct": false, "explanation": "语义：“咦”表示疑惑或意外，与孙子不吃饭引起的不满语境不符。"}], "explanations": {"真是的": "真是的表示埋怨，与奶奶对不吃饭的孙子的不满语气相符。", "太好了": "语义：“太好了”表示高兴满意，与孙子不吃饭引起的不满语气相反。", "嘻嘻": "语义：“嘻嘻”表示轻松嬉笑，没有责备的意思，与语境不合。", "咦": "语义：“咦”表示疑惑或意外，与孙子不吃饭引起的不满语境不符。"}, "sentence_index": 6, "correct_answer": "真是的"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师，真是的，谢谢您的指导。", "explanation": "语用：“真是的”是对他人不如意之事的埋怨，对老师表示感谢时使用，语境相反，显得不礼貌。"}, {"text": "我们终于完成了计划，真是的，大家都很高兴。", "explanation": "这里把“真是的”当作表示高兴的感叹用了，但它只表示埋怨和不满，与完成计划的喜悦不合。"}, {"text": "他的画得了金奖，真是的，我们都为他骄傲。", "explanation": "这里把“真是的”用成了表示骄傲、称赞的语气，但它只表示埋怨和不满，与为他骄傲的情感不合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f5f1d31-ca2a-49c7-8237-0c9588c31fa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
