INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92868, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "很真是的，奶奶等你吃饭，你怎么又不吃？", "corrected_sentence": "真是的，奶奶等你吃饭，你怎么又不吃？", "error_description": "错误形式：“很真是的”；正确形式：“真是的”。“很”是程度副词，不能修饰叹词“真是的”，这个感叹语前面不能加“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f5f1d31-ca2a-49c7-8237-0c9588c31fa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
