INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92869, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "解除是把原来有的限制去掉。", "primary_collocate": null, "pronunciation": "jiě chú", "ipa": "tɕjɛ˨˩ ʈʂʰu˧˥", "syllable_count": 2, "sentences": [{"text": "政府解除了旅行的限制。", "target_word": "解除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长解除了手机的禁令。", "target_word": "解除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校解除了学生晚上外出的限制。", "target_word": "解除", "complexity_tier": "T3", "furigana": "xué xiào jiě chú le xué shēng wǎn shàng wài chū de xiàn zhì", "sentence_source": "generated"}, {"text": "城市的封锁今天解除了。", "target_word": "解除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈解除了对我的限制，我能晚点回家。", "target_word": "解除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周一，这条路的交通管制就解除了。", "target_word": "解除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师解除了不能说话的规定。", "target_word": "解除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛结束后，对球员的禁赛解除了。", "target_word": "解除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板解除了员工周末加班的限制。", "target_word": "解除", "complexity_tier": "T3", "furigana": "lǎo bǎn jiě chú le yuán gōng zhōu mò jiā bān de xiàn zhì", "sentence_source": "generated"}, {"text": "国家解除了对这种水果的进口限制。", "target_word": "解除", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "解除了", "label": "体标（了）"}, {"form": "解除过", "label": "体标（过）"}, {"form": "解除禁令", "label": "复合"}], "register": "书面", "sense_fingerprint": "把原有的限制、禁令、管制等去掉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2247d90f-0ad5-44a6-82f3-355e9a0b1ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92869, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "解除", "is_correct": true, "explanation": "正确答案：解除（jiěchú）。"}, {"text": "戒除", "is_correct": false, "explanation": "戒除 jièchú 与 解除 jiěchú 只有第一个音节声调不同（jiè 为第四声，jiě 为第三声），意思是戒掉。"}, {"text": "接触", "is_correct": false, "explanation": "接触 jiēchù 与 解除 jiěchú 两个音节的声调都不同，意思是碰到、联系。"}, {"text": "解出", "is_correct": false, "explanation": "解出 jiěchū 与 解除 jiěchú 只有第二个音节声调不同（chū 为第一声），意思是算出、解答出来。"}, {"text": "借出", "is_correct": false, "explanation": "借出 jièchū 与 解除 jiěchú 两个音节的声调都不同，意思是借给别人。"}], "explanations": {"解除": "正确答案：解除（jiěchú）。", "戒除": "戒除 jièchú 与 解除 jiěchú 只有第一个音节声调不同（jiè 为第四声，jiě 为第三声），意思是戒掉。", "接触": "接触 jiēchù 与 解除 jiěchú 两个音节的声调都不同，意思是碰到、联系。", "解出": "解出 jiěchū 与 解除 jiěchú 只有第二个音节声调不同（chū 为第一声），意思是算出、解答出来。", "借出": "借出 jièchū 与 解除 jiěchú 两个音节的声调都不同，意思是借给别人。"}, "sentence_index": null, "correct_answer": "解除"}, "level_3": {"options": [{"text": "解除", "is_correct": true, "explanation": "解除：去掉政府对旅行的限制，与句意相合。"}, {"text": "享受", "is_correct": false, "explanation": "搭配：“享受”多搭配生活、待遇，不说享受限制。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”的对象是艺术、风景，限制不能被欣赏。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：“驾驶”的对象是车、船、飞机，不说驾驶限制。"}], "explanations": {"解除": "解除：去掉政府对旅行的限制，与句意相合。", "享受": "搭配：“享受”多搭配生活、待遇，不说享受限制。", "欣赏": "语义：“欣赏”的对象是艺术、风景，限制不能被欣赏。", "驾驶": "搭配：“驾驶”的对象是车、船、飞机，不说驾驶限制。"}, "sentence_index": 0, "correct_answer": "解除"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个航班终于解除了。", "explanation": "这里应该用〈取消〉。解除用于限制、危险、约定等，航班不再飞要用取消。"}, {"text": "他解除了背包。", "explanation": "这里应该用〈解开〉。解除指消除抽象的限制，把背包的带子打开要用解开。"}, {"text": "这场比赛解除了。", "explanation": "这里应该用〈结束〉。解除用于限制、危险、约定等，比赛完了要用结束。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b17ac9-90e3-47d7-bc08-ac64f78b44c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92869, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "解除", "is_correct": true, "explanation": "解除：取消老师不能说话的规定，与句意相合。"}, {"text": "品尝", "is_correct": false, "explanation": "搭配：“品尝”多搭配食物，不说品尝规定。"}, {"text": "修剪", "is_correct": false, "explanation": "语义：“修剪”指剪掉多余的枝叶，规定不能被修剪。"}, {"text": "烤", "is_correct": false, "explanation": "语义：“烤”指用火加热食物，规定不能被烤。"}], "explanations": {"解除": "解除：取消老师不能说话的规定，与句意相合。", "品尝": "搭配：“品尝”多搭配食物，不说品尝规定。", "修剪": "语义：“修剪”指剪掉多余的枝叶，规定不能被修剪。", "烤": "语义：“烤”指用火加热食物，规定不能被烤。"}, "sentence_index": 6, "correct_answer": "解除"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "法院解除了这项判决。", "explanation": "这里应该用〈撤销〉。解除用于限制、危险、约定等，推翻判决要用撤销。"}, {"text": "医生解除了他的阑尾。", "explanation": "这里应该用〈摘除〉。解除不用于切除器官，切除阑尾要用摘除。"}, {"text": "公司解除了这个团队。", "explanation": "这里应该用〈解散〉。解除不用于团队，团体散掉要用解散。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b17ac9-90e3-47d7-bc08-ac64f78b44c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92869, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们终于解除在对出境的限制。", "corrected_sentence": "他们终于解除了对出境的限制。", "error_description": "“在”误用：“解除”后面接“了”表示完成，不能接“在”，应说“解除了对出境的限制”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b17ac9-90e3-47d7-bc08-ac64f78b44c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
