INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92870, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "消除；去掉（限制、危险、约定等）。", "primary_collocate": null, "pronunciation": "jiě chú", "ipa": "tɕjɛ˨˩ ʈʂʰu˧˥", "syllable_count": 2, "sentences": [{"text": "公司和他解除了合同。", "target_word": "解除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，他的危险已经解除了。", "target_word": "解除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听了她的话，我的误会解除了。", "target_word": "解除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警报终于解除了，大家回家了。", "target_word": "解除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板和他解除了约定。", "target_word": "解除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃了这种药，他的痛苦解除了。", "target_word": "解除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两家公司解除了合作协议。", "target_word": "解除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "隔离解除后，他马上去看奶奶。", "target_word": "解除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药能解除你的疲劳。", "target_word": "解除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨停后，山上的警戒解除了。", "target_word": "解除", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "解除了", "label": "体标（了）"}, {"form": "解除过", "label": "体标（过）"}, {"form": "解除合同", "label": "复合"}], "register": "书面", "sense_fingerprint": "消除或去掉限制、危险、约定、误会等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2247d90f-0ad5-44a6-82f3-355e9a0b1ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92870, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "解除", "is_correct": true, "explanation": "正确答案：解除（jiěchú）。"}, {"text": "戒除", "is_correct": false, "explanation": "戒除 jièchú 与 解除 jiěchú 只有第一个音节声调不同（jiè 为第四声，jiě 为第三声），意思是戒掉（习惯）。"}, {"text": "接触", "is_correct": false, "explanation": "接触 jiēchù 与 解除 jiěchú 两个音节的声调都不同（jiē 为第一声，chù 为第四声），意思是碰到、联系。"}, {"text": "解出", "is_correct": false, "explanation": "解出 jiěchū 与 解除 jiěchú 只有第二个音节声调不同（chū 为第一声），意思是算出、解答出来。"}, {"text": "借出", "is_correct": false, "explanation": "借出 jièchū 与 解除 jiěchú 两个音节的声调都不同，意思是借给别人。"}], "explanations": {"解除": "正确答案：解除（jiěchú）。", "戒除": "戒除 jièchú 与 解除 jiěchú 只有第一个音节声调不同（jiè 为第四声，jiě 为第三声），意思是戒掉（习惯）。", "接触": "接触 jiēchù 与 解除 jiěchú 两个音节的声调都不同（jiē 为第一声，chù 为第四声），意思是碰到、联系。", "解出": "解出 jiěchū 与 解除 jiěchú 只有第二个音节声调不同（chū 为第一声），意思是算出、解答出来。", "借出": "借出 jièchū 与 解除 jiěchú 两个音节的声调都不同，意思是借给别人。"}, "sentence_index": null, "correct_answer": "解除"}, "level_3": {"options": [{"text": "解除", "is_correct": true, "explanation": "解除：消除合同的约束，与句意相合。"}, {"text": "设立", "is_correct": false, "explanation": "搭配：“设立”多搭配机构、制度，不说设立合同。"}, {"text": "参观", "is_correct": false, "explanation": "语义：“参观”的对象是场所、展览等，合同不能被参观。"}, {"text": "享用", "is_correct": false, "explanation": "搭配：“享用”多搭配食物、待遇，不说享用合同。"}], "explanations": {"解除": "解除：消除合同的约束，与句意相合。", "设立": "搭配：“设立”多搭配机构、制度，不说设立合同。", "参观": "语义：“参观”的对象是场所、展览等，合同不能被参观。", "享用": "搭配：“享用”多搭配食物、待遇，不说享用合同。"}, "sentence_index": 0, "correct_answer": "解除"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场比赛因为大雨解除了。", "explanation": "这里应该用〈取消〉。解除用于限制、危险、约定等，比赛不再举行要用取消。"}, {"text": "法院解除了这项判决。", "explanation": "这里应该用〈撤销〉。解除多用于限制、危险、约定等，推翻判决要用撤销。"}, {"text": "他解除了鞋带。", "explanation": "这里应该用〈解开〉。解除指消除限制、危险等抽象的东西，把鞋带的结打开要用解开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b17ac9-90e3-47d7-bc08-ac64f78b44c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92870, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "解除", "is_correct": true, "explanation": "解除：去掉协议的约束，符合句意。"}, {"text": "烘焙", "is_correct": false, "explanation": "语义：“烘焙”指做面包、点心，协议不能被烘焙。"}, {"text": "浇灌", "is_correct": false, "explanation": "语义：“浇灌”用于植物或土地，与协议无关。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：“驾驶”的对象是车、船、飞机，不说驾驶协议。"}], "explanations": {"解除": "解除：去掉协议的约束，符合句意。", "烘焙": "语义：“烘焙”指做面包、点心，协议不能被烘焙。", "浇灌": "语义：“浇灌”用于植物或土地，与协议无关。", "驾驶": "搭配：“驾驶”的对象是车、船、飞机，不说驾驶协议。"}, "sentence_index": 6, "correct_answer": "解除"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "垃圾终于解除了。", "explanation": "这里应该用〈清除〉。解除用于消除限制、危险、约定等，垃圾被清走要用清除。"}, {"text": "这个社团解除了。", "explanation": "这里应该用〈解散〉。解除针对限制、危险、约定等，社团解体、不再存在要用解散。"}, {"text": "士兵解除了阵地。", "explanation": "这里应该用〈撤离〉。解除针对限制或封锁，士兵离开阵地是转移，要用撤离。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b17ac9-90e3-47d7-bc08-ac64f78b44c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92870, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她终于解除在心里的顾虑。", "corrected_sentence": "她终于解除了心里的顾虑。", "error_description": "“在”误用：“解除”后面接“了”表示完成，不能接“在”，应说“解除了心里的顾虑”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b17ac9-90e3-47d7-bc08-ac64f78b44c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92870, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的疑虑还没有解除了。", "corrected_sentence": "他的疑虑还没有解除。", "error_description": "“了”误用：“还没有”否定尚未发生的动作，句末不能加“了”，应说“还没有解除”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b17ac9-90e3-47d7-bc08-ac64f78b44c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
