INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92872, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "真理；正道（宗教用语，特指基督教教义）。", "primary_collocate": null, "pronunciation": "zhēn dào", "ipa": "ʈʂən˥ tau˥˩", "syllable_count": 2, "sentences": [{"text": "他在教会里听到了真道，决定信主。", "target_word": "真道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牧师常常给大家讲真道。", "target_word": "真道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人一生都在寻找真道。", "target_word": "真道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教会的人说，真道能给人带来平安。", "target_word": "真道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他读了《圣经》，慢慢明白了真道。", "target_word": "真道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "传教士把真道带到了这个小村子。", "target_word": "真道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她相信真道，每个星期天都去教堂。", "target_word": "真道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟兄姐妹们一起学习真道。", "target_word": "真道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻时他不懂真道，后来才信了。", "target_word": "真道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牧师说，真道比金子还宝贵。", "target_word": "真道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "基督教所说的真理与正道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd93837-ff1f-44d8-9b8c-6d7a0431f7eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92872, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "真道", "is_correct": true, "explanation": "正确：“真道”指基督教所说的真理，与“听到了……决定信主”相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“听到”的内容应是话语或消息，天气与“决定信主”无关。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是可以被“听到”的内容，与信主无关。"}, {"text": "眼泪", "is_correct": false, "explanation": "搭配：“听到”配声音、消息，不配“眼泪”。"}], "explanations": {"真道": "正确：“真道”指基督教所说的真理，与“听到了……决定信主”相符。", "天气": "语义：“听到”的内容应是话语或消息，天气与“决定信主”无关。", "石头": "语义：石头不是可以被“听到”的内容，与信主无关。", "眼泪": "搭配：“听到”配声音、消息，不配“眼泪”。"}, "sentence_index": 0, "correct_answer": "真道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他买了一件真道，穿在身上。", "explanation": "这里应该用〈衣服〉。衣服可以买、可以穿，“真道”是宗教真理，不能穿在身上。"}, {"text": "她每天早上给真道喂饭。", "explanation": "这里应该用〈小狗〉。小狗可以喂饭，“真道”是宗教真理，不能喂饭。"}, {"text": "孩子们在操场上踢那个真道。", "explanation": "这里应该用〈足球〉。足球可以踢，“真道”是宗教真理，不能被踢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60d60860-2d32-4eff-ad4b-bfb7fc1c6c2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92872, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "真道", "is_correct": true, "explanation": "正确：“相信真道”与“每个星期天都去教堂”的语境相符。"}, {"text": "数学", "is_correct": false, "explanation": "语义：“相信”的对象是信仰或道理，数学与去教堂的语境不符。"}, {"text": "小说", "is_correct": false, "explanation": "语义：小说是虚构的故事，不是信仰的对象，与去教堂的语境冲突。"}, {"text": "蛋糕", "is_correct": false, "explanation": "搭配：“相信”配道理或人，不配“蛋糕”。"}], "explanations": {"真道": "正确：“相信真道”与“每个星期天都去教堂”的语境相符。", "数学": "语义：“相信”的对象是信仰或道理，数学与去教堂的语境不符。", "小说": "语义：小说是虚构的故事，不是信仰的对象，与去教堂的语境冲突。", "蛋糕": "搭配：“相信”配道理或人，不配“蛋糕”。"}, "sentence_index": 6, "correct_answer": "真道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在厨房里炒了一个真道。", "explanation": "这里应该用〈菜〉。菜可以炒，“真道”是宗教真理，不能被炒。"}, {"text": "老师在操场上骑真道。", "explanation": "这里应该用〈自行车〉。自行车可以骑，“真道”不能被骑。"}, {"text": "他在河边钓了一条真道。", "explanation": "这里应该用〈鱼〉。鱼可以钓，“真道”不能被钓。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60d60860-2d32-4eff-ad4b-bfb7fc1c6c2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92872, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位真道能让人得到平安。", "corrected_sentence": "这种真道能让人得到平安。", "error_description": "量词错误：“真道”指教义，不指人，量词应用“种”，不能用“位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60d60860-2d32-4eff-ad4b-bfb7fc1c6c2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92872, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "弟兄们每周聚会，一起学习真道们。", "corrected_sentence": "弟兄们每周聚会，一起学习真道。", "error_description": "“真道们”是错误形式，应为“真道”。“真道”是抽象名词，不指人，不能加“们”表示复数。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60d60860-2d32-4eff-ad4b-bfb7fc1c6c2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
