INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92873, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "谋杀是事先想好，害死别人。", "primary_collocate": null, "pronunciation": "móu shā", "ipa": "mou̯˧˥ ʂa˥", "syllable_count": 2, "sentences": [{"text": "他计划谋杀自己的妻子。", "target_word": "谋杀", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "警察说，这个人谋杀了他的朋友。", "target_word": "谋杀", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书里的坏人为了钱谋杀老人。", "target_word": "谋杀", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察正在查他为什么谋杀邻居。", "target_word": "谋杀", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个男人谋杀过两个人，后来跑了。", "target_word": "谋杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们计划在周末谋杀那位经理。", "target_word": "谋杀", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法官问他：“你为什么要谋杀她？”", "target_word": "谋杀", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个电影讲的是一个人谋杀朋友的故事。", "target_word": "谋杀", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把毒药放进杯子里，想谋杀老板。", "target_word": "谋杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说自己没有谋杀丈夫，只是和他吵了一架。", "target_word": "谋杀", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "谋杀了", "label": "体标（了）"}, {"form": "谋杀过", "label": "体标（过）"}, {"form": "谋杀案", "label": "复合词"}, {"form": "谋杀犯", "label": "复合词"}], "register": "中性", "sense_fingerprint": "事先计划好后杀死别人的行为", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1bf60fe-067d-49a1-bd98-e843615aaeb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92873, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "谋杀", "is_correct": true, "explanation": "谋杀：事先计划好并杀害他人，与“计划”和“妻子”的语境相符，是本题正确答案。"}, {"text": "演唱", "is_correct": false, "explanation": "搭配：“演唱”的对象是歌曲，不能说演唱自己的妻子。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：“驾驶”的对象是车辆等交通工具，不能说驾驶自己的妻子。"}, {"text": "品尝", "is_correct": false, "explanation": "语义：“品尝”指尝食物的味道，与“妻子”不合。"}], "explanations": {"谋杀": "谋杀：事先计划好并杀害他人，与“计划”和“妻子”的语境相符，是本题正确答案。", "演唱": "搭配：“演唱”的对象是歌曲，不能说演唱自己的妻子。", "驾驶": "搭配：“驾驶”的对象是车辆等交通工具，不能说驾驶自己的妻子。", "品尝": "语义：“品尝”指尝食物的味道，与“妻子”不合。"}, "sentence_index": 0, "correct_answer": "谋杀"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他开车时走神，谋杀了一个路人。", "explanation": "这里应该用〈误杀〉。谋杀指事先计划好的杀人，开车走神造成的过失不能说谋杀。"}, {"text": "那个人因为生意失败，谋杀了自己。", "explanation": "这里应该用〈自杀〉。谋杀的对象必须是别人，不能指杀害自己。"}, {"text": "法院依法谋杀了那个死刑犯。", "explanation": "这里应该用〈处死〉。谋杀是非法且事先计划的杀人，依法执行死刑不能说谋杀。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be722e46-e32d-4a8d-8189-15ca20c8e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92873, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "谋杀", "is_correct": true, "explanation": "谋杀：事先计划好并杀害他人，与“你为什么要”和“她”的语境相符，是本题正确答案。"}, {"text": "印刷", "is_correct": false, "explanation": "搭配：“印刷”的对象是书报、材料，不能用于人。"}, {"text": "烹调", "is_correct": false, "explanation": "语义：“烹调”指做菜，不能用来指对人的行为。"}, {"text": "洗涤", "is_correct": false, "explanation": "搭配：“洗涤”的对象是衣物、餐具等，不能说洗涤她。"}], "explanations": {"谋杀": "谋杀：事先计划好并杀害他人，与“你为什么要”和“她”的语境相符，是本题正确答案。", "印刷": "搭配：“印刷”的对象是书报、材料，不能用于人。", "烹调": "语义：“烹调”指做菜，不能用来指对人的行为。", "洗涤": "搭配：“洗涤”的对象是衣物、餐具等，不能说洗涤她。"}, "sentence_index": 6, "correct_answer": "谋杀"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他为了保护家人，在搏斗中谋杀了歹徒。", "explanation": "这里应该用〈打死〉。谋杀是事先计划的杀害，在搏斗中为保护家人而打死歹徒属于自卫，不能说谋杀。"}, {"text": "他一时冲动，谋杀了朋友。", "explanation": "这里应该用〈杀害〉。谋杀必须事先计划，“一时冲动”是临时起意，不能说谋杀。"}, {"text": "他在战场上谋杀了三名敌人。", "explanation": "这里应该用〈杀死〉。谋杀是非法、事先计划的杀人，战场上杀死敌人不属于谋杀。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be722e46-e32d-4a8d-8189-15ca20c8e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92873, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他正在谋杀了那个邻居。", "corrected_sentence": "他正在谋杀那个邻居。", "error_description": "“正在”表示动作进行中，不能与“了”同用，应说“正在谋杀那个邻居”，不能说“正在谋杀了那个邻居”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be722e46-e32d-4a8d-8189-15ca20c8e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92873, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他十年前谋杀了过一个商人，至今还在逃。", "corrected_sentence": "他十年前谋杀过一个商人，至今还在逃。", "error_description": "“谋杀”后面不能同时带“了”和“过”，应去掉“了”，说“谋杀过”，不能说“谋杀了过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be722e46-e32d-4a8d-8189-15ca20c8e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
