INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92874, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "预先计划好并杀害他人。", "primary_collocate": null, "pronunciation": "móu shā", "ipa": "mou̯˧˥ ʂa˥", "syllable_count": 2, "sentences": [{"text": "他为了钱计划谋杀富人。", "target_word": "谋杀", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "法院说，他谋杀了自己的邻居。", "target_word": "谋杀", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个坏人想谋杀证人，不让他说话。", "target_word": "谋杀", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察没有证据，说不清谁谋杀了他。", "target_word": "谋杀", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小说里的医生偷偷谋杀病人。", "target_word": "谋杀", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他曾经谋杀过一个人，所以进了监狱。", "target_word": "谋杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人想在飞机上谋杀这位歌手。", "target_word": "谋杀", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他先买了刀，再去谋杀那个老师。", "target_word": "谋杀", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们商量着怎样谋杀那位老人。", "target_word": "谋杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察怀疑他谋杀了自己的哥哥。", "target_word": "谋杀", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "谋杀了", "label": "体标（了）"}, {"form": "谋杀过", "label": "体标（过）"}, {"form": "谋杀案", "label": "复合词"}, {"form": "谋杀犯", "label": "复合词"}], "register": "中性", "sense_fingerprint": "预谋并杀害他人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1bf60fe-067d-49a1-bd98-e843615aaeb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92874, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "谋杀", "is_correct": true, "explanation": "谋杀：预先计划好并杀害他人，与“为了钱计划”和“富人”的语境相符，是本题正确答案。"}, {"text": "拍卖", "is_correct": false, "explanation": "搭配：“拍卖”的对象是物品，不能说拍卖富人。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：“翻译”指转换语言，不能用来指对人的行为。"}, {"text": "粉刷", "is_correct": false, "explanation": "搭配：“粉刷”用于墙面等表面，不能说粉刷富人。"}], "explanations": {"谋杀": "谋杀：预先计划好并杀害他人，与“为了钱计划”和“富人”的语境相符，是本题正确答案。", "拍卖": "搭配：“拍卖”的对象是物品，不能说拍卖富人。", "翻译": "语义：“翻译”指转换语言，不能用来指对人的行为。", "粉刷": "搭配：“粉刷”用于墙面等表面，不能说粉刷富人。"}, "sentence_index": 0, "correct_answer": "谋杀"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一时失手，谋杀了一个同事。", "explanation": "这里应该用〈误杀〉。谋杀指事先计划好的杀人，“一时失手”属于过失，不能说谋杀。"}, {"text": "法院依法谋杀了那个罪犯。", "explanation": "这里应该用〈处死〉。谋杀是非法且事先计划的杀人，依法执行死刑不能说谋杀。"}, {"text": "他因为太痛苦，谋杀了自己。", "explanation": "这里应该用〈自杀〉。谋杀的对象必须是别人，不能指杀害自己。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be722e46-e32d-4a8d-8189-15ca20c8e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92874, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "谋杀", "is_correct": true, "explanation": "谋杀：预先计划好并杀害他人，与“有人想在飞机上”和“这位歌手”的语境相符，是本题正确答案。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：“驾驶”的对象是交通工具，不能说驾驶这位歌手。"}, {"text": "缝补", "is_correct": false, "explanation": "搭配：“缝补”的对象是衣物等，不能说缝补这位歌手。"}, {"text": "冷藏", "is_correct": false, "explanation": "语义：“冷藏”指保存食物，不能用于人。"}], "explanations": {"谋杀": "谋杀：预先计划好并杀害他人，与“有人想在飞机上”和“这位歌手”的语境相符，是本题正确答案。", "驾驶": "搭配：“驾驶”的对象是交通工具，不能说驾驶这位歌手。", "缝补": "搭配：“缝补”的对象是衣物等，不能说缝补这位歌手。", "冷藏": "语义：“冷藏”指保存食物，不能用于人。"}, "sentence_index": 6, "correct_answer": "谋杀"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "店主在抢劫中谋杀了一个抢匪。", "explanation": "这里应该用〈打死〉。谋杀是事先计划的杀害，在抢劫中为自卫打死抢匪不能说谋杀。"}, {"text": "他一时气愤，谋杀了妻子。", "explanation": "这里应该用〈杀害〉。谋杀必须事先计划，“一时气愤”是临时起意，不能说谋杀。"}, {"text": "战斗中，士兵谋杀了三个敌人。", "explanation": "这里应该用〈杀死〉。谋杀是非法、事先计划的杀人，战斗中杀死敌人不属于谋杀。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be722e46-e32d-4a8d-8189-15ca20c8e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92874, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他计划在下个月谋杀了那位富商。", "corrected_sentence": "他计划在下个月谋杀那位富商。", "error_description": "“计划在下个月”说的是还没发生的事，“谋杀”后面不能加表示完成的“了”，应说“计划在下个月谋杀那位富商”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be722e46-e32d-4a8d-8189-15ca20c8e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92874, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他谋杀了过哥哥，后来被判刑。", "corrected_sentence": "他谋杀过哥哥，后来被判刑。", "error_description": "“谋杀”后面不能同时带“了”和“过”，应去掉“了”，说“谋杀过”，不能说“谋杀了过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be722e46-e32d-4a8d-8189-15ca20c8e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
