INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92876, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "眼睛的神态，目光所流露的神情。", "primary_collocate": null, "pronunciation": "yǎn shén", "ipa": "jɛn˨˩˦ ʂən˧˥", "syllable_count": 2, "sentences": [{"text": "她的眼神很温柔。", "target_word": "眼神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从他的眼神里，我看出他很难过。", "target_word": "眼神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的眼神又干净又明亮。", "target_word": "眼神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的眼神里有很多故事。", "target_word": "眼神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的眼神突然变得很害怕。", "target_word": "眼神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的眼神里有一点点高兴。", "target_word": "眼神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看着妈妈的眼神，我什么也不想说了。", "target_word": "眼神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只小狗的眼神好像在说话。", "target_word": "眼神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的眼神让我觉得很安心。", "target_word": "眼神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的眼神很坚定，我相信他会做到。", "target_word": "眼神", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个眼神", "label": "量词"}, {"form": "眼神交流", "label": "复合词"}], "register": "中性", "sense_fingerprint": "眼睛里流露出来的心情和神态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdadcb77-e6c4-4c9d-9376-79a977628fc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92876, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "眼神", "is_correct": true, "explanation": "正确答案。眼神指眼睛的神态，目光所流露的神情。"}, {"text": "养神", "is_correct": false, "explanation": "yǎng（第三声）与 yǎn（第三声）只有韵母不同：ang 与 an。养神意思是调养精神、闭目休息，不是眼睛的神态。"}, {"text": "眼生", "is_correct": false, "explanation": "shēng（第一声）与 shén（第二声）韵母 eng 与 en 不同，声调也不同。眼生意思是面孔陌生、不熟悉。"}, {"text": "延伸", "is_correct": false, "explanation": "yán（第二声）与 yǎn（第三声）、shēn（第一声）与 shén（第二声）声调都不同。延伸意思是向外伸展。"}], "explanations": {"眼神": "正确答案。眼神指眼睛的神态，目光所流露的神情。", "养神": "yǎng（第三声）与 yǎn（第三声）只有韵母不同：ang 与 an。养神意思是调养精神、闭目休息，不是眼睛的神态。", "眼生": "shēng（第一声）与 shén（第二声）韵母 eng 与 en 不同，声调也不同。眼生意思是面孔陌生、不熟悉。", "延伸": "yán（第二声）与 yǎn（第三声）、shēn（第一声）与 shén（第二声）声调都不同。延伸意思是向外伸展。"}, "sentence_index": null, "correct_answer": "眼神"}, "level_3": {"options": [{"text": "眼神", "is_correct": true, "explanation": "正确答案。眼神是眼睛流露的神态，可以用“温柔”来形容。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子是建筑，不能用“温柔”形容。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材指身体的体形，不是神态，不能说“温柔”。"}, {"text": "酒量", "is_correct": false, "explanation": "搭配：“酒量”只说大小，不与“温柔”搭配。"}], "explanations": {"眼神": "正确答案。眼神是眼睛流露的神态，可以用“温柔”来形容。", "房子": "语义：房子是建筑，不能用“温柔”形容。", "身材": "体貌：身材指身体的体形，不是神态，不能说“温柔”。", "酒量": "搭配：“酒量”只说大小，不与“温柔”搭配。"}, "sentence_index": 0, "correct_answer": "眼神"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他哭了一整夜，眼神又红又肿。", "explanation": "这里应该用〈眼睛〉。“又红又肿”说的是眼睛这个器官，眼神指眼睛流露的神态，不能红肿。"}, {"text": "她的眼神哑了，说不出话。", "explanation": "这里应该用〈嗓子〉。“哑”说的是嗓子发不出声，眼神是眼睛的神态，不能说哑。"}, {"text": "他眼神发白，像是生病了。", "explanation": "这里应该用〈脸色〉。脸色指脸部的气色，可以发白；眼神只指眼睛的神态，不能说“发白”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6205d22-05d7-4d8a-99ec-90516221c3f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92876, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "眼神", "is_correct": true, "explanation": "正确答案。“看着”的对象是眼神，可以说“看着妈妈的眼神”。"}, {"text": "声音", "is_correct": false, "explanation": "配价：“看”的对象要能被看见，“声音”只能听，不能看。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”是嗅觉或味觉的对象，不能用眼睛“看”。"}, {"text": "笑声", "is_correct": false, "explanation": "配价：“笑声”能听见，不能被“看”，与“看着”搭配不通。"}], "explanations": {"眼神": "正确答案。“看着”的对象是眼神，可以说“看着妈妈的眼神”。", "声音": "配价：“看”的对象要能被看见，“声音”只能听，不能看。", "味道": "语义：“味道”是嗅觉或味觉的对象，不能用眼睛“看”。", "笑声": "配价：“笑声”能听见，不能被“看”，与“看着”搭配不通。"}, "sentence_index": 6, "correct_answer": "眼神"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子的眼神很结实，坐上去很稳。", "explanation": "这里应该用〈质量〉。“结实”和“坐上去很稳”说的是东西的质量；眼神指眼睛的神态，不能用来形容椅子。"}, {"text": "她的眼神很好听，让人想多听一会儿。", "explanation": "这里应该用〈声音〉。“好听”“想多听”说的是声音，眼神指眼睛的神态，不能用来形容声音。"}, {"text": "这碗汤的眼神很咸，你少放点盐吧。", "explanation": "这里应该用〈味道〉。“咸”说的是味道，眼神不能用来形容味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6205d22-05d7-4d8a-99ec-90516221c3f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92876, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她温柔眼神让人难忘。", "corrected_sentence": "她温柔的眼神让人难忘。", "error_description": "错误：“温柔”修饰名词“眼神”时，中间要加“的”。错误形式是“温柔眼神”，正确形式是“温柔的眼神”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6205d22-05d7-4d8a-99ec-90516221c3f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92876, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她朝我投来一只眼神，我立刻明白了。", "corrected_sentence": "她朝我投来一个眼神，我立刻明白了。", "error_description": "错误：“眼神”的量词用错，应该用“个”，不能用“只”。“只”多用于动物或成对的东西。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6205d22-05d7-4d8a-99ec-90516221c3f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
