INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92877, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "躺是身体平平地放在床上。", "primary_collocate": null, "pronunciation": "tǎng", "ipa": "tʰɑŋ˨˩˦", "syllable_count": 1, "sentences": [{"text": "我喜欢躺在床上看书。", "target_word": "躺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他累了，躺下就睡着了。", "target_word": "躺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈让孩子躺好，别乱动。", "target_word": "躺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人躺在床上，不能起来。", "target_word": "躺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上我躺在床上听音乐。", "target_word": "躺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天中午都躺在床上睡一会儿。", "target_word": "躺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，你要多躺在床上休息。", "target_word": "躺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫躺在我的床上睡觉。", "target_word": "躺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天感冒了，一天都躺在床上。", "target_word": "躺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子躺在小床上，很快就睡了。", "target_word": "躺", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "躺了", "label": "完成体"}, {"form": "躺着", "label": "持续体"}, {"form": "躺过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "动词，人平平地躺在床上休息、睡觉或养病", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af85ea54-62da-4af3-896a-ad3c590683d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92877, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "躺", "is_correct": true, "explanation": "正确。“躺”（tǎng，第三声）指身体平放在床、地面等处。"}, {"text": "汤", "is_correct": false, "explanation": "tǎng（第三声）与 tāng（第一声）声调不同，意思是汤。"}, {"text": "糖", "is_correct": false, "explanation": "tǎng（第三声）与 táng（第二声）声调不同，意思是糖。"}, {"text": "烫", "is_correct": false, "explanation": "tǎng（第三声）与 tàng（第四声）声调不同，意思是烫。"}], "explanations": {"躺": "正确。“躺”（tǎng，第三声）指身体平放在床、地面等处。", "汤": "tǎng（第三声）与 tāng（第一声）声调不同，意思是汤。", "糖": "tǎng（第三声）与 táng（第二声）声调不同，意思是糖。", "烫": "tǎng（第三声）与 tàng（第四声）声调不同，意思是烫。"}, "sentence_index": null, "correct_answer": "躺"}, "level_3": {"options": [{"text": "躺", "is_correct": true, "explanation": "正确。“我喜欢___在床上看书”中，只有“躺”符合卧在床上看书的姿势。"}, {"text": "站", "is_correct": false, "explanation": "语义：“站”表示直立，站在床上看书不合常理，与卧姿不符。"}, {"text": "蹲", "is_correct": false, "explanation": "搭配：“蹲”多用于地面、台阶等低处，不说“蹲在床上看书”。"}, {"text": "跳", "is_correct": false, "explanation": "语义：“跳”是跃动，与安静看书的状态冲突。"}], "explanations": {"躺": "正确。“我喜欢___在床上看书”中，只有“躺”符合卧在床上看书的姿势。", "站": "语义：“站”表示直立，站在床上看书不合常理，与卧姿不符。", "蹲": "搭配：“蹲”多用于地面、台阶等低处，不说“蹲在床上看书”。", "跳": "语义：“跳”是跃动，与安静看书的状态冲突。"}, "sentence_index": 0, "correct_answer": "躺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我躺着跳舞。", "explanation": "这里应该用〈站〉。“躺”指身体平放，跳舞时应当站着，“躺着跳舞”不符合这个词的用法。"}, {"text": "他躺着开会。", "explanation": "这里应该用〈坐〉。“躺”指身体平放，开会时应当坐着，“躺着开会”不符合这个词的用法。"}, {"text": "她躺着擦地板。", "explanation": "这里应该用〈跪〉。“躺”指身体平放，擦地板时应当跪着，“躺着擦地板”不符合这个词的用法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ca9d1d-04ee-41ab-b579-02df7548e6d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors,