INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92878, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "身体横着放在地上、草地、沙发等处。", "primary_collocate": null, "pronunciation": "tǎng", "ipa": "tʰɑŋ˨˩˦", "syllable_count": 1, "sentences": [{"text": "他躺在草地上看天空。", "target_word": "躺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们躺在沙滩上晒太阳。", "target_word": "躺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上很凉，别躺在地上。", "target_word": "躺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸躺在沙发上看电视。", "target_word": "躺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他累得躺在地板上不想动。", "target_word": "躺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们躺在草地上数星星。", "target_word": "躺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人躺在长椅上休息。", "target_word": "躺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他躺在地毯上玩手机。", "target_word": "躺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗躺在门口，一动不动。", "target_word": "躺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跑累了，直接躺在操场上。", "target_word": "躺", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "躺了", "label": "完成体"}, {"form": "躺着", "label": "持续体"}, {"form": "躺过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "动词，人或动物身体横放在地上、草地、沙发等处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af85ea54-62da-4af3-896a-ad3c590683d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92878, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "躺", "is_correct": true, "explanation": "正确。“躺”（tǎng，第三声）指身体横放在地面、草地等处。"}, {"text": "烫", "is_correct": false, "explanation": "tǎng（第三声）与 tàng（第四声）声调不同，意思是烫。"}, {"text": "糖", "is_correct": false, "explanation": "tǎng（第三声）与 táng（第二声）声调不同，意思是糖。"}, {"text": "挡", "is_correct": false, "explanation": "tǎng 与 dǎng 声母不同，dǎng 的意思是挡。"}], "explanations": {"躺": "正确。“躺”（tǎng，第三声）指身体横放在地面、草地等处。", "烫": "tǎng（第三声）与 tàng（第四声）声调不同，意思是烫。", "糖": "tǎng（第三声）与 táng（第二声）声调不同，意思是糖。", "挡": "tǎng 与 dǎng 声母不同，dǎng 的意思是挡。"}, "sentence_index": null, "correct_answer": "躺"}, "level_3": {"options": [{"text": "躺", "is_correct": true, "explanation": "正确。“他___在草地上看天空”中，“躺”表示身体横放在草地上，最合适。"}, {"text": "跳", "is_correct": false, "explanation": "语义：“跳”是跃动，不能表示静止地看天空。"}, {"text": "跑", "is_correct": false, "explanation": "语义：“跑”指移动，与“看天空”的静止状态矛盾。"}, {"text": "蹦", "is_correct": false, "explanation": "搭配：“蹦”指弹跳，不与“在草地上看天空”搭配。"}], "explanations": {"躺": "正确。“他___在草地上看天空”中，“躺”表示身体横放在草地上，最合适。", "跳": "语义：“跳”是跃动，不能表示静止地看天空。", "跑": "语义：“跑”指移动，与“看天空”的静止状态矛盾。", "蹦": "搭配：“蹦”指弹跳，不与“在草地上看天空”搭配。"}, "sentence_index": 0, "correct_answer": "躺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "售货员躺着卖东西。", "explanation": "这里应该用〈站〉。“躺”指身体横着放，卖东西时售货员应当站着，躺着卖东西不符合这个词的用法。"}, {"text": "妈妈躺着包饺子。", "explanation": "这里应该用〈坐〉。“躺”指身体横着放，包饺子时应当坐着，躺着包饺子不符合这个词的用法。"}, {"text": "奶奶躺着擦地板。", "explanation": "这里应该用〈跪〉。“躺”指身体横着放，擦地板时应当跪着，躺着擦地板不符合这个词的用法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ca9d1d-04ee-41ab-b579-02df7548e6d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92878, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "躺", "is_correct": true, "explanation": "正确。“躺”（tǎng，第三声）指身体横放在地面、沙发等处。"}, {"text": "汤", "is_correct": false, "explanation": "tǎng（第三声）与 tāng（第一声）声调不同，意思是汤。"}, {"text": "堂", "is_correct": false, "explanation": "tǎng（第三声）与 táng（第二声）声调不同，意思是堂。"}, {"text": "趟", "is_correct": false, "explanation": "tǎng（第三声）与 tàng（第四声）声调不同，意思是趟。"}], "explanations": {"躺": "正确。“躺”（tǎng，第三声）指身体横放在地面、沙发等处。", "汤": "tǎng（第三声）与 tāng（第一声）声调不同，意思是汤。", "堂": "tǎng（第三声）与 táng（第二声）声调不同，意思是堂。", "趟": "tǎng（第三声）与 tàng（第四声）声调不同，意思是趟。"}, "sentence_index": null, "correct_answer": "躺"}, "level_3": {"options": [{"text": "躺", "is_correct": true, "explanation": "正确。“老人___在长椅上休息”中，“躺”表示身体横放在长椅上，符合句意。"}, {"text": "站", "is_correct": false, "explanation": "语义：“站”是直立，站着休息不是在长椅上休息的常态，与句意冲突。"}, {"text": "蹲", "is_correct": false, "explanation": "搭配：“蹲”多指蹲在地面或台阶上，不说“蹲在长椅上休息”。"}, {"text": "跪", "is_correct": false, "explanation": "搭配：“跪”指双膝着地，不用于在长椅上休息。"}], "explanations": {"躺": "正确。“老人___在长椅上休息”中，“躺”表示身体横放在长椅上，符合句意。", "站": "语义：“站”是直立，站着休息不是在长椅上休息的常态，与句意冲突。", "蹲": "搭配：“蹲”多指蹲在地面或台阶上，不说“蹲在长椅上休息”。", "跪": "搭配：“跪”指双膝着地，不用于在长椅上休息。"}, "sentence_index": 6, "correct_answer": "躺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他躺着喂鸡。", "explanation": "这里应该用〈蹲〉。“躺”指身体横着放，喂鸡时应当蹲着，躺着喂鸡不符合这个词的用法。"}, {"text": "他躺着给客人鞠躬。", "explanation": "这里应该用〈站〉。“躺”指身体横着放，鞠躬时应当站着，躺着鞠躬不符合这个词的用法。"}, {"text": "我躺着踢足球。", "explanation": "这里应该用〈跑〉。“躺”指身体横着放，踢足球需要跑动，躺着踢足球不符合这个词的用法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ca9d1d-04ee-41ab-b579-02df7548e6d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92878, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他躺很舒服。", "corrected_sentence": "他躺得很舒服。", "error_description": "“躺”后面的补语要用“得”连接，应说“躺得很舒服”，不能说“躺很舒服”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ca9d1d-04ee-41ab-b579-02df7548e6d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92878, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小狗在门口躺睡觉。", "corrected_sentence": "小狗在门口躺着睡觉。", "error_description": "“躺”表示持续的姿态，后面应加“着”，应说“在门口躺着睡觉”，不能说“在门口躺睡觉”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ca9d1d-04ee-41ab-b579-02df7548e6d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
