INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92879, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "瞎是眼睛看不见东西。", "primary_collocate": null, "pronunciation": "xiā", "ipa": "ɕja˥˥", "syllable_count": 1, "sentences": [{"text": "他的左眼瞎了。", "target_word": "瞎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位老人两只眼睛都瞎了。", "target_word": "瞎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只猫生下来就是瞎的。", "target_word": "瞎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的眼睛瞎了，看不见路。", "target_word": "瞎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年轻时因为生病瞎了一只眼。", "target_word": "瞎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条狗老了，眼睛也瞎了。", "target_word": "瞎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的眼睛天生就瞎。", "target_word": "瞎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个瞎了的老人坐在门口。", "target_word": "瞎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事故以后，他的右眼瞎了。", "target_word": "瞎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，她的眼睛不会瞎。", "target_word": "瞎", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "瞎了", "label": "体标"}, {"form": "瞎子", "label": "复合"}], "register": "口语", "sense_fingerprint": "眼睛看不见东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b3468b2-e9de-4767-8dc9-fa5cc27facb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92879, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "瞎", "is_correct": true, "explanation": "正确。瞎指眼睛看不见东西。"}, {"text": "下", "is_correct": false, "explanation": "声调不同：xià（第四声）与 xiā（第一声）。“下”意思是下面。"}, {"text": "夏", "is_correct": false, "explanation": "声调不同：xià（第四声）与 xiā（第一声）。“夏”意思是夏天。"}, {"text": "吓", "is_correct": false, "explanation": "声调不同：xià（第四声）与 xiā（第一声）。“吓”意思是使人害怕。"}, {"text": "峡", "is_correct": false, "explanation": "声调不同：xiá（第二声）与 xiā（第一声）。“峡”意思是两山之间的狭窄水道。"}], "explanations": {"瞎": "正确。瞎指眼睛看不见东西。", "下": "声调不同：xià（第四声）与 xiā（第一声）。“下”意思是下面。", "夏": "声调不同：xià（第四声）与 xiā（第一声）。“夏”意思是夏天。", "吓": "声调不同：xià（第四声）与 xiā（第一声）。“吓”意思是使人害怕。", "峡": "声调不同：xiá（第二声）与 xiā（第一声）。“峡”意思是两山之间的狭窄水道。"}, "sentence_index": null, "correct_answer": "瞎"}, "level_3": {"options": [{"text": "瞎", "is_correct": true, "explanation": "正确。“瞎”表示眼睛看不见，与“他的左眼……了”相符。"}, {"text": "矮", "is_correct": false, "explanation": "语义：眼睛不会变矮，“矮”与“他的左眼”的描述不合。"}, {"text": "厚", "is_correct": false, "explanation": "语义：“厚”形容物体的厚度，不能描述眼睛失去视力的状态。"}, {"text": "轻", "is_correct": false, "explanation": "搭配：“轻”多形容物体或动作，不用来形容眼睛的状态。"}], "explanations": {"瞎": "正确。“瞎”表示眼睛看不见，与“他的左眼……了”相符。", "矮": "语义：眼睛不会变矮，“矮”与“他的左眼”的描述不合。", "厚": "语义：“厚”形容物体的厚度，不能描述眼睛失去视力的状态。", "轻": "搭配：“轻”多形容物体或动作，不用来形容眼睛的状态。"}, "sentence_index": 0, "correct_answer": "瞎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她的嗓子瞎了，说不出话。", "explanation": "这里应该用〈哑〉。瞎只指眼睛看不见，嗓子不能用“瞎”，说不出话应说“哑”。"}, {"text": "他感冒了，鼻子瞎了，闻不到任何味道。", "explanation": "这里应该用〈堵〉。瞎指眼睛看不见，鼻子不通应说“堵”。"}, {"text": "他的腿瞎了，走路很慢。", "explanation": "这里应该用〈瘸〉。瞎指看不见，腿受伤应说“瘸”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d0f262c-458f-4cf8-8d35-f247ff9e23e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92879, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "瞎", "is_correct": true, "explanation": "正确。瞎指眼睛看不见东西。"}, {"text": "霞", "is_correct": false, "explanation": "声调不同：xiá（第二声）与 xiā（第一声）。“霞”意思是早晨或傍晚天边的彩色云气。"}, {"text": "侠", "is_correct": false, "explanation": "声调不同：xiá（第二声）与 xiā（第一声）。“侠”意思是有武艺、讲义气的人。"}, {"text": "狭", "is_correct": false, "explanation": "声调不同：xiá（第二声）与 xiā（第一声）。“狭”意思是宽度小。"}, {"text": "香", "is_correct": false, "explanation": "韵母不同：xiāng 比 xiā 多一个 ng。“香”意思是气味好闻。"}], "explanations": {"瞎": "正确。瞎指眼睛看不见东西。", "霞": "声调不同：xiá（第二声）与 xiā（第一声）。“霞”意思是早晨或傍晚天边的彩色云气。", "侠": "声调不同：xiá（第二声）与 xiā（第一声）。“侠”意思是有武艺、讲义气的人。", "狭": "声调不同：xiá（第二声）与 xiā（第一声）。“狭”意思是宽度小。", "香": "韵母不同：xiāng 比 xiā 多一个 ng。“香”意思是气味好闻。"}, "sentence_index": null, "correct_answer": "瞎"}, "level_3": {"options": [{"text": "瞎", "is_correct": true, "explanation": "正确。“瞎”表示眼睛看不见，与“他的眼睛天生就……”相符。"}, {"text": "饱", "is_correct": false, "explanation": "语义：“饱”形容吃得足够，不能用来描述眼睛的状态，与语境不合。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”指味道，不用来描述眼睛的状态，与语境不合。"}, {"text": "高", "is_correct": false, "explanation": "搭配：“高”多形容身高或位置，不与“眼睛天生就”搭配。"}], "explanations": {"瞎": "正确。“瞎”表示眼睛看不见，与“他的眼睛天生就……”相符。", "饱": "语义：“饱”形容吃得足够，不能用来描述眼睛的状态，与语境不合。", "甜": "语义：“甜”指味道，不用来描述眼睛的状态，与语境不合。", "高": "搭配：“高”多形容身高或位置，不与“眼睛天生就”搭配。"}, "sentence_index": 6, "correct_answer": "瞎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的肚子瞎了，吃不下饭。", "explanation": "这里应该用〈坏〉。瞎只指眼睛看不见，肠胃不舒服应说“坏”。"}, {"text": "他的耳朵瞎了，听不见声音。", "explanation": "这里应该用〈聋〉。瞎只指眼睛看不见，耳朵听不见应说“聋”。"}, {"text": "他的手指瞎了，不能写字。", "explanation": "这里应该用〈断〉。瞎指眼睛看不见，手指受伤应说“断”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d0f262c-458f-4cf8-8d35-f247ff9e23e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92879, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她的右眼被瞎了五年。", "corrected_sentence": "她的右眼瞎了五年。", "error_description": "被字句错误：“瞎”表示眼睛失去视力，本身不带施事，不能直接用“被”引出；应说“瞎了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d0f262c-458f-4cf8-8d35-f247ff9e23e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92879, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爷爷年轻时瞎了一个眼睛。", "corrected_sentence": "爷爷年轻时瞎了一只眼睛。", "error_description": "量词错误：说“瞎了”几只眼睛时，眼睛的量词是“只”，不说“一个眼睛”。正确说法是“瞎了一只眼睛”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d0f262c-458f-4cf8-8d35-f247ff9e23e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
