INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92882, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "最近几天；不久前或不久后的一段日子。", "primary_collocate": null, "pronunciation": "jìn rì", "ipa": "tɕin˥˩ ʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "近日，这个城市连续下了几场大雨。", "target_word": "近日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "近日天气变冷，请大家多穿衣服。", "target_word": "近日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司近日宣布了一个新计划。", "target_word": "近日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个产品近日将在市场上出售。", "target_word": "近日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校近日会通知大家考试的时间。", "target_word": "近日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他近日一直在医院照顾生病的父亲。", "target_word": "近日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "近日，很多游客来到这座小城参观。", "target_word": "近日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新书近日就要出版了，请大家等一等。", "target_word": "近日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说他近日身体不太好，需要休息。", "target_word": "近日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府近日发出通知，提醒大家注意安全。", "target_word": "近日", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "不久前或不久后的几天（可指过去也可指将来）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5582003f-0fa5-4559-bf80-a34613800f6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92882, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "明天", "is_correct": false, "explanation": "体貌：句中“下了”表示已经发生的动作，而“明天”指尚未到来的日子，二者冲突。"}, {"text": "近日", "is_correct": true, "explanation": "正确：“近日”指最近几天，与“连续下了几场大雨”的时段相合。"}, {"text": "此刻", "is_correct": false, "explanation": "语义：“此刻”指眼下的一瞬间，与“连续下了几场大雨”这种持续一段时间的情况矛盾。"}, {"text": "明年", "is_correct": false, "explanation": "体貌：“明年”尚未到来，不能与表示已完成的“下了”搭配。"}], "explanations": {"明天": "体貌：句中“下了”表示已经发生的动作，而“明天”指尚未到来的日子，二者冲突。", "近日": "正确：“近日”指最近几天，与“连续下了几场大雨”的时段相合。", "此刻": "语义：“此刻”指眼下的一瞬间，与“连续下了几场大雨”这种持续一段时间的情况矛盾。", "明年": "体貌：“明年”尚未到来，不能与表示已完成的“下了”搭配。"}, "sentence_index": 0, "correct_answer": "近日"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆车是我近日买的，已经开了十年了。", "explanation": "“近日”指最近几天，与“已经开了十年”的长时段相矛盾，不能用来说很久以前买的车。"}, {"text": "我们近日分开了三年。", "explanation": "“近日”只指较短的一段时间，不能与“三年”这样的长时段搭配。"}, {"text": "他是我近日的一位老同学。", "explanation": "“近日”指最近几天，与“老同学”所表示的长久关系相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d88747a-ad7c-4c30-8cd2-ef8e3ad8f667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92882, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "近况", "is_correct": false, "explanation": "词性：“近况”是普通名词，不能作时间状语放在句首。"}, {"text": "近日", "is_correct": true, "explanation": "正确：“近日”指最近几天，与句中“很多游客来到”的时间相合。"}, {"text": "日记", "is_correct": false, "explanation": "语义：“日记”是记事的文字，不表示时间，不能引出“很多游客来到”。"}, {"text": "近视", "is_correct": false, "explanation": "语义：“近视”指视力问题，与时间无关。"}], "explanations": {"近况": "词性：“近况”是普通名词，不能作时间状语放在句首。", "近日": "正确：“近日”指最近几天，与句中“很多游客来到”的时间相合。", "日记": "语义：“日记”是记事的文字，不表示时间，不能引出“很多游客来到”。", "近视": "语义：“近视”指视力问题，与时间无关。"}, "sentence_index": 6, "correct_answer": "近日"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在2010年近日搬进了这栋楼。", "explanation": "“近日”指说话前后不久的几天，不能与“2010年”这样的具体年份搭配。"}, {"text": "这份通知是三十年前近日发出的。", "explanation": "“近日”指不久前的几天，与“三十年前”的时间跨度矛盾。"}, {"text": "市政府近日那次通知，早在很久以前就已经发出了。", "explanation": "“近日”指最近几天，与“早在很久以前”的说法矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d88747a-ad7c-4c30-8cd2-ef8e3ad8f667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92882, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校的图书馆近日的关门了。", "corrected_sentence": "学校的图书馆近日关门了。", "error_description": "错误形式是“近日的关门了”，正确形式是“近日关门了”。“近日”作时间状语，直接放在动词“关门”前，后面不加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d88747a-ad7c-4c30-8cd2-ef8e3ad8f667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92882, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家医院近日的增加了护士。", "corrected_sentence": "这家医院近日增加了护士。", "error_description": "错误形式是“近日的增加了护士”，正确形式是“近日增加了护士”。“近日”作时间状语，直接放在动词“增加”前，后面不加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d88747a-ad7c-4c30-8cd2-ef8e3ad8f667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92883, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "细", "is_correct": true, "explanation": "与“粗”互为反义，指圆形或条状物直径小、不粗。"}, {"text": "短", "is_correct": false, "explanation": "“短”说长度，与“粗”指直径大小不构成反义关系。"}, {"text": "窄", "is_correct": false, "explanation": "“窄”说宽度，与“粗”没有反义关系。"}, {"text": "轻", "is_correct": false, "explanation": "“轻”说重量，与“粗”的直径义无关。"}], "correct_answer": "细", "explanations": {"细": "与“粗”互为反义，指圆形或条状物直径小、不粗。", "短": "“短”说长度，与“粗”指直径大小不构成反义关系。", "窄": "“窄”说宽度，与“粗”没有反义关系。", "轻": "“轻”说重量，与“粗”的直径义无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60d60860-2d32-4eff-ad4b-bfb7fc1c6c2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92883, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "细", "is_correct": true, "explanation": "与“粗”互为反义，指圆形或条状物直径小、不粗。"}, {"text": "薄", "is_correct": false, "explanation": "“薄”说扁平物的厚度小，与“粗”没有反义关系。"}, {"text": "宽", "is_correct": false, "explanation": "“宽”说宽度，与“粗”的直径义无反义关系。"}, {"text": "软", "is_correct": false, "explanation": "“软”说质地柔软，与“粗”没有反义关系。"}], "correct_answer": "细", "explanations": {"细": "与“粗”互为反义，指圆形或条状物直径小、不粗。", "薄": "“薄”说扁平物的厚度小，与“粗”没有反义关系。", "宽": "“宽”说宽度，与“粗”的直径义无反义关系。", "软": "“软”说质地柔软，与“粗”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60d60860-2d32-4eff-ad4b-bfb7fc1c6c2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92883, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "粗是东西圆圆的，中间很宽，不细。", "primary_collocate": null, "pronunciation": "cū", "ipa": "tsʰu˥", "syllable_count": 1, "sentences": [{"text": "这棵树很粗，三个人才抱得住。", "target_word": "粗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的手指又短又粗。", "target_word": "粗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买一根粗一点的绳子。", "target_word": "粗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这根水管太粗了，放不进墙里。", "target_word": "粗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大象的腿又粗又壮。", "target_word": "粗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿着一支很粗的笔写大字。", "target_word": "粗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷的胳膊比我的粗多了。", "target_word": "粗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这根竹子不粗，也不细。", "target_word": "粗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树干那么粗，一把小斧子砍不断。", "target_word": "粗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把粗的那根棍子递给我。", "target_word": "粗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "粗细", "label": "复合"}], "register": "中性", "sense_fingerprint": "圆形物体直径大、不细", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd93837-ff1f-44d8-9b8c-6d7a0431f7eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92883, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "粗", "is_correct": true, "explanation": "粗（cū，第一声）指圆形物体直径大、不细，是本题要听出的词。"}, {"text": "醋", "is_correct": false, "explanation": "cù（第四声）与 cū（第一声）声调不同，意思是醋。"}, {"text": "初", "is_correct": false, "explanation": "chū 与 cū 声母不同（ch 与 c），意思是开始、第一。"}, {"text": "出", "is_correct": false, "explanation": "chū 与 cū 声母不同（ch 与 c），意思是出来、出去。"}, {"text": "促", "is_correct": false, "explanation": "cù（第四声）与 cū（第一声）声调不同，意思是促使、推动。"}], "explanations": {"粗": "粗（cū，第一声）指圆形物体直径大、不细，是本题要听出的词。", "醋": "cù（第四声）与 cū（第一声）声调不同，意思是醋。", "初": "chū 与 cū 声母不同（ch 与 c），意思是开始、第一。", "出": "chū 与 cū 声母不同（ch 与 c），意思是出来、出去。", "促": "cù（第四声）与 cū（第一声）声调不同，意思是促使、推动。"}, "sentence_index": null, "correct_answer": "粗"}, "level_3": {"options": [{"text": "粗", "is_correct": true, "explanation": "“粗”描述树干直径大，与“三个人才抱得住”相符。"}, {"text": "细", "is_correct": false, "explanation": "语义：“细”指直径小，与“三个人才抱得住”矛盾，细树不需要三个人合抱。"}, {"text": "高", "is_correct": false, "explanation": "语义：“高”说高度，与“三个人才抱得住”描述的粗细无关。"}, {"text": "软", "is_correct": false, "explanation": "搭配：“软”说质地，不用来形容树干的粗细。"}], "explanations": {"粗": "“粗”描述树干直径大，与“三个人才抱得住”相符。", "细": "语义：“细”指直径小，与“三个人才抱得住”矛盾，细树不需要三个人合抱。", "高": "语义：“高”说高度，与“三个人才抱得住”描述的粗细无关。", "软": "搭配：“软”说质地，不用来形容树干的粗细。"}, "sentence_index": 0, "correct_answer": "粗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书很粗，有五百页。", "explanation": "这里应该用〈厚〉。粗指圆柱形或条状物的直径大；书等扁平物的厚薄要用厚。"}, {"text": "这条马路很粗，两辆卡车可以并排开过去。", "explanation": "这里应该用〈宽〉。粗指条状物直径大，马路的宽窄要用宽。"}, {"text": "这根绳子很粗，能从教室拉到操场。", "explanation": "这里应该用〈长〉。粗指条状物横截面大，绳子的长短要用长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60d60860-2d32-4eff-ad4b-bfb7fc1c6c2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92883, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "粗", "is_correct": true, "explanation": "粗（cū，第一声）指圆形物体直径大、不细，是本题要听出的词。"}, {"text": "苏", "is_correct": false, "explanation": "sū 与 cū 声母不同（s 与 c），意思是苏醒、江苏。"}, {"text": "租", "is_correct": false, "explanation": "zū 与 cū 声母不同（z 与 c），声调相同，意思是出租、租用。"}, {"text": "初", "is_correct": false, "explanation": "chū 与 cū 声母不同（ch 与 c），声调相同，意思是开始、第一。"}, {"text": "簇", "is_correct": false, "explanation": "cù（第四声）与 cū（第一声）声调不同，意思是丛、聚集，如“一簇花”。"}], "explanations": {"粗": "粗（cū，第一声）指圆形物体直径大、不细，是本题要听出的词。", "苏": "sū 与 cū 声母不同（s 与 c），意思是苏醒、江苏。", "租": "zū 与 cū 声母不同（z 与 c），声调相同，意思是出租、租用。", "初": "chū 与 cū 声母不同（ch 与 c），声调相同，意思是开始、第一。", "簇": "cù（第四声）与 cū（第一声）声调不同，意思是丛、聚集，如“一簇花”。"}, "sentence_index": null, "correct_answer": "粗"}, "level_3": {"options": [{"text": "粗", "is_correct": true, "explanation": "“粗”说胳膊的粗细，与“比我的……多了”相符。"}, {"text": "矮", "is_correct": false, "explanation": "搭配：“矮”说高度，不用来比较胳膊的粗细。"}, {"text": "亮", "is_correct": false, "explanation": "语义：“亮”说光线或颜色，与胳膊的粗细无关。"}, {"text": "慢", "is_correct": false, "explanation": "语义：“慢”说速度，与胳膊的粗细无关。"}], "explanations": {"粗": "“粗”说胳膊的粗细，与“比我的……多了”相符。", "矮": "搭配：“矮”说高度，不用来比较胳膊的粗细。", "亮": "语义：“亮”说光线或颜色，与胳膊的粗细无关。", "慢": "语义：“慢”说速度，与胳膊的粗细无关。"}, "sentence_index": 6, "correct_answer": "粗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个房间很粗，能放下两张床。", "explanation": "这里应该用〈大〉。粗指条状物直径大，房间的大小要用大。"}, {"text": "这只猫很粗，一眨眼就跑没影了。", "explanation": "这里应该用〈快〉。粗指条状物直径大，猫跑得快要用快。"}, {"text": "这座楼很粗，有三十层。", "explanation": "这里应该用〈高〉。粗指条状物横截面大，楼的高低要用高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60d60860-2d32-4eff-ad4b-bfb7fc1c6c2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92883, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这根木柱粗要两个人才能抱住。", "corrected_sentence": "这根木柱粗得要两个人才能抱住。", "error_description": "错误形式“粗要两个人才能抱住”，正确形式“粗得要两个人才能抱住”。“粗”作谓语后接结果或程度补语时要用“得”，漏掉“得”，句子不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60d60860-2d32-4eff-ad4b-bfb7fc1c6c2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92883, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这根竹竿用了两年，比新的时候粗过一圈。", "corrected_sentence": "这根竹竿用了两年，比新的时候粗了一圈。", "error_description": "错误形式“粗过一圈”，正确形式“粗了一圈”。说明粗细变化的结果要用“了”；“过”表示经历，不能用来说明这种变化。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60d60860-2d32-4eff-ad4b-bfb7fc1c6c2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92884, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "细", "is_correct": true, "explanation": "与“粗”互为反义，指条状物横截面小、不粗。"}, {"text": "短", "is_correct": false, "explanation": "“短”说长度，与“粗”指横截面大小不构成反义关系。"}, {"text": "窄", "is_correct": false, "explanation": "“窄”说宽度，与“粗”没有反义关系。"}, {"text": "轻", "is_correct": false, "explanation": "“轻”说重量，与“粗”的横截面义无关。"}], "correct_answer": "细", "explanations": {"细": "与“粗”互为反义，指条状物横截面小、不粗。", "短": "“短”说长度，与“粗”指横截面大小不构成反义关系。", "窄": "“窄”说宽度，与“粗”没有反义关系。", "轻": "“轻”说重量，与“粗”的横截面义无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60d60860-2d32-4eff-ad4b-bfb7fc1c6c2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92884, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "细", "is_correct": true, "explanation": "与“粗”互为反义，指条状物横截面小、不粗。"}, {"text": "薄", "is_correct": false, "explanation": "“薄”说扁平物的厚度小，与“粗”没有反义关系。"}, {"text": "软", "is_correct": false, "explanation": "“软”说质地柔软，与“粗”没有反义关系。"}, {"text": "慢", "is_correct": false, "explanation": "“慢”说速度，与“粗”的横截面义无关。"}], "correct_answer": "细", "explanations": {"细": "与“粗”互为反义，指条状物横截面小、不粗。", "薄": "“薄”说扁平物的厚度小，与“粗”没有反义关系。", "软": "“软”说质地柔软，与“粗”没有反义关系。", "慢": "“慢”说速度，与“粗”的横截面义无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60d60860-2d32-4eff-ad4b-bfb7fc1c6c2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92884, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "（条状物）横截面大；不细。", "primary_collocate": null, "pronunciation": "cū", "ipa": "tsʰu˥", "syllable_count": 1, "sentences": [{"text": "这根电线太粗，插头放不进去。", "target_word": "粗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的头发又黑又粗。", "target_word": "粗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种面条比较粗，要多煮一会儿。", "target_word": "粗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用粗铁丝把门绑住了。", "target_word": "粗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毛衣的线很粗，穿起来很暖和。", "target_word": "粗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的眉毛又粗又黑。", "target_word": "粗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支铅笔的笔芯太粗了，写不出小字。", "target_word": "粗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钓鱼线别买太粗的，鱼会看见。", "target_word": "粗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那条绳子粗得像手腕。", "target_word": "粗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这根线太粗了，穿不进针眼里。", "target_word": "粗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "粗细", "label": "复合"}], "register": "中性", "sense_fingerprint": "条状物横截面大、不细", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd93837-ff1f-44d8-9b8c-6d7a0431f7eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92884, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "粗", "is_correct": true, "explanation": "粗（cū，第一声）指条状物横截面大、不细，是本题要听出的词。"}, {"text": "醋", "is_correct": false, "explanation": "cù（第四声）与 cū（第一声）声调不同，意思是醋。"}, {"text": "初", "is_correct": false, "explanation": "chū 与 cū 声母不同（ch 与 c），意思是开始、第一。"}, {"text": "出", "is_correct": false, "explanation": "chū 与 cū 声母不同（ch 与 c），意思是出来、出去。"}, {"text": "促", "is_correct": false, "explanation": "cù（第四声）与 cū（第一声）声调不同，意思是促使、推动。"}], "explanations": {"粗": "粗（cū，第一声）指条状物横截面大、不细，是本题要听出的词。", "醋": "cù（第四声）与 cū（第一声）声调不同，意思是醋。", "初": "chū 与 cū 声母不同（ch 与 c），意思是开始、第一。", "出": "chū 与 cū 声母不同（ch 与 c），意思是出来、出去。", "促": "cù（第四声）与 cū（第一声）声调不同，意思是促使、推动。"}, "sentence_index": null, "correct_answer": "粗"}, "level_3": {"options": [{"text": "粗", "is_correct": true, "explanation": "“粗”说电线的横截面大，与“插头放不进去”的原因相符。"}, {"text": "热", "is_correct": false, "explanation": "语义：“热”说温度，与插头能否放进去无关，句子不通。"}, {"text": "高", "is_correct": false, "explanation": "搭配：“高”说高度，不用来形容电线的粗细。"}, {"text": "白", "is_correct": false, "explanation": "语义：“白”说颜色，与插头能否放进去无关。"}], "explanations": {"粗": "“粗”说电线的横截面大，与“插头放不进去”的原因相符。", "热": "语义：“热”说温度，与插头能否放进去无关，句子不通。", "高": "搭配：“高”说高度，不用来形容电线的粗细。", "白": "语义：“白”说颜色，与插头能否放进去无关。"}, "sentence_index": 0, "correct_answer": "粗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书很粗，有上千页。", "explanation": "这里应该用〈厚〉。粗指条状物横截面大；书、本子等扁平物的厚薄要用厚。"}, {"text": "这条河很粗，船能开过去。", "explanation": "这里应该用〈宽〉。粗指条状物直径大，河面的宽窄要用宽。"}, {"text": "这块玻璃很粗，能从门口铺到楼梯。", "explanation": "这里应该用〈长〉。粗指条状物横截面大，玻璃的长短要用长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60d60860-2d32-4eff-ad4b-bfb7fc1c6c2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92884, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "粗", "is_correct": true, "explanation": "粗（cū，第一声）指条状物横截面大、不细，是本题要听出的词。"}, {"text": "苏", "is_correct": false, "explanation": "sū 与 cū 声母不同（s 与 c），意思是苏醒、江苏。"}, {"text": "租", "is_correct": false, "explanation": "zū 与 cū 声母不同（z 与 c），声调相同，意思是出租、租用。"}, {"text": "初", "is_correct": false, "explanation": "chū 与 cū 声母不同（ch 与 c），声调相同，意思是开始、第一。"}, {"text": "簇", "is_correct": false, "explanation": "cù（第四声）与 cū（第一声）声调不同，意思是丛、聚集。"}], "explanations": {"粗": "粗（cū，第一声）指条状物横截面大、不细，是本题要听出的词。", "苏": "sū 与 cū 声母不同（s 与 c），意思是苏醒、江苏。", "租": "zū 与 cū 声母不同（z 与 c），声调相同，意思是出租、租用。", "初": "chū 与 cū 声母不同（ch 与 c），声调相同，意思是开始、第一。", "簇": "cù（第四声）与 cū（第一声）声调不同，意思是丛、聚集。"}, "sentence_index": null, "correct_answer": "粗"}, "level_3": {"options": [{"text": "粗", "is_correct": true, "explanation": "“粗”说笔芯粗，粗笔芯才会写不出小字，与句意相符。"}, {"text": "贵", "is_correct": false, "explanation": "语义：“贵”说价格，与笔芯粗细和能否写小字无关。"}, {"text": "冷", "is_correct": false, "explanation": "语义：“冷”说温度，与笔芯粗细无关。"}, {"text": "矮", "is_correct": false, "explanation": "搭配：“矮”说高度，不用来描述笔芯的粗细。"}], "explanations": {"粗": "“粗”说笔芯粗，粗笔芯才会写不出小字，与句意相符。", "贵": "语义：“贵”说价格，与笔芯粗细和能否写小字无关。", "冷": "语义：“冷”说温度，与笔芯粗细无关。", "矮": "搭配：“矮”说高度，不用来描述笔芯的粗细。"}, "sentence_index": 6, "correct_answer": "粗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座楼很粗，能看到整个城市。", "explanation": "这里应该用〈高〉。粗指条状物横截面大，楼的高低要用高。"}, {"text": "这个房间很粗，能放下两张床。", "explanation": "这里应该用〈大〉。粗指横截面大，房间的大小要用大。"}, {"text": "这个班的学生很粗，有五十个人。", "explanation": "这里应该用〈多〉。粗指条状物横截面大，人数的多少要用多。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60d60860-2d32-4eff-ad4b-bfb7fc1c6c2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid 