INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92885, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "迫害是用很坏的办法一直欺负人。", "primary_collocate": null, "pronunciation": "pò hài", "ipa": "pʰɔ˥˩ xaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "坏人一直迫害那个老人。", "target_word": "迫害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们长期迫害邻居，大家都很气愤。", "target_word": "迫害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那时候，很多人因为说了真话被迫害。", "target_word": "迫害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不能迫害无辜的人。", "target_word": "迫害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说有人一直迫害她，所以很害怕。", "target_word": "迫害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史上，有的国王迫害过说真话的人。", "target_word": "迫害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们迫害了这家人很多年。", "target_word": "迫害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的坏人天天迫害穷人。", "target_word": "迫害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个军官长期迫害村里的百姓。", "target_word": "迫害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁也没有权利迫害别人。", "target_word": "迫害", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "迫害了", "label": "完成体"}, {"form": "迫害过", "label": "经历体"}, {"form": "迫害着", "label": "持续体"}, {"form": "迫害者", "label": "复合词"}], "register": "书面", "sense_fingerprint": "用坏办法长期欺负、为难别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c43aef69-b6a0-4454-8d6b-0589435b9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92885, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "批准", "is_correct": false, "explanation": "配价：“批准”的宾语应是申请、事项，不能是人，“批准那个老人”不通。"}, {"text": "迫害", "is_correct": true, "explanation": "“迫害”指用坏办法长期欺负、为难人，与“坏人”和“一直”相合，填入后句意通顺。"}, {"text": "修建", "is_correct": false, "explanation": "搭配：“修建”的对象是房屋、道路等建筑，不说修建老人。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：“翻译”是把语言或文字转换成另一种形式，与“老人”不相合。"}], "explanations": {"批准": "配价：“批准”的宾语应是申请、事项，不能是人，“批准那个老人”不通。", "迫害": "“迫害”指用坏办法长期欺负、为难人，与“坏人”和“一直”相合，填入后句意通顺。", "修建": "搭配：“修建”的对象是房屋、道路等建筑，不说修建老人。", "翻译": "语义：“翻译”是把语言或文字转换成另一种形式，与“老人”不相合。"}, "sentence_index": 0, "correct_answer": "迫害"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的话迫害了我的感情。", "explanation": "这里应该用〈伤害〉。迫害多指用残酷手段压迫、为难人或群体，不能用于感情。"}, {"text": "敌人迫害了我们的阵地。", "explanation": "这里应该用〈攻击〉。迫害的对象是人，不用于阵地。"}, {"text": "工厂排出的废水迫害了河流的环境。", "explanation": "这里应该用〈破坏〉。迫害的对象是人或群体，不用于环境。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b55e6d1-d065-468e-8962-434097609120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92885, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "完成", "is_correct": false, "explanation": "配价：“完成”的宾语应是任务、工作，不能是人，“完成这家人”不通。"}, {"text": "迫害", "is_correct": true, "explanation": "“迫害”指用坏办法长期欺负人，与“很多年”和“这家人”相合，填入后句意通顺。"}, {"text": "粉刷", "is_correct": false, "explanation": "搭配：“粉刷”的对象是墙、房子，不能是“这家人”。"}, {"text": "种植", "is_correct": false, "explanation": "搭配：“种植”的对象是植物，不能与“这家人”搭配。"}], "explanations": {"完成": "配价：“完成”的宾语应是任务、工作，不能是人，“完成这家人”不通。", "迫害": "“迫害”指用坏办法长期欺负人，与“很多年”和“这家人”相合，填入后句意通顺。", "粉刷": "搭配：“粉刷”的对象是墙、房子，不能是“这家人”。", "种植": "搭配：“种植”的对象是植物，不能与“这家人”搭配。"}, "sentence_index": 6, "correct_answer": "迫害"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "洪水迫害了附近的村民。", "explanation": "这里应该用〈困住〉。迫害的主语须是有意施害的人，洪水是自然现象，不能迫害。"}, {"text": "那场地震迫害了很多人。", "explanation": "这里应该用〈砸伤〉。迫害指有意的压迫，地震造成的伤害不用迫害。"}, {"text": "寒冷的冬天迫害了那些老人。", "explanation": "这里应该用〈折磨〉。迫害的主语须是有意施害的人，寒冬这样的自然条件不能迫害。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b55e6d1-d065-468e-8962-434097609120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92885, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们迫害了那位老人了很多年。", "corrected_sentence": "他们迫害了那位老人很多年。", "error_description": "“了”多写了一个。“迫害了”已有完成体的“了”，“老人”后不能再加“了”；应写作“迫害了那位老人很多年”。只删去多出的“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b55e6d1-d065-468e-8962-434097609120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92885, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们把那位老人迫害地很惨。", "corrected_sentence": "他们把那位老人迫害得很惨。", "error_description": "“得”误写为“地”。“得”引出程度补语，应写作“迫害得很惨”；“地”是状语标记，不能这样用。只改动这一个字。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b55e6d1-d065-468e-8962-434097609120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92888, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "经济衰退", "is_correct": true, "explanation": "“经济衰退”指经济总量下降，与“经济增长”的意思相反。"}, {"text": "房价", "is_correct": false, "explanation": "“房价”指房屋的价格，与“经济增长”不构成反义。"}, {"text": "汇率", "is_correct": false, "explanation": "“汇率”指两种货币之间的兑换比率，不构成反义。"}, {"text": "股价", "is_correct": false, "explanation": "“股价”指股票的价格，不构成反义。"}], "correct_answer": "经济衰退", "explanations": {"经济衰退": "“经济衰退”指经济总量下降，与“经济增长”的意思相反。", "房价": "“房价”指房屋的价格，与“经济增长”不构成反义。", "汇率": "“汇率”指两种货币之间的兑换比率，不构成反义。", "股价": "“股价”指股票的价格，不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce34d5c8-1069-48d2-b285-555364cb3fb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92888, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "工资", "is_correct": false, "explanation": "“工资”是劳动的报酬，与“经济增长”没有反义关系。"}, {"text": "存款", "is_correct": false, "explanation": "“存款”指存在银行里的钱，与“经济增长”不构成反义。"}, {"text": "经济下滑", "is_correct": true, "explanation": "“经济下滑”指经济下降，与“经济增长”的意思相反。"}, {"text": "基金", "is_correct": false, "explanation": "“基金”是一种投资方式，与“经济增长”不构成反义。"}], "correct_answer": "经济下滑", "explanations": {"工资": "“工资”是劳动的报酬，与“经济增长”没有反义关系。", "存款": "“存款”指存在银行里的钱，与“经济增长”不构成反义。", "经济下滑": "“经济下滑”指经济下降，与“经济增长”的意思相反。", "基金": "“基金”是一种投资方式，与“经济增长”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce34d5c8-1069-48d2-b285-555364cb3fb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92888, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个国家或地区在一定时期内生产的商品和服务总量增加。", "primary_collocate": null, "pronunciation": "jīng jì zēng zhǎng", "ipa": "tɕiŋ⁵⁵ tɕi⁵¹ tsəŋ⁵⁵ ʈʂɑŋ²¹⁴", "syllable_count": 4, "sentences": [{"text": "今年第一季度，这个国家的经济增长是百分之五。", "target_word": "经济增长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报告说，明年的经济增长会放慢。", "target_word": "经济增长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个地区的经济增长，要看生产的商品和服务。", "target_word": "经济增长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年全国经济增长超过了百分之六。", "target_word": "经济增长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家认为经济增长要靠新技术。", "target_word": "经济增长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个省的经济增长速度不一样。", "target_word": "经济增长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济增长的数字出来了，比大家想的好。", "target_word": "经济增长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "世界经济增长正在变慢。", "target_word": "经济增长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了经济增长，政府花了很多钱修路。", "target_word": "经济增长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天看新闻，关心国家经济增长的数据。", "target_word": "经济增长", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "经济增长率", "label": "复合词"}, {"form": "經濟增長", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一定时期内商品和服务总量的增加，常用数据表示", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088928fc-a436-497e-8711-79f5a28a97a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92888, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "气温", "is_correct": false, "explanation": "语义：气温是温度，不能用“百分之五”来表示。"}, {"text": "经济增长", "is_correct": true, "explanation": "“经济增长”是增长率，可以用百分比表示，符合语境。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：年龄不用百分比表示，不能说“是百分之五”。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重是重量，不能说“是百分之五”。"}], "explanations": {"气温": "语义：气温是温度，不能用“百分之五”来表示。", "经济增长": "“经济增长”是增长率，可以用百分比表示，符合语境。", "年龄": "搭配：年龄不用百分比表示，不能说“是百分之五”。", "体重": "语义：体重是重量，不能说“是百分之五”。"}, "sentence_index": 0, "correct_answer": "经济增长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂的经济增长超过了百分之六。", "explanation": "这里应该用〈产量〉。经济增长指一个地区或国家的整体经济，不能用来说一家工厂。"}, {"text": "这所学校的经济增长超过了百分之六。", "explanation": "这里应该用〈人数〉。经济增长指一个地区或国家的整体经济，不能说一所学校。"}, {"text": "他的经济增长超过了百分之六。", "explanation": "这里应该用〈工资涨幅〉。经济增长指一个国家或地区的经济总量增加，不能用来说一个人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce34d5c8-1069-48d2-b285-555364cb3fb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92888, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "性格", "is_correct": false, "explanation": "语义：性格是人的心理特征，没有数字可以统计。"}, {"text": "经济增长", "is_correct": true, "explanation": "“经济增长”的数字可以统计，符合“比大家想的好”的语境。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“数字”要与可以计量的东西搭配，味道无法用数字表示。"}, {"text": "语法", "is_correct": false, "explanation": "语义：语法是语言规则，不是数字统计的对象。"}], "explanations": {"性格": "语义：性格是人的心理特征，没有数字可以统计。", "经济增长": "“经济增长”的数字可以统计，符合“比大家想的好”的语境。", "味道": "搭配：“数字”要与可以计量的东西搭配，味道无法用数字表示。", "语法": "语义：语法是语言规则，不是数字统计的对象。"}, "sentence_index": 6, "correct_answer": "经济增长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的经济增长很甜。", "explanation": "这里应该用〈笑容〉。“甜”形容笑容或味道，经济增长是经济数量的变化，不能用“甜”形容。"}, {"text": "他尽到了自己的经济增长。", "explanation": "这里应该用〈责任〉。“尽到”搭配责任、义务，经济增长不能被尽到。"}, {"text": "他的经济增长很轻。", "explanation": "这里应该用〈脚步〉。“轻”形容脚步、声音，不能用来形容经济增长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce34d5c8-1069-48d2-b285-555364cb3fb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92888, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个省的经济增长很高兴。", "corrected_sentence": "这个省的经济增长很快。", "error_description": "错误在于“高兴”。“高兴”只能形容人的心情，不能形容经济增长；经济增长要说“快”或“慢”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce34d5c8-1069-48d2-b285-555364cb3fb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92888, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块经济增长很难持续。", "corrected_sentence": "这种经济增长很难持续。", "error_description": "量词错误：“经济增长”应与“种”搭配，写成“块”是错的。“块”用于块状的东西，不能用来数经济增长。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce34d5c8-1069-48d2-b285-555364cb3fb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
