INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92889, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "这么着是说就像这个样子去做。", "primary_collocate": null, "pronunciation": "zhè me zhe", "ipa": "ʈʂɤ⁵¹ mə ʈʂə", "syllable_count": 3, "sentences": [{"text": "他一直这么着，我也没有办法。", "target_word": "这么着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "绳子得这么着绕两圈，再打结。", "target_word": "这么着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别这么着了，大家都看着你呢。", "target_word": "这么着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要是你们都这么着，事情就好办了。", "target_word": "这么着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王天天这么着，从早忙到晚。", "target_word": "这么着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你再这么着下去，身体会垮的。", "target_word": "这么着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿起笔，这么着一画，圆就出来了。", "target_word": "这么着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈教我包饺子，先这么着，再那么着。", "target_word": "这么着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你这么着，别人会不高兴的。", "target_word": "这么着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们都这么着，你也试试吧。", "target_word": "这么着", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "口语代词，指代前面说过或做过的样子，表示照这样去做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df81c267-6b39-4d12-95ab-3643a04c33bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92889, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "这么着", "is_correct": true, "explanation": "正确：“这么着”指照这样持续做下去，与“一直”和“没有办法”的语境相合。"}, {"text": "怎样", "is_correct": false, "explanation": "语义：“怎样”是疑问代词，用来问方式，句子需要的是陈述，不能直接描述一直如此。"}, {"text": "怎么样", "is_correct": false, "explanation": "搭配：“怎么样”多用于询问或评价状态，放在“一直”之后作陈述显得不通。"}, {"text": "这会儿", "is_correct": false, "explanation": "搭配：“这会儿”指说话的这一时刻，不能与表示持续的“一直”搭配。"}], "explanations": {"这么着": "正确：“这么着”指照这样持续做下去，与“一直”和“没有办法”的语境相合。", "怎样": "语义：“怎样”是疑问代词，用来问方式，句子需要的是陈述，不能直接描述一直如此。", "怎么样": "搭配：“怎么样”多用于询问或评价状态，放在“一直”之后作陈述显得不通。", "这会儿": "搭配：“这会儿”指说话的这一时刻，不能与表示持续的“一直”搭配。"}, "sentence_index": 0, "correct_answer": "这么着"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想请这么着来帮忙。", "explanation": "这里指人，应该用〈他〉。“这么着”只指做法，不能指代人。"}, {"text": "这么着的时候，我们正在吃饭。", "explanation": "这里表示“那时”，应该用〈那时〉。“这么着”不表示时间。"}, {"text": "我把这么着放进了抽屉。", "explanation": "这里指物，应该用〈它〉。“这么着”只指做法，不指物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72d4ba4f-26a6-401a-a7cf-4f3bd8c05067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92889, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "这么着", "is_correct": true, "explanation": "正确：“这么着”指照这样的动作去画，与“一画，圆就出来了”相合。"}, {"text": "那些", "is_correct": false, "explanation": "搭配：“那些”指代复数事物，不能修饰“一画”这个动作。"}, {"text": "跳", "is_correct": false, "explanation": "语义：跳是跳跃，与画圆的动作无关。"}, {"text": "哭", "is_correct": false, "explanation": "语义：哭是流泪，与画圆的动作无关。"}], "explanations": {"这么着": "正确：“这么着”指照这样的动作去画，与“一画，圆就出来了”相合。", "那些": "搭配：“那些”指代复数事物，不能修饰“一画”这个动作。", "跳": "语义：跳是跳跃，与画圆的动作无关。", "哭": "语义：哭是流泪，与画圆的动作无关。"}, "sentence_index": 6, "correct_answer": "这么着"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这么着是我的书，你别拿。", "explanation": "这里应该用〈这个〉。“这么着”只指做法，不能指代具体的物品。"}, {"text": "我买了一个这么着，很好吃。", "explanation": "这里是名词位置，应该用具体的名词。“这么着”只指做法，不能作名词。"}, {"text": "我昨天在街上遇见了这么着。", "explanation": "这里指人，应该用〈他〉。“这么着”只指做法，不能指代人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72d4ba4f-26a6-401a-a7cf-4f3bd8c05067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92889, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你要是这么着的做，就会更快。", "corrected_sentence": "你要是这么着做，就会更快。", "error_description": "“的”是结构助词，不能加在“这么着”后面；“这么着做”中间不用“的”，写成“这么着的做”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72d4ba4f-26a6-401a-a7cf-4f3bd8c05067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92889, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你再这么着起来，身体就坏了。", "corrected_sentence": "你再这么着下去，身体就坏了。", "error_description": "“再……下去”表示继续这样做，应说“这么着下去”；“起来”不能接在“这么着”后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72d4ba4f-26a6-401a-a7cf-4f3bd8c05067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
