INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92890, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "口语，表示按这样的方式做；也作为承接用语。", "primary_collocate": null, "pronunciation": "zhè me zhe", "ipa": "ʈʂɤ⁵¹ mə ʈʂə", "syllable_count": 3, "sentences": [{"text": "这么着吧，你先回家，我明天给你打电话。", "target_word": "这么着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么着，我们先吃饭，吃完再去看电影。", "target_word": "这么着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别急，这么着，我先帮你问问。", "target_word": "这么着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么着吧，今天太晚了，明天再说。", "target_word": "这么着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么着，你出钱，我出力，行不行？", "target_word": "这么着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么着吧，你先走，我留下来收拾。", "target_word": "这么着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么着吧，你们俩一起去，我在家等着。", "target_word": "这么着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么着，我先走了，你们慢慢聊。", "target_word": "这么着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车坏了，这么着，咱们坐地铁去吧。", "target_word": "这么着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么着，我请你吃饭，你帮我搬家。", "target_word": "这么着", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "口语里提出办法或承接上文，常说“这么着吧”“这么着，……”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df81c267-6b39-4d12-95ab-3643a04c33bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92890, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "这么着", "is_correct": true, "explanation": "正确：“这么着吧”提出办法、承接上文，与句中“你先回家”的安排相合。"}, {"text": "怎样", "is_correct": false, "explanation": "语义：“怎样”是疑问代词，用来问办法，不能直接引出一个提议。"}, {"text": "这会儿", "is_correct": false, "explanation": "搭配：“这会儿”指此刻，不能用来引出一个提议。"}, {"text": "这些", "is_correct": false, "explanation": "搭配：“这些”指代复数事物，不能用来引出一个提议。"}], "explanations": {"这么着": "正确：“这么着吧”提出办法、承接上文，与句中“你先回家”的安排相合。", "怎样": "语义：“怎样”是疑问代词，用来问办法，不能直接引出一个提议。", "这会儿": "搭配：“这会儿”指此刻，不能用来引出一个提议。", "这些": "搭配：“这些”指代复数事物，不能用来引出一个提议。"}, "sentence_index": 0, "correct_answer": "这么着"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的同学想请这么着来做客。", "explanation": "这里指人，应该用〈他〉。“这么着”只指做法，不能指代人。"}, {"text": "这么着是我的书，你别拿。", "explanation": "这里应该用〈这个〉。“这么着”只指做法，不能指代具体的物品。"}, {"text": "我买了两张这么着。", "explanation": "这里应该用〈票〉。“这么着”只指做法，不能作名词宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72d4ba4f-26a6-401a-a7cf-4f3bd8c05067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92890, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "这么着", "is_correct": true, "explanation": "正确：“这么着吧”提出办法，与“你们俩一起去，我在家等着”的安排相合。"}, {"text": "那些", "is_correct": false, "explanation": "搭配：“那些”指代复数事物，不能用来引出一个提议。"}, {"text": "这儿", "is_correct": false, "explanation": "搭配：“这儿”指地点，不能用来引出一个提议。"}, {"text": "怎么", "is_correct": false, "explanation": "语义：“怎么”是疑问词，问如何去做，不能提出办法。"}], "explanations": {"这么着": "正确：“这么着吧”提出办法，与“你们俩一起去，我在家等着”的安排相合。", "那些": "搭配：“那些”指代复数事物，不能用来引出一个提议。", "这儿": "搭配：“这儿”指地点，不能用来引出一个提议。", "怎么": "语义：“怎么”是疑问词，问如何去做，不能提出办法。"}, "sentence_index": 6, "correct_answer": "这么着"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这么着的时候，我们正在吃饭。", "explanation": "这里表示“那时”，应该用〈那时〉。“这么着”不表示时间。"}, {"text": "我买了一个这么着，很好吃。", "explanation": "这里是名词位置，应该用具体的名词。“这么着”只指做法，不能作名词。"}, {"text": "他把这么着放进了包里。", "explanation": "这里指物，应用〈它〉或具体的名词。“这么着”只指做法，不指物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72d4ba4f-26a6-401a-a7cf-4f3bd8c05067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92890, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这么着地，你先回家，我来收拾。", "corrected_sentence": "这么着吧，你先回家，我来收拾。", "error_description": "提议语气须用语气词“吧”，写成结构助词“地”是错误的；应说“这么着吧”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72d4ba4f-26a6-401a-a7cf-4f3bd8c05067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92890, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这么着的吧，我先走，你们再慢慢聊。", "corrected_sentence": "这么着吧，我先走，你们再慢慢聊。", "error_description": "“的”是结构助词，不能加在“这么着”后面；应说“这么着吧”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72d4ba4f-26a6-401a-a7cf-4f3bd8c05067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
