INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92893, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "边境是一个国家和另一个国家相连的地方。", "primary_collocate": null, "pronunciation": "biān jìng", "ipa": "pjɛn˥ tɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "中国和越南的边境有很长的一段山路。", "target_word": "边境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河就在两国的边境上。", "target_word": "边境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们坐火车到了边境，然后下车走路过去。", "target_word": "边境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "边境那边是另一个国家。", "target_word": "边境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在边境，你要给警察看护照。", "target_word": "边境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在边境上住了很多年。", "target_word": "边境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "边境的两边说不同的语言。", "target_word": "边境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过边境的时候，所有人都要检查行李。", "target_word": "边境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国的士兵每天在边境巡逻。", "target_word": "边境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友在边境开了一家小商店。", "target_word": "边境", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "两个国家相连接的地方，强调两国交界处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c651e1d1-7d7e-4bf6-8590-9fbd5db22afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92893, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "海洋", "is_correct": false, "explanation": "语义：海洋是大片水域，“海洋有很长的一段山路”与常识相矛盾。"}, {"text": "边境", "is_correct": true, "explanation": "“边境”指两国相连的地区，“中国和越南的边境有很长的一段山路”符合常识。"}, {"text": "电视", "is_correct": false, "explanation": "语义：“电视”是家用电器，不能有“一段山路”，句子不成立。"}, {"text": "大海", "is_correct": false, "explanation": "语义：“大海”是水域，不可能有山路，与句中的“山路”矛盾。"}], "explanations": {"海洋": "语义：海洋是大片水域，“海洋有很长的一段山路”与常识相矛盾。", "边境": "“边境”指两国相连的地区，“中国和越南的边境有很长的一段山路”符合常识。", "电视": "语义：“电视”是家用电器，不能有“一段山路”，句子不成立。", "大海": "语义：“大海”是水域，不可能有山路，与句中的“山路”矛盾。"}, "sentence_index": 0, "correct_answer": "边境"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在一只边境住了三年。", "explanation": "量词“只”多用于动物或成对的东西，不能用来修饰“边境”，这里的量词搭配错了。"}, {"text": "他的画功已经到了很高的边境。", "explanation": "这里应该用〈境界〉。“边境”指两国交界的地区，不表示技艺达到的程度。"}, {"text": "这座岛的边境上有一条小路。", "explanation": "这里应该用〈边缘〉。“边境”专指两国交界的地区，岛屿的边缘不是国界，不能用“边境”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e94bd45b-59e6-43ab-9dab-bfdfda6bf16a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92893, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "饭碗", "is_correct": false, "explanation": "语义：“饭碗”是盛饭的器具，它的两边不会说不同的语言，句子不成立。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”是家用电器，它的两边不会说不同的语言。"}, {"text": "边境", "is_correct": true, "explanation": "“边境”指两国相连的地区，“边境的两边说不同的语言”符合常识。"}, {"text": "电梯", "is_correct": false, "explanation": "语义：“电梯”是升降设备，它的两边不会说不同的语言，句子不成立。"}], "explanations": {"饭碗": "语义：“饭碗”是盛饭的器具，它的两边不会说不同的语言，句子不成立。", "冰箱": "语义：“冰箱”是家用电器，它的两边不会说不同的语言。", "边境": "“边境”指两国相连的地区，“边境的两边说不同的语言”符合常识。", "电梯": "语义：“电梯”是升降设备，它的两边不会说不同的语言，句子不成立。"}, "sentence_index": 6, "correct_answer": "边境"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张纸的边境画着一朵花。", "explanation": "这里应该用〈边沿〉。“边境”指两个国家相连的地区，纸张的边沿不能说“边境”。"}, {"text": "他把这个问题的边境划得很清楚。", "explanation": "这里应该用〈界限〉。“边境”指地区，不指抽象的界限或范围。"}, {"text": "这块石头的边境很粗糙。", "explanation": "这里应该用〈棱角〉。“边境”指两国交界的地区，不指物体的边角。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e94bd45b-59e6-43ab-9dab-bfdfda6bf16a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92893, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们徒步穿过了一颗边境。", "corrected_sentence": "我们徒步穿过了边境。", "error_description": "量词错误：“边境”指国家交界的地方，这里不需要量词，更不能用“颗”（“颗”多用于圆形的小东西）。应说“穿过了边境”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e94bd45b-59e6-43ab-9dab-bfdfda6bf16a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92893, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天都在边境在巡逻。", "corrected_sentence": "他每天都在边境巡逻。", "error_description": "多余的“在”：地点状语“在边境”后面不能再加“在”，应说“在边境巡逻”，“在”只需出现一次。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e94bd45b-59e6-43ab-9dab-bfdfda6bf16a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92894, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e94bd45b-59e6-43ab-9dab-bfdfda6bf16a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92894, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e94bd45b-59e6-43ab-9dab-bfdfda6bf16a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92894, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "靠近国界的地区。", "primary_collocate": null, "pronunciation": "biān jìng", "ipa": "pjɛn˥ tɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他在边境地区当了二十年老师。", "target_word": "边境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "边境的冬天又长又冷。", "target_word": "边境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个边境小镇很安静。", "target_word": "边境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府给边境的学校送去了新书。", "target_word": "边境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "边境地区的人常常去对面买东西。", "target_word": "边境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位医生每年去边境给农民看病。", "target_word": "边境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "边境的山上住着很多少数民族。", "target_word": "边境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军人日夜守卫边境，保护国家安全。", "target_word": "边境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "边境的路不好走，车开得很慢。", "target_word": "边境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "近几年，边境的生活变好了。", "target_word": "边境", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "靠近国界的一片地区，强调地区的生活、环境", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c651e1d1-7d7e-4bf6-8590-9fbd5db22afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92894, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”是室内空间，不能作为一个“地区”，句子不成立。"}, {"text": "边境", "is_correct": true, "explanation": "“边境”指靠近国界的地区，“他在边境地区当了二十年老师”符合句意。"}, {"text": "天空", "is_correct": false, "explanation": "语义：“天空”不是地区，人不能在天空里当老师，与句意矛盾。"}, {"text": "卧室", "is_correct": false, "explanation": "搭配：“地区”一般不与“卧室”搭配，“卧室地区”不成词组。"}], "explanations": {"厨房": "语义：“厨房”是室内空间，不能作为一个“地区”，句子不成立。", "边境": "“边境”指靠近国界的地区，“他在边境地区当了二十年老师”符合句意。", "天空": "语义：“天空”不是地区，人不能在天空里当老师，与句意矛盾。", "卧室": "搭配：“地区”一般不与“卧室”搭配，“卧室地区”不成词组。"}, "sentence_index": 0, "correct_answer": "边境"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座城市的边境有很多高楼。", "explanation": "这里应该用〈边缘〉。“边境”指两国交界的地区，城市的外围不说“边境”。"}, {"text": "他的汉语已经到了很高的边境。", "explanation": "这里应该用〈水平〉。“边境”不能表示能力达到的程度。"}, {"text": "我在一颗边境住了二十年。", "explanation": "量词“颗”用于圆形的小东西，不能用来修饰“边境”，这里的量词搭配错了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e94bd45b-59e6-43ab-9dab-bfdfda6bf16a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92894, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "海洋", "is_correct": false, "explanation": "语义：海洋中没有“山上”，“海洋的山上住着很多少数民族”与常识矛盾。"}, {"text": "教室", "is_correct": false, "explanation": "语义：“教室”是室内空间，不能有“山上”，句意不成立。"}, {"text": "边境", "is_correct": true, "explanation": "“边境”指靠近国界的地区，“边境的山上住着很多少数民族”符合句意。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“冰箱”不能与“的山上”搭配，句子的修饰关系不成立。"}], "explanations": {"海洋": "语义：海洋中没有“山上”，“海洋的山上住着很多少数民族”与常识矛盾。", "教室": "语义：“教室”是室内空间，不能有“山上”，句意不成立。", "边境": "“边境”指靠近国界的地区，“边境的山上住着很多少数民族”符合句意。", "冰箱": "搭配：“冰箱”不能与“的山上”搭配，句子的修饰关系不成立。"}, "sentence_index": 6, "correct_answer": "边境"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块木板的边境刮破了我的手。", "explanation": "这里应该用〈边沿〉。“边境”指靠近国界的地区，木板的边沿不能说“边境”。"}, {"text": "他把两家的边境划得很清楚。", "explanation": "这里应该用〈界限〉。“边境”指地区，不指抽象的界限。"}, {"text": "这个小区的边境很安静。", "explanation": "这里应该用〈外围〉。“边境”指靠近国界的地区，小区的外围不说“边境”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e94bd45b-59e6-43ab-9dab-bfdfda6bf16a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92894, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在一颗边境待了一个月。", "corrected_sentence": "我们在边境待了一个月。", "error_description": "量词错误：“边境”前不能用“颗”（“颗”多用于圆形的小东西），这里也不需要量词，应说“在边境待了一个月”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e94bd45b-59e6-43ab-9dab-bfdfda6bf16a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92894, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们每年都去在边境采访。", "corrected_sentence": "我们每年都去边境采访。", "error_description": "介词多余：“去”后面直接带地点“边境”，不能再加“在”，应说“去边境采访”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e94bd45b-59e6-43ab-9dab-bfdfda6bf16a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
