INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92895, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f64cdb5-3745-42f4-ba36-e5a3b1258b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92895, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "网络环境是上网时周围的样子，比如网速快不快，安不安全。", "primary_collocate": null, "pronunciation": "wǎng luò huán jìng", "ipa": "wɑŋ˨˩ luɔ˥˩ xuan˧˥ tɕiŋ˥˩", "syllable_count": 4, "sentences": [{"text": "这里的网络环境很好，网速很快。", "target_word": "网络环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "家里的网络环境不好，视频总是卡。", "target_word": "网络环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在咖啡馆工作，网络环境安全吗？", "target_word": "网络环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他搬家前先问了新房的网络环境。", "target_word": "网络环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公共场所的网络环境常常不太安全。", "target_word": "网络环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生宿舍的网络环境怎么样？", "target_word": "网络环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了开视频会议，我很在意网络环境。", "target_word": "网络环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山里的网络环境差，手机常常没有信号。", "target_word": "网络环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家酒店的网络环境让我很满意。", "target_word": "网络环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我住过的几个地方，网络环境都不错。", "target_word": "网络环境", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "網絡環境", "label": "繁体"}], "register": "中性", "sense_fingerprint": "上网时所处的具体情况，如网速快慢、是否安全", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83b79118-3afa-43a8-854c-cfbbc5147759') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92895, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "噪音", "is_correct": false, "explanation": "语义：“噪音”是不好的声音，不能说“很好”，句子说不通。"}, {"text": "网络环境", "is_correct": true, "explanation": "“网络环境”指上网时的网速、安全等状况，与“网速很快”相符，正好填入这里。"}, {"text": "交通事故", "is_correct": false, "explanation": "语义：“交通事故”是坏事，不能用“很好”形容，与句意相反。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：“垃圾”是要清理的东西，不能用“很好”形容，句子说不通。"}], "explanations": {"噪音": "语义：“噪音”是不好的声音，不能说“很好”，句子说不通。", "网络环境": "“网络环境”指上网时的网速、安全等状况，与“网速很快”相符，正好填入这里。", "交通事故": "语义：“交通事故”是坏事，不能用“很好”形容，与句意相反。", "垃圾": "语义：“垃圾”是要清理的东西，不能用“很好”形容，句子说不通。"}, "sentence_index": 0, "correct_answer": "网络环境"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们小区的网络环境很安静，绿化也很好。", "explanation": "这里应该用〈居住环境〉。“安静”“绿化”描述的是居住空间，网络环境指上网的网速和安全，不能这样形容。"}, {"text": "这家饭馆的网络环境很好吃，菜很便宜。", "explanation": "这里应该用〈饭菜〉。“好吃”说的是食物，网络环境指上网的网速和安全，不能说好吃。"}, {"text": "这片森林的网络环境很好，鸟很多。", "explanation": "这里应该用〈生态环境〉。森林和鸟类描述的是自然环境，“网络环境”只指上网条件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f64cdb5-3745-42f4-ba36-e5a3b1258b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92895, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "午餐菜单", "is_correct": false, "explanation": "语义：开视频会议需要的是上网条件，“午餐菜单”与此无关，不符合句中的目的。"}, {"text": "网络环境", "is_correct": true, "explanation": "“网络环境”指上网时的网速和稳定性，与“开视频会议”的需要相符，填入这里正确。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：开视频会议需要的是上网条件，“雨伞”与此毫不相干，句子说不通。"}, {"text": "宠物粮食", "is_correct": false, "explanation": "语义：视频会议关心的是网络是否流畅，“宠物粮食”与此无关。"}], "explanations": {"午餐菜单": "语义：开视频会议需要的是上网条件，“午餐菜单”与此无关，不符合句中的目的。", "网络环境": "“网络环境”指上网时的网速和稳定性，与“开视频会议”的需要相符，填入这里正确。", "雨伞": "语义：开视频会议需要的是上网条件，“雨伞”与此毫不相干，句子说不通。", "宠物粮食": "语义：视频会议关心的是网络是否流畅，“宠物粮食”与此无关。"}, "sentence_index": 6, "correct_answer": "网络环境"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这所学校的网络环境很美丽，校园里有很多花。", "explanation": "这里应该用〈校园环境〉。“美丽”“很多花”描述的是校园景色，网络环境只指上网条件，不能这样说。"}, {"text": "这家公司的网络环境很宽敞，楼上还有一个健身房。", "explanation": "这里应该用〈工作环境〉。“宽敞”“健身房”说的是办公场所，网络环境不指房间或设施。"}, {"text": "这座湖的网络环境很清澈，能看见水底的鱼。", "explanation": "这里应该用〈自然环境〉。“清澈”“水底的鱼”描述的是自然景观，网络环境不能这样形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f64cdb5-3745-42f4-ba36-e5a3b1258b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92895, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家酒店有一只很好的网络环境，我们开会很顺利。", "corrected_sentence": "这家酒店有一个很好的网络环境，我们开会很顺利。", "error_description": "量词错误：“网络环境”应用量词“个”，不能用“只”，“只”一般用于动物或成对的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f64cdb5-3745-42f4-ba36-e5a3b1258b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92895, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家的网络环境好着很多，视频再也不卡了。", "corrected_sentence": "我家的网络环境好了很多，视频再也不卡了。", "error_description": "了用错：“好了很多”表示变化已经完成，应用“了”。“好着很多”错误，“着”只表示状态持续，不能用于已经发生的变化和程度比较。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f64cdb5-3745-42f4-ba36-e5a3b1258b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
