INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92896, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "上网活动所处的技术条件和信息、秩序等总体状况。", "primary_collocate": null, "pronunciation": "wǎng luò huán jìng", "ipa": "wɑŋ˨˩ luɔ˥˩ xuan˧˥ tɕiŋ˥˩", "syllable_count": 4, "sentences": [{"text": "政府正在努力改善网络环境。", "target_word": "网络环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "良好的网络环境需要大家一起保护。", "target_word": "网络环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网络环境中有很多不真实的信息。", "target_word": "网络环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校希望给孩子一个干净的网络环境。", "target_word": "网络环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网络环境变好了，上网的人也更多了。", "target_word": "网络环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "管理网络环境，需要法律和技术一起努力。", "target_word": "网络环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "清朗的网络环境对青少年很重要。", "target_word": "网络环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网络谣言会破坏网络环境。", "target_word": "网络环境", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "很多人在网上发假消息，网络环境越来越乱。", "target_word": "网络环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的网络环境要靠平台和用户共同维护。", "target_word": "网络环境", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "網絡環境", "label": "繁体"}], "register": "中性", "sense_fingerprint": "网络空间的整体技术条件、信息内容与秩序状况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83b79118-3afa-43a8-854c-cfbbc5147759') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92896, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "搭配：“改善”一般不用于天气这种自然现象，天气不能被政府改善。"}, {"text": "网络环境", "is_correct": true, "explanation": "“网络环境”指网络空间的技术条件、信息和秩序，可以由政府努力改善，符合句意。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高是个人的生理数据，不是政府可以去改善的状况。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“改善时间”不通，时间的多少应说节约或浪费，不说改善。"}], "explanations": {"天气": "搭配：“改善”一般不用于天气这种自然现象，天气不能被政府改善。", "网络环境": "“网络环境”指网络空间的技术条件、信息和秩序，可以由政府努力改善，符合句意。", "身高": "语义：身高是个人的生理数据，不是政府可以去改善的状况。", "时间": "搭配：“改善时间”不通，时间的多少应说节约或浪费，不说改善。"}, "sentence_index": 0, "correct_answer": "网络环境"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们家附近的网络环境很安静，适合散步。", "explanation": "这里应该用〈居住环境〉。“安静”“散步”说的是住处周围的环境，网络环境指上网条件，不能这样形容。"}, {"text": "这家饭馆的网络环境很好吃，价格也不贵。", "explanation": "这里应该用〈饭菜〉。“好吃”形容食物，网络环境指网络空间的信息和秩序，不能说好吃。"}, {"text": "这片海域的网络环境很好，鱼很多。", "explanation": "这里应该用〈生态环境〉。海域和鱼类描述的是自然生态，“网络环境”只指上网条件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f64cdb5-3745-42f4-ba36-e5a3b1258b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92896, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "数学成绩", "is_correct": false, "explanation": "搭配：“清朗”形容天空、声音或风气，不说“清朗的成绩”，应说“优秀的成绩”。"}, {"text": "网络环境", "is_correct": true, "explanation": "“清朗的网络环境”指风清气正、信息健康的网络空间，与句意相符，填入这里正确。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“清朗”不用来形容价格，价格可以高或低，不能说清朗。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“清朗”形容明亮清澈的天空或环境，不能用来形容体重这种身体数据。"}], "explanations": {"数学成绩": "搭配：“清朗”形容天空、声音或风气，不说“清朗的成绩”，应说“优秀的成绩”。", "网络环境": "“清朗的网络环境”指风清气正、信息健康的网络空间，与句意相符，填入这里正确。", "价格": "搭配：“清朗”不用来形容价格，价格可以高或低，不能说清朗。", "体重": "语义：“清朗”形容明亮清澈的天空或环境，不能用来形容体重这种身体数据。"}, "sentence_index": 6, "correct_answer": "网络环境"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这所学校的网络环境很整洁，操场上有很多树。", "explanation": "这里应该用〈校园环境〉。“整洁”“操场上的树”描述的是校园，网络环境只指上网条件。"}, {"text": "这家公司的网络环境很宽敞，楼上还有一个健身房。", "explanation": "这里应该用〈工作环境〉。“宽敞”“健身房”说的是办公场所，网络环境不指房间或设施。"}, {"text": "这座湖的网络环境很清澈，能看见水底的鱼。", "explanation": "这里应该用〈自然环境〉。“清澈”“水底的鱼”描述的是自然景观，网络环境不能这样形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f64cdb5-3745-42f4-ba36-e5a3b1258b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92896, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个平台维护了一条清朗的网络环境，用户很满意。", "corrected_sentence": "这个平台维护了一个清朗的网络环境，用户很满意。", "error_description": "量词错误：“网络环境”应用量词“个”或“种”，不能用“条”，“条”用于河流、道路等细长的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f64cdb5-3745-42f4-ba36-e5a3b1258b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92896, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这颗网络环境变差了，大家很不满意。", "corrected_sentence": "这个网络环境变差了，大家很不满意。", "error_description": "量词错误：“颗”用于圆而小的东西，网络环境是抽象概念，应用“个”，不说“这颗网络环境”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f64cdb5-3745-42f4-ba36-e5a3b1258b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
