INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92897, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "除非是说只有这样做，才会有那个结果。", "primary_collocate": null, "pronunciation": "chú fēi", "ipa": "ʈʂʰu˧˥ fei˥˥", "syllable_count": 2, "sentences": [{"text": "除非你来，我才去。", "target_word": "除非", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "除非明天天气好，我们才去爬山。", "target_word": "除非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "除非你道歉，他才会原谅你。", "target_word": "除非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "除非有急事，我不会给你打电话。", "target_word": "除非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "除非天气特别好，他才会出门散步。", "target_word": "除非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "除非你多练习，不然很难说好汉语。", "target_word": "除非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "除非他亲口告诉我，我才相信这件事。", "target_word": "除非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "除非你把作业写完，妈妈才让你玩手机。", "target_word": "除非", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "除非有人帮忙，否则这么重的箱子搬不上楼。", "target_word": "除非", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很少迟到，除非路上堵车。", "target_word": "除非", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "除非……才……", "label": "固定搭配"}], "register": "中性", "sense_fingerprint": "引出唯一的做法，只有这样做才会有那个结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd2a1ec9-6f0b-449f-8068-f924ac67d7eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92897, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "除非", "is_correct": true, "explanation": "正确：“除非”引出唯一条件，与“我才去”搭配，意思通顺。"}, {"text": "虽然", "is_correct": false, "explanation": "语义：“虽然”表示让步，与“我才去”的唯一条件矛盾。"}, {"text": "即使", "is_correct": false, "explanation": "搭配：“即使”通常与“也”“还”搭配，不能与“才”构成唯一条件。"}, {"text": "而且", "is_correct": false, "explanation": "语义：“而且”表示并列或递进，不能引出条件。"}], "explanations": {"除非": "正确：“除非”引出唯一条件，与“我才去”搭配，意思通顺。", "虽然": "语义：“虽然”表示让步，与“我才去”的唯一条件矛盾。", "即使": "搭配：“即使”通常与“也”“还”搭配，不能与“才”构成唯一条件。", "而且": "语义：“而且”表示并列或递进，不能引出条件。"}, "sentence_index": 0, "correct_answer": "除非"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们先去超市，除非回家。", "explanation": "这里应该用〈然后〉，表示先后顺序。〈除非〉引出唯一条件，不能表示动作的先后。"}, {"text": "这家饭店很便宜，除非很好吃。", "explanation": "这里应该用〈而且〉，表示并列。〈除非〉引出唯一条件，不能并列两个优点。"}, {"text": "除非你，我谁都不认识。", "explanation": "这里应该用〈除了〉，表示排除，后面接名词。〈除非〉要接条件小句，不能接名词“你”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9bab58-da2f-4ece-9e35-f06ef4287688') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92897, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "除非", "is_correct": true, "explanation": "正确：“除非”引出唯一条件，“他亲口告诉我，我才相信”符合这个条件关系。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示结果，与“我才相信”的条件关系矛盾。"}, {"text": "然而", "is_correct": false, "explanation": "搭配：“然而”要承接前文的转折，句中没有转折。"}, {"text": "无论", "is_correct": false, "explanation": "搭配：“无论”后面要配“都”，表示任何情况，与唯一条件矛盾。"}], "explanations": {"除非": "正确：“除非”引出唯一条件，“他亲口告诉我，我才相信”符合这个条件关系。", "所以": "语义：“所以”表示结果，与“我才相信”的条件关系矛盾。", "然而": "搭配：“然而”要承接前文的转折，句中没有转折。", "无论": "搭配：“无论”后面要配“都”，表示任何情况，与唯一条件矛盾。"}, "sentence_index": 6, "correct_answer": "除非"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他昨天没睡好，除非今天很累。", "explanation": "这里应该用〈所以〉，表示结果。〈除非〉引出唯一条件，不能引出结果。"}, {"text": "除非下雨，他却没带伞。", "explanation": "这里不能用〈除非〉。〈除非〉引出唯一条件，不能用来表示转折；表示“下雨，但是他没带伞”这类转折，应用〈但是〉。"}, {"text": "除非他会说英语，所以能找到工作。", "explanation": "这里应该用〈因为〉，表示原因，与“所以”搭配。〈除非〉引出唯一条件，不能用来说明原因。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9bab58-da2f-4ece-9e35-f06ef4287688') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92897, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "除非你同意，所以我去。", "corrected_sentence": "除非你同意，我才去。", "error_description": "关联词用错：「除非」引出唯一条件，结果分句不能用表示结果的「所以」，应说「除非你同意，我才去」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9bab58-da2f-4ece-9e35-f06ef4287688') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92897, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "除非提前预约，却见不到医生。", "corrected_sentence": "除非提前预约，才能见到医生。", "error_description": "关联词用错：「除非」引出唯一条件，结果分句不能用表示转折的「却」，应说「除非提前预约，才能见到医生」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9bab58-da2f-4ece-9e35-f06ef4287688') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
