INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92898, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，表示唯一的条件，常与“才”“否则”搭配。", "primary_collocate": null, "pronunciation": "chú fēi", "ipa": "ʈʂʰu˧˥ fei˥˥", "syllable_count": 2, "sentences": [{"text": "除非你告诉我，我才知道。", "target_word": "除非", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "除非他自己想学，否则别人说也没用。", "target_word": "除非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "除非明天下大雨，比赛才会取消。", "target_word": "除非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "除非你有票，否则不能进去。", "target_word": "除非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "除非现在出发，否则赶不上最后一班车。", "target_word": "除非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事除非老师帮忙，不然谁也做不好。", "target_word": "除非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "除非你愿意帮我，我才有办法解决这个问题。", "target_word": "除非", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子除非生病，否则每天都去上学。", "target_word": "除非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "除非你先付钱，老板才肯把东西给你。", "target_word": "除非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "除非我们一起想办法，不然这个问题很难解决。", "target_word": "除非", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "除非……否则……", "label": "固定搭配"}], "register": "中性", "sense_fingerprint": "连词，提出唯一的条件，后面常接“才”或“否则”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd2a1ec9-6f0b-449f-8068-f924ac67d7eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92898, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "除非", "is_correct": true, "explanation": "正确：“除非”引出唯一条件，与“我才知道”搭配，意思通顺。"}, {"text": "不但", "is_correct": false, "explanation": "搭配：“不但”要与“而且”“还”搭配，不能引出条件。"}, {"text": "无论", "is_correct": false, "explanation": "搭配：“无论”后面要配“都”，表示任何情况，与“才知道”的唯一条件不符。"}, {"text": "虽然", "is_correct": false, "explanation": "语义：“虽然”表示让步，与唯一条件的意思冲突。"}], "explanations": {"除非": "正确：“除非”引出唯一条件，与“我才知道”搭配，意思通顺。", "不但": "搭配：“不但”要与“而且”“还”搭配，不能引出条件。", "无论": "搭配：“无论”后面要配“都”，表示任何情况，与“才知道”的唯一条件不符。", "虽然": "语义：“虽然”表示让步，与唯一条件的意思冲突。"}, "sentence_index": 0, "correct_answer": "除非"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "除非今天下雨，所以我们没去公园。", "explanation": "这里应该用〈因为〉，表示原因，与“所以”搭配。〈除非〉引出唯一条件，不能说明原因。"}, {"text": "他会说英语，除非会说日语。", "explanation": "这里应该用〈并且〉，表示并列。〈除非〉引出唯一条件，不能并列两项。"}, {"text": "我们先吃饭，除非去看电影。", "explanation": "这里应该用〈然后〉，表示先后顺序。〈除非〉引出条件，不能表示动作的先后。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9bab58-da2f-4ece-9e35-f06ef4287688') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92898, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "除非", "is_correct": true, "explanation": "正确：“除非”引出唯一条件，“你愿意帮我，我才有办法解决”符合这个关系。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示结果，与“才有办法解决”的条件关系矛盾。"}, {"text": "然而", "is_correct": false, "explanation": "搭配：“然而”要承接前文的转折，句中没有转折。"}, {"text": "即使", "is_correct": false, "explanation": "语义：“即使”表示让步，与唯一条件的意思矛盾。"}], "explanations": {"除非": "正确：“除非”引出唯一条件，“你愿意帮我，我才有办法解决”符合这个关系。", "所以": "语义：“所以”表示结果，与“才有办法解决”的条件关系矛盾。", "然而": "搭配：“然而”要承接前文的转折，句中没有转折。", "即使": "语义：“即使”表示让步，与唯一条件的意思矛盾。"}, "sentence_index": 6, "correct_answer": "除非"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服很漂亮，除非有点贵。", "explanation": "这里应该用〈不过〉，表示转折。〈除非〉引出唯一条件，不能用来表示转折。"}, {"text": "除非我们一起想办法，却很难解决这个问题。", "explanation": "这里不能用〈除非〉。〈除非〉引出唯一条件，结果分句要用〈才〉〈否则〉或〈不然〉引出，不能用来表示转折；转折应使用〈但是〉。"}, {"text": "我们提前出发，除非就能赶上车。", "explanation": "这里应该用〈这样〉，表示结果。〈除非〉引出唯一条件，不能接结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9bab58-da2f-4ece-9e35-f06ef4287688') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92898, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "除非你有钱，所以买不了房子。", "corrected_sentence": "除非你有钱，否则买不了房子。", "error_description": "关联词用错：「除非」引出唯一条件，结果分句不能用表示结果的「所以」，应说「除非你有钱，否则买不了房子」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9bab58-da2f-4ece-9e35-f06ef4287688') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92898, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "除非下大雨，比赛却会取消。", "corrected_sentence": "除非下大雨，比赛才会取消。", "error_description": "关联词用错：「除非」引出唯一条件，结果分句不能用表示转折的「却」，应说「除非下大雨，比赛才会取消」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9bab58-da2f-4ece-9e35-f06ef4287688') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
