INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92900, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "年老而死；因衰老而死亡。", "primary_collocate": null, "pronunciation": "lǎo sǐ", "ipa": "laʊ˨˩ sɹ̩˨˩˦", "syllable_count": 2, "sentences": [{"text": "那位老人在家乡老死了，享年九十岁。", "target_word": "老死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他希望自己能在家里老死。", "target_word": "老死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人不想在医院老死。", "target_word": "老死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只老猫在院子里老死了。", "target_word": "老死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一辈子没离开过小镇，最后在那里老死。", "target_word": "老死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说自己不想一个人老死。", "target_word": "老死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷是在睡梦中老死的。", "target_word": "老死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人们都希望能平平安安地老死。", "target_word": "老死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那条老狗在主人身边老死了。", "target_word": "老死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候，很多人在村里出生，也在村里老死。", "target_word": "老死", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "老死了", "label": "体标（了）"}], "register": "中性", "sense_fingerprint": "因年纪很大、身体衰老而自然死亡", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0006e141-8dc4-4804-a206-f5967740a580') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92900, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "老死", "is_correct": true, "explanation": "老死（lǎo sǐ）：年老而死，即本词。"}, {"text": "老子", "is_correct": false, "explanation": "zǐ 与 sǐ 声调相同，仅声母不同（z/s），意思是父亲或古代思想家老子。"}, {"text": "老师", "is_correct": false, "explanation": "shī（第一声）与 sǐ（第三声）声母不同（sh/s），声调也不同，意思是教书的人。"}, {"text": "老实", "is_correct": false, "explanation": "shí（第二声）与 sǐ（第三声）声母不同（sh/s），声调也不同，意思是诚实、不欺骗。"}, {"text": "老四", "is_correct": false, "explanation": "sì（第四声）与 sǐ（第三声）声调不同，意思是家里排行第四的人。"}], "explanations": {"老死": "老死（lǎo sǐ）：年老而死，即本词。", "老子": "zǐ 与 sǐ 声调相同，仅声母不同（z/s），意思是父亲或古代思想家老子。", "老师": "shī（第一声）与 sǐ（第三声）声母不同（sh/s），声调也不同，意思是教书的人。", "老实": "shí（第二声）与 sǐ（第三声）声母不同（sh/s），声调也不同，意思是诚实、不欺骗。", "老四": "sì（第四声）与 sǐ（第三声）声调不同，意思是家里排行第四的人。"}, "sentence_index": null, "correct_answer": "老死"}, "level_3": {"options": [{"text": "老死", "is_correct": true, "explanation": "老死：年老时自然离世，与“享年九十岁”的高寿相符。"}, {"text": "夭折", "is_correct": false, "explanation": "语义：夭折指年轻时早逝，与“享年九十岁”的高寿相矛盾。"}, {"text": "殉职", "is_correct": false, "explanation": "搭配：殉职只用于为公事在工作岗位上牺牲的人，不用于一般老人的去世。"}, {"text": "出生", "is_correct": false, "explanation": "语义：出生指降生，与“享年九十岁”的寿终叙述矛盾，句意不通。"}], "explanations": {"老死": "老死：年老时自然离世，与“享年九十岁”的高寿相符。", "夭折": "语义：夭折指年轻时早逝，与“享年九十岁”的高寿相矛盾。", "殉职": "搭配：殉职只用于为公事在工作岗位上牺牲的人，不用于一般老人的去世。", "出生": "语义：出生指降生，与“享年九十岁”的寿终叙述矛盾，句意不通。"}, "sentence_index": 0, "correct_answer": "老死"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子出生后三天就老死了。", "explanation": "这里应该用〈夭折〉。老死指年老时自然离世，婴儿早逝要用〈夭折〉。"}, {"text": "他在车祸中老死了。", "explanation": "这里应该用〈丧生〉。老死指年老时自然去世，车祸中意外死亡要用〈丧生〉。"}, {"text": "他为了保护同伴老死了。", "explanation": "这里应该用〈牺牲〉。老死指年老时自然去世，为了保护他人而死要用〈牺牲〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f74798a-5a73-4add-9ed7-fed78d2d8d9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92900, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "老死", "is_correct": true, "explanation": "老死：年老时自然离世，与“在睡梦中”安然去世的语境相符。"}, {"text": "出生", "is_correct": false, "explanation": "语义：出生指降生，与句子讲述的死亡方式完全不符。"}, {"text": "牺牲", "is_correct": false, "explanation": "搭配：牺牲指为了某种事业或他人而舍弃生命，与在睡梦中自然去世不相符。"}, {"text": "逃走", "is_correct": false, "explanation": "语义：逃走指离开某地躲避，与“在睡梦中”的死亡语境无关。"}], "explanations": {"老死": "老死：年老时自然离世，与“在睡梦中”安然去世的语境相符。", "出生": "语义：出生指降生，与句子讲述的死亡方式完全不符。", "牺牲": "搭配：牺牲指为了某种事业或他人而舍弃生命，与在睡梦中自然去世不相符。", "逃走": "语义：逃走指离开某地躲避，与“在睡梦中”的死亡语境无关。"}, "sentence_index": 6, "correct_answer": "老死"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他昨天突然老死了，家人都没来得及道别。", "explanation": "这里应该用〈猝死〉。老死指年老时慢慢离世，突然的意外去世要用〈猝死〉。"}, {"text": "他因为肺癌老死了。", "explanation": "这里应该用〈病逝〉。老死指年老时自然去世，因病去世要用〈病逝〉。"}, {"text": "地震中，很多人老死了。", "explanation": "这里应该用〈遇难〉。老死指年老时自然离世，地震等灾难中丧生要用〈遇难〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f74798a-5a73-4add-9ed7-fed78d2d8d9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92900, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我外婆在家里被老死了。", "corrected_sentence": "我外婆在家里老死了。", "error_description": "“老死”是不及物动词，不能用“被”构成被动句。错误形式是“被老死了”，正确形式是“老死了”，应去掉“被”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f74798a-5a73-4add-9ed7-fed78d2d8d9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92900, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位老教授在书房里老死着。", "corrected_sentence": "这位老教授在书房里老死了。", "error_description": "“老死”表示一次性完成的结束，应使用“了”，不能用表示持续状态的“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f74798a-5a73-4add-9ed7-fed78d2d8d9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92901, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "饱", "is_correct": true, "explanation": "饱：指吃够了，肚子满足，与“饿”互为反义词。"}, {"text": "渴", "is_correct": false, "explanation": "渴：指想喝水，与“饿”没有反义关系，只是另一种身体需要。"}, {"text": "累", "is_correct": false, "explanation": "累：指身体疲劳，与“饿”没有反义关系。"}, {"text": "冷", "is_correct": false, "explanation": "冷：指温度低，与“饿”没有反义关系。"}], "correct_answer": "饱", "explanations": {"饱": "饱：指吃够了，肚子满足，与“饿”互为反义词。", "渴": "渴：指想喝水，与“饿”没有反义关系，只是另一种身体需要。", "累": "累：指身体疲劳，与“饿”没有反义关系。", "冷": "冷：指温度低，与“饿”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b55e6d1-d065-468e-8962-434097609120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92901, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "饱", "is_correct": true, "explanation": "饱：指吃够了，与“饿”互为反义词。"}, {"text": "忙", "is_correct": false, "explanation": "忙：指事情多、没有空，与“饿”没有反义关系。"}, {"text": "困", "is_correct": false, "explanation": "困：指想睡觉，与“饿”没有反义关系。"}, {"text": "急", "is_correct": false, "explanation": "急：指着急、迫切，与“饿”没有反义关系。"}], "correct_answer": "饱", "explanations": {"饱": "饱：指吃够了，与“饿”互为反义词。", "忙": "忙：指事情多、没有空，与“饿”没有反义关系。", "困": "困：指想睡觉，与“饿”没有反义关系。", "急": "急：指着急、迫切，与“饿”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b55e6d1-d065-468e-8962-434097609120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92901, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "饿是肚子空了，想吃东西。", "primary_collocate": null, "pronunciation": "è", "ipa": "ɤ˥˩", "syllable_count": 1, "sentences": [{"text": "我今天没吃早饭，现在很饿。", "target_word": "饿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子饿了，妈妈给他做了面条。", "target_word": "饿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你饿不饿？我们去吃饭吧。", "target_word": "饿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中午只吃了一点米饭，下午三点就饿了。", "target_word": "饿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我饿得走不动路了。", "target_word": "饿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗一天没吃东西，看起来很饿。", "target_word": "饿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他饿着肚子走了很远的路。", "target_word": "饿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上我饿了，就煮了一碗面。", "target_word": "饿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不饿，你先吃吧。", "target_word": "饿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟饿了，一直看着桌子上的饭。", "target_word": "饿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "饿了", "label": "了 体标"}, {"form": "饿着", "label": "着 体标"}, {"form": "餓", "label": "繁体"}], "register": "中性", "sense_fingerprint": "肚子空了，想吃东西的感觉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c43aef69-b6a0-4454-8d6b-0589435b9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92901, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "饿", "is_correct": true, "explanation": "饿（è，第四声）：肚子空了，想吃东西，正是本词。"}, {"text": "热", "is_correct": false, "explanation": "热（rè，第四声）比 è 多一个声母 r，意思是热。"}, {"text": "课", "is_correct": false, "explanation": "课（kè，第四声）与 è 声母不同（k 与零声母），意思是课程。"}, {"text": "鹅", "is_correct": false, "explanation": "鹅（é，第二声）与 è 声调不同，意思是鹅。"}, {"text": "哦", "is_correct": false, "explanation": "哦（ò，第四声）与 è 韵母不同（o 与 e），意思是语气词。"}, {"text": "个", "is_correct": false, "explanation": "个（gè，第四声）与 è 声母不同（g 与零声母），是量词。"}], "explanations": {"饿": "饿（è，第四声）：肚子空了，想吃东西，正是本词。", "热": "热（rè，第四声）比 è 多一个声母 r，意思是热。", "课": "课（kè，第四声）与 è 声母不同（k 与零声母），意思是课程。", "鹅": "鹅（é，第二声）与 è 声调不同，意思是鹅。", "哦": "哦（ò，第四声）与 è 韵母不同（o 与 e），意思是语气词。", "个": "个（gè，第四声）与 è 声母不同（g 与零声母），是量词。"}, "sentence_index": null, "correct_answer": "饿"}, "level_3": {"options": [{"text": "饿", "is_correct": true, "explanation": "饿：没吃早饭，所以现在很饿，与“没吃早饭”的语境一致。"}, {"text": "撑", "is_correct": false, "explanation": "语义：“撑”指吃得太多而胀，与“没吃早饭”矛盾。"}, {"text": "烫", "is_correct": false, "explanation": "搭配：“烫”形容食物或水的温度，不用来说人“很烫”。"}, {"text": "满", "is_correct": false, "explanation": "搭配：“满”形容容器或事物装满，不能用来说人的状态“很满”。"}], "explanations": {"饿": "饿：没吃早饭，所以现在很饿，与“没吃早饭”的语境一致。", "撑": "语义：“撑”指吃得太多而胀，与“没吃早饭”矛盾。", "烫": "搭配：“烫”形容食物或水的温度，不用来说人“很烫”。", "满": "搭配：“满”形容容器或事物装满，不能用来说人的状态“很满”。"}, "sentence_index": 0, "correct_answer": "饿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他跑了一下午，饿得一口气喝了三瓶水。", "explanation": "这里应该用〈渴〉。想喝很多水是口渴，“饿”指想吃东西。"}, {"text": "他爬了一下午的山，饿得腿都抬不起来。", "explanation": "这里应该用〈累〉。爬山后腿抬不起来是累，“饿”指肚子空想吃东西，不能这样用。"}, {"text": "吃了好多，肚子都快饿了。", "explanation": "这里应该用〈饱〉。吃得多，肚子应该是“饱”，“饿”指肚子空想吃东西，与句意相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b55e6d1-d065-468e-8962-434097609120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92901, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "饿", "is_correct": true, "explanation": "饿（è，第四声）：肚子空了，想吃东西，正是本词。"}, {"text": "客", "is_correct": false, "explanation": "客（kè，第四声）与 è 声母不同（k 与零声母），意思是客人。"}, {"text": "乐", "is_correct": false, "explanation": "乐（lè，第四声）与 è 声母不同（l 与零声母），意思是快乐。"}, {"text": "额", "is_correct": false, "explanation": "额（é，第二声）与 è 声调不同，意思是额头。"}, {"text": "蛾", "is_correct": false, "explanation": "蛾（é，第二声）与 è 声调不同，意思是蛾子。"}], "explanations": {"饿": "饿（è，第四声）：肚子空了，想吃东西，正是本词。", "客": "客（kè，第四声）与 è 声母不同（k 与零声母），意思是客人。", "乐": "乐（lè，第四声）与 è 声母不同（l 与零声母），意思是快乐。", "额": "额（é，第二声）与 è 声调不同，意思是额头。", "蛾": "蛾（é，第二声）与 è 声调不同，意思是蛾子。"}, "sentence_index": null, "correct_answer": "饿"}, "level_3": {"options": [{"text": "饿", "is_correct": true, "explanation": "饿：他饿着肚子走了很远的路，表示肚子空着，与语境一致。"}, {"text": "咬", "is_correct": false, "explanation": "搭配：〈咬〉不能与〈肚子〉搭配，〈咬着肚子〉说不通。"}, {"text": "笑", "is_correct": false, "explanation": "搭配：“笑”不能和“肚子”搭配，“笑着肚子”说不通。"}, {"text": "烦", "is_correct": false, "explanation": "搭配：“烦”说心情，不能修饰“肚子”，“烦着肚子”说不通。"}], "explanations": {"饿": "饿：他饿着肚子走了很远的路，表示肚子空着，与语境一致。", "咬": "搭配：〈咬〉不能与〈肚子〉搭配，〈咬着肚子〉说不通。", "笑": "搭配：“笑”不能和“肚子”搭配，“笑着肚子”说不通。", "烦": "搭配：“烦”说心情，不能修饰“肚子”，“烦着肚子”说不通。"}, "sentence_index": 6, "correct_answer": "饿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他熬了一夜，饿得眼睛都睁不开。", "explanation": "这里应该用〈困〉。眼睛睁不开是因为困，“饿”指肚子空想吃东西，不能这样用。"}, {"text": "他跑了一个下午，饿得只想喝一杯水。", "explanation": "这里应该用〈渴〉。想喝水是口渴，“饿”指想吃东西，与“喝水”的语境不合。"}, {"text": "吃了满满一桌菜，肚子却快饿了。", "explanation": "这里应该用〈饱〉。吃了很多，肚子应该是“饱”，不应说“饿”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b55e6d1-d065-468e-8962-434097609120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92901, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子放学回家，已经饿直叫。", "corrected_sentence": "孩子放学回家，已经饿得直叫。", "error_description": "错误形式：“饿直叫”；正确形式：“饿得直叫”。表示程度的补语要用“得”连接形容词和后面的补语，“饿”后漏掉了“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b55e6d1-d065-468e-8962-434097609120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92901, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下午了饿，我就去厨房找吃的。", "corrected_sentence": "下午饿了，我就去厨房找吃的。", "error_description": "错误形式：“了饿”；正确形式：“饿了”。“了”表示状态的变化，应放在形容词“饿”之后，不能放在前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b55e6d1-d065-468e-8962-434097609120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92904, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "瘦", "is_correct": true, "explanation": "“瘦”与“肥”是反义词，指身上脂肪少，与本义相反。"}, {"text": "高", "is_correct": false, "explanation": "“高”与“肥”没有反义关系，不能构成对立。"}, {"text": "快", "is_correct": false, "explanation": "“快”与“肥”没有反义关系，不能构成对立。"}, {"text": "亮", "is_correct": false, "explanation": "“亮”与“肥”没有反义关系，不能构成对立。"}], "correct_answer": "瘦", "explanations": {"瘦": "“瘦”与“肥”是反义词，指身上脂肪少，与本义相反。", "高": "“高”与“肥”没有反义关系，不能构成对立。", "快": "“快”与“肥”没有反义关系，不能构成对立。", "亮": "“亮”与“肥”没有反义关系，不能构成对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f13dd8b-44f3-452d-9085-3d547cbca762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
