INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92904, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "（人或动物）脂肪多，与瘦相对。", "primary_collocate": null, "pronunciation": "féi", "ipa": "feɪ̯˧˥", "syllable_count": 1, "sentences": [{"text": "这只猫太肥了，跑不快。", "target_word": "肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农场里的猪养得又肥又大。", "target_word": "肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这头猪吃得太多，变得很肥。", "target_word": "肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那条鱼很肥，一定很好吃。", "target_word": "肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗每天吃很多，现在有点肥。", "target_word": "肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天到了，小鸟都长得肥肥的。", "target_word": "肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说这只兔子太肥，要少吃一点。", "target_word": "肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只狗不肥，只是毛很厚。", "target_word": "肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这头牛又肥又壮，农民很高兴。", "target_word": "肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的猫比我的猫肥多了。", "target_word": "肥", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "肥肥的", "label": "重叠"}, {"form": "肥胖", "label": "复合"}], "register": "中性", "sense_fingerprint": "人或动物脂肪多，与瘦相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f09b97c-38a8-4ff2-bcb2-0a886cdc7162') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92904, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "肥", "is_correct": true, "explanation": "肥（féi，第二声）是本词，指人或动物脂肪多。"}, {"text": "飞", "is_correct": false, "explanation": "fēi（第一声）与 féi（第二声）声调不同，意思是飞翔。"}, {"text": "费", "is_correct": false, "explanation": "fèi（第四声）与 féi（第二声）声调不同，意思是花费。"}, {"text": "匪", "is_correct": false, "explanation": "fěi（第三声）与 féi（第二声）声调不同，意思是土匪。"}, {"text": "肺", "is_correct": false, "explanation": "fèi（第四声）与 féi（第二声）声调不同，意思是肺脏。"}], "explanations": {"肥": "肥（féi，第二声）是本词，指人或动物脂肪多。", "飞": "fēi（第一声）与 féi（第二声）声调不同，意思是飞翔。", "费": "fèi（第四声）与 féi（第二声）声调不同，意思是花费。", "匪": "fěi（第三声）与 féi（第二声）声调不同，意思是土匪。", "肺": "fèi（第四声）与 féi（第二声）声调不同，意思是肺脏。"}, "sentence_index": null, "correct_answer": "肥"}, "level_3": {"options": [{"text": "肥", "is_correct": true, "explanation": "正确。“太肥了”说明身体脂肪多，行动笨重，所以跑不快。"}, {"text": "敏捷", "is_correct": false, "explanation": "语义：“敏捷”指动作灵活快速，与后半句“跑不快”直接矛盾。"}, {"text": "快", "is_correct": false, "explanation": "语义：“太快了”与后半句“跑不快”相互矛盾。"}, {"text": "矫健", "is_correct": false, "explanation": "语义：“矫健”指动作敏捷有力，与“跑不快”矛盾。"}], "explanations": {"肥": "正确。“太肥了”说明身体脂肪多，行动笨重，所以跑不快。", "敏捷": "语义：“敏捷”指动作灵活快速，与后半句“跑不快”直接矛盾。", "快": "语义：“太快了”与后半句“跑不快”相互矛盾。", "矫健": "语义：“矫健”指动作敏捷有力，与“跑不快”矛盾。"}, "sentence_index": 0, "correct_answer": "肥"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本词典很肥，有一千多页。", "explanation": "这里应该用〈厚〉。肥指人或动物脂肪多，形容书的厚薄要用厚。"}, {"text": "这床被子很肥，盖在身上很沉。", "explanation": "这里应该用〈厚〉。肥指身上肉多，形容被子的厚薄要用厚。"}, {"text": "这座楼很肥，一共有三十层。", "explanation": "这里应该用〈高〉。肥指身上肉多，形容楼的高矮要用高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f13dd8b-44f3-452d-9085-3d547cbca762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92904, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "肥", "is_correct": true, "explanation": "肥（féi，第二声）是本词，指人或动物脂肪多。"}, {"text": "废", "is_correct": false, "explanation": "fèi（第四声）与 féi（第二声）声调不同，意思是废弃。"}, {"text": "肺", "is_correct": false, "explanation": "fèi（第四声）与 féi（第二声）声调不同，意思是肺脏。"}, {"text": "飞", "is_correct": false, "explanation": "fēi（第一声）与 féi（第二声）声调不同，意思是飞翔。"}, {"text": "非", "is_correct": false, "explanation": "fēi（第一声）与 féi（第二声）声调不同，意思是不是。"}], "explanations": {"肥": "肥（féi，第二声）是本词，指人或动物脂肪多。", "废": "fèi（第四声）与 féi（第二声）声调不同，意思是废弃。", "肺": "fèi（第四声）与 féi（第二声）声调不同，意思是肺脏。", "飞": "fēi（第一声）与 féi（第二声）声调不同，意思是飞翔。", "非": "fēi（第一声）与 féi（第二声）声调不同，意思是不是。"}, "sentence_index": null, "correct_answer": "肥"}, "level_3": {"options": [{"text": "肥", "is_correct": true, "explanation": "正确。“太肥”说明身上脂肪多，所以医生建议少吃一点。"}, {"text": "瘦", "is_correct": false, "explanation": "语义：“太瘦”与“要少吃一点”的建议矛盾。"}, {"text": "轻", "is_correct": false, "explanation": "语义：“太轻”与“要少吃一点”的建议矛盾。"}, {"text": "苗条", "is_correct": false, "explanation": "体貌：“苗条”形容身材细长，多用于人，且与“要少吃一点”的建议相反。"}], "explanations": {"肥": "正确。“太肥”说明身上脂肪多，所以医生建议少吃一点。", "瘦": "语义：“太瘦”与“要少吃一点”的建议矛盾。", "轻": "语义：“太轻”与“要少吃一点”的建议矛盾。", "苗条": "体貌：“苗条”形容身材细长，多用于人，且与“要少吃一点”的建议相反。"}, "sentence_index": 6, "correct_answer": "肥"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间屋子很肥，住起来很舒服。", "explanation": "这里应该用〈宽敞〉。肥指身上肉多，形容房间的大小要用宽敞。"}, {"text": "这把椅子很肥，坐上去很舒服。", "explanation": "这里应该用〈宽大〉。肥指身上肉多，形容椅子的大小要用宽大。"}, {"text": "这个柜子很肥，放不进房间。", "explanation": "这里应该用〈宽〉。肥指身上肉多，形容柜子的宽窄要用宽。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f13dd8b-44f3-452d-9085-3d547cbca762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92904, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只很肥猫整天都在睡觉。", "corrected_sentence": "那只很肥的猫整天都在睡觉。", "error_description": "“肥”修饰名词“猫”时，前面有“很”要加“的”，应说“很肥的猫”，不说“很肥猫”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f13dd8b-44f3-452d-9085-3d547cbca762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92904, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只小兔子肥很，最喜欢吃胡萝卜。", "corrected_sentence": "那只小兔子很肥，最喜欢吃胡萝卜。", "error_description": "“很”应放在形容词“肥”前作状语，应说“很肥”，不说“肥很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f13dd8b-44f3-452d-9085-3d547cbca762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
