INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92905, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "一同是大家在一起做。", "primary_collocate": null, "pronunciation": "yì tóng", "ipa": "i˥˩ tʰʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "我们一同去公园玩。", "target_word": "一同", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子们一同唱歌。", "target_word": "一同", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他和朋友一同吃了晚饭。", "target_word": "一同", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家一同努力，一定能成功。", "target_word": "一同", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末我和家人一同看电影。", "target_word": "一同", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同学们一同打扫教室。", "target_word": "一同", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爸爸妈妈一同来接我。", "target_word": "一同", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们一同走进了教室。", "target_word": "一同", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想和你一同去北京。", "target_word": "一同", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "两个人一同过了一个快乐的春节。", "target_word": "一同", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一同：副词，放在动词前，表示几个人在一起做同一件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2534af2a-1516-45ed-a22b-20f025827a87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92905, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一同", "is_correct": true, "explanation": "正确。「一同」指几个人一起做同一件事，读 yì tóng。"}, {"text": "一通", "is_correct": false, "explanation": "tóng（第二声）与 tōng（第一声）声调不同，「一通」指一阵或一番，意思与「一同」不符。"}, {"text": "一桶", "is_correct": false, "explanation": "tóng（第二声）与 tǒng（第三声）声调不同，「一桶」指一个桶的量，意思不同。"}, {"text": "一头", "is_correct": false, "explanation": "tóng 与 tóu 韵母不同（-ong 与 -ou），「一头」表示一下子、径直，意思不同。"}], "explanations": {"一同": "正确。「一同」指几个人一起做同一件事，读 yì tóng。", "一通": "tóng（第二声）与 tōng（第一声）声调不同，「一通」指一阵或一番，意思与「一同」不符。", "一桶": "tóng（第二声）与 tǒng（第三声）声调不同，「一桶」指一个桶的量，意思不同。", "一头": "tóng 与 tóu 韵母不同（-ong 与 -ou），「一头」表示一下子、径直，意思不同。"}, "sentence_index": null, "correct_answer": "一同"}, "level_3": {"options": [{"text": "一同", "is_correct": true, "explanation": "正确。「一同」表示几个人一起做，与「我们」相符。"}, {"text": "十分", "is_correct": false, "explanation": "搭配：「十分」修饰形容词，不能直接放在动作动词「去」前。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：「非常」修饰形容词或心理动词，不能修饰「去」这类动作。"}, {"text": "很", "is_correct": false, "explanation": "搭配：「很」修饰形容词，不能直接放在动作动词「去」前。"}], "explanations": {"一同": "正确。「一同」表示几个人一起做，与「我们」相符。", "十分": "搭配：「十分」修饰形容词，不能直接放在动作动词「去」前。", "非常": "搭配：「非常」修饰形容词或心理动词，不能修饰「去」这类动作。", "很": "搭配：「很」修饰形容词，不能直接放在动作动词「去」前。"}, "sentence_index": 0, "correct_answer": "一同"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一个人一同吃了一桌菜。", "explanation": "这里应该用「自己」。「一同」指几个人一起做，与「一个人」矛盾，应说「他自己吃了一桌菜」。"}, {"text": "我一同去了一趟图书馆。", "explanation": "这里应该用「单独」。「一同」要求几个人一起做，主语只有「我」一人时不能用，应说「我单独去了一趟图书馆」。"}, {"text": "那位老人一同住在山里，身边只有他一个人。", "explanation": "这里应该用「独自」。「一同」指几个人一起，与「只有他一个人」矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ded08da-eef4-42ea-a58b-074c223c2b8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92905, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一同", "is_correct": true, "explanation": "正确。「一同」表示几个人一起来接我，与「爸爸妈妈」相符。"}, {"text": "更", "is_correct": false, "explanation": "搭配：「更」表示程度的加深，不能直接修饰「来接我」这样的动作。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：「非常」修饰形容词或心理动词，不能直接放在「来接我」这样的动作前。"}, {"text": "亲手", "is_correct": false, "explanation": "搭配：「亲手」强调用手做，不能修饰「来接我」这样的移动动作。"}], "explanations": {"一同": "正确。「一同」表示几个人一起来接我，与「爸爸妈妈」相符。", "更": "搭配：「更」表示程度的加深，不能直接修饰「来接我」这样的动作。", "非常": "搭配：「非常」修饰形容词或心理动词，不能直接放在「来接我」这样的动作前。", "亲手": "搭配：「亲手」强调用手做，不能修饰「来接我」这样的移动动作。"}, "sentence_index": 6, "correct_answer": "一同"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们一同分别回了家。", "explanation": "这里应该用「各自」。「一同」表示共同做，与「分别」矛盾。"}, {"text": "孩子们一同各自写作业。", "explanation": "这里应该用「分别」。「一同」指共同做，与「各自」矛盾。"}, {"text": "我们俩一同分开坐，各占一张桌子。", "explanation": "这里应该用「分别」。「一同」指共同做，与「分开坐」矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ded08da-eef4-42ea-a58b-074c223c2b8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92905, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们一同一起去图书馆看书。", "corrected_sentence": "我们一同去图书馆看书。", "error_description": "错误在于「一同」和「一起」意思相同，句中叠用了。应只用其一，正确说法是「我们一同去图书馆看书」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ded08da-eef4-42ea-a58b-074c223c2b8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92905, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们一同了吃午饭。", "corrected_sentence": "我们一同吃午饭。", "error_description": "错误在于「了」放在了「一同」后面。「一同」是副词，后面不能直接加「了」，「了」应放在动词之后，正确说法是「我们一同吃午饭」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ded08da-eef4-42ea-a58b-074c223c2b8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
