INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92908, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "原子、分子等微观系统所具有的不连续的能量状态。", "primary_collocate": null, "pronunciation": "néng jí", "ipa": "nɤŋ˧˥ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "原子的能级不是连续的。", "target_word": "能级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电子从高能级跳到低能级，会放出光。", "target_word": "能级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "氢原子的能级最简单。", "target_word": "能级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分子也有自己的能级。", "target_word": "能级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师讲了原子的能级是怎么来的。", "target_word": "能级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "光的颜色和原子能级有关。", "target_word": "能级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电子吸收能量，就会进入更高的能级。", "target_word": "能级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张图画的是氢原子的几个能级。", "target_word": "能级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同的原子，能级也不一样。", "target_word": "能级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家一直在研究分子的能级。", "target_word": "能级", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个能级", "label": "量词（个）"}, {"form": "能級", "label": "繁体"}], "register": "书面", "sense_fingerprint": "原子分子的不连续能量状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f25efb-a327-4991-90ce-e83d14deee0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92908, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "成绩", "is_correct": false, "explanation": "语义：成绩指学业评价，不能用来描述原子的能量状态。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“味道”不用于描述原子这类微观粒子。"}, {"text": "能级", "is_correct": true, "explanation": "正确：原子的能量状态是不连续的，用“能级”。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情不属于原子，句子说的是原子的能量状态。"}], "explanations": {"成绩": "语义：成绩指学业评价，不能用来描述原子的能量状态。", "味道": "搭配：“味道”不用于描述原子这类微观粒子。", "能级": "正确：原子的能量状态是不连续的，用“能级”。", "心情": "语义：心情不属于原子，句子说的是原子的能量状态。"}, "sentence_index": 0, "correct_answer": "能级"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家商店的能级很多。", "explanation": "这里应该用〈种类〉。能级指原子、分子等微观系统的能量状态，商店的货品多少要说种类。"}, {"text": "他每天早上都要喝一杯能级。", "explanation": "这里应该用〈咖啡〉。能级指原子、分子等微观系统的能量状态，不是可以喝的东西。"}, {"text": "这台电机的能级很高。", "explanation": "这里应该用〈功率〉。能级指原子等微观系统的能量状态，机器的输出能力要用功率。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f1ba74c-3a11-4bcb-904b-2e1ea4ec7fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92908, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "房间", "is_correct": false, "explanation": "语义：电子不会进入房间，句子说的是能量状态的变化。"}, {"text": "体积", "is_correct": false, "explanation": "搭配：“进入更高的”不搭配“体积”。"}, {"text": "能级", "is_correct": true, "explanation": "正确：电子吸收能量后进入更高的能量状态，用“能级”。"}, {"text": "年级", "is_correct": false, "explanation": "语义：年级指学生的班次，不能指电子的能量状态。"}], "explanations": {"房间": "语义：电子不会进入房间，句子说的是能量状态的变化。", "体积": "搭配：“进入更高的”不搭配“体积”。", "能级": "正确：电子吸收能量后进入更高的能量状态，用“能级”。", "年级": "语义：年级指学生的班次，不能指电子的能量状态。"}, "sentence_index": 6, "correct_answer": "能级"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "科学家一直在研究地形的能级。", "explanation": "这里应该用〈梯度〉。能级指微观系统的能量状态，地形的变化幅度要用梯度。"}, {"text": "这台电脑的能级很多。", "explanation": "这里应该用〈功能〉。能级指原子、分子等微观系统的能量状态，电脑能做的事要用功能。"}, {"text": "他的能级很强。", "explanation": "这里应该用〈能力〉。能级指微观系统的能量状态，人的本领要用能力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f1ba74c-3a11-4bcb-904b-2e1ea4ec7fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92908, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "原子的一只能级比另一个低。", "corrected_sentence": "原子的一个能级比另一个低。", "error_description": "量词错误：“能级”应该用量词“个”，写成“一只能级”不对，“只”多用于动物等。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f1ba74c-3a11-4bcb-904b-2e1ea4ec7fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92908, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "书上画出了钠原子的三位能级。", "corrected_sentence": "书上画出了钠原子的三个能级。", "error_description": "量词错误：“能级”应该用量词“个”，“位”用于人，不能说“三位能级”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f1ba74c-3a11-4bcb-904b-2e1ea4ec7fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
