INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92911, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "草原是一大片平平的、长满草的地方。", "primary_collocate": null, "pronunciation": "cǎo yuán", "ipa": "tsʰɑʊ˨˩ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "我想去草原看羊和马。", "target_word": "草原", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "草原很大，一眼看不到头。", "target_word": "草原", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "草原上没有高楼，只有草和天。", "target_word": "草原", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在草原上玩得很开心。", "target_word": "草原", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "秋天，草原慢慢变黄了。", "target_word": "草原", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们在草原上搭了一顶帐篷。", "target_word": "草原", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里是一片草原，不是沙漠。", "target_word": "草原", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "草原上晚上能看见很多星星。", "target_word": "草原", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我第一次去草原，就爱上了那里。", "target_word": "草原", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨以后，草原闻起来很香。", "target_word": "草原", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "片", "label": "量词"}, {"form": "大草原", "label": "复合"}], "register": "中性", "sense_fingerprint": "一大片平坦、长满青草的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83b79118-3afa-43a8-854c-cfbbc5147759') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92911, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "教室", "is_correct": false, "explanation": "语义：教室里不会有羊和马，“去教室看羊和马”不合常理"}, {"text": "草原", "is_correct": true, "explanation": "草原：长满草、可以放牧的大片地方，“去草原看羊和马”符合常理"}, {"text": "银行", "is_correct": false, "explanation": "语义：银行与羊和马无关，句子说不通"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋里没有可以放牧的羊和马，“去海洋看羊和马”不合常理。"}], "explanations": {"教室": "语义：教室里不会有羊和马，“去教室看羊和马”不合常理", "草原": "草原：长满草、可以放牧的大片地方，“去草原看羊和马”符合常理", "银行": "语义：银行与羊和马无关，句子说不通", "海洋": "语义：海洋里没有可以放牧的羊和马，“去海洋看羊和马”不合常理。"}, "sentence_index": 0, "correct_answer": "草原"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在草原上用海边的细沙堆了一座城堡，海浪一来就冲倒了。", "explanation": "这里应该用〈沙滩〉。海浪和细沙在海边，草原是长满草的陆地，没有海浪。"}, {"text": "草原上飘着几只小船。", "explanation": "这里应该用〈湖面〉。小船要在水上，草原是陆地，不能飘着小船"}, {"text": "我们在草原上的写字楼里开会。", "explanation": "这里应该用〈城市〉。写字楼是城市里的建筑，草原上不会有写字楼"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f64cdb5-3745-42f4-ba36-e5a3b1258b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92911, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "厨房", "is_correct": false, "explanation": "量词：“一片”修饰大片地域，不说“一片厨房”，句子说不通。"}, {"text": "卧室", "is_correct": false, "explanation": "量词：“一片”修饰大片地域，不说“一片卧室”，句子说不通。"}, {"text": "草原", "is_correct": true, "explanation": "草原：长满草的大片地域，与“不是沙漠”形成对比，句意成立"}, {"text": "医院", "is_correct": false, "explanation": "搭配：“一片”修饰大片地域，不说“一片医院”"}], "explanations": {"厨房": "量词：“一片”修饰大片地域，不说“一片厨房”，句子说不通。", "卧室": "量词：“一片”修饰大片地域，不说“一片卧室”，句子说不通。", "草原": "草原：长满草的大片地域，与“不是沙漠”形成对比，句意成立", "医院": "搭配：“一片”修饰大片地域，不说“一片医院”"}, "sentence_index": 6, "correct_answer": "草原"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这片草原里的稻子快要成熟了。", "explanation": "这里应该用〈农田〉。稻子是人种的，草原是天然长满草的地方"}, {"text": "这片草原一望无际，蓝得很深。", "explanation": "这里应该用〈海洋〉。“蓝得很深”描述的是海水，草原不会这样"}, {"text": "这片草原上铺着光滑的大理石，被雨水冲得发亮。", "explanation": "这里应该用〈广场〉。大理石铺在城市的硬地面上，草原是天然长满草的地方"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f64cdb5-3745-42f4-ba36-e5a3b1258b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92911, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一只很大的草原。", "corrected_sentence": "这是一片很大的草原。", "error_description": "量词错误：“只”用于动物，草原是大片地域，应说“一片很大的草原”，不说“一只很大的草原”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f64cdb5-3745-42f4-ba36-e5a3b1258b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92911, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我去过一颗草原，那里的草很香。", "corrected_sentence": "我去过一片草原，那里的草很香。", "error_description": "量词错误：“颗”用于圆而小的东西，草原是大片地域，应用“片”，不说“一颗草原”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f64cdb5-3745-42f4-ba36-e5a3b1258b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
