INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92912, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "地势平坦、以草本植物为主的广阔地带。", "primary_collocate": null, "pronunciation": "cǎo yuán", "ipa": "tsʰɑʊ˨˩ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "内蒙古有一片很大的草原。", "target_word": "草原", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "草原上有很多牛和羊。", "target_word": "草原", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "夏天的草原又绿又美。", "target_word": "草原", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们坐车穿过了一片草原。", "target_word": "草原", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蒙古族人世世代代生活在草原上。", "target_word": "草原", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这片草原一直延伸到远处的山脚。", "target_word": "草原", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "草原上的气候变化很快。", "target_word": "草原", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他骑着马在草原上跑。", "target_word": "草原", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "草原的风很大，也很干净。", "target_word": "草原", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "保护草原需要大家一起努力。", "target_word": "草原", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "片", "label": "量词"}, {"form": "大草原", "label": "复合"}], "register": "中性", "sense_fingerprint": "地势平坦、草本植物为主的广阔自然地带", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83b79118-3afa-43a8-854c-cfbbc5147759') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92912, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "海洋", "is_correct": false, "explanation": "语义：内蒙古是内陆地区，没有海洋，“一片很大的海洋”与句中地名矛盾"}, {"text": "草原", "is_correct": true, "explanation": "草原：以草本植物为主的广阔地带。内蒙古以草原闻名，“一片很大的草原”自然"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是室内房间，不是可以用“一片很大的”形容的地域"}, {"text": "图书馆", "is_correct": false, "explanation": "搭配：量词“一片”多用于大面积的地面或水面，不说“一片图书馆”"}], "explanations": {"海洋": "语义：内蒙古是内陆地区，没有海洋，“一片很大的海洋”与句中地名矛盾", "草原": "草原：以草本植物为主的广阔地带。内蒙古以草原闻名，“一片很大的草原”自然", "厨房": "语义：厨房是室内房间，不是可以用“一片很大的”形容的地域", "图书馆": "搭配：量词“一片”多用于大面积的地面或水面，不说“一片图书馆”"}, "sentence_index": 0, "correct_answer": "草原"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公园里的草原修得很整齐。", "explanation": "这里应该用〈草坪〉。草原是广阔的自然地带，不经修剪；修剪整齐的小片草地要用草坪"}, {"text": "草原上漂着一艘大船，船上挂着白帆。", "explanation": "这里应该用〈湖泊〉。船要在水面上漂，草原是陆地上长满草的地方，不能漂着大船"}, {"text": "我们在草原上游了一会儿泳，水很凉。", "explanation": "这里应该用〈游泳池〉。游泳要在水里，草原是陆地上长满草的地方，不能在上面游泳"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f64cdb5-3745-42f4-ba36-e5a3b1258b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92912, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "教室", "is_correct": false, "explanation": "语义：“上的气候”指大片地域的天气，教室是室内空间，句子说不通。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“上的气候”指大片地域的天气，手机不能与“气候”搭配"}, {"text": "草原", "is_correct": true, "explanation": "草原：地处广阔地带，天气和气候受地形、季节影响大，“草原上的气候变化很快”自然"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是随身物件，不存在“气候”的问题"}], "explanations": {"教室": "语义：“上的气候”指大片地域的天气，教室是室内空间，句子说不通。", "手机": "搭配：“上的气候”指大片地域的天气，手机不能与“气候”搭配", "草原": "草原：地处广阔地带，天气和气候受地形、季节影响大，“草原上的气候变化很快”自然", "书包": "语义：书包是随身物件，不存在“气候”的问题"}, "sentence_index": 6, "correct_answer": "草原"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "秋天的草原上长满了金黄的小麦。", "explanation": "这里应该用〈农田〉。小麦是人工种植的作物，草原是天然长满草本植物的地带"}, {"text": "这片草原里树木参天，几乎遮住了阳光。", "explanation": "这里应该用〈森林〉。草原以草本植物为主，树木参天、遮住阳光的是森林"}, {"text": "这片草原上，鱼群游来游去，海鸥在头顶盘旋。", "explanation": "这里应该用〈大海〉。鱼群游动、海鸥盘旋的是海洋，草原是陆地上长满草的地方"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f64cdb5-3745-42f4-ba36-e5a3b1258b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92912, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我今天去了一颗草原。", "corrected_sentence": "我今天去了一片草原。", "error_description": "量词错误：“颗”用于圆而小的东西，草原是大片地域，应用“片”，不说“一颗草原”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f64cdb5-3745-42f4-ba36-e5a3b1258b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92912, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们草原上露营，风很大。", "corrected_sentence": "我们在草原上露营，风很大。", "error_description": "介词错误：表示地点的“草原上”前要加“在”，应说“我们在草原上露营”，不能省略“在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f64cdb5-3745-42f4-ba36-e5a3b1258b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
