INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92913, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "书面语助词，用在形容词后，表示程度达到极点。", "primary_collocate": null, "pronunciation": "zhī zhì", "ipa": "ʈʂɻ̩˥ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "见到您，我高兴之至。", "target_word": "之至", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这次旅行辛苦之至，大家都累坏了。", "target_word": "之至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "收到您的礼物，我感动之至。", "target_word": "之至", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他对我的态度冷淡之至。", "target_word": "之至", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事麻烦之至，我不想再管了。", "target_word": "之至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的风景美丽之至。", "target_word": "之至", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房间里脏乱之至，没法住人。", "target_word": "之至", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "得知他平安回来，全家欣慰之至。", "target_word": "之至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样的天气出门，实在是难受之至。", "target_word": "之至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "您能来参加，我们光荣之至。", "target_word": "之至", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "放在形容词后面，表示非常非常，语气正式，多用于表达感受", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c651e1d1-7d7e-4bf6-8590-9fbd5db22afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92913, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "之至", "is_correct": true, "explanation": "之至（zhī zhì）是书面语助词，附在形容词后面，表示程度达到极点。这是本题的正确答案。"}, {"text": "直至", "is_correct": false, "explanation": "zhí（第二声）与 zhī（第一声）声调不同，直至的意思是一直到某个时间或地点。"}, {"text": "资质", "is_correct": false, "explanation": "zī 与 zhī 声母不同（z 与 zh），资质的意思是天资或素质。"}, {"text": "制止", "is_correct": false, "explanation": "制止读 zhì zhǐ，与 zhī zhì 音节相同、声调不同；制止的意思是强力阻止。"}, {"text": "芝士", "is_correct": false, "explanation": "shì 与 zhì 声母不同（sh 与 zh），芝士的意思是奶酪。"}], "explanations": {"之至": "之至（zhī zhì）是书面语助词，附在形容词后面，表示程度达到极点。这是本题的正确答案。", "直至": "zhí（第二声）与 zhī（第一声）声调不同，直至的意思是一直到某个时间或地点。", "资质": "zī 与 zhī 声母不同（z 与 zh），资质的意思是天资或素质。", "制止": "制止读 zhì zhǐ，与 zhī zhì 音节相同、声调不同；制止的意思是强力阻止。", "芝士": "shì 与 zhì 声母不同（sh 与 zh），芝士的意思是奶酪。"}, "sentence_index": null, "correct_answer": "之至"}, "level_3": {"options": [{"text": "的", "is_correct": false, "explanation": "语义：“的”标示定语，后面没有中心名词，“高兴的”句末不成立，表达不了程度。"}, {"text": "之至", "is_correct": true, "explanation": "“之至”附在“高兴”后面，表示程度达到极点，与句意相合。"}, {"text": "地", "is_correct": false, "explanation": "配价：“地”引出修饰动词的状语，“高兴地”后面没有动词，句子不成立。"}, {"text": "得", "is_correct": false, "explanation": "搭配：“得”引出补语，“高兴得”后面要接程度或结果，句末不成立。"}], "explanations": {"的": "语义：“的”标示定语，后面没有中心名词，“高兴的”句末不成立，表达不了程度。", "之至": "“之至”附在“高兴”后面，表示程度达到极点，与句意相合。", "地": "配价：“地”引出修饰动词的状语，“高兴地”后面没有动词，句子不成立。", "得": "搭配：“得”引出补语，“高兴得”后面要接程度或结果，句末不成立。"}, "sentence_index": 0, "correct_answer": "之至"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部电影有点好看之至。", "explanation": "“之至”表示程度达到极点，与“有点”所表示的轻微程度互相矛盾，不能这样搭配。"}, {"text": "他一点儿也不着急之至。", "explanation": "“之至”表示程度达到极点，与“一点儿也不”的否定程度互相矛盾，这里不能用。"}, {"text": "这个房间非常干净之至。", "explanation": "“之至”本身已表示程度达到极点，前面再加“非常”就重复了，应说“干净之至”或“非常干净”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e94bd45b-59e6-43ab-9dab-bfdfda6bf16a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
