INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92914, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "之至", "is_correct": true, "explanation": "之至（zhī zhì）是书面语助词，附在形容词后面，表示程度达到极点。这是本题的正确答案。"}, {"text": "直至", "is_correct": false, "explanation": "zhí（第二声）与 zhī（第一声）声调不同，直至的意思是一直到某个时间或地点。"}, {"text": "资质", "is_correct": false, "explanation": "zī 与 zhī 声母不同（z 与 zh），资质的意思是天资或素质。"}, {"text": "机制", "is_correct": false, "explanation": "jī 与 zhī 声母不同（j 与 zh），机制的意思是事物内部的工作方式。"}, {"text": "芝士", "is_correct": false, "explanation": "shì 与 zhì 声母不同（sh 与 zh），芝士的意思是奶酪。"}], "explanations": {"之至": "之至（zhī zhì）是书面语助词，附在形容词后面，表示程度达到极点。这是本题的正确答案。", "直至": "zhí（第二声）与 zhī（第一声）声调不同，直至的意思是一直到某个时间或地点。", "资质": "zī 与 zhī 声母不同（z 与 zh），资质的意思是天资或素质。", "机制": "jī 与 zhī 声母不同（j 与 zh），机制的意思是事物内部的工作方式。", "芝士": "shì 与 zhì 声母不同（sh 与 zh），芝士的意思是奶酪。"}, "sentence_index": null, "correct_answer": "之至"}, "level_3": {"options": [{"text": "地", "is_correct": false, "explanation": "配价：“地”引出修饰动词的状语，“荣幸地”后面没有动词，句子不成立。"}, {"text": "之至", "is_correct": true, "explanation": "“之至”附在“荣幸”后面，表示程度达到极点，与句意相合。"}, {"text": "过", "is_correct": false, "explanation": "体貌：“过”表示曾经经历，“荣幸过”不能表示此刻的心情程度。"}, {"text": "的", "is_correct": false, "explanation": "语义：“的”标示定语，后面没有中心名词，“荣幸的”句末不成立。"}], "explanations": {"地": "配价：“地”引出修饰动词的状语，“荣幸地”后面没有动词，句子不成立。", "之至": "“之至”附在“荣幸”后面，表示程度达到极点，与句意相合。", "过": "体貌：“过”表示曾经经历，“荣幸过”不能表示此刻的心情程度。", "的": "语义：“的”标示定语，后面没有中心名词，“荣幸的”句末不成立。"}, "sentence_index": 0, "correct_answer": "之至"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个题有点难之至。", "explanation": "“之至”表示程度达到极点，与“有点”所表示的轻微程度互相矛盾，不能这样搭配。"}, {"text": "我一点儿也不害怕之至。", "explanation": "“之至”表示感受达到极点，与“一点儿也不”的否定程度互相矛盾，这里不能用。"}, {"text": "这朵花红之至。", "explanation": "“之至”只接表示感受或评价的形容词，“红”描述颜色，不能用“之至”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e94bd45b-59e6-43ab-9dab-bfdfda6bf16a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92914, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "之至", "is_correct": true, "explanation": "之至（zhī zhì）是书面语助词，附在形容词后面，表示程度达到极点。这是本题的正确答案。"}, {"text": "低至", "is_correct": false, "explanation": "dī 与 zhī 声母不同（d 与 zh），低至的意思是低到某个程度，如“低至五折”。"}, {"text": "机智", "is_correct": false, "explanation": "jī 与 zhī 声母不同（j 与 zh），机智的意思是反应快、善于应变。"}, {"text": "失智", "is_correct": false, "explanation": "shī 与 zhī 声母不同（sh 与 zh），失智指记忆、判断等智力功能下降。"}, {"text": "基质", "is_correct": false, "explanation": "jī 与 zhī 声母不同（j 与 zh），基质指某些物质赖以存在或发生作用的基础物质。"}], "explanations": {"之至": "之至（zhī zhì）是书面语助词，附在形容词后面，表示程度达到极点。这是本题的正确答案。", "低至": "dī 与 zhī 声母不同（d 与 zh），低至的意思是低到某个程度，如“低至五折”。", "机智": "jī 与 zhī 声母不同（j 与 zh），机智的意思是反应快、善于应变。", "失智": "shī 与 zhī 声母不同（sh 与 zh），失智指记忆、判断等智力功能下降。", "基质": "jī 与 zhī 声母不同（j 与 zh），基质指某些物质赖以存在或发生作用的基础物质。"}, "sentence_index": null, "correct_answer": "之至"}, "level_3": {"options": [{"text": "地", "is_correct": false, "explanation": "配价：“地”引出修饰动词的状语，“兴奋地”后面没有动词，句子不成立。"}, {"text": "之至", "is_correct": true, "explanation": "“之至”附在“兴奋”后面，表示程度达到极点，与句意相合。"}, {"text": "得", "is_correct": false, "explanation": "搭配：“得”后面要接补语，“兴奋得”单独出现时句子不完整。"}, {"text": "吗", "is_correct": false, "explanation": "语义：“吗”表示疑问，这句是陈述，不能用在句末表示程度。"}], "explanations": {"地": "配价：“地”引出修饰动词的状语，“兴奋地”后面没有动词，句子不成立。", "之至": "“之至”附在“兴奋”后面，表示程度达到极点，与句意相合。", "得": "搭配：“得”后面要接补语，“兴奋得”单独出现时句子不完整。", "吗": "语义：“吗”表示疑问，这句是陈述，不能用在句末表示程度。"}, "sentence_index": 6, "correct_answer": "之至"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部电影比上一部更无聊之至。", "explanation": "“之至”表示程度达到极点，与“比……更”的比较义互相矛盾，这里不能这样用。"}, {"text": "这首歌比那首更好听之至。", "explanation": "“之至”已表示程度达到极点，与“比……更”的比较义重复冲突，这里不能用。"}, {"text": "这条路长之至。", "explanation": "“之至”只接表示感受或评价的形容词，“长”描述长度，不能用“之至”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e94bd45b-59e6-43ab-9dab-bfdfda6bf16a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92914, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他居然没来，我惊讶的之至。", "corrected_sentence": "他居然没来，我惊讶之至。", "error_description": "多余的“的”：“之至”是书面语助词，直接附在形容词后面，前面不能加“的”，应说“惊讶之至”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e94bd45b-59e6-43ab-9dab-bfdfda6bf16a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92914, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一直没有消息，我担心了之至。", "corrected_sentence": "他一直没有消息，我担心之至。", "error_description": "多余的“了”：“之至”已表示程度达到极点，“担心了之至”中间的“了”要去掉，应说“担心之至”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e94bd45b-59e6-43ab-9dab-bfdfda6bf16a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
