INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92917, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "尽量是用全部的力气，做到最多。", "primary_collocate": null, "pronunciation": "jìn liàng", "ipa": "tɕin˥˩ ljaŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这里的菜随便点，大家尽量吃。", "target_word": "尽量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别客气，想喝多少就尽量喝。", "target_word": "尽量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水果很多，你们尽量拿，不要不好意思。", "target_word": "尽量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天我请客，你尽量点，不用省钱。", "target_word": "尽量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "米饭管够，饿了的人可以尽量盛。", "target_word": "尽量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些书都是新的，同学们尽量借吧。", "target_word": "尽量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "饺子包了很多，孩子们尽量吃，吃饱为止。", "target_word": "尽量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "难得来一次，你就尽量买吧。", "target_word": "尽量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "主人说，菜不够再做，客人尽量吃。", "target_word": "尽量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "钱都在这儿了，你想买什么就尽量买，别省着。", "target_word": "尽量", "complexity_tier": "T3", "furigana": "jìn liàng", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "副词：放开量，做到自己能承受的最多，常说尽量吃、尽量喝，读jìnliàng", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37389423-afce-42fb-8c84-9ff544ce5cc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92917, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "尽量", "is_correct": true, "explanation": "正确：「尽量」表示放开来做到最多，与「菜随便点，大家……吃」的语境相符。"}, {"text": "竟然", "is_correct": false, "explanation": "语义：「竟然」表示出乎意料，与「菜随便点」的平常语境不合。"}, {"text": "已经", "is_correct": false, "explanation": "体貌：「已经」表示动作已完成，与鼓励大家吃的未发生动作不符。"}, {"text": "幸亏", "is_correct": false, "explanation": "语义：「幸亏」表示庆幸于有利的结果，与此处鼓励大家多吃的语境不合。"}], "explanations": {"尽量": "正确：「尽量」表示放开来做到最多，与「菜随便点，大家……吃」的语境相符。", "竟然": "语义：「竟然」表示出乎意料，与「菜随便点」的平常语境不合。", "已经": "体貌：「已经」表示动作已完成，与鼓励大家吃的未发生动作不符。", "幸亏": "语义：「幸亏」表示庆幸于有利的结果，与此处鼓励大家多吃的语境不合。"}, "sentence_index": 0, "correct_answer": "尽量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明天的雪尽量下得大一点。", "explanation": "这里应该用〈希望〉。「尽量」只修饰人能尽力做到的事，下雪不能靠努力决定；表示期盼要用「希望」。"}, {"text": "今年的雨水尽量多，所以庄稼长得好。", "explanation": "这里应该用〈很〉。「雨水很多」只说数量；「尽量」只表示人尽力做到最多，不能用来形容雨水的多少。"}, {"text": "这张桌子尽量大，大家都能坐下。", "explanation": "这里应该用〈挺〉。「挺大」用于描述事物的大小；「尽量」只修饰人能尽力去做的事，不能用来形容桌子的性质。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab211b87-ba01-4b87-ab29-4a9296f4379a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92917, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "尽量", "is_correct": true, "explanation": "正确：「尽量」表示放开来做到最多，与「饺子包了很多，孩子们……吃」的语境相符。"}, {"text": "曾经", "is_correct": false, "explanation": "体貌：「曾经」表示过去有过的经历，与「过年了」这一当下的状况不合。"}, {"text": "果然", "is_correct": false, "explanation": "语义：「果然」表示与预期相符，此处没有任何预期，句意不通。"}, {"text": "千万", "is_correct": false, "explanation": "搭配：「千万」多用于叮嘱或禁止，不能直接修饰「玩」。"}], "explanations": {"尽量": "正确：「尽量」表示放开来做到最多，与「饺子包了很多，孩子们……吃」的语境相符。", "曾经": "体貌：「曾经」表示过去有过的经历，与「过年了」这一当下的状况不合。", "果然": "语义：「果然」表示与预期相符，此处没有任何预期，句意不通。", "千万": "搭配：「千万」多用于叮嘱或禁止，不能直接修饰「玩」。"}, "sentence_index": 6, "correct_answer": "尽量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这里的风景尽量美，大家都爱来。", "explanation": "这里应该用〈很〉。「很美」描述风景的性质；「尽量」只修饰人能放开去做的动作，不能用来形容风景。"}, {"text": "他尽量在去年就毕业了。", "explanation": "这里应该用〈早就〉。「早就」表示很久以前已经发生；「尽量」表示尽力去做，不能用于已经过去的时间。"}, {"text": "天快黑了，我们尽量回家吧。", "explanation": "这里应该用〈赶紧〉。「赶紧」表示催促快点行动，「尽量」没有这个意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab211b87-ba01-4b87-ab29-4a9296f4379a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92917, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今天家里来了客人，大家尽量很吃。", "corrected_sentence": "今天家里来了客人，大家尽量吃。", "error_description": "「尽量」是副词，后面应直接跟动词「吃」。「很」不能修饰动作动词「吃」，不能插在「尽量」和「吃」之间。去掉「很」就对了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab211b87-ba01-4b87-ab29-4a9296f4379a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92917, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "饭菜还很多，你们尽量了吃吧。", "corrected_sentence": "饭菜还很多，你们尽量吃吧。", "error_description": "「了」不能直接放在副词「尽量」后面，它应该放在动词之后。这里「了」被放在「尽量」后面，体标位置错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab211b87-ba01-4b87-ab29-4a9296f4379a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
