INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92921, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "其余是剩下的那些。", "primary_collocate": null, "pronunciation": "qí yú", "ipa": "tɕʰi˧˥ y˧˥", "syllable_count": 2, "sentences": [{"text": "先做重要的事，其余的以后再说。", "target_word": "其余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "班里十个人考了满分，其余的人也都及格了。", "target_word": "其余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们两个人先走，其余的同事晚点到。", "target_word": "其余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服太贵，其余的都比较便宜。", "target_word": "其余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿了一个红包，其余的送给朋友了。", "target_word": "其余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上有五个杯子，其余的在厨房里。", "target_word": "其余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前两天我很忙，其余的几天都在休息。", "target_word": "其余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你只要带护照，其余的东西我来准备。", "target_word": "其余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的鱼很有名，其余的菜也不错。", "target_word": "其余", "complexity_tier": "T3", "furigana": "Zhè jiā diàn de yú hěn yǒumíng, qíyú de cài yě bú cuò.", "sentence_source": "generated"}, {"text": "老师表扬了小明，其余同学都很高兴。", "target_word": "其余", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "其余：代词，指除了已说的以外剩下的那些", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0802c43-0ce8-40f0-87ca-f93fb1d9c662') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92921, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "其余", "is_correct": true, "explanation": "其余指除重要的事以外剩下的事，与“先做重要的事”吻合。"}, {"text": "所有", "is_correct": false, "explanation": "语义：“所有”包括重要的事在内，与“先做重要的事”前后矛盾。"}, {"text": "全部", "is_correct": false, "explanation": "语义：“全部”也包括重要的事，与“先做重要的事”冲突。"}, {"text": "其中", "is_correct": false, "explanation": "搭配：“其中”需指已提到范围之内的部分，这里指重要的事之外的事，不搭。"}], "explanations": {"其余": "其余指除重要的事以外剩下的事，与“先做重要的事”吻合。", "所有": "语义：“所有”包括重要的事在内，与“先做重要的事”前后矛盾。", "全部": "语义：“全部”也包括重要的事，与“先做重要的事”冲突。", "其中": "搭配：“其中”需指已提到范围之内的部分，这里指重要的事之外的事，不搭。"}, "sentence_index": 0, "correct_answer": "其余"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这些城市我全部去过了，其余的还没去。", "explanation": "前文说城市“全部去过”，已没有剩下的城市，“其余的还没去”与之矛盾。"}, {"text": "他把衣服全部穿上了，其余的还放在衣柜里。", "explanation": "前文说衣服“全部穿上”，衣柜里没有剩下的衣服，“其余的还放在衣柜里”与之矛盾。"}, {"text": "这笔补贴我已经全部领完，其余的还没到账。", "explanation": "前文说补贴已“全部领完”，就没有剩下的补贴，“其余的还没到账”与之矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7ca5229-d3bd-448b-a0d1-9cae56a6a3cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92921, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "其余", "is_correct": true, "explanation": "其余指前两天之外剩下的几天，与“前两天我很忙”吻合。"}, {"text": "整个", "is_correct": false, "explanation": "语义：“整个”包括前两天在内，与“前两天我很忙”冲突。"}, {"text": "前面", "is_correct": false, "explanation": "语义：“前面的几天”就是前两天，与“前两天我很忙”重复且矛盾。"}, {"text": "一半", "is_correct": false, "explanation": "搭配：“一半”是比例词，不能直接修饰“几天”。"}], "explanations": {"其余": "其余指前两天之外剩下的几天，与“前两天我很忙”吻合。", "整个": "语义：“整个”包括前两天在内，与“前两天我很忙”冲突。", "前面": "语义：“前面的几天”就是前两天，与“前两天我很忙”重复且矛盾。", "一半": "搭配：“一半”是比例词，不能直接修饰“几天”。"}, "sentence_index": 6, "correct_answer": "其余"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他只有一个女儿，其余的女儿都在国外。", "explanation": "前文说“只有一个女儿”，就没有剩下的女儿，“其余的女儿都在国外”与之矛盾。"}, {"text": "他是班里唯一的女生，其余的女生都很活泼。", "explanation": "这里不能说“剩下的女生”。前文说“唯一”，班里没有别的女生，不存在剩下的女生。"}, {"text": "这箱橘子我全部吃完了，其余的还在桌上。", "explanation": "前文说橘子已“全部吃完”，就没有剩下的橘子，“其余的还在桌上”与之矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7ca5229-d3bd-448b-a0d1-9cae56a6a3cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92921, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个班有十个学生，其余地同学都在操场上。", "corrected_sentence": "这个班有十个学生，其余的同学都在操场上。", "error_description": "错误在“其余”后的结构助词。“其余”修饰名词时常加“的”，写成“其余的同学”；这里用“地”不对，“地”只用于修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7ca5229-d3bd-448b-a0d1-9cae56a6a3cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92921, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们吃完饭，其余地碗明天洗。", "corrected_sentence": "我们吃完饭，其余的碗明天洗。", "error_description": "错误在“其余”后的结构助词。“其余”修饰名词时常加“的”，写成“其余的碗”；这里用“地”不对，“地”只用于修饰动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7ca5229-d3bd-448b-a0d1-9cae56a6a3cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
