INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92922, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7ca5229-d3bd-448b-a0d1-9cae56a6a3cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92922, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "剩下的人或事物。", "primary_collocate": null, "pronunciation": "qí yú", "ipa": "tɕʰi˧˥ y˧˥", "syllable_count": 2, "sentences": [{"text": "我只买了苹果，其余的东西你来买。", "target_word": "其余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三个人去了，其余的人都在家。", "target_word": "其余", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这道题我做对了，其余的都做错了。", "target_word": "其余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师先看了第一页，其余的明天再看。", "target_word": "其余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你先吃一半，其余的留给弟弟。", "target_word": "其余", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他最喜欢红色，其余的颜色他很少穿。", "target_word": "其余", "complexity_tier": "T3", "furigana": "Tā zuì xǐhuan hóngsè, qíyú de yánsè tā hěn shǎo chuān.", "sentence_source": "generated"}, {"text": "一部分学生去公园，其余学生留在教室。", "target_word": "其余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些书我看过两本，其余的还没看。", "target_word": "其余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把红的放这里，其余的放那里。", "target_word": "其余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿走了三千块，其余的钱还在银行里。", "target_word": "其余", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "其余：代词，指已提到的部分以外剩下的人或事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0802c43-0ce8-40f0-87ca-f93fb1d9c662') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92922, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "其余", "is_correct": true, "explanation": "其余指已提到的苹果之外剩下的东西，与前句“只买了苹果”吻合。"}, {"text": "所有", "is_correct": false, "explanation": "语义：“所有”包括苹果在内，与“只买了苹果”矛盾。"}, {"text": "全部", "is_correct": false, "explanation": "语义：“全部”同样包括苹果，与前句“只买了苹果”冲突。"}, {"text": "其中", "is_correct": false, "explanation": "搭配：“其中”需指已提到范围之内的部分，接“的东西”后不能指苹果之外的东西。"}], "explanations": {"其余": "其余指已提到的苹果之外剩下的东西，与前句“只买了苹果”吻合。", "所有": "语义：“所有”包括苹果在内，与“只买了苹果”矛盾。", "全部": "语义：“全部”同样包括苹果，与前句“只买了苹果”冲突。", "其中": "搭配：“其中”需指已提到范围之内的部分，接“的东西”后不能指苹果之外的东西。"}, "sentence_index": 0, "correct_answer": "其余"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这些作业我全部做完了，其余的还没做。", "explanation": "前文说“全部做完”，已没有剩下的作业，“其余的还没做”与之矛盾。"}, {"text": "他把饭菜全部吃光了，其余的还留在桌上。", "explanation": "前文说饭菜已“全部吃光”，桌上没有剩下的饭菜，“其余的还留在桌上”与之矛盾。"}, {"text": "这笔奖金我已经全部花完了，其余的钱还在账上。", "explanation": "前文说奖金已“全部花完”，就没有剩下的钱，与“还在账上”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7ca5229-d3bd-448b-a0d1-9cae56a6a3cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92922, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "其余", "is_correct": true, "explanation": "其余指一部分学生之外剩下的学生，与前句“一部分学生去公园”吻合。"}, {"text": "全体", "is_correct": false, "explanation": "语义：“全体”指所有人，与“一部分学生去公园”矛盾。"}, {"text": "每个", "is_correct": false, "explanation": "语义：“每个”指全部学生，与前句“一部分学生去公园”冲突。"}, {"text": "那个", "is_correct": false, "explanation": "搭配：“那个”指单一的人，与复数的“学生”群体不搭。"}], "explanations": {"其余": "其余指一部分学生之外剩下的学生，与前句“一部分学生去公园”吻合。", "全体": "语义：“全体”指所有人，与“一部分学生去公园”矛盾。", "每个": "语义：“每个”指全部学生，与前句“一部分学生去公园”冲突。", "那个": "搭配：“那个”指单一的人，与复数的“学生”群体不搭。"}, "sentence_index": 6, "correct_answer": "其余"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这盒苹果我全部吃了，其余的还在桌上。", "explanation": "前文说“全部吃了”，盒中已没有剩下的苹果，“其余的还在桌上”与之矛盾。"}, {"text": "他家的猫全都在院子里，其余的猫还在屋里。", "explanation": "前文说猫“全都在院子里”，已没有剩下的猫，“其余的还在屋里”与之矛盾。"}, {"text": "这是唯一的一本书，其余的书在柜子里。", "explanation": "这里不能说“剩下的书”。前文说“唯一”，除这一本外没有别的书，不存在剩下的部分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7ca5229-d3bd-448b-a0d1-9cae56a6a3cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92922, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他只喝了一杯茶，其余地酒他没碰。", "corrected_sentence": "他只喝了一杯茶，其余的酒他没碰。", "error_description": "错误在“其余”后的结构助词。“其余”作定语修饰名词时常加“的”，写成“其余的酒”；这里用“地”不对，“地”只用于修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7ca5229-d3bd-448b-a0d1-9cae56a6a3cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92922, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些苹果我吃了两个，其余地都给了朋友。", "corrected_sentence": "这些苹果我吃了两个，其余的都给了朋友。", "error_description": "错误在“其余”后的结构助词。这里“其余”作主语，写成“其余的都给了朋友”或“其余都给了朋友”均可；“地”用于修饰动词，不能用在这里。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7ca5229-d3bd-448b-a0d1-9cae56a6a3cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
