INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92924, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "经评议、评比而确定为（某种称号或等级）。", "primary_collocate": null, "pronunciation": "píng wéi", "ipa": "pʰiŋ˧˥ weɪ˧˥", "syllable_count": 2, "sentences": [{"text": "学校把李老师评为优秀教师。", "target_word": "评为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司把小王评为今年的先进工作者。", "target_word": "评为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市里把这家医院评为一级医院。", "target_word": "评为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校把小明评为三好学生。", "target_word": "评为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年专家们把这个小城评为最美城市。", "target_word": "评为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过检查，学校把三班评为优秀班集体。", "target_word": "评为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工会把张师傅评为劳动模范。", "target_word": "评为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里今年把她家评为文明家庭。", "target_word": "评为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报社把这本书评为年度好书。", "target_word": "评为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "评委会把这位老人评为感动人物。", "target_word": "评为", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "评为了", "label": "体标（了）"}, {"form": "评为过", "label": "体标（过）"}, {"form": "被评为", "label": "被动"}], "register": "中性", "sense_fingerprint": "经单位或组织正式评议、评比后，确定某种称号或等级", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8173b1b7-e271-40b8-a04e-530729132fbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92924, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "评为", "is_correct": true, "explanation": "正确答案：评为（píng wéi）。"}, {"text": "评委", "is_correct": false, "explanation": "wěi（第三声）与 wéi（第二声）声调不同，意思是评审人员。"}, {"text": "行为", "is_correct": false, "explanation": "xíng 与 píng 声母不同（x 与 p），意思是行动、举止。"}, {"text": "名为", "is_correct": false, "explanation": "míng 与 píng 声母不同（m 与 p），意思是名义上是。"}], "explanations": {"评为": "正确答案：评为（píng wéi）。", "评委": "wěi（第三声）与 wéi（第二声）声调不同，意思是评审人员。", "行为": "xíng 与 píng 声母不同（x 与 p），意思是行动、举止。", "名为": "míng 与 píng 声母不同（m 与 p），意思是名义上是。"}, "sentence_index": null, "correct_answer": "评为"}, "level_3": {"options": [{"text": "评为", "is_correct": true, "explanation": "正确答案：评为，指经评议确定为某种称号。"}, {"text": "判为", "is_correct": false, "explanation": "语义：“判为”指依法或依规定作出裁决，不用于授予称号。"}, {"text": "任为", "is_correct": false, "explanation": "搭配：“任为”后接职务，不接“优秀教师”这类称号。"}, {"text": "装扮为", "is_correct": false, "explanation": "体貌：“装扮为”指打扮成某种角色的外形，与授予称号无关。"}], "explanations": {"评为": "正确答案：评为，指经评议确定为某种称号。", "判为": "语义：“判为”指依法或依规定作出裁决，不用于授予称号。", "任为": "搭配：“任为”后接职务，不接“优秀教师”这类称号。", "装扮为": "体貌：“装扮为”指打扮成某种角色的外形，与授予称号无关。"}, "sentence_index": 0, "correct_answer": "评为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他今年被评为研究生。", "explanation": "这里应该用〈录取〉。录取指招收入学，评为指经评议确定称号或等级，不用于入学资格。"}, {"text": "他把这个孩子评为徒弟。", "explanation": "这里应该用〈收为〉。收为指收人为徒弟或养子，评为指经评议确定称号或等级，不用于收纳关系。"}, {"text": "周日被评为休息日。", "explanation": "这里应该用〈定为〉。定为指规定某日为某种日子，评为指经评议确定称号或等级，不用于规定日期。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29b77f53-c4e8-4e1a-bd01-fe9be5f8cc36') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92924, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "评为", "is_correct": true, "explanation": "正确答案：评为，指经评议确定为某种称号。"}, {"text": "伪装为", "is_correct": false, "explanation": "语义：“伪装为”指假扮，与工会正式表彰相悖。"}, {"text": "招为", "is_correct": false, "explanation": "搭配：“招为”只接女婿、弟子等人身关系，不接“劳动模范”。"}, {"text": "娶为", "is_correct": false, "explanation": "搭配：“娶为”只接配偶，不能接“劳动模范”这类称号。"}], "explanations": {"评为": "正确答案：评为，指经评议确定为某种称号。", "伪装为": "语义：“伪装为”指假扮，与工会正式表彰相悖。", "招为": "搭配：“招为”只接女婿、弟子等人身关系，不接“劳动模范”。", "娶为": "搭配：“娶为”只接配偶，不能接“劳动模范”这类称号。"}, "sentence_index": 6, "correct_answer": "评为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校把他评为校长。", "explanation": "这里应该用〈任命〉。任命指按程序委派职务，评为指经评议确定称号或等级，不用于职务委派。"}, {"text": "他把我评为兄弟。", "explanation": "这里应该用〈认作〉。认作指认定为某种关系或身份，评为指经评议确定称号或等级，不用于确立兄弟关系。"}, {"text": "皇上把她评为公主。", "explanation": "这里应该用〈封〉。封指帝王授予封号，评为指经评议确定称号或等级，不用于帝王封赏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29b77f53-c4e8-4e1a-bd01-fe9be5f8cc36') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92924, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "经过评议，学校把她评为着优秀学生干部。", "corrected_sentence": "经过评议，学校把她评为优秀学生干部。", "error_description": "体标错误：“评为”后不能加“着”，应去掉“着”，即“学校把她评为优秀学生干部”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29b77f53-c4e8-4e1a-bd01-fe9be5f8cc36') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92924, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "评委会评为先进集体。", "corrected_sentence": "评委会把这支队伍评为先进集体。", "error_description": "缺宾语：“评为”前需要说明被评的对象，应加“把这支队伍”，即“评委会把这支队伍评为先进集体”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29b77f53-c4e8-4e1a-bd01-fe9be5f8cc36') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
