INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92925, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "调研是到现场去看一看，问一问，弄清楚情况。", "primary_collocate": null, "pronunciation": "diào yán", "ipa": "tiɑʊ̯˥˩ jɛn˧˥", "syllable_count": 2, "sentences": [{"text": "经理下周要去工厂调研。", "target_word": "调研", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先到社区调研，再写报告。", "target_word": "调研", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王去农村调研了三天。", "target_word": "调研", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带学生到公园调研鸟的种类。", "target_word": "调研", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想调研一下这条街的商店。", "target_word": "调研", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司派人去山区调研学校的情况。", "target_word": "调研", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们去超市调研了价格，发现便宜不少。", "target_word": "调研", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者在小镇调研过很多次。", "target_word": "调研", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要先调研清楚，才能做决定。", "target_word": "调研", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李在医院门口调研病人的看法。", "target_word": "调研", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "调研了", "label": "体标"}, {"form": "调研过", "label": "体标"}, {"form": "调研着", "label": "体标"}], "register": "书面", "sense_fingerprint": "到现场实地察看、询问，弄清情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd93837-ff1f-44d8-9b8c-6d7a0431f7eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92925, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "调研", "is_correct": true, "explanation": "调研（diào yán）指到现场实地察看、询问，弄清情况，是本题要听出的词。"}, {"text": "教研", "is_correct": false, "explanation": "jiào（第四声）与 diào 声母不同（j 与 d），意思是教学研究。"}, {"text": "笑言", "is_correct": false, "explanation": "xiào（第四声）与 diào 声母不同（x 与 d），意思是笑着说。"}, {"text": "叼烟", "is_correct": false, "explanation": "diāo（第一声）与 diào 声调不同，yān 与 yán 声调也不同，意思是嘴里衔着烟。"}], "explanations": {"调研": "调研（diào yán）指到现场实地察看、询问，弄清情况，是本题要听出的词。", "教研": "jiào（第四声）与 diào 声母不同（j 与 d），意思是教学研究。", "笑言": "xiào（第四声）与 diào 声母不同（x 与 d），意思是笑着说。", "叼烟": "diāo（第一声）与 diào 声调不同，yān 与 yán 声调也不同，意思是嘴里衔着烟。"}, "sentence_index": null, "correct_answer": "调研"}, "level_3": {"options": [{"text": "调研", "is_correct": true, "explanation": "调研指到现场实地了解情况，去工厂了解生产的情况，与句意相符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”与去工厂了解情况的目的不符，句子不通。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：工厂里去游泳与句中的工作安排无关，句子不合常理。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：“感冒”是身体状况，不是去工厂要做的事，句子不通。"}], "explanations": {"调研": "调研指到现场实地了解情况，去工厂了解生产的情况，与句意相符。", "睡觉": "语义：“睡觉”与去工厂了解情况的目的不符，句子不通。", "游泳": "语义：工厂里去游泳与句中的工作安排无关，句子不合常理。", "感冒": "语义：“感冒”是身体状况，不是去工厂要做的事，句子不通。"}, "sentence_index": 0, "correct_answer": "调研"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "科学家在实验室调研新药。", "explanation": "这里应该用〈研究〉。调研指到现场实地调查，在实验室里做的研究要用研究。"}, {"text": "医生调研了病人的身体。", "explanation": "这里应该用〈检查〉。调研用于了解情况或看法，检查身体要用检查。"}, {"text": "工人用尺子调研了桥的长度。", "explanation": "这里应该用〈测量〉。调研是调查情况，不用来测定长度等数量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60d60860-2d32-4eff-ad4b-bfb7fc1c6c2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92925, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "调研", "is_correct": true, "explanation": "调研指到现场实地察看、询问，去超市了解价格情况，与“发现便宜不少”相符。"}, {"text": "购买", "is_correct": false, "explanation": "搭配：“购买”要带具体商品作宾语，不能说“购买价格”。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”指清理卫生，与了解价格无关，句子不通。"}, {"text": "出售", "is_correct": false, "explanation": "搭配：“出售”的对象是商品，不用来说“出售价格”。"}], "explanations": {"调研": "调研指到现场实地察看、询问，去超市了解价格情况，与“发现便宜不少”相符。", "购买": "搭配：“购买”要带具体商品作宾语，不能说“购买价格”。", "打扫": "语义：“打扫”指清理卫生，与了解价格无关，句子不通。", "出售": "搭配：“出售”的对象是商品，不用来说“出售价格”。"}, "sentence_index": 6, "correct_answer": "调研"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "建筑师调研了一碗热汤，很快就喝光了。", "explanation": "这里应该用〈喝〉。调研是调查研究，不指喝汤。"}, {"text": "老师调研了黑板，用力擦了很久。", "explanation": "这里应该用〈擦〉。调研是调查研究，不指擦拭黑板。"}, {"text": "摄影师调研了一台冰箱，把它搬到了厨房。", "explanation": "这里应该用〈搬〉。调研是调查研究，不指搬运物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60d60860-2d32-4eff-ad4b-bfb7fc1c6c2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92925, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把这个村的情况调研很透彻。", "corrected_sentence": "他把这个村的情况调研得很透彻。", "error_description": "错误形式“调研很透彻”，正确形式“调研得很透彻”。“调研”后接结果或程度补语时要用“得”，漏掉“得”，句子不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60d60860-2d32-4eff-ad4b-bfb7fc1c6c2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92925, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们明天要去市场调研着消费者的想法。", "corrected_sentence": "我们明天要去市场调研消费者的想法。", "error_description": "错误形式“调研着”，多出了“着”。正确形式“调研”后不加“着”。“着”表示动作正在进行，与将来时间“明天”矛盾，应去掉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60d60860-2d32-4eff-ad4b-bfb7fc1c6c2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
