INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92926, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "调查研究。", "primary_collocate": null, "pronunciation": "diào yán", "ipa": "tiɑʊ̯˥˩ jɛn˧˥", "syllable_count": 2, "sentences": [{"text": "没有调研，就没有发言权。", "target_word": "调研", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司正在调研新产品的市场。", "target_word": "调研", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家调研了三个月，才写出报告。", "target_word": "调研", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们必须认真调研，不能随便写。", "target_word": "调研", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们调研着本地的水质问题。", "target_word": "调研", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他调研过很多城市的交通。", "target_word": "调研", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "调研的结果让大家很吃惊。", "target_word": "调研", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她负责调研年轻人的消费习惯。", "target_word": "调研", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大学生们想调研一下网上学习的效果。", "target_word": "调研", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报告写好前，我们要把问题调研清楚。", "target_word": "调研", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "调研了", "label": "体标"}, {"form": "调研过", "label": "体标"}, {"form": "调研着", "label": "体标"}], "register": "书面", "sense_fingerprint": "对某个问题或情况做调查并加以研究", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd93837-ff1f-44d8-9b8c-6d7a0431f7eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92926, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "调研", "is_correct": true, "explanation": "调研（diào yán）指对某个问题或情况做调查并加以研究，是本题要听出的词。"}, {"text": "教研", "is_correct": false, "explanation": "jiào（第四声）与 diào 声母不同（j 与 d），意思是教学研究。"}, {"text": "笑言", "is_correct": false, "explanation": "xiào（第四声）与 diào 声母不同（x 与 d），意思是笑着说。"}, {"text": "叼烟", "is_correct": false, "explanation": "diāo（第一声）与 diào 声调不同，yān 与 yán 声调也不同，意思是嘴里衔着烟。"}], "explanations": {"调研": "调研（diào yán）指对某个问题或情况做调查并加以研究，是本题要听出的词。", "教研": "jiào（第四声）与 diào 声母不同（j 与 d），意思是教学研究。", "笑言": "xiào（第四声）与 diào 声母不同（x 与 d），意思是笑着说。", "叼烟": "diāo（第一声）与 diào 声调不同，yān 与 yán 声调也不同，意思是嘴里衔着烟。"}, "sentence_index": null, "correct_answer": "调研"}, "level_3": {"options": [{"text": "调研", "is_correct": true, "explanation": "调研指调查研究，“没有调研”才会缺少发言的依据，与句意相符。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”与“发言权”没有逻辑关系，句子不通。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”与“发言权”无关，句子不成立。"}, {"text": "瞎搞", "is_correct": false, "explanation": "语域：“瞎搞”是口语，含贬义，与本句的书面语体不合，也与“发言权”的依据无关。"}], "explanations": {"调研": "调研指调查研究，“没有调研”才会缺少发言的依据，与句意相符。", "唱歌": "语义：“唱歌”与“发言权”没有逻辑关系，句子不通。", "散步": "语义：“散步”与“发言权”无关，句子不成立。", "瞎搞": "语域：“瞎搞”是口语，含贬义，与本句的书面语体不合，也与“发言权”的依据无关。"}, "sentence_index": 0, "correct_answer": "调研"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "厨师调研了一碗汤，把它喝光了。", "explanation": "这里应该用〈喝〉。调研是调查研究，不指喝汤。"}, {"text": "工人调研了墙壁，把它刷成了蓝色。", "explanation": "这里应该用〈刷〉。调研是调查研究，不指给墙壁刷漆。"}, {"text": "工人用尺子调研了桥的长度。", "explanation": "这里应该用〈测量〉。调研是调查情况，不用来测定长度等数量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60d60860-2d32-4eff-ad4b-bfb7fc1c6c2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92926, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "调研", "is_correct": true, "explanation": "“调研的结果”指调查研究得出的结论，与“让大家很吃惊”相符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉的结果”与句中的意思不符，让人无法理解。"}, {"text": "发呆", "is_correct": false, "explanation": "语义：“发呆”不会产生让人吃惊的结果，“发呆的结果”不成立。"}, {"text": "出席", "is_correct": false, "explanation": "配价：“出席”要带会议等宾语，不能单独与“的结果”组合。"}], "explanations": {"调研": "“调研的结果”指调查研究得出的结论，与“让大家很吃惊”相符。", "睡觉": "语义：“睡觉的结果”与句中的意思不符，让人无法理解。", "发呆": "语义：“发呆”不会产生让人吃惊的结果，“发呆的结果”不成立。", "出席": "配价：“出席”要带会议等宾语，不能单独与“的结果”组合。"}, "sentence_index": 6, "correct_answer": "调研"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他调研了一碗热面，吃得很满足。", "explanation": "这里应该用〈吃〉。调研是调查研究，不指吃东西。"}, {"text": "老师调研了教室的窗户，把它们擦得很亮。", "explanation": "这里应该用〈擦〉。调研是调查研究，不指擦拭窗户。"}, {"text": "摄影师调研了一棵树，把它砍倒了。", "explanation": "这里应该用〈砍〉。调研是调查研究，不指砍伐树木。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60d60860-2d32-4eff-ad4b-bfb7fc1c6c2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92926, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把这个村子的情况调研很仔细。", "corrected_sentence": "他把这个村子的情况调研得很仔细。", "error_description": "错误形式“调研很仔细”，正确形式“调研得很仔细”。“调研”后接程度补语时要用“得”，漏掉“得”，句子不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60d60860-2d32-4eff-ad4b-bfb7fc1c6c2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92926, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们想请专家调研了这个问题。", "corrected_sentence": "我们想请专家调研这个问题。", "error_description": "错误形式“调研了这个问题”，多出了“了”。“想请”表示未来的打算，而“了”表示已经完成，二者矛盾，应去掉“了”，改为“调研这个问题”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60d60860-2d32-4eff-ad4b-bfb7fc1c6c2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
