INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92928, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "表明事物已经发生或将要发生的隐约现象。", "primary_collocate": null, "pronunciation": "jì xiàng", "ipa": "tɕi˥˩ ɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这些迹象表明，他昨晚没有回家。", "target_word": "迹象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济出现了好转的迹象。", "target_word": "迹象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说病人没有恢复的迹象。", "target_word": "迹象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察在房间里发现了有人来过的迹象。", "target_word": "迹象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上的脚印是有人进来的迹象。", "target_word": "迹象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房价有下降的迹象。", "target_word": "迹象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从这些迹象看，他们早就认识。", "target_word": "迹象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的脸上没有一点高兴的迹象。", "target_word": "迹象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市似乎有发展的迹象。", "target_word": "迹象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说公司没有变好的迹象。", "target_word": "迹象", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "种", "label": "量词"}], "register": "中性", "sense_fingerprint": "表明事物已经或将要发生的隐约现象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdadcb77-e6c4-4c9d-9376-79a977628fc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92928, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "迹象", "is_correct": true, "explanation": "正确答案。迹象指表明事物已经发生或将要发生的隐约现象。"}, {"text": "气象", "is_correct": false, "explanation": "qì（第四声）与 jì（第四声）声母不同，j 与 q 相混。气象意思是天气和气候的状况。"}, {"text": "几项", "is_correct": false, "explanation": "jǐ（第三声）与 jì（第四声）声调不同。几项意思是几个项目。"}, {"text": "吉祥", "is_correct": false, "explanation": "jí（第二声）与 jì（第四声）、xiáng（第二声）与 xiàng（第四声）声调都不同。吉祥意思是吉利、好运。"}], "explanations": {"迹象": "正确答案。迹象指表明事物已经发生或将要发生的隐约现象。", "气象": "qì（第四声）与 jì（第四声）声母不同，j 与 q 相混。气象意思是天气和气候的状况。", "几项": "jǐ（第三声）与 jì（第四声）声调不同。几项意思是几个项目。", "吉祥": "jí（第二声）与 jì（第四声）、xiáng（第二声）与 xiàng（第四声）声调都不同。吉祥意思是吉利、好运。"}, "sentence_index": null, "correct_answer": "迹象"}, "level_3": {"options": [{"text": "迹象", "is_correct": true, "explanation": "正确答案。“这些迹象表明”指这些隐约的现象说明了事情。"}, {"text": "大楼", "is_correct": false, "explanation": "语义：“大楼”是建筑，不能用来表明他的行踪。"}, {"text": "口味", "is_correct": false, "explanation": "语义：“口味”指对食物的喜好，不能“表明”他昨晚的行踪。"}, {"text": "体型", "is_correct": false, "explanation": "体貌：“体型”说身形，不能作“表明”的主语。"}], "explanations": {"迹象": "正确答案。“这些迹象表明”指这些隐约的现象说明了事情。", "大楼": "语义：“大楼”是建筑，不能用来表明他的行踪。", "口味": "语义：“口味”指对食物的喜好，不能“表明”他昨晚的行踪。", "体型": "体貌：“体型”说身形，不能作“表明”的主语。"}, "sentence_index": 0, "correct_answer": "迹象"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这锅菜的迹象很咸，你少放点盐吧。", "explanation": "这里应该用〈味道〉。“咸”说的是味道，迹象指表明事物已经或将要发生的隐约现象，不能用来形容味道。"}, {"text": "山顶的迹象美得让人说不出话。", "explanation": "这里应该用〈景象〉。景象指眼前看到的景色，“美得让人说不出话”说的是景色；迹象不指景色。"}, {"text": "他在老师心中的迹象很好。", "explanation": "这里应该用〈形象〉。“心中的形象”指别人对他的印象，要用形象；迹象指事情将要发生的征兆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6205d22-05d7-4d8a-99ec-90516221c3f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92928, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "迹象", "is_correct": true, "explanation": "正确答案。“从这些迹象看”指根据隐约的现象来推断。"}, {"text": "硬币", "is_correct": false, "explanation": "语义：“硬币”是钱币，不能作为推断的依据来“看”。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”是嗅觉或味觉的对象，不能用来推断他们的关系。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”说身体的高矮，不能用来推断他们早就认识。"}], "explanations": {"迹象": "正确答案。“从这些迹象看”指根据隐约的现象来推断。", "硬币": "语义：“硬币”是钱币，不能作为推断的依据来“看”。", "味道": "语义：“味道”是嗅觉或味觉的对象，不能用来推断他们的关系。", "身高": "体貌：“身高”说身体的高矮，不能用来推断他们早就认识。"}, "sentence_index": 6, "correct_answer": "迹象"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的迹象很安静，从不大声说话。", "explanation": "这里应该用〈性格〉。“很安静”“从不大声说话”说的是性格；迹象指表明事物发生的隐约现象，不能用来形容人。"}, {"text": "这一带的迹象一年四季都很潮湿。", "explanation": "这里应该用〈气候〉。气候指一个地区长期的天气状况，“一年四季很潮湿”说的是气候；迹象不指气候。"}, {"text": "湖边的迹象很美，我们坐了一下午。", "explanation": "这里应该用〈景色〉。景色指眼前的自然风景，“湖边很美”说的是风景；迹象不指风景。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6205d22-05d7-4d8a-99ec-90516221c3f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92928, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "门口好像有一只刚下过雨的迹象。", "corrected_sentence": "门口好像有一种刚下过雨的迹象。", "error_description": "错误：“迹象”的量词用错，应该用“种”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6205d22-05d7-4d8a-99ec-90516221c3f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92928, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医生在他身上看到了一张好转的迹象。", "corrected_sentence": "医生在他身上看到了一些好转的迹象。", "error_description": "错误：“迹象”的量词用错。“张”用于纸、桌子等平面的东西，不能用于“迹象”；应该说“一些迹象”或“一种迹象”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6205d22-05d7-4d8a-99ec-90516221c3f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92929, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f64cdb5-3745-42f4-ba36-e5a3b1258b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92929, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f64cdb5-3745-42f4-ba36-e5a3b1258b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92929, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "车把是自行车前面手握的地方，用它来拐弯。", "primary_collocate": null, "pronunciation": "chē bǎ", "ipa": "ʈʂʰɤ˥ pa˨˩˦", "syllable_count": 2, "sentences": [{"text": "要拐弯的时候，请转动车把。", "target_word": "车把", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把车把向右一转，车就拐进了小路。", "target_word": "车把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆自行车的车把很低，我骑着不舒服。", "target_word": "车把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天很冷，我的手握着车把都冻红了。", "target_word": "车把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一松开车把，自行车就倒了。", "target_word": "车把", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路上有石头，他用力把住车把，不让车摔倒。", "target_word": "车把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸教我骑车，先让我扶好车把。", "target_word": "车把", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "车把一歪，车就往旁边走了。", "target_word": "车把", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那辆车的车把是红色的，很好看。", "target_word": "车把", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小孩儿的车把上常常装着铃铛，一按就响。", "target_word": "车把", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "车把套", "label": "复合"}, {"form": "車把", "label": "繁体"}], "register": "中性", "sense_fingerprint": "自行车前面手握、用来拐弯的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83b79118-3afa-43a8-854c-cfbbc5147759') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92929, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "车灯", "is_correct": false, "explanation": "语义：车灯是照明部件，转动它不能控制拐弯"}, {"text": "车铃", "is_correct": false, "explanation": "语义：车铃是用来发声的，不能控制自行车的方向"}, {"text": "车把", "is_correct": true, "explanation": "车把：转动车把可以控制自行车拐弯，与“要拐弯的时候”一致"}, {"text": "行李架", "is_correct": false, "explanation": "搭配：“转动”不用于行李架这类固定的部件"}], "explanations": {"车灯": "语义：车灯是照明部件，转动它不能控制拐弯", "车铃": "语义：车铃是用来发声的，不能控制自行车的方向", "车把": "车把：转动车把可以控制自行车拐弯，与“要拐弯的时候”一致", "行李架": "搭配：“转动”不用于行李架这类固定的部件"}, "sentence_index": 0, "correct_answer": "车把"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "车把坏了，一直在滴水。", "explanation": "这里应该用〈水龙头〉。滴水的是水龙头，车把是自行车的部件，不会滴水"}, {"text": "行李箱的车把断了，只能抱着走。", "explanation": "这里应该用〈手柄〉。行李箱上提着走的是手柄，车把只属于车辆"}, {"text": "用力踩车把，车子就快起来了。", "explanation": "这里应该用〈脚踏板〉。踩的是脚踏板，车把是用手握、控制方向的"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f64cdb5-3745-42f4-ba36-e5a3b1258b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92929, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "书包", "is_correct": false, "explanation": "语义：扶书包不能帮助控制骑车的方向"}, {"text": "扫帚", "is_correct": false, "explanation": "语义：扫帚是扫地用的工具，不是骑车时用来控制方向的部件，与“扶好”的语境不符"}, {"text": "车把", "is_correct": true, "explanation": "车把：扶着车把才能控制骑车的方向，“先让我扶好车把”自然"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机与控制骑车方向无关，扶着手机不能骑车"}], "explanations": {"书包": "语义：扶书包不能帮助控制骑车的方向", "扫帚": "语义：扫帚是扫地用的工具，不是骑车时用来控制方向的部件，与“扶好”的语境不符", "车把": "车把：扶着车把才能控制骑车的方向，“先让我扶好车把”自然", "手机": "语义：手机与控制骑车方向无关，扶着手机不能骑车"}, "sentence_index": 6, "correct_answer": "车把"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "门上的车把坏了，我怎么也拉不开门。", "explanation": "这里应该用〈把手〉。门上的把手用来开门，车把是车辆的部件"}, {"text": "骑手猛地收紧车把，马立刻站住了。", "explanation": "这里应该用〈缰绳〉。勒马站住要用缰绳，车把只用于骑车控制方向"}, {"text": "船长转动车把，船慢慢拐进了港口。", "explanation": "这里应该用〈舵〉。船靠船舵拐弯，车把是自行车、摩托车的部件"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f64cdb5-3745-42f4-ba36-e5a3b1258b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92929, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一直车把握紧，不敢放手。", "corrected_sentence": "他一直把车把握紧，不敢放手。", "error_description": "动词带结果补语（如“握紧”）时，宾语提前须用“把”，应说“他一直把车把握紧”，不说“他一直车把握紧”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f64cdb5-3745-42f4-ba36-e5a3b1258b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92929, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把车把扶了稳，才慢慢骑走。", "corrected_sentence": "他把车把扶稳了，才慢慢骑走。", "error_description": "“了”应放在补语“稳”之后，说“扶稳了”，不说“扶了稳”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f64cdb5-3745-42f4-ba36-e5a3b1258b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
