INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92931, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "军队按地域划分的大型管理区域。", "primary_collocate": null, "pronunciation": "jūn qū", "ipa": "tɕyn˥ tɕʰy˥", "syllable_count": 2, "sentences": [{"text": "哥哥是北京军区的一名军人。", "target_word": "军区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个军区管着很多地方的部队。", "target_word": "军区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家把全国分成几个军区。", "target_word": "军区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军区里的战士每天早上六点起床。", "target_word": "军区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸年轻时在西南军区当兵。", "target_word": "军区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个军区都有一位负责的将军。", "target_word": "军区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个军区离我们家很远。", "target_word": "军区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的部队属于东部军区。", "target_word": "军区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军区的人今天来学校帮忙。", "target_word": "军区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想看看军区是什么样子的。", "target_word": "军区", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "军区司令员", "label": "复合"}, {"form": "軍區", "label": "繁体"}], "register": "书面", "sense_fingerprint": "军队按地域划分的大型管理区域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '964c90de-6e63-4a08-9795-75c3d131a85e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92931, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "军区", "is_correct": true, "explanation": "北京军区是军队的地域性管理区域，哥哥可以是其中的一名军人，与句意相符。"}, {"text": "饭店", "is_correct": false, "explanation": "语义：饭店不是军队单位，不会有“一名军人”这样的编制身份。"}, {"text": "动物园", "is_correct": false, "explanation": "搭配：“动物园的一名军人”搭配不通，军人不属于动物园的编制。"}, {"text": "银行", "is_correct": false, "explanation": "语义：银行是金融机构，与“军人”的身份不符，句意不合。"}], "explanations": {"军区": "北京军区是军队的地域性管理区域，哥哥可以是其中的一名军人，与句意相符。", "饭店": "语义：饭店不是军队单位，不会有“一名军人”这样的编制身份。", "动物园": "搭配：“动物园的一名军人”搭配不通，军人不属于动物园的编制。", "银行": "语义：银行是金融机构，与“军人”的身份不符，句意不合。"}, "sentence_index": 0, "correct_answer": "军区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他被任命为军区，负责全军的训练。", "explanation": "这里把“军区”当成职务用了。军区是地区和机构，任职要说“军区司令员”之类，不能直接用“军区”。"}, {"text": "这个军区只有一间小屋。", "explanation": "军区是大型军事管理区域，不能指一间小屋，规模不合。"}, {"text": "妈妈把军区放进了冰箱。", "explanation": "军区是军队按地域划分的大型区域和机构，不是可以拿起来的物品，不能放进冰箱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f5f1d31-ca2a-49c7-8237-0c9588c31fa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92931, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "军区", "is_correct": true, "explanation": "军区是一个地区或机构，可以作为主语谈论离家的远近，与句意相符。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气是物质，不能作为有地点距离的对象，与句意不合。"}, {"text": "友谊", "is_correct": false, "explanation": "语义：友谊是抽象关系，不能用“离我们家很远”来描述。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“这个脾气”不能作为主语谈论与家的距离，搭配不当。"}], "explanations": {"军区": "军区是一个地区或机构，可以作为主语谈论离家的远近，与句意相符。", "空气": "语义：空气是物质，不能作为有地点距离的对象，与句意不合。", "友谊": "语义：友谊是抽象关系，不能用“离我们家很远”来描述。", "脾气": "搭配：“这个脾气”不能作为主语谈论与家的距离，搭配不当。"}, "sentence_index": 6, "correct_answer": "军区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把军区换成了一本新书。", "explanation": "这里把“军区”当成可以交换的物品用了。军区是地区和机构，不是可以换来换去的东西。"}, {"text": "我昨天把军区借给了朋友。", "explanation": "军区是军队按地域划分的大型区域和机构，不是可以借出的物品，用法错误。"}, {"text": "他一直觉得军区很好吃。", "explanation": "军区是地区和机构，不能作为食物被品尝，这种用法错误。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f5f1d31-ca2a-49c7-8237-0c9588c31fa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92931, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我叔叔在一只军区当了三年兵。", "corrected_sentence": "我叔叔在一个军区当了三年兵。", "error_description": "错误形式：“一只军区”；正确形式：“一个军区”。军区是地区和机构，量词应该用“个”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f5f1d31-ca2a-49c7-8237-0c9588c31fa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92931, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只军区离我们学校很远。", "corrected_sentence": "那个军区离我们学校很远。", "error_description": "错误形式：“那只军区”；正确形式：“那个军区”。军区是地区和机构，量词应该用“个”，不能用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f5f1d31-ca2a-49c7-8237-0c9588c31fa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
