INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92932, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "军队按地域划分的最高一级管理区域及其指挥机构。", "primary_collocate": null, "pronunciation": "jūn qū", "ipa": "tɕyn˥ tɕʰy˥", "syllable_count": 2, "sentences": [{"text": "这个军区的司令员今天来学校讲话。", "target_word": "军区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我叔叔在北方的一个军区工作。", "target_word": "军区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前中国有七个军区。", "target_word": "军区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军区的大门外站着两名战士。", "target_word": "军区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在军区当了二十年医生。", "target_word": "军区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位将军管理着整个军区的部队。", "target_word": "军区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军区开会决定，明年增加训练。", "target_word": "军区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从部队调到了另一个军区。", "target_word": "军区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个军区都有自己的指挥机构。", "target_word": "军区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新兵先在本军区训练三个月。", "target_word": "军区", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "军区司令员", "label": "复合"}, {"form": "軍區", "label": "繁体"}], "register": "书面", "sense_fingerprint": "军队按地域划分的最高一级区域及其指挥机构", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '964c90de-6e63-4a08-9795-75c3d131a85e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92932, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "军区", "is_correct": true, "explanation": "军区是军队按地域划分的最高一级管理区域，与“司令员”和“来学校讲话”的语境相符。"}, {"text": "学校", "is_correct": false, "explanation": "语义：学校不是军队的管理区域，没有司令员，与句意不合。"}, {"text": "医院", "is_correct": false, "explanation": "搭配：“医院的司令员”搭配不通，司令员属于军队单位。"}, {"text": "工厂", "is_correct": false, "explanation": "语义：工厂是生产单位，不是按地域划分的军队指挥区域。"}], "explanations": {"军区": "军区是军队按地域划分的最高一级管理区域，与“司令员”和“来学校讲话”的语境相符。", "学校": "语义：学校不是军队的管理区域，没有司令员，与句意不合。", "医院": "搭配：“医院的司令员”搭配不通，司令员属于军队单位。", "工厂": "语义：工厂是生产单位，不是按地域划分的军队指挥区域。"}, "sentence_index": 0, "correct_answer": "军区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上把军区煮成了粥。", "explanation": "军区是地区和机构，不能被煮成食物，这种用法明显错误。"}, {"text": "他每天早上去军区买菜。", "explanation": "这里把“军区”当成菜市场用了。军区是军队的管理区域，不是买菜的地方。"}, {"text": "我的哥哥是军区。", "explanation": "军区指地区和机构，不能用来指代人，这里应该说“军人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f5f1d31-ca2a-49c7-8237-0c9588c31fa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92932, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "军区", "is_correct": true, "explanation": "军区是军队的管理区域，能够开会决定增加训练，与句意相符。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园不是有决策机构的单位，不能开会决定训练事宜。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的地方，没有开会决定增加训练的功能，与句意不合。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，不能开会作决定，与句意不合。"}], "explanations": {"军区": "军区是军队的管理区域，能够开会决定增加训练，与句意相符。", "花园": "语义：花园不是有决策机构的单位，不能开会决定训练事宜。", "厨房": "语义：厨房是做饭的地方，没有开会决定增加训练的功能，与句意不合。", "冰箱": "语义：冰箱是家用电器，不能开会作决定，与句意不合。"}, "sentence_index": 6, "correct_answer": "军区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个军区的价格很便宜，大家都来买。", "explanation": "这里把“军区”当成商品用了。军区是地区和机构，没有价格，也不能购买。"}, {"text": "这个军区只有十个人，很热闹。", "explanation": "军区是大型的军事管理区域，不指只有十人的小单位，这里规模不合。"}, {"text": "他下班后常去军区逛街。", "explanation": "军区是军队的管理区域，不是商业场所，不能用来逛街。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f5f1d31-ca2a-49c7-8237-0c9588c31fa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92932, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只军区的战士每天早上训练。", "corrected_sentence": "这个军区的战士每天早上训练。", "error_description": "错误形式：“这只军区”；正确形式：“这个军区”。量词错误，军区应该用“个”计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f5f1d31-ca2a-49c7-8237-0c9588c31fa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92932, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他三年前调到了北方的一只军区。", "corrected_sentence": "他三年前调到了北方的一个军区。", "error_description": "错误形式：“一只军区”；正确形式：“一个军区”。军区是地区和机构，量词应该用“个”，不能用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f5f1d31-ca2a-49c7-8237-0c9588c31fa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
