INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92933, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "辉煌是很亮很漂亮，让人觉得了不起。", "primary_collocate": null, "pronunciation": "huī huáng", "ipa": "xweɪ˥ xwɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "晚上，大厅里的灯火辉煌，像白天一样亮。", "target_word": "辉煌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座宫殿里金光闪闪，看起来非常辉煌。", "target_word": "辉煌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新年的时候，街上的灯光特别辉煌。", "target_word": "辉煌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夜里，城市的灯火那么辉煌，我看了很久。", "target_word": "辉煌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新剧院外面灯光辉煌，好多人在拍照。", "target_word": "辉煌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夕阳照在海面上，一片辉煌。", "target_word": "辉煌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "酒店的大厅装得十分辉煌，水晶灯特别大。", "target_word": "辉煌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他带我参观了那座辉煌的皇宫，里面全是金子。", "target_word": "辉煌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "舞台上灯光辉煌，音乐一响，大家都安静了。", "target_word": "辉煌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山下的小城灯火辉煌，远远看去像一片星星。", "target_word": "辉煌", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "輝煌", "label": "繁体"}, {"form": "金碧辉煌", "label": "复合"}], "register": "书面", "sense_fingerprint": "灯光、宫殿等又亮又华丽，让人觉得壮观", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f09b97c-38a8-4ff2-bcb2-0a886cdc7162') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
